# Captured at TOP LEVEL, before any function runs: inside a "function name"-style
# ksh93 function, $0 is the FUNCTION NAME (ksh88 keeps the script path) — so any
# later dirname-$0 self-location done inside a function is silently wrong on one
# of the two target shells. AIXRAY_SELF is the only self-path source used below.
AIXRAY_SELF=$0

FORMAT=html
FLRTVC_REPORT=""
FLRTVC_KSH=""
FLRTVC_APARCSV=""
FLRTVC_DATA_SOURCE="none"
FLRTVC_DATA_VERSION=""
FLRTVC_DATA_VINTAGE=""
FLRTVC_DATA_AGE=""
FV_PROVENANCE_REAL=0
COMPLIANCE=""
FLRT_EXPORT=""
OUT_DIR=""
OUT_EXPLICIT=0
[ "$#" -eq 0 ] && OUT_DIR=.
USAGE="usage: $0 [--html|--json|--compliance stig|cis-l1|ffiec] [--out <dir>] [--flrtvc-ksh <script> --flrtvc-apar-csv <file> | --flrtvc-report <file>] [--flrt-export <dir>]"
while [ "$#" -gt 0 ]; do
  case "$1" in
    --json) FORMAT=json;;
    --html) FORMAT=html;;
    --compliance)
      shift
      COMPLIANCE=${1:-}
      case "$COMPLIANCE" in
        stig|cis-l1|ffiec) FORMAT=compliance;;
        *) echo "$USAGE" >&2; echo "aixray: --compliance needs one of: stig, cis-l1, ffiec" >&2; exit 2;;
      esac
      ;;
    --flrtvc-ksh)
      shift
      FLRTVC_KSH=${1:-}
      if [ -z "$FLRTVC_KSH" ]; then echo "$USAGE" >&2; exit 2; fi
      ;;
    --flrtvc-apar-csv)
      shift
      FLRTVC_APARCSV=${1:-}
      if [ -z "$FLRTVC_APARCSV" ]; then echo "$USAGE" >&2; exit 2; fi
      ;;
    --flrtvc-report)
      shift
      FLRTVC_REPORT=${1:-}
      if [ -z "$FLRTVC_REPORT" ]; then echo "$USAGE" >&2; exit 2; fi
      ;;
    --flrt-export)
      shift
      FLRT_EXPORT=${1:-}
      if [ -z "$FLRT_EXPORT" ]; then echo "$USAGE" >&2; echo "aixray: --flrt-export needs an output directory" >&2; exit 2; fi
      ;;
    --out)
      OUT_EXPLICIT=1
      shift
      OUT_DIR=${1:-}
      case "$OUT_DIR" in
        ""|--*)
          echo "$USAGE" >&2
          echo "aixray: --out needs an output directory" >&2
          exit 2
          ;;
      esac
      ;;
    *) echo "$USAGE" >&2; exit 2;;
  esac
  shift
done

if [ -n "$OUT_DIR" ]; then
  if [ "$FORMAT" != "html" ] || [ -n "$FLRT_EXPORT" ]; then
    echo "$USAGE" >&2
    echo "aixray: --out writes the easy HTML report; use stdout redirection for --json, --compliance, or --flrt-export" >&2
    exit 2
  fi
fi

if [ -z "${AIXRAY_FIXTURES:-}" ] && [ "$(uname -s 2>/dev/null)" != "AIX" ]; then
  echo "aixray-aix.sh: this is the AIX/VIOS edition (this host is not AIX). Use aixray.sh for Linux." >&2
  exit 2
fi

