# ======================= infrastructure ===============================================

REVIEW_CTA='Free engineer review: email your report to review@powertruesystems.com — a principal engineer replies within 2 business days.'
function progress { printf '[%s/9] %s…\n' "$1" "$2" >&2; }
function finish_report { printf '%s\n' "$REVIEW_CTA" >&2; }

# aix <key> <command> [args...] — every external read goes through here.
#   Live: run the command, stderr suppressed, return its rc.
#   Fixture mode: cat $AIXRAY_FIXTURES/<key>.out; rc from <key>.rc (default 0);
#   a missing <key>.out means "command absent / no data" (rc 127).
function aix {
  typeset key rc
  key=$1; shift
  if [ -n "${AIXRAY_FIXTURES:-}" ]; then
    if [ -r "$AIXRAY_FIXTURES/$key.out" ]; then
      cat "$AIXRAY_FIXTURES/$key.out"
      rc=0
      [ -r "$AIXRAY_FIXTURES/$key.rc" ] && read rc < "$AIXRAY_FIXTURES/$key.rc"
      return $rc
    fi
    return 127
  fi
  "$@" 2>/dev/null
}

# count_nonempty_lines <command> [args...] — stream a potentially large command
# through awk and emit only its small decimal count. The producer appends its rc
# as a completion marker so awk, whose status is the pipeline status on ksh88,
# can propagate a failed/incomplete producer instead of laundering it through a
# successful count. A marker collision fails closed because exactly one marker
# is required. Used by failed_logins so a multi-MB log never enters a ksh
# command-substitution variable.
function count_nonempty_lines {
  {
    "$@"
    printf '__AIXRAY_COUNT_RC__=%s\n' "$?"
  } | awk '
    /^__AIXRAY_COUNT_RC__=[0-9][0-9]*$/ {
      markers++
      capture_rc=$0
      sub(/^__AIXRAY_COUNT_RC__=/,"",capture_rc)
      next
    }
    NF { count++ }
    END {
      if (markers != 1) exit 125
      if (capture_rc+0 != 0) exit capture_rc+0
      print count+0
    }'
}

# aixv <key> <command> [args...] — like aix() above, but for checks whose sourced rule
# treats ANY output (stdout OR stderr) as adverse, where aix()'s blanket '2>/dev/null'
# would silently discard a real stderr diagnostic before the caller's own '2>&1' ever sees
# it -- laundering a real rc=0 stderr diagnostic into a false clean PASS (Codex primary
# review, M5, HIGH finding #2: a call site spelled '2>&1' but aix()'s internal redirection
# already ran, so it never had a chance to capture anything). Only used where that
# distinction matters; existing 'aix()' callers are untouched.
#   Live: run the command with stderr MERGED into stdout (2>&1) — nothing is discarded.
#   Fixture mode: <key>.out (stdout) then <key>.err (stderr) concatenated, in that order,
#   both optional (default empty) — this lets a fixture simulate a stderr-only diagnostic
#   on an otherwise-empty stdout, which the single-channel 'aix()' fixture format cannot
#   represent at all; rc from <key>.rc (default 0); both files absent means "command
#   absent / no data" (rc 127), same convention as aix().
function aixv {
  typeset key rc
  key=$1; shift
  if [ -n "${AIXRAY_FIXTURES:-}" ]; then
    if [ -r "$AIXRAY_FIXTURES/$key.out" ] || [ -r "$AIXRAY_FIXTURES/$key.err" ]; then
      [ -r "$AIXRAY_FIXTURES/$key.out" ] && cat "$AIXRAY_FIXTURES/$key.out"
      [ -r "$AIXRAY_FIXTURES/$key.err" ] && cat "$AIXRAY_FIXTURES/$key.err"
      rc=0
      [ -r "$AIXRAY_FIXTURES/$key.rc" ] && read rc < "$AIXRAY_FIXTURES/$key.rc"
      return $rc
    fi
    return 127
  fi
  "$@" 2>&1
}

# aixv_confirmed <key> <command> [args...] — like aixv() above, but for a caller that must
# tell a GENUINELY CONFIRMED rc=0 (an explicit <key>.rc file was actually present and read)
# apart from an ASSUMED rc=0 (no <key>.rc file existed at all -- aixv()'s own documented
# default, indistinguishable from a real rc=0 to every existing caller). Only matters in
# fixture-replay mode: a LIVE command invocation always returns ITS OWN real exit code, so
# this function behaves IDENTICALLY to aixv() on the live path -- 126 is a fixture-replay-
# only sentinel meaning "no completion signal was recorded for this capture at all," never
# something a live command itself returns for this reason (Codex confirming review,
# 2026-07-14, HIGH: 'rc=0 + empty output' is genuinely, unavoidably ambiguous between a
# real clean result and a wholesale capture-session failure that left BOTH a primary
# command AND its own corroborating cross-check equally empty with no recorded rc --
# no purely-textual signal from either capture's OWN content can ever tell these apart;
# only a distinct sentinel for "we were never told" closes this, and ONLY for callers that
# opt into it). Existing 'aix()'/'aixv()' callers are completely untouched -- this is a
# new, additive function, not a change to either's documented default behavior (which the
# vast majority of this repo's fixtures rely on implicitly and would otherwise all need a
# newly-required .rc file, a disproportionate blast-radius change out of scope here).
function aixv_confirmed {
  typeset key rc
  key=$1; shift
  if [ -n "${AIXRAY_FIXTURES:-}" ]; then
    if [ -r "$AIXRAY_FIXTURES/$key.out" ] || [ -r "$AIXRAY_FIXTURES/$key.err" ]; then
      [ -r "$AIXRAY_FIXTURES/$key.out" ] && cat "$AIXRAY_FIXTURES/$key.out"
      [ -r "$AIXRAY_FIXTURES/$key.err" ] && cat "$AIXRAY_FIXTURES/$key.err"
      if [ -r "$AIXRAY_FIXTURES/$key.rc" ]; then
        read rc < "$AIXRAY_FIXTURES/$key.rc"
      else
        rc=126
      fi
      return $rc
    fi
    return 127
  fi
  "$@" 2>&1
}

# HTML / JSON escaping — AIX sed/awk only.
function hesc { sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g'; }
function jesc {
  # C-locale awk: escape backslash, quote, tab; CR -> \r; then strip any
  # remaining control bytes (0x00-0x1f) that would break JSON. gsub with a
  # 0x80-0x9f-safe class leaves high bytes (>=0x80) untouched.
  awk 'BEGIN{ORS=""} {gsub(/\\/,"\\\\"); gsub(/"/,"\\\""); gsub(/\t/,"\\t"); gsub(/\r/,"\\r"); gsub(/[\001-\010\013\014\016-\037]/,""); if (NR>1) printf "\\n"; print}'
}
# jn <value> -> a JSON string literal (escaped) or the bare token null for an empty value.
# Used by the upgrade_readiness block, where an unread on-box fact (e.g. no VIOS, firmware
# unreadable) must render as JSON null, not an empty/misleading string.
function jn { if [ -z "$1" ]; then printf 'null'; else printf '"%s"' "$(printf '%s' "$1" | jesc)"; fi; }
# jnum <value> -> a bare JSON number for a numeric value, else the token null.
function jnum { case "$1" in ''|*[!0-9.-]*) printf 'null';; *) printf '%s' "$1";; esac; }
# Assignment-time guard for numeric facts.  jnum intentionally remains the
# contract-specified last-resort emitter; no FACT_* numeric reaches it unless
# this strict JSON-number grammar accepted the captured token first.
function valid_json_number {
  printf '%s\n' "$1" | awk '
    NR==1 && $0 ~ /^-?(0|[1-9][0-9]*)([.][0-9]+)?([eE][+-]?[0-9]+)?$/ {ok=1}
    END{exit ok?0:1}'
}
# ipart understands only the plain integer/decimal shapes emitted by AIX
# svmon/vmstat.  Reject exponent/comma/malformed forms before conversion so
# ipart's prose-oriented fallback zero can never become a structured fact.
function valid_plain_decimal {
  printf '%s\n' "$1" | awk '
    NR==1 && $0 ~ /^-?[0-9]+([.][0-9]+)?$/ {ok=1}
    END{exit ok?0:1}'
}
# valid_pct_decimal <token> <max> — accept the raw observed percentage only
# when its lexical value is inside 0..max. Check BEFORE ipart truncates it.
function valid_pct_decimal {
  printf '%s\n' "$1" | awk -v max="$2" '
    NR==1 && $0 ~ /^-?[0-9]+([.][0-9]+)?$/ {
      if(substr($0,1,1)!="-" && $0+0<=max+0) ok=1
    }
    END{exit ok?0:1}'
}
function jbool { case "$1" in true|false) printf '%s' "$1";; *) printf 'null';; esac; }
function jlist { # space-delimited field names -> JSON string array
  typeset item sep
  sep=""
  printf '['
  for item in $1; do
    printf '%s"%s"' "$sep" "$item"
    sep=', '
  done
  printf ']'
}
# jcmds <pipe-delimited commands> -> JSON string array. Lifecycle evidence uses
# a delimiter rather than shell words so each command retains its spaces. The
# command names are fixed by this read-only scanner, but still pass through the
# ordinary JSON escaping path so the renderer has one safe rule.
function jcmds {
  printf '%s\n' "$1" | awk -F'|' '
    function je(s){
      gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\t/,"\\t",s); gsub(/\r/,"\\r",s)
      gsub(/[\001-\010\013\014\016-\037]/,"",s); return s
    }
    BEGIN{printf "["}
    {for(i=1;i<=NF;i++) if($i!="" && !seen[$i]++) printf "%s\"%s\"", (n++?", ":""), je($i)}
    END{printf "]"}'
}

# Date math in pure integer arithmetic (no GNU date on AIX).
function d2j { # YYYY-MM-DD -> julian day number
  typeset y m d a
  # Defense-in-depth: never let a non-calendar-shaped value reach the arithmetic
  # below — ksh $(( )) recursively evaluates its operands, so a crafted field
  # (e.g. AIXRAY_TODAY="x[$(cmd)]-07-18") would otherwise be executed. valid_ymd
  # anchors the shape to pure digits before any $(( )) runs.
  if [ "$(valid_ymd "$1")" != 1 ]; then
    echo "aixray: internal error: d2j requires a real calendar date in YYYY-MM-DD format" >&2
    return 1
  fi
  y=${1%%-*}; m=${1#*-}; m=${m%%-*}; d=${1##*-}
  m=${m#0}; d=${d#0}
  a=$(( (14 - m) / 12 ))
  y=$(( y + 4800 - a ))
  m=$(( m + 12*a - 3 ))
  echo $(( d + (153*m + 2)/5 + 365*y + y/4 - y/100 + y/400 - 32045 ))
}
function j2d { # julian day number -> "YYYY MM DD"
  typeset a b c d e m
  a=$(( $1 + 32044 )); b=$(( (4*a + 3) / 146097 )); c=$(( a - 146097*b/4 ))
  d=$(( (4*c + 3) / 1461 )); e=$(( c - 1461*d/4 )); m=$(( (5*e + 2) / 153 ))
  echo "$(( 100*b + d - 4800 + m/10 )) $(( m + 3 - 12*(m/10) )) $(( e - (153*m + 2)/5 + 1 ))"
}
# d2j/j2d do pure Julian-day arithmetic and will silently accept an IMPOSSIBLE
# calendar date (e.g. 2026-02-31) — the formula just produces some other real
# date instead of erroring. valid_ymd is the explicit calendar-correctness
# check a vintage stamp needs before its age can be trusted (Codex review: a
# feed dated Feb-31 must never silently pass as "3 days old" or similar).
function is_leap_year { # YYYY -> 1/0
  typeset y=$1
  y=${y#0}; y=${y#0}; y=${y#0}
  if [ $((y % 400)) -eq 0 ]; then echo 1
  elif [ $((y % 100)) -eq 0 ]; then echo 0
  elif [ $((y % 4)) -eq 0 ]; then echo 1
  else echo 0; fi
}
function valid_ymd { # "YYYY-MM-DD" -> 1/0 (real calendar date, not just digit-shaped)
  typeset ymd=$1 y m d rest dim
  case "$ymd" in
    [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]) ;;
    *) echo 0; return;;
  esac
  y=${ymd%%-*}; rest=${ymd#*-}; m=${rest%%-*}; d=${rest#*-}
  m=${m#0}; d=${d#0}
  [ -z "$m" ] && m=0; [ -z "$d" ] && d=0
  if [ "$m" -lt 1 ] || [ "$m" -gt 12 ]; then echo 0; return; fi
  case "$m" in
    1|3|5|7|8|10|12) dim=31;;
    4|6|9|11) dim=30;;
    2) if [ "$(is_leap_year "$y")" -eq 1 ]; then dim=29; else dim=28; fi;;
    *) echo 0; return;;
  esac
  if [ "$d" -lt 1 ] || [ "$d" -gt "$dim" ]; then echo 0; else echo 1; fi
}
# yyyymmdd2iso: "YYYYMMDD" (8 digits, no separators -- the exact shape 'lparstat -u'
# and 'lscfg -vpl sysplanar0' both print for UAK expiry dates, ksh88-safe pattern
# matching, no substring-offset extension) -> "YYYY-MM-DD". Caller must still run
# valid_ymd on the result before trusting it as a real calendar date — this
# function only reshapes digits, exactly like d2j/j2d, never validates them.
function yyyymmdd2iso {
  typeset raw=$1 y md m d
  y=${raw%????}
  md=${raw#????}
  m=${md%??}
  d=${raw#??????}
  echo "${y}-${m}-${d}"
}
# sha256_of <file> -> lowercase hex digest on stdout, or empty + nonzero rc if no
# SHA256-capable tool was found on this box. Used by the --flrtvc-ksh invoke-mode
# runtime integrity check. Real AIX (verified live on lab-host-02/lab-host-03, 2026-07-12)
# ships `openssl` but NOT `mktemp`, and its `csum` does not support SHA256 ("SHA256
# is not a valid hash algorithm") — so `openssl dgst -sha256 -r` (the -r flag gives
# a version-independent "<hex> *<path>" format; different OpenSSL builds otherwise
# print "SHA256(...)=" vs "SHA2-256(...)=", confirmed different across the two lab
# boxes' OpenSSL versions) is the one portable path. Fails closed (empty output) if
# openssl is unavailable, rather than falling back to a weaker/no check.
function sha256_of {
  if command -v openssl >/dev/null 2>&1; then
    openssl dgst -sha256 -r "$1" 2>/dev/null | awk '{print $1}'
  fi
}

# decode_b64_to <payload> <file> — decode an embedded base64 data slot directly
# into the already-private FLRTVC scratch directory. OpenSSL is the same AIX-
# verified dependency used for SHA256; a decode failure is a hard refusal.
function decode_b64_to {
  typeset payload=$1 out=$2
  printf '%s\n' "$payload" | openssl base64 -d -out "$out" 2>/dev/null
}

# dir_untrusted <dir> — echoes a reason string if <dir> is attacker-writable (so a
# file inside it could be swapped out from under a metadata check), or nothing if it
# is safe. Used to close the pin-file TOCTOU (Codex review rounds 6+7): if the
# install dir and the pin's parent dir cannot be written by anyone but a trusted
# account, the pin file cannot be replaced between the moment we check its metadata
# and the moment we copy it.
#   * OWNERSHIP is always enforced: the directory must be owned by root, the trusted
#     system account 'bin' (AIX ships /, /usr, /tmp, ... owned by bin), or the
#     invoking user. An ATTACKER-OWNED directory is untrusted even if sticky —
#     because the directory OWNER can always rename/delete entries in it, sticky bit
#     or not (Codex round 7, item 2: sticky trust was too broad).
#   * A STICKY dir (e.g. AIX /tmp, drwxrwxrwt owned by bin) may be group/other
#     writable and still safe: the sticky bit means only a file's own owner may
#     rename or delete it, so a root/bin-owned pin there cannot be swapped by another
#     user. A NON-sticky dir must additionally be not group/other writable.
#   * A SYMLINKED directory entry is refused outright — we validate and use the entry
#     we see, never a link whose target could be re-pointed.
function dir_untrusted {
  typeset d ls mode typ owner gw ow sticky me
  d="$1"
  ls=$(LC_ALL=C ls -ld "$d" 2>/dev/null) || { echo "cannot stat $d"; return; }
  mode=$(printf '%s\n' "$ls" | awk '{print $1}')
  owner=$(printf '%s\n' "$ls" | awk '{print $3}')
  typ=$(printf '%s' "$mode" | cut -c1)
  gw=$(printf '%s' "$mode" | cut -c6)
  ow=$(printf '%s' "$mode" | cut -c9)
  sticky=$(printf '%s' "$mode" | cut -c10)
  me=$(id -un 2>/dev/null)
  if [ "$typ" = "l" ]; then
    echo "$d is a symlink — its target could be re-pointed after validation"; return
  fi
  # Ownership is enforced in ALL cases (sticky or not): only root, the trusted
  # system account bin, or the invoking user may own a trusted directory.
  if [ "$owner" != "root" ] && [ "$owner" != "bin" ] && [ "$owner" != "$me" ]; then
    echo "$d is owned by $owner (not root, bin, or $me) — its owner could replace entries in it"; return
  fi
  case "$sticky" in
    t|T) return ;;  # sticky + trusted owner: only a file's own owner can replace it
  esac
  # Non-sticky: anyone with group/other write can replace entries.
  if [ "$gw" = "w" ] || [ "$ow" = "w" ]; then
    echo "$d is group/other-writable ($mode) without the sticky bit"; return
  fi
}

# path_untrusted <physical-dir> — applies dir_untrusted, unchanged, to the leaf
# and every ancestor through /. A safe leaf alone is insufficient: the owner of
# a writable non-sticky ancestor can rename that leaf and replace it after the
# leaf check. The caller resolves symlinks with pwd -P before invoking this.
function path_untrusted {
  typeset p why parent
  p="$1"
  case "$p" in
    /*) ;;
    *) echo "$p is not an absolute physical path"; return ;;
  esac
  while :; do
    why=$(dir_untrusted "$p")
    if [ -n "$why" ]; then
      echo "$why"; return
    fi
    [ "$p" = "/" ] && return
    parent=${p%/*}
    [ -n "$parent" ] || parent=/
    [ "$parent" != "$p" ] || { echo "cannot walk ancestors of $p"; return; }
    p=$parent
  done
}
TODAY=${AIXRAY_TODAY:-$(date +%Y-%m-%d)}
# Validate the "today" value (AIXRAY_TODAY override or system date) as a real
# calendar date BEFORE it reaches any Julian arithmetic. Without this, a crafted
# AIXRAY_TODAY reaches d2j's $(( )) and ksh evaluates it (command injection on a
# root-run tool). valid_ymd anchors the shape to pure digits.
if [ "$(valid_ymd "$TODAY")" != 1 ]; then
  echo "aixray: AIXRAY_TODAY must be a real calendar date in YYYY-MM-DD format" >&2
  exit 2
fi
TODAY_J=$(d2j "$TODAY")
function errpt_cutoff { # <days-ago> -> MMDDhhmmYY for errpt -s
  j2d $(( TODAY_J - $1 )) | awk '{printf "%02d%02d0000%02d", $2, $3, $1 % 100}'
}

# ---- finding model: parallel arrays + per-category rollup ----------------------------
set -A F_CAT; set -A F_ID; set -A F_LBL; set -A F_ST; set -A F_SEV
set -A F_OBS; set -A F_MEAN; set -A F_FIX; set -A F_CTL
# F_RULES: parallel per-finding rule-engine detail — newline-joined "id|status|observed"
# lines for rule-engine (grouped STIG) findings, empty "" for every normal finding.
set -A F_RULES
# F_EXPOSURES: parallel per-finding FLRT exposure detail (apar_scan only) — newline-joined
# TSV rows "cve<TAB>hiper<TAB>fileset<TAB>installed<TAB>vulnerable_range<TAB>fixed_at_or_above
# <TAB>apar<TAB>ifix<TAB>bulletin<TAB>cvss<TAB>reboot", one row per CVE/APAR the box is
# exposed to per the supplied --flrtvc-report. Empty "" for every other finding.
set -A F_EXPOSURES
# F_EVIDENCE_COMMANDS: optional pipe-delimited source-command list for findings
# whose assessed/NA result is part of the structured lifecycle contract.
set -A F_EVIDENCE_COMMANDS
# Upgrade-planning facts captured on-box for Blueprint's stepped upgrade sequencing (current
# firmware/VIOS/model levels). The full OS x firmware x VIOS x HMC cross-product COMPATIBILITY
# MATRIX is FLRT-web-service output, not on-box data — never invented here; see
# upgrade_readiness in the JSON output for the honest boundary.
UC_FW=""; UC_FWFAM=""; UC_MODEL=""; UC_IOSL=""; UC_LATEST=""; UC_UPGTEXT=""
# CAP-1 structured facts. Values are promoted at the existing capture points below;
# no facts code invokes an additional on-box command.
FACT_FRAME_SERIAL=""; FACT_PARTITION_ID=""; FACT_PARTITION_NAME=""
FACT_OS_TL=""; FACT_OS_SP=""; FACT_OS_EOS=""; FACT_OS_EOSPS=""
FACT_HW_GEN=""; FACT_HW_EOS=""; FACT_FW_UAK_EXPIRY=""; FACT_AIX_UAK_EXPIRY=""
FACT_OS_VIOS_COMMANDS="ls /usr/ios/cli/ioscli"
FACT_FW_UAK_COMMANDS="lparstat -u"
FACT_AIX_UAK_COMMANDS="lparstat -u"
FACT_CPU_MODE=""; FACT_CPU_CAPPED=""; FACT_CPU_ENT=""; FACT_CPU_OVP=""
FACT_CPU_WEIGHT=""; FACT_CPU_SMT=""; FACT_CPU_PHYSC=""; FACT_CPU_ENTC=""; FACT_CPU_IDLE=""
FACT_CPU_LPI_READ=0; FACT_CPU_SAMPLE_READ=0
FACT_MEM_TOTAL=""; FACT_MEM_INUSE=""; FACT_MEM_AVAILABLE=""; FACT_MEM_PINNED=""
FACT_MEM_COMP=""; FACT_MEM_NUMPERM=""; FACT_MEM_PRIMARY_READ=0
FACT_PAGING_SPACES=""; FACT_PAGING_MAX=""; FACT_PAGING_ROOT=""; FACT_PAGING_DUP=""
FACT_PAGING_READ=0
FACT_STORAGE_FS_ROWS=""; FACT_STORAGE_WORST_FS_PCT=""; FACT_STORAGE_WORST_FS_MOUNT=""
FACT_STORAGE_WORST_VG_PCT=""; FACT_STORAGE_WORST_VG=""; FACT_STORAGE_MAX_INODE=""
FACT_STORAGE_FS_USED_UNREAD=0; FACT_STORAGE_FS_IUSED_UNREAD=0
FACT_STORAGE_DF_READ=0; FACT_STORAGE_VG_READ=0; FACT_OS_SOURCE_READ=0
FACT_RECOVERY_MKSYSB="unreadable"; FACT_RECOVERY_ALT=""; FACT_RECOVERY_MIRROR=""
FACT_RECOVERY_MIRROR_DISKS=""; FACT_RECOVERY_BOOTLIST=""; FACT_RECOVERY_NIM=""
FACT_RECOVERY_POWERHA=""; FACT_RECOVERY_POWERHA_APPLICABLE=""
NFIND=0
PASS=0; WARN=0; FAIL=0; NASSESSED=0
set -A CAT_ID  lifecycle patch storage performance errors resilience security config monitoring
set -A CAT_LBL "A. Lifecycle & support" "B. Patch & vulnerability currency" \
               "C. Storage & capacity" "D. Performance & sizing" "E. Errors & events" \
               "F. Availability & resilience" "G. Security & hardening" "H. Config hygiene" \
               "I. Monitoring & operational readiness"
set -A CP 0 0 0 0 0 0 0 0 0
set -A CW 0 0 0 0 0 0 0 0 0
set -A CF 0 0 0 0 0 0 0 0 0
# CN: per-category NOT_ASSESSED count — a check whose source data is missing/incomplete
# (believability review 2026-07-13, review-queue #62 finding #9: PASS asserted over an
# admittedly uncaptured observation, e.g. FC adapter counters "not reported" yet PASS).
# NOT_ASSESSED is deliberately its own status, excluded from PASS/WARN/FAIL/SCORE — a
# gap in what was measured must never silently read as either "clean" or "found a
# problem." See docs/aixray-spec-v2.md's NOT_ASSESSED precedent (the v2 contract
# pipeline); this is the same status literal, ported to the v1 engine's own model.
set -A CN 0 0 0 0 0 0 0 0 0

function add { # category id label status sev observed meaning fix [controls]
  typeset ci ADD_STATUS
  case "$1" in
    lifecycle) ci=0;; patch) ci=1;; storage) ci=2;; performance) ci=3;; errors) ci=4;;
    resilience) ci=5;; security) ci=6;; config) ci=7;; monitoring) ci=8;;
    *) echo "aixray: internal error: unknown category '$1'" >&2; exit 3;;
  esac
  ADD_STATUS=$4
  # The legacy FLRTVC path historically encoded incomplete runs as WARN with
  # "not assessed" prose. Normalize that state at the model boundary so an
  # uncompleted scan is machine-readable NOT_ASSESSED everywhere. A completed
  # clean scan over stale apar.csv remains WARN: it was evaluated, but its
  # currency is degraded rather than its completion being unknown.
  if [ "$2" = "apar_scan" ] && [ "$ADD_STATUS" = "WARN" ]; then
    case "$6" in
      "not assessed — underlying apar.csv was"*) ;;
      "not assessed —"*) ADD_STATUS=NOT_ASSESSED;;
    esac
  fi
  F_CAT[$NFIND]=$1; F_ID[$NFIND]=$2; F_LBL[$NFIND]=$3; F_ST[$NFIND]=$ADD_STATUS
  F_SEV[$NFIND]=$5; F_OBS[$NFIND]=$6; F_MEAN[$NFIND]=$7; F_FIX[$NFIND]=$8; F_CTL[$NFIND]=${9:-}
  F_RULES[$NFIND]=""
  F_EXPOSURES[$NFIND]=""
  F_EVIDENCE_COMMANDS[$NFIND]=""
  case "$ADD_STATUS" in
    PASS) PASS=$((PASS+1)); CP[$ci]=$(( ${CP[$ci]} + 1 ));;
    WARN) WARN=$((WARN+1)); CW[$ci]=$(( ${CW[$ci]} + 1 ));;
    FAIL) FAIL=$((FAIL+1)); CF[$ci]=$(( ${CF[$ci]} + 1 ));;
    NOT_ASSESSED) NASSESSED=$((NASSESSED+1)); CN[$ci]=$(( ${CN[$ci]} + 1 ));;
  esac
  NFIND=$((NFIND+1))
}

MYUID=$(aix id_u id -u)
function nr_warn { # category id label <what> <command> [controls] [status] [severity]
  typeset NR_STATUS NR_SEVERITY
  NR_STATUS=${7:-WARN}
  NR_SEVERITY=${8:-med}
  if [ "${MYUID:-0}" != "0" ]; then
    add "$1" "$2" "$3" "$NR_STATUS" "$NR_SEVERITY" "n/a" "Could not read $4 (needs root)." \
        "re-run aixray as root, or inspect '$5' manually." "${6:-}"
  else
    add "$1" "$2" "$3" "$NR_STATUS" "$NR_SEVERITY" "n/a" "Could not read $4 (unexpected as root)." \
        "inspect '$5' manually." "${6:-}"
  fi
}

HOST=$(aix hostname hostname)
if [ -n "${AIXRAY_TODAY:-}" ]; then NOW="$TODAY"; else NOW=$(date '+%Y-%m-%d %H:%M %Z'); fi

# ---- role detection: VIOS vs plain AIX LPAR ------------------------------------------
# A VIOS is AIX underneath, so essentially every check below runs unchanged; a handful
# key off the ROLE. The canonical VIOS marker is the ioscli binary — PJ's real scripts
# (Java.auto.ksh, FLRT.report) branch on exactly '[ -f /usr/ios/cli/ioscli ]', NOT on
# ioslevel (which reads empty on a plain LPAR). Detect ONCE here; reuse $IS_VIOS / $ROLE
# throughout (presentation, lifecycle weighting, and the VIOS-role depth in checks_vios).
VIOS_MARKER=$(aix ls_ioscli ls /usr/ios/cli/ioscli); VIOS_MARKER_RC=$?
VIOS_MARKER_ROWS=$(printf '%s\n' "$VIOS_MARKER" | awk '$0=="/usr/ios/cli/ioscli"{n++} NF{all++} END{print n+0 ":" all+0}')
VIOS_MARKER_MATCH=${VIOS_MARKER_ROWS%%:*}
VIOS_MARKER_NONEMPTY=${VIOS_MARKER_ROWS#*:}
if [ "$VIOS_MARKER_RC" -eq 0 ] && [ "$VIOS_MARKER_MATCH" -eq 1 ] && [ "$VIOS_MARKER_NONEMPTY" -eq 1 ]; then
  IS_VIOS=1; ROLE=vios
elif [ "$VIOS_MARKER_RC" -eq 2 ] && [ "$VIOS_MARKER_NONEMPTY" -eq 0 ]; then
  IS_VIOS=0; ROLE=aix; UC_IOSL=NOT_APPLICABLE
else
  # A failed command or rc=0 garbage is not positive proof of a plain AIX role.
  # Keep the scanner operational, but make vios_level explicitly unreadable.
  IS_VIOS=0; ROLE=unknown
fi

# ============================ CHECKS (read-only) ======================================

# ---- A. Lifecycle & support ----------------------------------------------------------
OSLEVEL=$(aix oslevel_s oslevel -s); OSLEVEL_RC=$?
if [ "$OSLEVEL_RC" -eq 0 ] && [ -n "$OSLEVEL" ]; then FACT_OS_SOURCE_READ=1; fi
if [ "$OSLEVEL_RC" -eq 0 ]; then
  OSLEVEL=$(printf '%s\n' "$OSLEVEL" | awk -F- '
    NF==4 && $1 ~ /^[0-9][0-9][0-9][0-9]$/ && $2 ~ /^[0-9][0-9]$/ &&
      $3 ~ /^[0-9][0-9]$/ && $4 ~ /^[0-9][0-9][0-9][0-9]$/ {print; exit}')
else
  OSLEVEL=""
fi
REL=$(printf '%s' "$OSLEVEL" | awk -F- '{print $1}')
TLLEVEL=$(printf '%s' "$OSLEVEL" | awk -F- 'NF>=2{print $1"-"$2}')
FACT_OS_TL=$(printf '%s' "$OSLEVEL" | awk -F- 'NF>=2{print $2}')
FACT_OS_SP=$(printf '%s' "$OSLEVEL" | awk -F- 'NF>=3{print $3}')
BWEEK=$(printf '%s' "$OSLEVEL" | awk -F- 'NF>=4{print $4}')
PRTCONF=$(aix prtconf prtconf); PRTCONF_RC=$?
if [ "$PRTCONF_RC" -ne 0 ]; then PRTCONF=""; fi
FACT_FRAME_SERIAL=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^Machine Serial Number:/{print $2; exit}')
PARTITION_ID_RAW=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^LPAR Info:/{split($2,a,/[ \t]+/); if(a[1] ~ /^[0-9]+$/) print a[1]+0; exit}')
if valid_json_number "$PARTITION_ID_RAW"; then FACT_PARTITION_ID="$PARTITION_ID_RAW"; fi
FACT_PARTITION_NAME=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^LPAR Info:/{s=$2; sub(/^[^ \t]+[ \t]+/,"",s); if(s!=$2 && s!="") print s; exit}')

function checks_lifecycle {
  typeset EOS EOSJ LATEST CURTL LTL BEHIND EOSPS ST MEAN FW MODEL TM ROW GEN HWEOS IOSL RC
  typeset UPTEXT PATHSUF FWFAM FWMT FWROW CURFAM CURN BOXN SEV FIX OBS LSADPH PHYSADP
  typeset RELEASE_OUT RELEASE_NEEDS_UPGRADE TLFIX EOSPS_OUT EOSPS_NEAR

  RELEASE_OUT=0
  RELEASE_NEEDS_UPGRADE=0
  UC_UPGTEXT=""

  # upgrade-path fix text appended to os_level / os_tl_sp when they are not PASS
  UPTEXT=$(printf '%s\n' "$UPGRADE_PATH" | awk -F'|' -v r="$REL" '$1==r{print $2; exit}')
  PATHSUF=""
  [ -n "$UPTEXT" ] && PATHSUF=" Path: $UPTEXT."
  # On a VIOS the underlying AIX release is a SECONDARY signal: a VIOS admin patches with
  # 'updateios'/viosupgrade, not update_all/smitty. Say so wherever we hand out AIX-level
  # remediation, and point back to vios_level as the primary currency signal.
  [ "$IS_VIOS" -eq 1 ] && PATHSUF="$PATHSUF On a VIOS this AIX level is secondary — patch the VIOS with 'updateios' (or viosupgrade), not update_all; the VIOS level (vios_level, above) is the primary currency signal."

  # os_level — is this AIX release still supported at all?
  if [ -z "$OSLEVEL" ]; then
    add lifecycle os_level "AIX release support" WARN med "unknown" \
        "Could not read 'oslevel -s' — cannot judge the support window." "verify the OS level manually." "ffiec:II.C.11"
  else
    EOS=$(printf '%s\n' "$EOS_OS" | awk -F'|' -v r="$REL" '$1==r{print $2; exit}')
    if [ "$EOS" = "SUPPORTED" ]; then FACT_OS_EOS=supported; else FACT_OS_EOS="$EOS"; fi
    if [ -z "$EOS" ]; then
      add lifecycle os_level "AIX release support" WARN med "$OSLEVEL" \
          "Release $REL is not in the bundled reference data (vintage $DATA_VINTAGE)." \
          "check IBM's AIX support lifecycle page for this release.$PATHSUF" "ffiec:II.C.11"
    elif [ "$EOS" = "SUPPORTED" ]; then
      add lifecycle os_level "AIX release support" PASS low "$OSLEVEL — no announced end of support" \
          "This AIX release is in active support and still receives security fixes." "n/a" "ffiec:II.C.11"
    else
      EOSJ=$(d2j "$EOS")
      if [ "$TODAY_J" -gt "$EOSJ" ]; then
        RELEASE_OUT=1
        RELEASE_NEEDS_UPGRADE=1
        add lifecycle os_level "AIX release support" FAIL high "$OSLEVEL — support ended $EOS" \
            "This AIX release is past standard support — without an IBM Software Support Service Extension, it no longer receives IBM security fixes, so newly disclosed CVEs remain open here." \
            "plan the upgrade to a supported release now; consider an IBM Software Support Service Extension only as a bridge.$PATHSUF" "ffiec:II.C.11"
      elif [ $(( EOSJ - TODAY_J )) -le 365 ]; then
        RELEASE_NEEDS_UPGRADE=1
        add lifecycle os_level "AIX release support" WARN high "$OSLEVEL — support ends $EOS" \
            "IBM standard support for this release ends within a year — after that, security fixes require a Software Support Service Extension." \
            "plan and schedule the upgrade to a supported release before $EOS.$PATHSUF" "ffiec:II.C.11"
      else
        add lifecycle os_level "AIX release support" PASS low "$OSLEVEL — supported until $EOS" \
            "This AIX release is in active support." "n/a" "ffiec:II.C.11"
      fi
    fi
  fi
  if [ "$RELEASE_NEEDS_UPGRADE" -eq 1 ] && [ -n "$UPTEXT" ]; then
    UC_UPGTEXT="$UPTEXT"
  fi

  # os_tl_sp — is this Technology Level current and still receiving fixes?
  if [ -n "$TLLEVEL" ]; then
    LATEST=$(printf '%s\n' "$LATEST_TL" | awk -F'|' -v r="$REL" '$1==r{print $2; exit}')
    EOSPS=$(printf '%s\n' "$TL_SUPPORT" | awk -F'|' -v t="$TLLEVEL" '$1==t{print $2; exit}')
    UC_LATEST="$LATEST"
    if [ "$EOSPS" = "SUPPORTED" ]; then FACT_OS_EOSPS=supported; else FACT_OS_EOSPS="$EOSPS"; fi
    EOSPS_OUT=0
    EOSPS_NEAR=0
    if [ -z "$LATEST" ]; then
      ST=NOT_ASSESSED
      MEAN="Technology Level currency was not assessed because release $REL has no latest-TL entry in the bundled lifecycle data (vintage $DATA_VINTAGE)."
    else
      ST=PASS
      MEAN="This Technology Level is current for its release."
    fi
    if [ -n "$LATEST" ] && [ "$LATEST" != "$TLLEVEL" ]; then
      CURTL=${TLLEVEL#*-}; CURTL=${CURTL#0}
      LTL=${LATEST#*-}; LTL=${LTL#0}
      BEHIND=$(( LTL - CURTL ))
      if [ "$BEHIND" -ge 2 ]; then
        ST=FAIL; MEAN="This box is $BEHIND Technology Levels behind — years of fixed defects and CVEs it does not have."
      elif [ "$BEHIND" -ge 1 ]; then
        ST=WARN; MEAN="A newer Technology Level ($LATEST) is available — known fixed defects and CVEs this box does not have."
      fi
    fi
    if [ -n "$EOSPS" ] && [ "$EOSPS" != "SUPPORTED" ]; then
      if [ "$TODAY_J" -gt "$(d2j "$EOSPS")" ]; then
        EOSPS_OUT=1
        ST=FAIL
        if [ "$RELEASE_OUT" -eq 1 ]; then
          MEAN="Service Pack support for $TLLEVEL ended $EOSPS — the AIX release itself left standard support on $EOS, so this TL is not receiving fixes under standard support."
        else
          MEAN="Service Pack support for $TLLEVEL ended $EOSPS — this TL no longer receives fixes even though the release is supported."
        fi
      elif [ "$ST" = "PASS" ] && [ $(( $(d2j "$EOSPS") - TODAY_J )) -le 183 ]; then
        EOSPS_NEAR=1
        ST=WARN; MEAN="Fix support for $TLLEVEL ends $EOSPS — plan the TL update."
      fi
    elif [ -z "$EOSPS" ]; then
      if [ "$ST" = "PASS" ]; then
        ST=NOT_ASSESSED
        MEAN="Fix-window currency was not assessed because $TLLEVEL has no SP-support entry in the bundled lifecycle data (vintage $DATA_VINTAGE)."
      elif [ "$ST" = "NOT_ASSESSED" ]; then
        MEAN="Technology Level currency and fix-window support were not assessed because release $REL has no latest-TL or SP-support entry in the bundled lifecycle data (vintage $DATA_VINTAGE)."
      else
        MEAN="$MEAN Fix-window support was not assessed because $TLLEVEL has no SP-support entry in the bundled lifecycle data."
      fi
    fi
    if [ -n "$LATEST" ] && [ "$LATEST" = "$TLLEVEL" ]; then
      OBS="$TLLEVEL (latest TL"
    else
      OBS="$TLLEVEL (latest: ${LATEST:-unknown}"
    fi
    if [ "$EOSPS_OUT" -eq 1 ]; then
      if [ "$RELEASE_OUT" -eq 1 ]; then
        OBS="$OBS; release out of SP support $EOSPS"
      else
        OBS="$OBS; TL fix support ended $EOSPS"
      fi
    elif [ "$EOSPS_NEAR" -eq 1 ]; then
      OBS="$OBS; fix support ends $EOSPS"
    elif [ -z "$EOSPS" ]; then
      OBS="$OBS; fix-support window unavailable in bundled data"
    fi
    OBS="$OBS)"
    if [ -z "$UC_UPGTEXT" ] && [ -n "$UPTEXT" ] &&
       [ -n "$LATEST" ] && [ "$LATEST" != "$TLLEVEL" ]; then
      UC_UPGTEXT="$UPTEXT"
    fi
    case "$ST" in
      PASS) add lifecycle os_tl_sp "Technology Level currency" PASS low "$OBS" "$MEAN" "n/a" "ffiec:II.C.11";;
      WARN)
        if [ -n "$LATEST" ] && [ "$LATEST" = "$TLLEVEL" ]; then
          if [ "$RELEASE_NEEDS_UPGRADE" -eq 1 ]; then
            TLFIX="move to a supported AIX release before fix support ends — $TLLEVEL is already the latest TL for its release, so there is no newer in-release TL to install.$PATHSUF"
          else
            TLFIX="$TLLEVEL is already the latest TL in the bundled data; check IBM's current TL support page and plan the next supported target rather than scheduling a nonexistent TL upgrade."
          fi
        else
          TLFIX="schedule an update to the latest TL/SP in a maintenance window (smitty update_all from a downloaded lpp_source).$PATHSUF"
        fi
        add lifecycle os_tl_sp "Technology Level currency" WARN high "$OBS" "$MEAN" "$TLFIX" "ffiec:II.C.11"
        ;;
      FAIL)
        if [ -n "$LATEST" ] && [ "$LATEST" = "$TLLEVEL" ]; then
          if [ "$RELEASE_OUT" -eq 1 ]; then
            TLFIX="move to a supported AIX release now — $TLLEVEL is already the latest TL for its release, so there is no newer in-release TL to install.$PATHSUF"
          else
            TLFIX="$TLLEVEL is already the latest TL in the bundled data; check IBM's current TL support page and plan the next supported target rather than scheduling a nonexistent TL upgrade."
          fi
        else
          TLFIX="plan a TL upgrade now — the gap only gets more expensive to close.$PATHSUF"
        fi
        add lifecycle os_tl_sp "Technology Level currency" FAIL high "$OBS" "$MEAN" "$TLFIX" "ffiec:II.C.11"
        ;;
      NOT_ASSESSED)
        add lifecycle os_tl_sp "Technology Level currency" NOT_ASSESSED med "$OBS" "$MEAN" \
            "check IBM's current AIX lifecycle and TL support pages, refresh the bundled reference data, and rerun AIXray." "ffiec:II.C.11"
        ;;
    esac
  fi

  # Capture firmware ONCE here. Its finding is emitted after the hardware-EOS
  # and UAK measurements below, so the grade uses the same typed facts rather
  # than a second parse or a family-only proxy.
  FW=$(aix lsmcode_c lsmcode -c); RC=$?
  if [ "$RC" -eq 0 ]; then
    FW=$(printf '%s\n' "$FW" | awk 'NR==1{v=$NF; sub(/^[(]/,"",v); sub(/[)]$/,"",v); print v}')
  else
    FW=""
  fi
  if [ -n "$FW" ] && ! printf '%s\n' "$FW" | awk '
      NR==1 && $0 ~ /^[A-Za-z0-9][A-Za-z0-9._-]*$/ && $0 ~ /[0-9]/ {ok=1}
      END{exit ok?0:1}'; then
    FW=""
  fi
  if [ -z "$FW" ]; then
    FW=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^Platform Firmware level:/{print $2; exit}')
    if [ -n "$FW" ] && ! printf '%s\n' "$FW" | awk '
        NR==1 && $0 ~ /^[A-Za-z0-9][A-Za-z0-9._-]*$/ && $0 ~ /[0-9]/ {ok=1}
        END{exit ok?0:1}'; then
      FW=""
    fi
  fi
  FWFAM=$(printf '%s\n' "$PRTCONF" | awk '/^Firmware Version:/{n=index($0,"FW"); if(n>0){s=substr($0,n+2); sub(/[^0-9].*$/,"",s); if(s!="")print "FW" s; exit}}')
  FWMT=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^System Model:/{m=$2; sub(/^IBM,/,"",m); sub(/-.*/,"",m); print m; exit}')
  FWROW=$(printf '%s\n' "$FW_MIN" | awk -F'|' -v mt="$FWMT" '$1==mt{print; exit}')
  CURFAM=$(printf '%s' "$FWROW" | awk -F'|' '{print $2}')
  CURN=${CURFAM#FW}; BOXN=${FWFAM#FW}
  case "$CURN" in ''|*[!0-9]*) CURN="";; esac
  case "$BOXN" in ''|*[!0-9]*) BOXN="";; esac
  UC_FW="$FW"; UC_FWFAM="$FWFAM"

  # Hardware-generation lookup, computed here (ahead of the hw_gen check below, which
  # re-derives its own ROW/HWEOS for the lifecycle finding) so aix_uak_expiry can gate its
  # own "genuinely inapplicable" fallback on it. UAKGEN is intentionally coarse: only the
  # generations
  # this codebase can currently NAME as pre-Power10 (POWER7/8/9) count as confirmed-not-
  # applicable; a POWER10+ box or any unrecognized machine type falls through as unknown.
  # Only trust a generation classification derived from a 'prtconf' capture that itself
  # succeeded (Codex primary review, M5, round 3, finding #3 residual: a failed prtconf
  # invocation must never let plausible-looking leftover model text drive a confident
  # hardware-inapplicability verdict downstream, same failed-source-to-verdict class as
  # the UAK/hd5 fixes above). UAKGEN stays empty (falls through as unknown) whenever
  # PRTCONF_RC is nonzero, regardless of what $PRTCONF happens to contain.
  UAKGEN=""
  if [ "$PRTCONF_RC" -eq 0 ]; then
    UAKGEN_TM=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^System Model/{m=$2; sub(/^IBM,/,"",m); print m; exit}')
    UAKGEN=$(printf '%s\n' "$HW_GEN" | awk -F'|' -v tm="$UAKGEN_TM" 'NF>=3 {p=$1; gsub(/\./,"\\.",p); gsub(/\*/,".*",p); if (tm ~ "^"p"$") {print $2; exit}}')
  fi

  # firmware_uak_expiry / aix_uak_expiry — Update Access Key expiry (spec v2 docs/aixray-spec-v2.md
  # Sec 5/Sec 15 M5, cap-firmware). Ranked the single most-missed check in the sourced research's
  # own "5 hidden-risk checks" list: an expired UAK silently blocks applying any firmware/AIX level
  # RELEASED AFTER the expiry date — discovered only at the worst moment (an emergency update).
  # Sourced two ways, NEITHER requiring a new HMC credential surface (spec Sec 5: the HMC-observable
  # 'lslic' path is captured only when an HMC session is already part of the engagement — not
  # assumed here):
  #   - 'lparstat -u': "FW Update Access Key Expiration (YYYYMMDD)" + "AIX Update Access Key
  #     Expiration (YYYYMMDD)" — live-verified on a real POWER9 PowerVS lab box (lab-host-02, 7.2):
  #     the FW field reads a real date, the AIX field reads "-" (AIX UAK is Power10+ only, per
  #     spec) — correctly rendered NOT_APPLICABLE below, never PASS or WARN for an
  #     inapplicable fact.
  #   - 'lscfg -vpl sysplanar0': "Update Access Key Exp Date.." (variable dot-padding) — fallback/
  #     cross-check for the firmware UAK specifically, consulted only if lparstat's own field is
  #     unreadable. Same real box confirms an identical date from both commands.
  LPU=$(aix lparstat_u lparstat -u); LPU_RC=$?
  FACT_FW_UAK_COMMANDS="lparstat -u"
  FWUAKRAW=""; FWUAKROWS=0; FWUAK_SRC_OK=0; FWUAK_STATE=NOT_ASSESSED
  if [ "$LPU_RC" -eq 0 ]; then
    FWUAKPARSED=$(printf '%s\n' "$LPU" | awk -F: '/^FW Update Access Key Expiration/{n++; v=$2; gsub(/[ \t]/,"",v)} END{printf "%d:%s\n",n+0,v}')
    FWUAKROWS=${FWUAKPARSED%%:*}
    FWUAKRAW=${FWUAKPARSED#*:}
    [ "$FWUAKROWS" -eq 1 ] || FWUAKRAW=""
    case "$FWUAKRAW" in
      [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) FWUAK_SRC_OK=1;;
    esac
  fi
  # Fall back to lscfg whenever lparstat's own field does not (successfully) look like a
  # real 8-digit date -- not just when it's empty or exactly "-". A malformed/unexpected
  # value (a changed output shape, stray text) previously skipped the fallback silently,
  # so the result below could claim "could not read from lparstat -u or lscfg" while lscfg
  # was never actually consulted (Codex primary review, M5, round 1). Only a source that
  # itself SUCCEEDED (rc=0) AND produced a value that already looks like a valid date
  # short-circuits the fallback -- neither lparstat's rc nor lscfg's rc is ignored here
  # (Codex primary review, M5, round 2, finding #3: a nonzero-rc command's stdout, even
  # if it happens to contain plausible-looking text, must never be trusted as a source).
  if [ "$FWUAK_SRC_OK" -ne 1 ]; then
    FACT_FW_UAK_COMMANDS="$FACT_FW_UAK_COMMANDS|lscfg -vpl sysplanar0"
    LSCFG_SYSPLANAR=$(aix lscfg_sysplanar lscfg -vpl sysplanar0); LSCFG_RC=$?
    if [ "$LSCFG_RC" -eq 0 ]; then
      FWUAKRAW=$(printf '%s\n' "$LSCFG_SYSPLANAR" | awk -F'\\.\\.+' '/Update Access Key Exp Date/{v=$NF; gsub(/[ \t]/,"",v); print v; exit}')
      case "$FWUAKRAW" in
        [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) FWUAK_SRC_OK=1;;
        *) FWUAK_SRC_OK=0;;
      esac
    else
      FWUAK_SRC_OK=0
    fi
  fi
  FWUAKISO=""
  [ "$FWUAK_SRC_OK" -eq 1 ] && FWUAKISO=$(yyyymmdd2iso "$FWUAKRAW")
  if [ -n "$FWUAKISO" ] && [ "$(valid_ymd "$FWUAKISO")" -eq 1 ]; then
    FACT_FW_UAK_EXPIRY="$FWUAKISO"
    FWUAKJ=$(d2j "$FWUAKISO")
    if [ "$TODAY_J" -gt "$FWUAKJ" ]; then
      FWUAK_STATE=EXPIRED
      add lifecycle firmware_uak_expiry "Firmware Update Access Key" FAIL high "expired $FWUAKISO" \
          "The firmware Update Access Key expired $FWUAKISO — IBM firmware whose release date is after this expiry date cannot be applied with this key until it is renewed (firmware released BEFORE the expiry date remains eligible; IBM also documents narrow HIPER exceptions). This can block an emergency firmware update at the worst possible moment." \
          "renew the Update Access Key (IBM My Entitled Systems, or via the HMC) before the next firmware update." "ffiec:II.C.11"
    elif [ "$TODAY_J" -ge "$(( FWUAKJ - 30 ))" ]; then
      FWUAK_STATE=EXPIRING
      # Near-expiry, not yet expired -- IBM's own UAK guidance frames the 30 days before
      # expiry as the renewal window; a PASS on the day before expiry would be technically
      # true and practically useless (Codex primary review, M5, round 2, finding #5).
      add lifecycle firmware_uak_expiry "Firmware Update Access Key" WARN med "expires $FWUAKISO (within 30 days)" \
          "The firmware Update Access Key expires within 30 days ($FWUAKISO) — IBM's own guidance is to renew a UAK in the 30 days before it lapses, to avoid it expiring before the next firmware update is needed." \
          "renew the Update Access Key (IBM My Entitled Systems, or via the HMC) now, before it expires." "ffiec:II.C.11"
    else
      FWUAK_STATE=VALID
      add lifecycle firmware_uak_expiry "Firmware Update Access Key" PASS low "valid through $FWUAKISO" \
          "The firmware Update Access Key is current — firmware released before its expiry date can be applied." "n/a"
    fi
  else
    case "$UAKGEN" in
      POWER7)
        # Firmware UAKs are a POWER8-and-later entitlement (IBM: "Management of POWER8
        # and Later Update Access Keys") -- a POWER7 box genuinely does not carry this
        # field; never a WARN for a fact this hardware does not have in the first place
        # (Codex primary review, M5, round 2, finding #7).
        FACT_FW_UAK_COMMANDS="$FACT_FW_UAK_COMMANDS|prtconf"
        FACT_FW_UAK_EXPIRY=NOT_APPLICABLE; FWUAK_STATE=NOT_APPLICABLE
        add lifecycle firmware_uak_expiry "Firmware Update Access Key" NOT_APPLICABLE low "n/a (POWER8+ only)" \
            "The firmware Update Access Key is a POWER8-and-later entitlement; this is POWER7 hardware, which does not carry one." "n/a"
        ;;
      *)
        FWUAK_STATE=NOT_ASSESSED
        add lifecycle firmware_uak_expiry "Firmware Update Access Key" NOT_ASSESSED low "unreadable" \
            "Could not read the firmware Update Access Key expiry from 'lparstat -u' or 'lscfg -vpl sysplanar0' (or the command that would have supplied it did not itself succeed)." \
            "check 'lparstat -u' (FW Update Access Key Expiration) or the HMC directly."
        ;;
    esac
  fi
  F_EVIDENCE_COMMANDS[$((NFIND-1))]="$FACT_FW_UAK_COMMANDS"

  AIXUAKRAW=""; AIXUAKROWS=0; AIXUAK_STATE=NOT_ASSESSED
  if [ "$LPU_RC" -eq 0 ]; then
    # Parse exactly one real field row. The label must start at column 1 -- a
    # coincidental label substring inside a diagnostic/garbage line is not AIX output --
    # and duplicate rows are contradictory evidence, even when the first one looks valid.
    # Emit count and value together so the anchoring rule has one mutation-testable source.
    AIXUAKPARSED=$(printf '%s\n' "$LPU" | awk -F: '/^AIX Update Access Key Expiration/{n++; v=$2; gsub(/[ \t]/,"",v)} END{printf "%d:%s\n",n+0,v}')
    AIXUAKROWS=${AIXUAKPARSED%%:*}
    AIXUAKRAW=${AIXUAKPARSED#*:}
    [ "$AIXUAKROWS" -eq 1 ] || AIXUAKRAW=""
  fi
  AIXUAKISO=""
  case "$AIXUAKRAW" in
    [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) AIXUAKISO=$(yyyymmdd2iso "$AIXUAKRAW");;
  esac
  if [ -n "$AIXUAKISO" ] && [ "$(valid_ymd "$AIXUAKISO")" -eq 1 ]; then
    FACT_AIX_UAK_EXPIRY="$AIXUAKISO"
    AIXUAKJ=$(d2j "$AIXUAKISO")
    if [ "$TODAY_J" -gt "$AIXUAKJ" ]; then
      AIXUAK_STATE=EXPIRED
      add lifecycle aix_uak_expiry "AIX Update Access Key" FAIL high "expired $AIXUAKISO" \
          "The AIX Update Access Key (Power10+) expired $AIXUAKISO — this gates installing/running AIX levels released after expiry, and can block LPM to a destination requiring a newer entitlement." \
          "renew the AIX Update Access Key before the next AIX-level install or an LPM move to a newer-entitled destination." "ffiec:II.C.11"
    elif [ "$TODAY_J" -ge "$(( AIXUAKJ - 30 ))" ]; then
      AIXUAK_STATE=EXPIRING
      add lifecycle aix_uak_expiry "AIX Update Access Key" WARN med "expires $AIXUAKISO (within 30 days)" \
          "The AIX Update Access Key (Power10+) expires within 30 days ($AIXUAKISO) — renew it before it lapses." \
          "renew the AIX Update Access Key (IBM My Entitled Systems, or via the HMC) now, before it expires." "ffiec:II.C.11"
    else
      AIXUAK_STATE=VALID
      add lifecycle aix_uak_expiry "AIX Update Access Key" PASS low "valid through $AIXUAKISO" \
          "The AIX Update Access Key (Power10+) is current." "n/a"
    fi
  else
    if [ "$LPU_RC" -ne 0 ]; then
      # 'lparstat -u' itself did not succeed -- this is genuinely unreadable, never a
      # hardware-inapplicability fact regardless of generation (Codex primary review, M5,
      # round 2, finding #3: never trust the ABSENCE of a value from a command invocation
      # that itself did not succeed any more than a value FROM one).
      AIXUAK_STATE=NOT_ASSESSED
      add lifecycle aix_uak_expiry "AIX Update Access Key" NOT_ASSESSED low "unreadable" \
          "Could not read the AIX Update Access Key expiry: 'lparstat -u' itself did not succeed (rc=$LPU_RC)." \
          "check 'lparstat -u' (AIX Update Access Key Expiration) as root, or the HMC directly."
    else
      # LPU_RC=0 alone is not positive evidence the field was actually reported --
      # an empty or truncated capture defaults (or is defaulted, in the fixture-replay
      # convention this codebase's own aix()/aixv() wrappers document: a missing .rc
      # file reads as rc=0) to the SAME rc=0 an honest, complete 'lparstat -u' run
      # returns. Never treat "we saw rc=0" as "the command told us this field is
      # absent" -- require POSITIVE structural evidence, not merely that the field's
      # LABEL substring appears somewhere in the text (Codex primary review, 2026-07-14,
      # HIGH: a capture truncated to "AIX Update Access Key Expiration (YYYYMMDD):" with
      # no value at all still matched a bare label-substring check and reached PASS).
      # $AIXUAKRAW (already parsed above, same source line, via the SAME awk field-split
      # used for the real-date path) must equal EXACTLY the literal "-" this codebase's
      # own live verification (lab-host-02/lab-host-03) documents as the genuine reading on
      # confirmed pre-Power10 hardware -- any other value (empty, partial, garbled) is
      # never treated as confirmed inapplicability, regardless of hardware generation.
      if [ "$AIXUAKROWS" -ne 1 ] || [ "$AIXUAKRAW" != "-" ]; then
        AIXUAK_STATE=NOT_ASSESSED
        add lifecycle aix_uak_expiry "AIX Update Access Key" NOT_ASSESSED low "not assessed — capture empty or unrecognized" \
            "'lparstat -u' returned rc=0, but its output does not contain exactly one genuine, line-anchored 'AIX Update Access Key Expiration' reading (found $AIXUAKROWS matching row(s), with neither one unambiguous parseable date nor the documented literal '-' placeholder) -- this looks like an empty, truncated, duplicated, contradictory, prefixed-token, or otherwise unreadable capture, not a genuine reading, and must never be assumed inapplicable regardless of hardware generation." \
            "check 'lparstat -u' (AIX Update Access Key Expiration) as root, or the HMC directly."
      else
        # The literal '-' establishes the field reading; prtconf establishes
        # whether that reading is genuinely pre-Power10 inapplicability or an
        # ambiguous Power10+/unknown result. Preserve both provenance edges.
        FACT_AIX_UAK_COMMANDS="$FACT_AIX_UAK_COMMANDS|prtconf"
        case "$UAKGEN" in
          POWER7|POWER8|POWER9)
            # Genuinely inapplicable on hardware we can NAME as pre-Power10, the
            # command that reported the field's absence succeeded, AND the field's
            # own label was actually present in the captured output -- never a WARN
            # for a fact this hardware does not carry in the first place (live-
            # verified: lab-host-02/lab-host-03, both POWER9, both read "-" here).
            FACT_AIX_UAK_EXPIRY=NOT_APPLICABLE; AIXUAK_STATE=NOT_APPLICABLE
            add lifecycle aix_uak_expiry "AIX Update Access Key" NOT_APPLICABLE low "n/a (Power10+ only)" \
                "The AIX Update Access Key is a Power10+ entitlement; this hardware/level does not report one." "n/a"
            ;;
          *)
            # Power10+, or an unrecognized/future machine type: the field WAS read cleanly
            # (the literal "-" this codebase treats as the genuine pre-Power10 placeholder),
            # but on this hardware generation that reading is AMBIGUOUS, not proof of
            # inapplicability — the only live verification behind the PASS-n/a case above
            # was on real POWER9 hardware (Codex primary review, M5, round 1: the "healthy"
            # fixture is a real POWER10 9105-22A reporting "-", which the prior code
            # silently, and wrongly, treated as inapplicable). This is a structural
            # assessment gap, not a detected problem or a capture failure — never launder
            # it into a false-clean PASS on hardware that plausibly DOES carry this
            # entitlement, but also never render it as WARN (a real, actionable finding);
            # NOT_ASSESSED is the honest status (reconciliation, 2026-07-14, aligning with
            # the first-class NOT_ASSESSED architecture — semantic change, flagged for
            # John/PJ post-hoc confirmation).
            AIXUAK_STATE=NOT_ASSESSED
            add lifecycle aix_uak_expiry "AIX Update Access Key" NOT_ASSESSED low "ambiguous — Power10+/unrecognized hardware" \
                "'lparstat -u' returned the pre-Power10 placeholder reading, but this hardware is Power10+ (or an unrecognized machine type), where that reading cannot be assumed to mean inapplicable — this tool cannot determine applicability from this reading on this hardware generation." \
                "check 'lparstat -u' (AIX Update Access Key Expiration) as root, or the HMC directly."
            ;;
        esac
      fi
    fi
  fi
  F_EVIDENCE_COMMANDS[$((NFIND-1))]="$FACT_AIX_UAK_COMMANDS"

  # hw_gen — is the hardware generation still supported?
  MODEL=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/^System Model/{print $2; exit}')
  TM=${MODEL#IBM,}
  UC_MODEL="$TM"
  # fully-virtual LPAR detection: a physical I/O adapter is one whose lsdev
  # description names a physical bus ("PCI"/"PCIe"). Virtual adapters ("Virtual …")
  # and pseudo-devices (hdcrypt, pkcs11) do not — so no PCI line (or no adapters
  # at all) means this LPAR has no physical hardware of its own to maintain.
  LSADPH=$(aix lsdev_adapter lsdev -c adapter)
  PHYSADP=$(printf '%s\n' "$LSADPH" | awk 'NF && /PCI/{n++} END{print n+0}')
  if [ -z "$TM" ]; then
    add lifecycle hw_gen "Hardware generation" WARN low "unknown" \
        "Could not read the machine type/model from prtconf." "check 'prtconf | grep Model' or the HMC." "ffiec:II.C.11"
  else
    ROW=$(printf '%s\n' "$HW_GEN" | awk -F'|' -v tm="$TM" 'NF>=3 {p=$1; gsub(/\./,"\\.",p); gsub(/\*/,".*",p); if (tm ~ "^"p"$") {print; exit}}')
    GEN=$(printf '%s' "$ROW" | awk -F'|' '{print $2}')
    HWEOS=$(printf '%s' "$ROW" | awk -F'|' '{print $3}')
    FACT_HW_GEN="$GEN"
    if [ "$HWEOS" = "SUPPORTED" ]; then FACT_HW_EOS=supported; else FACT_HW_EOS="$HWEOS"; fi
    if [ -z "$ROW" ]; then
      add lifecycle hw_gen "Hardware generation" PASS low "$TM" \
          "Machine type not in the bundled reference data (vintage $DATA_VINTAGE)." \
          "verify this machine's support status on IBM's hardware lifecycle pages." "ffiec:II.C.11"
    elif [ "$HWEOS" = "SUPPORTED" ]; then
      add lifecycle hw_gen "Hardware generation" PASS low "$TM ($GEN)" \
          "This hardware generation is in active support." "n/a" "ffiec:II.C.11"
    elif [ "$TODAY_J" -gt "$(d2j "$HWEOS")" ]; then
      if [ "${PHYSADP:-0}" -eq 0 ]; then
        add lifecycle hw_gen "Hardware generation" WARN med "$TM ($GEN) — hardware support ended $HWEOS (fully-virtual LPAR)" \
            "This hardware generation is past IBM support, but this LPAR has no physical I/O adapters — the hardware is the host provider's to maintain (PowerVS or your VIOS estate). Confirm whose problem this is." \
            "confirm who owns the hardware (IBM on PowerVS; your team on-prem), then plan or request a host refresh to current-generation $CURRENT_POWER_GEN hardware; the host change is outside this LPAR." "ffiec:II.C.11"
      else
        add lifecycle hw_gen "Hardware generation" FAIL high "$TM ($GEN) — hardware support ended $HWEOS" \
            "Hardware support has ended — a part failure now has no IBM fix path. (On IBM Power Virtual Server the hardware is IBM's responsibility — confirm which applies.)" \
            "plan a refresh to current-generation $CURRENT_POWER_GEN hardware, or use third-party maintenance only as a documented bridge." "ffiec:II.C.11"
      fi
    else
      add lifecycle hw_gen "Hardware generation" PASS low "$TM ($GEN) — supported until $HWEOS" \
          "This hardware generation is in active support." "n/a" "ffiec:II.C.11"
    fi
  fi

  # firmware — one graded verdict over the already-promoted level, hardware
  # lifecycle, and firmware-UAK state. A conclusive adverse signal survives an
  # unrelated unreadable input; otherwise missing required evidence is honestly
  # NOT_ASSESSED, never a default PASS.
  FWST=PASS; FWSEV=low; FWREASONS=""; FWGAP=0
  if [ -z "$FW" ]; then
    FWGAP=1
    FWREASONS="firmware level not assessed"
  fi

  if [ -z "$CURN" ] || [ -z "$BOXN" ]; then
    FWGAP=1
    FWREASONS="$FWREASONS${FWREASONS:+; }firmware family/current-family baseline not assessed"
  elif [ "$BOXN" -lt "$CURN" ]; then
    FWST=WARN; FWSEV=med
    FWREASONS="$FWREASONS${FWREASONS:+; }family $FWFAM behind $CURFAM"
  elif [ "$BOXN" -eq "$CURN" ]; then
    FWREASONS="$FWREASONS${FWREASONS:+; }family $FWFAM current"
  else
    FWGAP=1
    FWREASONS="$FWREASONS${FWREASONS:+; }family $FWFAM newer than bundled $CURFAM"
  fi

  if [ "$FACT_HW_EOS" = supported ]; then
    FWREASONS="$FWREASONS${FWREASONS:+; }hardware supported"
  elif [ -n "$FACT_HW_EOS" ] && [ "$(valid_ymd "$FACT_HW_EOS")" -eq 1 ] &&
       [ "$TODAY_J" -gt "$(d2j "$FACT_HW_EOS")" ]; then
    FWREASONS="$FWREASONS${FWREASONS:+; }hardware support ended $FACT_HW_EOS"
    [ "$FWST" != FAIL ] && FWST=WARN
    FWSEV=high
  elif [ -n "$FACT_HW_EOS" ] && [ "$(valid_ymd "$FACT_HW_EOS")" -eq 1 ]; then
    FWREASONS="$FWREASONS${FWREASONS:+; }hardware supported until $FACT_HW_EOS"
  else
    FWGAP=1
    FWREASONS="$FWREASONS${FWREASONS:+; }hardware lifecycle not assessed"
  fi

  case "$FWUAK_STATE" in
    EXPIRED)
      FWST=FAIL; FWSEV=high
      FWREASONS="$FWREASONS${FWREASONS:+; }firmware UAK expired $FACT_FW_UAK_EXPIRY"
      ;;
    EXPIRING)
      [ "$FWST" != FAIL ] && FWST=WARN
      [ "$FWSEV" = low ] && FWSEV=med
      FWREASONS="$FWREASONS${FWREASONS:+; }firmware UAK expires $FACT_FW_UAK_EXPIRY within 30 days"
      ;;
    VALID)
      FWREASONS="$FWREASONS${FWREASONS:+; }firmware UAK valid through $FACT_FW_UAK_EXPIRY"
      ;;
    NOT_APPLICABLE)
      FWREASONS="$FWREASONS${FWREASONS:+; }firmware UAK not applicable to $UAKGEN"
      ;;
    *)
      FWGAP=1
      FWREASONS="$FWREASONS${FWREASONS:+; }firmware UAK not assessed"
      ;;
  esac
  [ "$FWST" = PASS ] && [ "$FWGAP" -eq 1 ] && FWST=NOT_ASSESSED
  FWOBS="${FW:-unreadable} — $FWREASONS"
  case "$FWST" in
    PASS)
      FWMEAN="The firmware family, hardware support window, and Update Access Key are current in the bundled lifecycle data."
      FWFIX="n/a"
      ;;
    WARN)
      FWMEAN="The measured firmware lifecycle evidence has one or more currency constraints: $FWREASONS."
      FWFIX="review IBM FLRT/Fix Central for machine type ${FWMT:-unknown}, renew a near-expiry UAK, and schedule the supported firmware/hardware path named above."
      ;;
    FAIL)
      FWMEAN="The firmware Update Access Key is expired, so firmware released after $FACT_FW_UAK_EXPIRY cannot be applied until entitlement is renewed; other measured lifecycle constraints are shown above."
      FWFIX="renew the firmware Update Access Key first, then use IBM FLRT/Fix Central and the HMC to move to the supported firmware family."
      ;;
    *)
      FWMEAN="Firmware currency could not be fully assessed from the captured level, hardware lifecycle, and Update Access Key evidence."
      FWFIX="check 'lsmcode -c', 'prtconf', and 'lparstat -u' (plus 'lscfg -vpl sysplanar0' when needed), then assess the exact level in IBM FLRT/Fix Central."
      ;;
  esac
  add lifecycle firmware "System firmware currency" "$FWST" "$FWSEV" "$FWOBS" "$FWMEAN" "$FWFIX" "ffiec:II.C.11"
  F_EVIDENCE_COMMANDS[$((NFIND-1))]="lsmcode -c|prtconf|$FACT_FW_UAK_COMMANDS"

  # vios_level — the PRIMARY lifecycle currency signal on a VIOS. Keyed off the top-level
  # IS_VIOS (ioscli presence — the canonical VIOS marker PJ's Java.auto.ksh / FLRT.report
  # branch on, not ioslevel, which reads empty on a plain LPAR). Evaluated against the
  # embedded EOS_VIOS table. The latest row still marked SUPPORTED is the
  # explicit currency target; an older line can be in support yet still behind.
  case "$ROLE" in
    vios)
      FACT_OS_VIOS_COMMANDS="$FACT_OS_VIOS_COMMANDS|ioslevel"
      IOSL_RAW=$(aix ioslevel ioslevel); RC=$?
      IOSL=""
      if [ "$RC" -eq 0 ]; then
        IOSL=$(printf '%s\n' "$IOSL_RAW" | awk '
          $0 ~ /^[0-9]+[.][0-9]+[.][0-9]+[.][0-9]+$/ {n++; v=$0}
          NF && $0 !~ /^[0-9]+[.][0-9]+[.][0-9]+[.][0-9]+$/ {bad=1}
          END{if(n==1 && !bad) print v}')
      fi
      if [ -n "$IOSL" ]; then
        UC_IOSL="$IOSL"
        IOSPFX=$(printf '%s' "$IOSL" | awk -F. '{print $1"."$2}')
        VEOS=$(printf '%s\n' "$EOS_VIOS" | awk -F'|' -v p="$IOSPFX" '$1==p{print $2; exit}')
        VLATEST=$(printf '%s\n' "$EOS_VIOS" | awk -F'|' '$2=="SUPPORTED"{v=$1} END{print v}')
        if [ -z "$VEOS" ] || [ -z "$VLATEST" ]; then
          add lifecycle vios_level "VIOS level currency" NOT_ASSESSED low "VIOS $IOSL — lifecycle baseline not assessed" \
              "The VIOS level is readable, but its support/current-line row is absent from the bundled reference data (vintage $DATA_VINTAGE)." \
              "check IBM's VIOS support lifecycle and refresh the bundled EOS_VIOS data before grading this level." "ffiec:II.C.11"
        elif [ "$VEOS" != SUPPORTED ] && [ "$TODAY_J" -gt "$(d2j "$VEOS")" ]; then
          add lifecycle vios_level "VIOS level currency" FAIL high "VIOS $IOSL — support ended $VEOS; latest supported line: $VLATEST" \
              "This VIOS line no longer receives fixes — and every client LPAR depends on this box." \
              "plan the VIOS upgrade to $VLATEST (viosupgrade, or 'updateios' within a stream); update the standby VIOS first and verify failover before the partner." "ffiec:II.C.11"
        elif [ "$IOSPFX" = "$VLATEST" ] && [ "$VEOS" = SUPPORTED ]; then
          add lifecycle vios_level "VIOS level currency" PASS low "VIOS $IOSL — latest supported line: $VLATEST" \
              "This VIOS is on the latest supported line in the bundled lifecycle data." \
              "keep current within the stream via 'updateios'." "ffiec:II.C.11"
        elif [ "$VEOS" != SUPPORTED ] && [ $(( $(d2j "$VEOS") - TODAY_J )) -le 365 ]; then
          add lifecycle vios_level "VIOS level currency" WARN high "VIOS $IOSL — support ends $VEOS; latest supported line: $VLATEST" \
              "This VIOS is behind the latest supported line and its current line leaves support within a year." \
              "schedule the VIOS upgrade to $VLATEST before $VEOS; update the standby VIOS first." "ffiec:II.C.11"
        else
          add lifecycle vios_level "VIOS level currency" WARN med "VIOS $IOSL — behind latest supported line: $VLATEST" \
              "This VIOS line is not the latest supported line in the bundled lifecycle data." \
              "plan the VIOS move to $VLATEST with viosupgrade/updateios and a one-VIOS-at-a-time failover sequence." "ffiec:II.C.11"
        fi
      else
        add lifecycle vios_level "VIOS level currency" NOT_ASSESSED low "not assessed — 'ioslevel' rc=$RC or output malformed" \
            "The VIOS marker was measured, but 'ioslevel' did not yield exactly one valid four-component VIOS level." \
            "run 'ioslevel' from oem_setup_env/root and verify the returned level manually." "ffiec:II.C.11"
      fi
      F_EVIDENCE_COMMANDS[$((NFIND-1))]="$FACT_OS_VIOS_COMMANDS"
      ;;
    aix)
      add lifecycle vios_level "VIOS level currency" NOT_APPLICABLE low "role=aix — /usr/ios/cli/ioscli absent (ls rc=$VIOS_MARKER_RC); ioslevel not applicable" \
          "The VIOS marker command positively proved this is a plain AIX LPAR, so a VIOS level does not apply." "n/a" "ffiec:II.C.11"
      F_EVIDENCE_COMMANDS[$((NFIND-1))]="$FACT_OS_VIOS_COMMANDS"
      ;;
    *)
      add lifecycle vios_level "VIOS level currency" NOT_ASSESSED low "role not assessed — VIOS marker rc=$VIOS_MARKER_RC, matching rows=$VIOS_MARKER_MATCH, nonempty rows=$VIOS_MARKER_NONEMPTY" \
          "The VIOS marker capture failed or returned an unrecognized shape, so absence cannot prove this is a non-VIOS LPAR." \
          "check 'ls /usr/ios/cli/ioscli' and then run 'ioslevel' only if the marker exists." "ffiec:II.C.11"
      F_EVIDENCE_COMMANDS[$((NFIND-1))]="$FACT_OS_VIOS_COMMANDS"
      ;;
  esac
}

# ---- B. Patch & vulnerability currency ------------------------------------------------
function checks_patch {
  typeset T W BJ AGE AGEMO TOTALFS BROKEN BLIST EOUT RC N LABELS NAPP MISS APAR PREF CVE TITLE IOUT LSSL SSHV SSLV
  typeset JAVALP HAS7 HAS8 V7 V8 RESULT NEXP APPLIC NAMES DVJ DVAGE

  # patch_age — how old is the installed build?
  if [ -n "$BWEEK" ]; then
    T=${BWEEK%??}; T=${T#0}; W=${BWEEK#??}; W=${W#0}
    BJ=$(( $(d2j "$((2000+T))-01-01") + (W-1)*7 ))
    AGE=$(( TODAY_J - BJ )); AGEMO=$(( AGE / 30 ))
    if [ "$AGE" -gt 730 ]; then
      add patch patch_age "Installed build age" FAIL high "built week $BWEEK (~$AGEMO months ago)" \
          "More than two years of security fixes are missing from this box." \
          "update to the current TL/SP; then hold a regular (at least annual) patch cadence." "ffiec:II.C.10"
    elif [ "$AGE" -gt 365 ]; then
      add patch patch_age "Installed build age" WARN high "built week $BWEEK (~$AGEMO months ago)" \
          "Over a year of security fixes is missing — a real exposure window." \
          "schedule the TL/SP update in the next maintenance window." "ffiec:II.C.10"
    else
      add patch patch_age "Installed build age" PASS low "built week $BWEEK (~$AGEMO months ago)" \
          "The installed build is reasonably current." "n/a" "ffiec:II.C.10"
    fi
  else
    add patch patch_age "Installed build age" WARN med "unknown" \
        "Could not derive the build week from 'oslevel -s'." "verify patch currency manually." "ffiec:II.C.10"
  fi

  # fileset_state — broken filesets block future updates. PJ parses filesets from
  # 'lslpp -qcL' (colon-delimited, one line per fileset) rather than columnar
  # 'lslpp -L', whose Description column wraps long entries onto continuation lines
  # (see any ICU4C/Java row) and makes positional parsing fragile. Colon fields:
  # 1=package 2=fileset 3=level 6=state (C=Committed, A=Applied, B=BROKEN, O=Obsolete).
  # A colon inside the later Description field (8) cannot shift fields 1-6, so -F: is
  # stable. Grounded live on lab-host-01 (lslpp -qcL bos.rte -> field 6 = state).
  LSLPPQ=$(aixv_confirmed lslpp_qcL lslpp -qcL); LSLPPQ_RC=$?   # colon form drives the fileset-state parse; the
  # exit status is kept because the FLRTVC invoke path below must refuse to run against a FAILED
  # inventory capture — an empty/garbled -l input reads to flrtvc.ksh as "nothing installed", which
  # an exit-0 clean report would then convert into a false PASS (Codex review round 5, item 2).
  if [ -z "$LSLPPQ" ]; then
    add patch fileset_state "Fileset consistency" WARN med "n/a" \
        "Could not read 'lslpp -qcL'." "inspect fileset state manually."
  else
    # A genuine lslpp -qcL row has package+fileset names, a numeric-leading level,
    # and one of AIX's real one-letter install states. Merely having six colon fields
    # and a digit in field 3 lets fabricated x:y:1:a:b:c tokens clear the floor.
    TOTALFS=$(printf '%s\n' "$LSLPPQ" | awk -F: 'NF>=6 && $1!="" && $2!="" && $3 ~ /^[0-9]/ && $6 ~ /^[ABCO]$/ {n++} END{print n+0}')
    BROKEN=$(printf '%s\n' "$LSLPPQ" | awk -F: 'NF>=6 && $1!="" && $2!="" && $3 ~ /^[0-9]/ && $6 ~ /^[ABCO]$/ && $6=="B" {n++} END{print n+0}')
    if [ "$BROKEN" -gt 0 ]; then
      BLIST=$(printf '%s\n' "$LSLPPQ" | awk -F: 'NF>=6 && $1!="" && $2!="" && $3 ~ /^[0-9]/ && $6 ~ /^[ABCO]$/ && $6=="B" {print $2}' | awk 'NR<=3{printf "%s%s",(NR>1?", ":""),$0} END{if(NR>3)printf " +%d more",NR-3}')
      add patch fileset_state "Fileset consistency" FAIL med "$BROKEN broken of $TOTALFS ($BLIST)" \
          "Broken filesets block future updates and can misbehave now — find this before it blocks an emergency fix." \
          "repair with 'installp -C' / reinstall the affected filesets, then re-check 'lppchk -v'."
    else
      add patch fileset_state "Fileset consistency" PASS low "$TOTALFS filesets, 0 broken" \
          "All installed filesets are in a consistent state." "n/a"
    fi
  fi

  # lppchk_consistency — a DIFFERENT, complementary signal from fileset_state above:
  # fileset_state reads lslpp's own recorded STATE column (catches a fileset already marked
  # BROKEN); lppchk -v independently verifies REQUISITE/dependency consistency across the whole
  # installed set (catches a fileset whose prerequisites are missing/mismatched even though its
  # own STATE looks fine) — docs/aixray-spec-v2.md Sec 5 cap-filesets row, IBM-sourced
  # (upgrade-readiness-checks.md Sec 4). Escalates to 'lppchk -m3 -v' (Sec 5's own escalation
  # rule) for full detail on any inconsistency — never asserts a specific IBM error-message
  # shape (real failure text was not observable on the read-only, currently-clean lab boxes);
  # bounded raw output IS the finding, not a re-parsed summary. Live-verified clean (rc=0, no
  # output — the documented "no output" success shape) on lab-host-02 (7.2) and lab-host-03 (7.1),
  # 2026-07-13. Uses 'aixv' (not the shared 'aix()') so a real stderr diagnostic is actually
  # captured instead of silently discarded (Codex primary review, M5, HIGH finding #2: this
  # call spelled '2>&1' but 'aix()' had already redirected the real command's stderr to
  # /dev/null internally before that '2>&1' ever ran, so an rc=0 stderr-only diagnostic was
  # laundered into a false clean PASS -- see 'aixv's own header comment).
  LPPCHKOUT=$(aixv_confirmed lppchk_v lppchk -v); LPPCHK_RC=$?
  # rc 127 means "command/fixture absent" (this codebase's established convention, e.g. the
  # 'ifixes' check above) -- a MISSING result must degrade to WARN "not assessed," never a
  # confident FAIL. Caught live during this check's own test-suite run (round 1 self-review):
  # every fixture set that has no 'lppchk_v.out' fixture file initially reported a false FAIL
  # "inconsistent (rc=127)" instead of the honest "could not run" -- exactly the NOT_ASSESSED-
  # laundered-into-a-verdict defect class this repo's own discipline exists to catch before
  # shipping, not after. Uses 'aixv_confirmed' (not the plain 'aixv') so an rc=0 that was only
  # EVER assumed (no <key>.rc file recorded at all) can never be treated identically to a
  # GENUINELY confirmed rc=0 -- see 'aixv_confirmed's own header comment (Codex confirming
  # review, 2026-07-14, HIGH: 'rc=0 + empty output' is genuinely ambiguous between a real
  # clean result and a wholesale capture-session failure, and no purely-textual corroboration
  # -- however many independent-looking signals -- can rule out a failure mode that empties
  # ALL of them identically; only a genuine, distinctly-recorded completion signal closes
  # this, on the CAPTURE THIS CHECK ITSELF DEPENDS ON, not merely a related one).
  if [ "$LPPCHK_RC" -eq 127 ]; then
    add patch lppchk_consistency "Fileset dependency consistency (lppchk -v)" WARN low "unreadable" \
        "Could not run 'lppchk -v' on this box." "check 'lppchk -v' manually."
  elif [ "$LPPCHK_RC" -eq 0 ] && [ -z "$LPPCHKOUT" ]; then
    # rc=0 here is a GENUINELY CONFIRMED reading (aixv_confirmed's 126 sentinel, meaning "no
    # completion signal was ever recorded," would already have failed this exact equality
    # test) -- "rc=0, no output" is lppchk -v's own documented clean-success shape, and this
    # is now a real completion signal for THIS capture, not an assumption. A second,
    # independent invocation ('lppchk -m3 -v', the documented escalation), ALSO required to
    # be genuinely confirmed rc=0 with empty output (not merely assumed), plus the box's own
    # fileset inventory clearing a small floor, corroborate further -- raising the bar over
    # trusting a single confirmed reading alone, though not a mathematical completeness proof
    # (disclosed honestly, same as this codebase's own FLRT apar_scan floor gate discloses
    # its own floor is "not a completeness proof").
    LPPCHKM3=$(aixv_confirmed lppchk_m3v lppchk -m3 -v); LPPCHKM3_RC=$?
    if [ "$LPPCHKM3_RC" -eq 0 ] && [ -z "$LPPCHKM3" ] && [ "${LSLPPQ_RC:-1}" -eq 0 ] && [ "${TOTALFS:-0}" -ge 5 ]; then
      add patch lppchk_consistency "Fileset dependency consistency (lppchk -v)" PASS low "consistent" \
          "'lppchk -v' AND the independent 'lppchk -m3 -v' escalation both returned a genuinely confirmed clean result (rc=0, stdout and stderr both empty), and the fileset inventory itself ($TOTALFS filesets) is a real, populated AIX system, not an empty/truncated capture." "n/a"
    else
      add patch lppchk_consistency "Fileset dependency consistency (lppchk -v)" WARN low "not assessed — capture empty or unconfirmed" \
          "'lppchk -v' reported no output, which is its documented clean-success shape -- but this cannot be credited as a clean scan without independent corroboration: the 'lppchk -m3 -v' cross-check returned rc=$LPPCHKM3_RC${LPPCHKM3:+ with output}, and/or the fileset inventory ('lslpp -qcL', confirmed rc=${LSLPPQ_RC:-unknown}, ${TOTALFS:-0} structurally valid row(s)) is empty, failed, token-shaped, unconfirmed, or implausibly small. Neither signal alone proves 'lppchk -v' itself actually completed; disagreement or an unconfirmed/implausible inventory means this cannot be assumed a genuine clean result." \
          "run 'lppchk -v 2>&1' and 'lppchk -m3 -v 2>&1' manually as root, and confirm 'lslpp -qcL' returns the full fileset inventory, before treating this as a clean scan."
    fi
  else
    # Never a confident FAIL here: real lppchk -v inconsistency output has never been
    # observed on the currently-clean lab boxes, so nonzero rc WITH output (or rc=0 with
    # unexpected output, now that 'aixv' actually captures stderr) cannot be reliably told
    # apart from a permission/ODM/usage error by shape alone (Codex primary review, M5). A
    # genuine inconsistency and a plain execution failure both route to the SAME WARN
    # (medium, since it may well be real) rather than gambling a confident FAIL on an
    # unverified pattern-match, or a confident PASS on any output at all — per the sourced
    # rule (upgrade-readiness-checks.md Sec 4), ANY 'lppchk -v' output, stdout or stderr,
    # is adverse; PASS above requires rc=0 AND genuinely empty output, nothing looser.
    # Escalates to 'lppchk -m3 -v' when there IS output, for a human to actually look at.
    if [ -n "$LPPCHKOUT" ]; then
      # Escalation rc is tracked (not just its output) so a FAILED '-m3 -v' escalation
      # never silently substitutes for the primary '-v' evidence -- fall back to the
      # primary output when the escalation itself didn't succeed (Codex primary review,
      # M5, round 3, low-severity finding: evidence provenance must stay honest even
      # though the status here is already safely WARN either way). Also uses 'aixv' so the
      # escalation's own stderr diagnostic (if any) is captured in the detail text too.
      LPPCHKDETAIL=$(aixv lppchk_m3v lppchk -m3 -v); LPPCHKDETAIL_RC=$?
      [ "$LPPCHKDETAIL_RC" -eq 0 ] || LPPCHKDETAIL=""
      LPPCHKBOUNDED=$(printf '%s\n' "${LPPCHKDETAIL:-$LPPCHKOUT}" | awk 'NR<=5{print} END{if(NR>5)printf "… (%d more line(s))\n",NR-5}' | tr '\n' ' ')
      # rc=$LPPCHK_RC here may be either 0 (unexpected output on an otherwise-successful
      # run) or nonzero -- never assert "exited nonzero" unconditionally in the wording
      # (Codex primary review, M5, round 3, low-severity finding).
      add patch lppchk_consistency "Fileset dependency consistency (lppchk -v)" WARN med "rc=$LPPCHK_RC, output: $LPPCHKBOUNDED" \
          "'lppchk -v' produced output (stdout and/or stderr, both captured) that doesn't match its documented clean-success shape (rc=0, no output) — rc=$LPPCHK_RC here. This MAY be a real fileset requisite/dependency inconsistency (which can block 'update_all'/'install_all_updates' the same way a BROKEN STATE does), or it may be a permission/ODM/usage error, or unexpected output on an otherwise-successful run; this tool has never observed a confirmed real-inconsistency sample and cannot reliably tell these apart from output shape alone, so this is never asserted as a confident FAIL." \
          "run 'lppchk -v 2>&1' and 'lppchk -m3 -v 2>&1' manually as root to see the actual result before treating this as a real inconsistency."
    else
      add patch lppchk_consistency "Fileset dependency consistency (lppchk -v)" WARN med "ambiguous (rc=$LPPCHK_RC, no captured output)" \
          "'lppchk -v' exited nonzero with no output captured on either stdout or stderr — this looks like a bare execution problem (permissions, ODM access) rather than a real diagnostic, but cannot be asserted as a confident FAIL from this alone." \
          "run 'lppchk -v 2>&1' manually as root to see the actual result."
    fi
  fi

  # upgrade_headroom_preview — framing note, docs/aixray-spec-v2.md Sec 5 cap-runtime row: the
  # IBM-sourced AUTHORITATIVE "will this update fit" answer is 'smitty update_all' with "PREVIEW
  # only? = yes" (or 'installp -p'), which reports an "Estimated system resource requirements"
  # table (Needed vs Free PER FILESYSTEM) against the SPECIFIC lpp_source being applied. AIXray
  # cannot compute this itself — it requires a real, chosen lpp_source/update target this general
  # health scan does not have, and running installp even in preview mode against one is an
  # update-time action, not a general scan action. This finding is deliberately always the same
  # informational framing (never a fabricated PASS/FAIL on a number this tool cannot compute) —
  # kept schema-distinct from the general 'fs_*' steady-state df -g findings elsewhere in this
  # report (Sec 5's own explicit rule: the two are NOT conflated), which remain the general-health
  # signal, not a substitute for the real preview-mode check before an actual update.
  # NOT_ASSESSED, never PASS or WARN: nothing was actually assessed here (Codex primary
  # review, M5, BLOCKER) -- a PASS on "not run this scan" reads to a CIO as verified-clean
  # evidence for the authoritative pre-update space check, when in fact this tool could not
  # and did not check it. This is an unconditional structural preview -- it runs identically
  # on every scan regardless of system health -- so WARN (a real, actionable per-system
  # finding) is also the wrong status: an unconditional WARN makes the honest INCOMPLETE
  # tier (a scan with a real assessment gap but zero real findings) UNREACHABLE, since every
  # scan would always carry at least this one WARN (reconciliation, 2026-07-14, restoring
  # INCOMPLETE reachability -- semantic change, flagged for John/PJ post-hoc confirmation).
  # NOT_ASSESSED is the honest status: a standing reminder of an assessment gap, not a
  # detected problem, aligning with the first-class NOT_ASSESSED architecture.
  add patch upgrade_headroom_preview "Update-time space preview (informational)" NOT_ASSESSED low "not run this scan (requires a specific lpp_source)" \
      "This scan's own filesystem-fullness findings are a general steady-state signal, not the authoritative 'will the next update fit' answer. IBM's own preview-mode check against your ACTUAL lpp_source is the one that matters before an update — this tool has not run it and cannot run it as a general scan." \
      "before the next update, run 'smitty update_all' with 'PREVIEW only? = yes' (or 'installp -p -a -d <lpp_source> all|<filesets>') and review its 'Estimated system resource requirements' table (Needed vs Free per filesystem) — this is read-only/non-committing and is the real pre-flight check, distinct from this tool's own general df -g findings."

  # ifixes — interim fixes are temporary by design
  EOUT=$(aix emgr_l emgr -l); RC=$?
  # rc 127 means "absent" only as root: emgr is mode 500, so an unprivileged
  # PATH search can't even resolve it and also reports 127.
  if [ "$RC" -eq 127 ] && [ "${MYUID:-0}" = "0" ]; then
    : # no emgr — nothing to report
  elif [ "$RC" -ne 0 ]; then
    nr_warn patch ifixes "Interim fixes (ifixes)" "the interim fix inventory" "emgr -l"
  else
    N=$(printf '%s\n' "$EOUT" | awk '$1 ~ /^[0-9]+$/ {n++} END{print n+0}')
    if [ "$N" -eq 0 ]; then
      add patch ifixes "Interim fixes (ifixes)" PASS low "none installed" \
          "No interim fixes — updates will not be blocked by leftover efixes." "n/a"
    else
      LABELS=$(printf '%s\n' "$EOUT" | awk '$1 ~ /^[0-9]+$/ {print $3}' | awk '{printf "%s%s",(NR>1?", ":""),$0}')
      add patch ifixes "Interim fixes (ifixes)" WARN low "$N installed ($LABELS)" \
          "Interim fixes are temporary — an unremoved ifix blocks the next TL/SP update." \
          "verify each is superseded by your current SP; remove superseded ones with 'emgr -r'."
    fi
  fi

  # sec_apars — tracked security APARs (bundled set, vintage $DATA_VINTAGE).
  # PJ's FLRT flow credits an APAR two ways: shipped in a fileset/SP (instfix -ik),
  # OR delivered as an interim fix. An ifix-delivered APAR is NOT in the installp fix
  # database, so instfix -ik alone FALSE-FAILS a box that applied the emergency ifix
  # but not yet the SP. emgr ifixes carry their APAR number in the LABEL (e.g.
  # IJ55968mAa) and ABSTRACT ("Fix for APAR IJ55968"); emgr -lv3 exposes both. We
  # extract that APAR set and count an APAR as addressed if an installed ifix covers it.
  # (Grounded on the real emgr LABEL/ABSTRACT shape; lab-host-01 has no efixes -> empty set.)
  EMGRV3=$(aix emgr_lv3 emgr -lv3); EMGRV3_RC=$?   # exit status kept: both the bundled-APAR
  # credit path and FLRTVC invoke path below must refuse this evidence when capture FAILED.
  # A silently-empty -e input reads to flrtvc.ksh as "no ifixes installed", so every
  # ifix-covered CVE would be reported as a false exposure
  # (Codex review round 5, item 3). A genuinely efix-free box is rc=0 with EMPTY stdout (verified
  # live on both lab boxes: emgr prints "There is no efix data on this system." on STDERR, rc 0).
  IFIX_APARS=""
  if [ "$EMGRV3_RC" -eq 0 ]; then
    # Credit only APARs from complete, successfully-captured STABLE efix
    # sections.  A BROKEN (or otherwise non-STABLE) efix is not evidence that
    # its APAR is installed, and stdout from a failed capture is not evidence
    # at all.  Buffer LABEL/ABSTRACT candidates until STATE is known because
    # emgr prints LABEL before STATE in each section.
    IFIX_APARS=$(printf '%s\n' "$EMGRV3" | awk '
      function scan(s){
        while(match(s, /[A-Z][A-Z][0-9][0-9][0-9][0-9][0-9]/)){
          candidates=candidates substr(s,RSTART,7) "\n"
          s=substr(s,RSTART+RLENGTH)
        }
      }
      function flush(){
        if(state=="STABLE") printf "%s",candidates
        candidates=""; state=""; in_efix=0
      }
      /^[ \t]*EFIX ID:/ { flush(); in_efix=1; next }
      in_efix && /^[ \t]*LABEL:/    { scan($0); next }
      in_efix && /^[ \t]*ABSTRACT:/ { scan($0); next }
      in_efix && /^[ \t]*STATE:/ {
        state=$0
        sub(/^[^:]*:[ \t]*/,"",state)
        sub(/[ \t\r]+$/,"",state)
      }
      END{flush()}
    ' | sort -u | tr '\n' ' ')
  fi
  NAPP=0; MISS=""; VIA_IFIX=""
  # ksh88-safe: a `cmd | while` runs the loop in a subshell on /bin/sh, discarding
  # NAPP/MISS. Feed SEC_APARS via a here-doc so the loop runs in THIS shell.
  while IFS='|' read APAR PREF CVE TITLE; do
    [ -z "$APAR" ] && continue
    [ "$PREF" = "$TLLEVEL" ] || continue
    NAPP=$((NAPP+1))
    IOUT=$(aix "instfix_ik_$APAR" instfix -ik "$APAR")
    # instfix says "All filesets for <APAR> were found." only when fully installed.
    # "Not all filesets for <APAR> were found." (and "no data ... in the fix
    # database.") both mean NOT installed — a bare "were found" match false-PASSes
    # on the "Not all" wording, so require "All filesets" AND reject "Not all".
    if printf '%s' "$IOUT" | grep -q "All filesets" && ! printf '%s' "$IOUT" | grep -q "Not all"; then
      :  # installed via fileset / Service Pack
    else
      case " $IFIX_APARS " in
        *" $APAR "*) VIA_IFIX="$VIA_IFIX $APAR" ;;   # addressed by an installed ifix
        *)           MISS="$MISS $APAR ($CVE)" ;;
      esac
    fi
  done <<SEC_APARS_EOF
$SEC_APARS
SEC_APARS_EOF
  if [ "$NAPP" -eq 0 ]; then
    add patch sec_apars "Tracked security APARs" NOT_ASSESSED high \
        "not assessed — no bundled security APAR rows apply to $TLLEVEL" \
        "Absence of a bundled row provides no evidence that the system has no CVE exposure." \
        "run current IBM flrtvc.ksh with a current apar.csv and pass the report via --flrtvc-report; review IBM PSIRT." \
        "ffiec:II.C.10"
  elif [ "$EMGRV3_RC" -ne 0 ]; then
    add patch sec_apars "Tracked security APARs" NOT_ASSESSED high \
        "not assessed — emgr -lv3 capture failed (rc=$EMGRV3_RC)" \
        "AIXray could not verify interim-fix coverage because emgr -lv3 did not complete successfully; its stdout was not used as evidence." \
        "rerun 'emgr -lv3' successfully, then rerun AIXray before treating tracked APAR coverage as complete." \
        "ffiec:II.C.10"
  elif [ -n "$MISS" ]; then
    add patch sec_apars "Tracked security APARs" FAIL high "missing:$MISS" \
        "This box is exposed to published, fixed vulnerabilities — the fix exists and is not applied." \
        "apply the listed APARs (ifix or SP) from IBM Fix Central / PSIRT bulletin." "ffiec:II.C.10"
  else
    IFIXNOTE=""
    [ -n "$VIA_IFIX" ] && IFIXNOTE=" ($(printf '%s' "$VIA_IFIX" | wc -w | awk '{print $1}') via installed ifix:$VIA_IFIX)"
    add patch sec_apars "Tracked security APARs" PASS high "$NAPP of $NAPP tracked APARs present$IFIXNOTE (data vintage $DATA_VINTAGE)" \
        "All tracked security APARs for this level are installed — by Service Pack or by an installed interim fix." "n/a" "ffiec:II.C.10"
  fi

  # ssl_ssh — crypto stack filesets. Colon-delimited 'lslpp -qcL' (field 2=fileset,
  # 3=level) parses cleanly where the columnar Description column can wrap.
  LSSL=$(aix lslpp_ssh_ssl lslpp -qcL openssh.base.server openssl.base)
  SSHV=$(printf '%s\n' "$LSSL" | awk -F: '$2=="openssh.base.server"{print $3; exit}')
  SSLV=$(printf '%s\n' "$LSSL" | awk -F: '$2=="openssl.base"{print $3; exit}')
  if [ -z "$SSHV$SSLV" ]; then
    add patch ssl_ssh "OpenSSH / OpenSSL levels" WARN med "not readable" \
        "Could not read openssh.base.server / openssl.base levels." "inspect 'lslpp -L openssh.base.server openssl.base'."
  else
    case "${SSLV:-unknown}" in
      3.*) add patch ssl_ssh "OpenSSH / OpenSSL levels" PASS low "openssh ${SSHV:-n/a}, openssl $SSLV" \
             "The OpenSSL 3.x line is current for AIX; keep both current via security bulletins." \
             "n/a";;
      *)   add patch ssl_ssh "OpenSSH / OpenSSL levels" WARN high "openssh ${SSHV:-n/a}, openssl ${SSLV:-n/a}" \
             "This OpenSSL line predates 3.0 — upstream support has ended and current fixes land on 3.x." \
             "update openssl.base (and openssh) from IBM Web Download Pack / Fix Central.";;
    esac
  fi

  # java_eol — IBM SDK Java on AIX lifecycle (Java 7/7.1 out of service; Java 8 is the last).
  # Colon 'lslpp -qcL Java*' (field 2=fileset, 3=level). PJ's Java.auto.ksh keys on the
  # per-stream fileset names — JavaN[.,_64].{jre,sdk} — so the observed detail carries the
  # JRE/SDK split and 32/64-bit-ness inherently (e.g. "Java8_64.jre 8.0.0.851") rather than
  # a bare version, which is exactly what an admin needs to know what to move off.
  JAVALP=$(aix lslpp_java lslpp -qcL 'Java*'); RC=$?
  if [ "$RC" -ne 127 ]; then
    HAS7=$(printf '%s\n' "$JAVALP" | awk -F: '$2 ~ /^Java7/{f=1} END{print f+0}')
    HAS8=$(printf '%s\n' "$JAVALP" | awk -F: '$2 ~ /^Java8/{f=1} END{print f+0}')
    V7=$(printf '%s\n' "$JAVALP" | awk -F: '$2 ~ /^Java7/{v[$2]=$3} END{n=0;for(k in v){printf "%s%s %s",(n++?", ":""),k,v[k]}}')
    V8=$(printf '%s\n' "$JAVALP" | awk -F: '$2 ~ /^Java8/{v[$2]=$3} END{n=0;for(k in v){printf "%s%s %s",(n++?", ":""),k,v[k]}}')
    if [ "$HAS7" -eq 1 ]; then
      add patch java_eol "IBM SDK Java lifecycle" WARN high "Java 7 installed (${V7:-unknown})" \
          "IBM SDK Java 7 and 7.1 reached end of service on AIX (2022-09-30) — this runtime no longer receives security fixes." \
          "move applications to Java 8 (the last IBM SDK on AIX) or IBM Semeru; then remove the Java 7 filesets."
    elif [ "$HAS8" -eq 1 ]; then
      add patch java_eol "IBM SDK Java lifecycle" PASS low "Java 8 installed (${V8:-unknown})" \
          "Java 8 is the last IBM SDK on AIX — track its service window (standard support ended 2025-04-30; extended runs to 2030-12-31 with an AIX SWMA contract)." "n/a"
    fi
    # VIOS reframe: a VIOS ships and updates its own Java as part of the VIOS image (carried
    # by updateios), so on a VIOS this is informational context, not an app you patch by hand.
    if [ "$IS_VIOS" -eq 1 ] && [ "${F_ID[$((NFIND-1))]}" = "java_eol" ]; then
      F_MEAN[$((NFIND-1))]="${F_MEAN[$((NFIND-1))]} (On a VIOS the bundled Java is maintained by the VIOS image via updateios, not patched directly — treat this as informational.)"
    fi
  fi

  # apar_scan — wraps IBM's OWN authoritative flrtvc.ksh (v0.8.14, IBM Public License 1.0);
  # never re-implements its matching. Every recurring defect in the prior hand-rolled
  # version (dedup across ambiguous multi-stream bulletins, coverage suppression across
  # unrelated streams, silent malformed-version coercion) lived in OUR re-derivation of
  # comparison logic IBM already wrote and tested at scale. This PARSES flrtvc.ksh's OWN
  # compact report (fileset, installed/vulnerable level, fix level FROM ITS OWN OUTPUT,
  # CVE, HIPER, APAR/ifix identifiers, bulletin, CVSS) — we wrap it, we do not out-guess it.
  #
  # THREE invocation paths, in preference order:
  #   0. Delivery bundle (DEFAULT when present): decode the embedded, pinned data into
  #      this run's private scratch directory and invoke offline. The committed/public
  #      scanner has empty slots, so it retains the seed-only fallback and ships no IBM IP.
  #   1. --flrtvc-ksh <script> --flrtvc-apar-csv <file> (explicit override): AIXray invokes
  #      flrtvc.ksh ITSELF, in the enforced offline mode (-s -f -l -e), and captures its
  #      real exit status directly via $? — the safe invocation is GUARANTEED, not hoped
  #      for from an externally-produced file (Codex review round 3, item 2). Fetch both
  #      inputs first: `python3 tools/refresh-data.py fetch-apar-csv --out apar.csv` and
  #      `fetch-flrtvc --out flrtvc.ksh` (pinned + checksum-verified against IBM's own
  #      published SHA256, per docs/DATA-REFRESH.md — a mismatch refuses to write).
  #   2. --flrtvc-report <file> (FALLBACK, e.g. no ksh93 on this box): parses a report
  #      generated elsewhere. Its completion proof is the `# FLRTVC_EXIT=<n>` trailer an
  #      admin-side wrapper must append — a weaker attestation than path 1, since AIXray
  #      cannot itself verify that invocation used the enforced offline flags. The finding
  #      text says which path produced the result.
  #
  # WRITES (precise, not "zero"): flrtvc.ksh ITSELF, given -s -f -l -e, makes no network
  # calls and no writes of its own (verified by reading the full script — the only such
  # paths, `rm hiper_security.csv` and `sudo emgr -lv3`, are on the download/no-file-given
  # code paths this invocation never takes). But the SURROUNDING workflow does write, to
  # paths under the operator's control only: `--flrt-export`'s capture files, the fetched
  # apar.csv/flrtvc.ksh, and (paths 0 and 1) the private decoded inputs plus small
  # scratch temp files holding this run's already-in-memory lslpp/emgr text, removed
  # immediately after the invocation. Nothing is ever written to the target system's
  # own config, filesets, or state.
  #
  # HONESTY CONTRACT: PASS requires ALL of — a banner/header matching flrtvc.ksh's own
  # compact-report format, a real-calendar non-future vintage parsed from line 2
  # SPECIFICALLY, a completion proof (direct exit-status capture on path 1; the
  # FLRTVC_EXIT trailer on path 2 — never merely "the output wasn't empty"), and — when
  # the exit code is 0 ("clean") — a body that is ONLY the recognized clean-exit text with
  # ZERO other/malformed/unrecognized rows (a corrupt or truncated report that happens to
  # also contain the clean-exit phrase must not slip through as PASS). When vulnerabilities
  # were reported (exit 2), at least one row must parse with both a fileset and a CVE/APAR.
  # Any of those missing renders WARN ("not assessed"), never PASS. (Codex adversarial
  # review, three rounds, PR #10.)
  FLRTVC_HEADER="Fileset|Current Version|Type|EFix Installed|Abstract|Unsafe Versions|APARs|Bulletin URL|Download URL|CVSS Base Score|Reboot Required|Last Update|Fixed In"
  FV_REPORT_FILE=""; FV_INVOKED=0; FV_CLEANUP=""; FVEXIT=""
  FV_INVOKE_MODE=""; FV_BUNDLE_ANY=0; FV_BUNDLE_COMPLETE=0
  if [ "${#flrtvc_ksh_b64}" -gt 0 ] || [ "${#flrtvc_ksh_sha256}" -gt 0 ] \
      || [ "${#flrtvc_ksh_version}" -gt 0 ] || [ "${#apar_csv_b64}" -gt 0 ] \
      || [ "${#apar_csv_sha256}" -gt 0 ] || [ "${#apar_csv_vintage}" -gt 0 ]; then
    FV_BUNDLE_ANY=1
  fi
  if [ "${#flrtvc_ksh_b64}" -gt 0 ] && [ "${#flrtvc_ksh_sha256}" -gt 0 ] \
      && [ "${#flrtvc_ksh_version}" -gt 0 ] && [ "${#apar_csv_b64}" -gt 0 ] \
      && [ "${#apar_csv_sha256}" -gt 0 ] && [ "${#apar_csv_vintage}" -gt 0 ]; then
    FV_BUNDLE_COMPLETE=1
  fi
  if [ -n "$FLRTVC_KSH" ] && [ -n "$FLRTVC_APARCSV" ]; then
    FV_INVOKE_MODE="external"
    FLRTVC_DATA_SOURCE="fetched-flag"
  elif [ -z "$FLRTVC_KSH" ] && [ -z "$FLRTVC_APARCSV" ] \
      && [ -z "$FLRTVC_REPORT" ] && [ "${AIXRAY_NO_BUNDLED_FLRTVC:-0}" != "1" ] \
      && [ "$FV_BUNDLE_COMPLETE" -eq 1 ]; then
    FV_INVOKE_MODE="bundled"
    FLRTVC_DATA_SOURCE="bundled"
    FLRTVC_DATA_VERSION=$flrtvc_ksh_version
    if [ "$(valid_ymd "$apar_csv_vintage")" -eq 1 ]; then
      FV_META_AGE=$(( TODAY_J - $(d2j "$apar_csv_vintage") ))
      if [ "$FV_META_AGE" -ge 0 ]; then
        FLRTVC_DATA_VINTAGE=$apar_csv_vintage
        FLRTVC_DATA_AGE=$FV_META_AGE
      fi
    fi
  elif [ -n "$FLRTVC_REPORT" ]; then
    FLRTVC_DATA_SOURCE="report-flag"
  fi

  if [ -n "$FLRTVC_KSH" ] && [ -z "$FLRTVC_APARCSV" ]; then
    FLRTVC_DATA_SOURCE="fetched-flag"
    add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — --flrtvc-ksh given without --flrtvc-apar-csv" \
        "Both are required together to invoke flrtvc.ksh directly." "supply --flrtvc-apar-csv <file> alongside --flrtvc-ksh." "ffiec:II.C.10"
  elif [ -z "$FLRTVC_KSH" ] && [ -n "$FLRTVC_APARCSV" ]; then
    FLRTVC_DATA_SOURCE="fetched-flag"
    add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — --flrtvc-apar-csv given without --flrtvc-ksh" \
        "Both are required together to invoke flrtvc.ksh directly." "supply --flrtvc-ksh <script> alongside --flrtvc-apar-csv." "ffiec:II.C.10"
  elif [ -n "$FV_INVOKE_MODE" ]; then
    # Paths 0 and 1 share capture gates, secure scratch, offline flags and parsing.
    # Only path 1 has external file/pin trust surfaces; path 0's bytes + pins are
    # already inside the same assembled script that is executing.
    if [ "$FV_INVOKE_MODE" = "external" ] && [ ! -r "$FLRTVC_KSH" ]; then
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — cannot read $FLRTVC_KSH" \
          "The --flrtvc-ksh file could not be read." "check the path and permissions of the flrtvc.ksh script." "ffiec:II.C.10"
    elif [ "$FV_INVOKE_MODE" = "external" ] && [ ! -r "$FLRTVC_APARCSV" ]; then
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — cannot read $FLRTVC_APARCSV" \
          "The --flrtvc-apar-csv file could not be read." "check the path and permissions of the apar.csv file." "ffiec:II.C.10"
    else
      # INPUT-CAPTURE GATES (Codex review round 5 items 2+3, round 6 items 1+2):
      # flrtvc.ksh trusts its -l and -e inputs completely, so a FAILED or STRUCTURALLY
      # INCOMPLETE capture must refuse assessment, never feed flrtvc.ksh a silently
      # partial inventory. A truncated lslpp reads as "these few filesets are all that
      # is installed" (omitted vulnerable filesets look absent -> false clean PASS); a
      # garbled/partial emgr reads as "these are all the ifixes" (missing sections ->
      # false exposures). Both refuse as WARN/not-assessed — the binary honesty
      # contract, never a "degraded but authoritative-looking" count.

      # lslpp -qcL floor. Completeness of an inventory cannot be PROVEN from the
      # inventory itself, so this is deliberately a BOUND-AND-DISCLOSE gate, not a
      # completeness proof: (a) a plausible row-count floor — a real AIX/VIOS box has
      # many hundreds of filesets, so a handful is a truncated capture; (b) a diverse
      # bos.rte.* base family (every real install carries bos.rte plus bos.rte.libc,
      # bos.rte.control, ... — a lone bos.rte is suspicious); and, once the report is
      # in hand, the PASS wording DISCLOSES the captured count so a clean result never
      # silently implies "complete inventory verified" (see the PASS branch below).
      # WHY NOT a stronger cross-check (Codex round 7 item 3, (a) explicitly assessed):
      # flrtvc.ksh emits NO count of the filesets it parsed — its report footer prints
      # only "// Vulnerable Filesets: N", and its parseLSLPP() deliberately SKIPS
      # /etc/objrepos and /usr/share rows, so its internal count legitimately differs
      # from our raw structural count and cannot be compared without false refusals.
      # A capture truncated ABOVE this floor (a plausible prefix) therefore still
      # proceeds; that residual is unavoidable from output alone and is why the PASS
      # is a disclosed, bounded result rather than a completeness claim.
      FV_LSLPP_ROWS=$(printf '%s\n' "$LSLPPQ" | awk -F: 'NF>=6 && $3 ~ /^[0-9]/ {n++} END{print n+0}')
      FV_LSLPP_BOSFAM=$(printf '%s\n' "$LSLPPQ" | awk -F: '$2 ~ /^bos\.rte(\.|:|$)/{print $2}' | sort -u | awk 'END{print NR+0}')
      FV_LSLPP_MIN=50

      # emgr -lv3 STRUCTURAL validity (round 6 item 2, tightened round 7 item 4,
      # tightened further round 8 item 2):
      # validated SECTION BY SECTION, not by global tallies (equal global counts can be
      # forged by duplicating a whole section). Real emgr prints, per installed efix, in
      # order: "EFIX ID: N", then "EFIX LABEL: <label>", then a padded "LABEL:"
      # attribute line, ..., then a "Description:" block (verified by reading
      # /usr/sbin/emgr db_list_v3 on real AIX 7.1 and 7.2, and confirmed against the
      # aix72-degraded fixture: EFIX LABEL precedes LABEL: precedes Description: in both
      # of its sections). Each section must therefore open with EFIX ID, carry exactly
      # one EFIX LABEL / LABEL: / Description: in that section IN THAT ORDER, and its
      # EFIX LABEL must be unique across sections. A LABEL: or Description: line seen
      # OUTSIDE any section (before the first EFIX ID, or after a prior section closed
      # without a new EFIX ID) is refused outright — round 7 silently ignored those.
      # This catches a section truncated mid-print (header but no Description), a
      # duplicated section (same label twice), out-of-order fields, and stray field
      # lines outside any section. rc 0 with empty stdout (or only the no-efix text and
      # zero sections) is a genuinely efix-free box; the no-efix text COEXISTING with
      # >=1 complete section is a provable contradiction (IBM's own "no efix data"
      # phrasing while sections claiming installed efixes are also present) and is
      # refused too — round 7 let the section count alone decide, ignoring that
      # contradiction. NOTE what is NOT enforced here, deliberately: the relative order
      # of the many OTHER attribute lines between LABEL: and Description: (STATE:,
      # UPDATED BY:, VUID:, ...) — IBM does not guarantee that ordering and inventing a
      # rule for it would be re-deriving emgr behavior we have not verified; only the
      # three markers this code already tracks are order-checked, because those three
      # are what is actually grounded in the real captured output. NOTE the one thing
      # output alone cannot reveal: a capture truncated cleanly after a COMPLETE section
      # is indistinguishable from a box with exactly that many efixes (emgr prints no
      # total-count footer) — the same bounded limit as lslpp.
      FV_EMGR_OK=0; FV_EMGR_WHY="ok"
      if [ "${EMGRV3_RC:-1}" -ne 0 ]; then
        FV_EMGR_WHY="emgr -lv3 exited ${EMGRV3_RC:-unknown}"
      elif [ -z "$EMGRV3" ]; then
        FV_EMGR_OK=1   # efix-free: rc 0, empty stdout
      else
        FV_EMGR_RES=$(printf '%s\n' "$EMGRV3" | awk '
          function closesec(){
            if(insec){
              if(hdr!=1 || attr!=1 || desc!=1){
                bad=1; why="section "nsec" ("curlabel") incomplete: EFIX LABEL="hdr" LABEL:="attr" Description:="desc
              }
            }
          }
          BEGIN{ insec=0; nsec=0; bad=0; noefix=0; hdr=0; attr=0; desc=0; why=""; stage=0 }
          bad{ next }
          /no efix data/{ noefix=1; next }
          /^EFIX ID: /{
            closesec()
            if(bad) next
            nsec++; insec=1; hdr=0; attr=0; desc=0; curlabel=""; stage=0
            next
          }
          /^EFIX LABEL: /{
            if(!insec){ bad=1; why="EFIX LABEL without a preceding EFIX ID"; next }
            if(stage!=0){ bad=1; why="section "nsec" ("curlabel") out of order: unexpected/repeated EFIX LABEL"; next }
            hdr++
            curlabel=substr($0,13)
            if(seen[curlabel]++){ bad=1; why="duplicate efix section: "curlabel; next }
            stage=1
            next
          }
          /^LABEL:[ ]/{
            if(!insec){ bad=1; why="LABEL: attribute line outside any efix section"; next }
            if(stage!=1){ bad=1; why="section "nsec" ("curlabel") field out of order: LABEL: must follow EFIX LABEL"; next }
            attr++; stage=2; next
          }
          /^Description:/{
            if(!insec){ bad=1; why="Description: block outside any efix section"; next }
            if(stage!=2){ bad=1; why="section "nsec" ("curlabel") field out of order: Description: must follow LABEL:"; next }
            desc++; stage=3; next
          }
          END{
            if(!bad) closesec()
            if(bad){ print "BAD "why; exit }
            if(noefix && nsec>=1){ print "BAD \"no efix data\" text present alongside "nsec" complete efix section(s) — contradictory capture"; exit }
            print "OK "nsec" "noefix
          }')
        FV_EMGR_STAT=$(printf '%s' "$FV_EMGR_RES" | awk '{print $1}')
        if [ "$FV_EMGR_STAT" = "OK" ]; then
          FV_EMGR_NSEC=$(printf '%s' "$FV_EMGR_RES" | awk '{print $2+0}')
          FV_EMGR_ENO=$(printf '%s' "$FV_EMGR_RES" | awk '{print $3+0}')
          if [ "$FV_EMGR_NSEC" -ge 1 ]; then
            FV_EMGR_OK=1   # >=1 internally complete, uniquely-labelled efix section(s)
          elif [ "$FV_EMGR_ENO" -eq 1 ]; then
            FV_EMGR_OK=1   # efix-free: no-efix text, zero sections
          else
            FV_EMGR_WHY="output has no efix sections and no no-efix marker"
          fi
        else
          FV_EMGR_WHY=$(printf '%s' "$FV_EMGR_RES" | awk '{sub(/^BAD /,""); print}')
          FV_EMGR_WHY="inconsistent efix sections — $FV_EMGR_WHY"
        fi
      fi

      # TRUSTED PIN LOCATION (Codex review round 5, item 1): dirname "$0" alone resolves
      # against the caller CWD when $0 arrives without a slash — and slashless $0 is a
      # REAL AIX case, verified live on ksh88: both "ksh aixray-aix.sh" (script-operand
      # PATH search) and a bare PATH exec leave $0 as just the command name. That let an
      # attacker in an untrusted CWD supply BOTH a malicious script and a matching
      # ./tools/flrtvc-pin.txt. Resolution order for a slashless $0:
      #   1. the shell PATH search (whence -p) — the PATH-launched case; the caller CWD
      #      is never consulted for it;
      #   2. only if $0 is NOT on PATH: ./$0 — because then the only way the running
      #      shell can have opened this script is from the CWD itself (verified on real
      #      ksh88: a CWD copy is what actually executes), so the CWD pin is exactly as
      #      trusted as the code already running;
      #   3. neither -> refuse.
      # A slashful $0 resolves to its own physical directory (cd + pwd -P).
      # $AIXRAY_SELF, never $0: this code runs inside a function, where ksh93 rebinds
      # $0 to the function name (see the top-level capture comment).
      FV_PINFILE=""; FV_PINPROBLEM=""
      if [ "$FV_INVOKE_MODE" = "external" ]; then
        FV_SELFDIR=""
        case "$AIXRAY_SELF" in
          */*) FV_SELFDIR=$(cd "$(dirname "$AIXRAY_SELF")" 2>/dev/null && (pwd -P 2>/dev/null || pwd)) ;;
          *)   FV_SELFRES=$(whence -p "$AIXRAY_SELF" 2>/dev/null)
               case "$FV_SELFRES" in
                 */*) FV_SELFDIR=$(cd "$(dirname "$FV_SELFRES")" 2>/dev/null && (pwd -P 2>/dev/null || pwd)) ;;
                 *)   if [ -r "./$AIXRAY_SELF" ]; then
                        FV_SELFDIR=$(pwd -P 2>/dev/null || pwd)
                      fi ;;
               esac ;;
        esac

      # PIN DIRECTORY TRUST (round 6 item 4): the install dir and the pin's parent dir
      # must not be attacker-writable, so the pin file cannot be swapped between the
      # moment its metadata is checked and the moment it is copied. This is what closes
      # the pin-file TOCTOU: with the parent dir non-writable-by-attacker, the ls -lL
      # below and the cp later (into the private scratch dir, from which the hash is
      # then read) necessarily see the SAME file. Sticky /tmp is accepted (see
      # dir_untrusted).
        FV_DIRPROBLEM=""
        if [ -n "$FV_SELFDIR" ]; then
          FV_DIRPROBLEM=$(dir_untrusted "$FV_SELFDIR")
          [ -z "$FV_DIRPROBLEM" ] && FV_DIRPROBLEM=$(dir_untrusted "$FV_SELFDIR/tools")
        fi

      # Pin file metadata (type + ownership + mode) of the ORIGINAL — the SHA256 itself
      # is not read here; it is read later from a PRIVATE COPY so the security-critical
      # value never comes from a second open of the caller-influenceable pathname
      # (round 6 item 4). The dir-trust guard above makes this metadata check and that
      # later copy see the same file. ls -l (NOT -lL) so the ENTRY itself is described,
      # never a symlink target; a symlinked pin is refused outright (round 7 item 2 —
      # a symlink target could be re-pointed between this check and the cp), and 'bin'
      # is accepted as a trusted owner (AIX system account).
        if [ -z "$FV_SELFDIR" ]; then
          FV_PINPROBLEM="could not resolve the AIXray install directory from \$0 ($AIXRAY_SELF) — refusing to guess a pin-file location (the caller CWD is never trusted)"
        elif [ -n "$FV_DIRPROBLEM" ]; then
          FV_PINPROBLEM="untrusted pin location — $FV_DIRPROBLEM; a pin in an attacker-writable directory could be swapped out from under its own verification"
        else
          FV_PINFILE="$FV_SELFDIR/tools/flrtvc-pin.txt"
          if [ ! -r "$FV_PINFILE" ]; then
            FV_PINPROBLEM="pin file missing or unreadable: $FV_PINFILE"
          else
            FV_PINLS=$(LC_ALL=C ls -l "$FV_PINFILE" 2>/dev/null)
            FV_PINMODE=$(printf '%s\n' "$FV_PINLS" | awk '{print $1}')
            FV_PINOWNER=$(printf '%s\n' "$FV_PINLS" | awk '{print $3}')
            FV_PINTYP=$(printf '%s' "$FV_PINMODE" | cut -c1)
            FV_GW=$(printf '%s' "$FV_PINMODE" | cut -c6)
            FV_OW=$(printf '%s' "$FV_PINMODE" | cut -c9)
            FV_ME=$(id -un 2>/dev/null)
            if [ "$FV_PINTYP" = "l" ]; then
              FV_PINPROBLEM="pin file $FV_PINFILE is a symlink — its target could be re-pointed between validation and use; refusing"
            elif [ "$FV_PINTYP" != "-" ]; then
              FV_PINPROBLEM="pin file $FV_PINFILE is not a regular file ($FV_PINMODE)"
            elif [ "$FV_GW" != "-" ] || [ "$FV_OW" != "-" ]; then
              FV_PINPROBLEM="pin file $FV_PINFILE is group/other-writable ($FV_PINMODE) — a writable pin is no pin"
            elif [ "$FV_PINOWNER" != "root" ] && [ "$FV_PINOWNER" != "bin" ] && [ "$FV_PINOWNER" != "$FV_ME" ]; then
              FV_PINPROBLEM="pin file $FV_PINFILE is owned by $FV_PINOWNER (not root, bin, or the invoking user) — not a trustworthy pin"
            fi
          fi
        fi
      else
        FV_BUNDLE_KHEX=$(printf '%s' "$flrtvc_ksh_sha256" | awk '$0 ~ /^[0-9a-f]+$/ {print "hex"}')
        FV_BUNDLE_AHEX=$(printf '%s' "$apar_csv_sha256" | awk '$0 ~ /^[0-9a-f]+$/ {print "hex"}')
        if [ "${#flrtvc_ksh_sha256}" -ne 64 ] || [ "$FV_BUNDLE_KHEX" != "hex" ] \
            || [ "${#apar_csv_sha256}" -ne 64 ] || [ "$FV_BUNDLE_AHEX" != "hex" ]; then
          FV_PINPROBLEM="bundled FLRTVC SHA256 metadata is missing or malformed"
        else
          case "$flrtvc_ksh_version" in
            ''|*[!A-Za-z0-9._-]*) FV_PINPROBLEM="bundled flrtvc.ksh version metadata is malformed" ;;
          esac
        fi
        if [ -z "$FV_PINPROBLEM" ] \
            && { [ "$(valid_ymd "$apar_csv_vintage")" -ne 1 ] || [ -z "$FLRTVC_DATA_AGE" ]; }; then
          FV_PINPROBLEM="bundled apar.csv vintage is invalid or in the future: $apar_csv_vintage"
        fi
      fi
      FV_HASHTOOL=$(command -v openssl 2>/dev/null)
      # Prefer a binary literally named ksh93 (the standard AIX path, /usr/bin/ksh93);
      # fall back to plain "ksh" for platforms where the default ksh already IS ksh93
      # (e.g. macOS ships ksh as AT&T ksh93u+). If a fallback ksh is actually ksh88, the
      # ksh93-specific syntax in flrtvc.ksh fails loudly with a real syntax error — a
      # safe, visible failure, never a silent wrong answer.
      FV_KSH93=$(command -v ksh93 2>/dev/null)
      [ -z "$FV_KSH93" ] && FV_KSH93=$(command -v ksh 2>/dev/null)

      # SCRATCH-PARENT TRUST: mode 700 protects an existing child, but it does not
      # protect that child's directory entry when its parent is non-sticky and
      # attacker-writable. Resolve TMPDIR to a physical path first (so a later symlink
      # retarget cannot change what we use), then apply the same ownership/write guard
      # used for external pin directories. Paths 0 and 1 share this parent and both
      # may execute the private copy as root, so either path fails closed here.
      FV_TMPBASE_RAW=${TMPDIR:-/tmp}
      FV_TMPBASE=""; FV_TMPPROBLEM=""
      FV_TMPBASE=$(CDPATH= cd -- "$FV_TMPBASE_RAW" 2>/dev/null \
        && (pwd -P 2>/dev/null || pwd))
      if [ -z "$FV_TMPBASE" ]; then
        FV_TMPPROBLEM="cannot resolve or enter $FV_TMPBASE_RAW"
      else
        FV_TMPPROBLEM=$(path_untrusted "$FV_TMPBASE")
      fi

      if [ "${LSLPPQ_RC:-1}" -ne 0 ] || [ "$FV_LSLPP_ROWS" -lt "$FV_LSLPP_MIN" ] || [ "$FV_LSLPP_BOSFAM" -lt 3 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — fileset inventory capture failed or is implausibly small (lslpp -qcL rc=${LSLPPQ_RC:-unknown}, $FV_LSLPP_ROWS structurally valid row(s) < floor $FV_LSLPP_MIN, distinct bos.rte.* filesets: $FV_LSLPP_BOSFAM)" \
            "flrtvc.ksh would read a truncated/empty fileset inventory as NOTHING INSTALLED and report the omitted vulnerable filesets as absent — a false clean PASS. A real AIX/VIOS box has many hundreds of filesets and a diverse bos.rte.* family; this capture does not, so it is refused, not scanned. (This is a bound-and-disclose floor against failed/truncated captures, not a completeness proof — completeness cannot be proven from the inventory alone.)" \
            "re-run as root and confirm lslpp -qcL returns the full inventory on this box, then re-run the scan." "ffiec:II.C.10"
      elif [ "$FV_EMGR_OK" -eq 0 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — interim-fix inventory capture failed or is structurally inconsistent ($FV_EMGR_WHY)" \
            "flrtvc.ksh would read a failed, truncated, or garbled efix inventory as NO/INCOMPLETE IFIXES INSTALLED, so ifix-covered CVEs would be reported as false exposures. A capture whose efix sections do not each carry their expected companion lines is refused, never partial-credited. (A genuinely efix-free box passes this gate: real emgr exits 0 with empty output in that case.)" \
            "re-run as root and confirm emgr -lv3 returns a complete listing on this box, then re-run the scan." "ffiec:II.C.10"
      elif [ -n "$FV_PINPROBLEM" ]; then
        if [ "$FV_INVOKE_MODE" = "bundled" ]; then
          add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — $FV_PINPROBLEM" \
              "The embedded delivery metadata is not trustworthy enough to decode or execute as root; the bundled sweep was refused and the seed remains the only patch signal." \
              "rebuild the local delivery artifact with tools/refresh-data.py bundle; never hand-edit or publish its slots." "ffiec:II.C.10"
        else
          add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — $FV_PINPROBLEM" \
              "There is no trustworthy pinned SHA256 to verify the supplied --flrtvc-ksh script against, and an unverified script must never be executed (it typically runs as root)." \
              "ensure tools/flrtvc-pin.txt is present, root-or-owner-owned, and not group/other-writable, in a non-attacker-writable AIXray install directory, or use --flrtvc-report instead." "ffiec:II.C.10"
        fi
      elif [ -n "$FV_TMPPROBLEM" ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — untrusted FLRTVC scratch parent — $FV_TMPPROBLEM" \
            "A mode-700 child is not private if another user can replace that child's directory entry through a non-sticky writable parent; decoded code and inventory captures are never placed or executed there." \
            "set TMPDIR to a root/bin/current-user-owned directory that is either non-writable by other users or sticky, then re-run." "ffiec:II.C.10"
      elif [ -z "$FV_HASHTOOL" ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — no SHA256 tool found on this box (need openssl)" \
            "Could not decode/checksum the selected flrtvc.ksh script to verify it against the pin — an unverified script must never be executed." \
            "install openssl, or generate the report elsewhere and supply it via --flrtvc-report." "ffiec:II.C.10"
      elif [ -z "$FV_KSH93" ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — no ksh93-capable shell found on this box" \
            "flrtvc.ksh requires ksh93 to run; neither ksh93 nor ksh was found on this box's PATH." \
            "install/locate ksh93, or generate the report elsewhere and supply it via --flrtvc-report." "ffiec:II.C.10"
      else
        # SAFE TEMP DIRECTORY (Codex review round 4 item 3, round 5 item 4, rounds 6+7
        # item 3): a predictable /tmp+$$ name written with plain '>' can be pre-created
        # as a symlink to a root-owned target and clobbered. Real AIX ships no mktemp
        # (confirmed live on both lab boxes); mkdir is the portable primitive and fails
        # closed on a pre-existing path (symlink or otherwise). The cleanup traps are
        # armed FIRST, but they act ONLY when FV_MADE=1, and FV_MADE (with FV_TMPDIR) is
        # set ONLY AFTER mkdir succeeds. This is the round-7 critical fix: the round-6
        # version assigned FV_TMPDIR to the candidate name BEFORE mkdir, so a signal in
        # the pre-mkdir window would rm -rf a predictable, possibly attacker-pre-created
        # path (or a followed symlink target) as root. Now, before a directory WE
        # created exists, FV_MADE is empty and the trap deletes nothing. EXIT is in the
        # set so an early/fatal shell exit also cleans the mode-700 scratch (which holds
        # the full fileset+efix inventories).
        FV_TMPDIR=""; FV_MADE=""
        trap '[ -n "$FV_MADE" ] && [ -n "$FV_TMPDIR" ] && rm -rf "$FV_TMPDIR"' EXIT
        trap '[ -n "$FV_MADE" ] && [ -n "$FV_TMPDIR" ] && rm -rf "$FV_TMPDIR"; trap - EXIT HUP INT TERM; exit 1' HUP INT TERM
        FV_TRY=0
        while [ "$FV_TRY" -lt 20 ] && [ -z "$FV_MADE" ]; do
          FV_CAND="$FV_TMPBASE/aixray-flrtvc.$$.$(date +%s 2>/dev/null)${FV_TRY}"
          # mkdir first; publish FV_TMPDIR/FV_MADE only on success, so the trap never
          # names a path AIXray did not itself create.
          if mkdir -m 700 "$FV_CAND" 2>/dev/null; then FV_TMPDIR="$FV_CAND"; FV_MADE=1; fi
          FV_TRY=$((FV_TRY+1))
        done
        FV_CLEANUP="$FV_TMPDIR"
        if [ -z "$FV_MADE" ]; then
          trap - EXIT HUP INT TERM   # nothing was created; disarm the (no-op) traps
          add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — could not create a secure temp directory for the flrtvc.ksh invocation" \
              "A private, mode-700 scratch directory could not be created after multiple attempts." \
              "check /tmp permissions and available space, then re-run." "ffiec:II.C.10"
        else
          FV_PINSHA=""; FV_PINVERSION=""
          if [ "$FV_INVOKE_MODE" = "bundled" ]; then
            # Path 0 has no external pin path: bytes and expected digests are slots in
            # the same already-executing artifact, so no writable-directory TOCTOU is
            # introduced. The decoded private copy is still verified before execution.
            FV_PINSHA=$flrtvc_ksh_sha256
            FV_PINVERSION=$flrtvc_ksh_version
          else
            # Path 1 PIN: copy into the private scratch dir and read the hash from the
            # COPY (round 6 item 4) — the security-critical SHA256 is never taken from
            # a second open of the pin pathname. The dir-trust guard above guarantees
            # this copy is of the same file whose metadata passed validation.
            FV_TMPPIN="$FV_TMPDIR/flrtvc-pin.txt"
            if cp "$FV_PINFILE" "$FV_TMPPIN" 2>/dev/null; then
              FV_PINSHA=$(awk -F= '/^SHA256=/{print $2; exit}' "$FV_TMPPIN")
              FV_PINVERSION=$(awk -F= '/^VERSION=/{print $2; exit}' "$FV_TMPPIN")
            fi
            [ -n "$FV_PINVERSION" ] && FLRTVC_DATA_VERSION=$FV_PINVERSION
          fi
          FV_PINHEX=$(printf '%s' "$FV_PINSHA" | awk '$0 ~ /^[0-9a-f]+$/ {print "hex"}')
          if [ "${#FV_PINSHA}" -ne 64 ] || [ "$FV_PINHEX" != "hex" ]; then
            add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — pinned flrtvc.ksh SHA256 is missing or malformed in tools/flrtvc-pin.txt" \
                "The pin file has no well-formed 64-hex SHA256= value, so there is nothing trustworthy to verify the supplied --flrtvc-ksh script against — an unverified script is never executed." \
                "restore a valid tools/flrtvc-pin.txt (tools/refresh-data.py rewrites it on fetch), or use --flrtvc-report instead." "ffiec:II.C.10"
          else
            FV_TMPKSH="$FV_TMPDIR/flrtvc.ksh"
            FV_RUN_APARCSV=$FLRTVC_APARCSV
            FV_PAYLOAD_READY=0
            if [ "$FV_INVOKE_MODE" = "bundled" ]; then
              FV_TMPAPAR="$FV_TMPDIR/apar.csv"
              if ! decode_b64_to "$flrtvc_ksh_b64" "$FV_TMPKSH"; then
                add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — bundled flrtvc.ksh base64 payload could not be decoded" \
                    "The local delivery artifact's embedded script was corrupt or incomplete; undecodable code is never executed." \
                    "rebuild the local delivery artifact with tools/refresh-data.py bundle." "ffiec:II.C.10"
              elif ! decode_b64_to "$apar_csv_b64" "$FV_TMPAPAR"; then
                add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — bundled apar.csv base64 payload could not be decoded" \
                    "The local delivery artifact's embedded feed was corrupt or incomplete; no sweep is claimed from undecodable data." \
                    "rebuild the local delivery artifact with tools/refresh-data.py bundle." "ffiec:II.C.10"
              else
                chmod 0600 "$FV_TMPKSH" "$FV_TMPAPAR" 2>/dev/null
                FV_ACTUALSHA=$(sha256_of "$FV_TMPKSH")
                FV_ACTUALAPARSHA=$(sha256_of "$FV_TMPAPAR")
                FV_DECODE_VINTAGE=$(awk -F, 'NR==2{print $2; exit}' "$FV_TMPAPAR" | tr -d ' \r' | tr '.' '-')
                if [ -z "$FV_ACTUALSHA" ] || [ -z "$FV_ACTUALAPARSHA" ]; then
                  add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — could not checksum decoded bundled FLRTVC data" \
                      "The decoded private copies could not be integrity-checked, so neither is trusted or executed." \
                      "confirm openssl works and rebuild the local delivery artifact." "ffiec:II.C.10"
                elif [ "$FV_ACTUALSHA" != "$FV_PINSHA" ]; then
                  add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — bundled flrtvc.ksh SHA256 does not match the embedded pin — REFUSING to execute it" \
                      "The decoded bundled script does not match the delivery artifact's expected SHA256 ($FV_ACTUALSHA vs. expected $FV_PINSHA). Corrupt or tampered embedded code is never executed, especially as root." \
                      "discard and rebuild the local delivery artifact with tools/refresh-data.py bundle." "ffiec:II.C.10"
                elif [ "$FV_ACTUALAPARSHA" != "$apar_csv_sha256" ]; then
                  add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — bundled apar.csv SHA256 does not match the embedded pin" \
                      "The decoded bundled feed does not match the delivery artifact's expected SHA256 ($FV_ACTUALAPARSHA vs. expected $apar_csv_sha256), so it is not a trustworthy assessment input." \
                      "discard and rebuild the local delivery artifact with tools/refresh-data.py bundle." "ffiec:II.C.10"
                elif [ "$FV_DECODE_VINTAGE" != "$apar_csv_vintage" ]; then
                  add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — bundled apar.csv row-2 vintage does not match embedded metadata ($FV_DECODE_VINTAGE vs. $apar_csv_vintage)" \
                      "The feed bytes and advertised vintage disagree; the scanner refuses to present either as authoritative." \
                      "discard and rebuild the local delivery artifact with tools/refresh-data.py bundle." "ffiec:II.C.10"
                else
                  FV_RUN_APARCSV=$FV_TMPAPAR
                  FV_PAYLOAD_READY=1
                fi
              fi
            else
              # Path 1 RUNTIME PIN ENFORCEMENT (round 4 item 1, round 5 item 1):
              # copy the supplied script into the private scratch dir FIRST, hash the
              # COPY, and execute the COPY — what was verified is exactly what runs.
              FV_ACTUALSHA=""
              if cp "$FLRTVC_KSH" "$FV_TMPKSH" 2>/dev/null; then
                FV_ACTUALSHA=$(sha256_of "$FV_TMPKSH")
              fi
              if [ -z "$FV_ACTUALSHA" ]; then
                add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — could not copy and checksum the supplied flrtvc.ksh script" \
                    "The supplied --flrtvc-ksh script could not be copied into the private scratch directory and hashed there — an unverified script must never be executed." \
                    "check the file, free space in ${TMPDIR:-/tmp}, and that openssl works, then re-run." "ffiec:II.C.10"
              elif [ "$FV_ACTUALSHA" != "$FV_PINSHA" ]; then
                add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — supplied flrtvc.ksh SHA256 does not match the pinned hash — REFUSING to execute it" \
                    "The file at --flrtvc-ksh does not match tools/flrtvc-pin.txt's pinned SHA256 ($FV_ACTUALSHA vs. expected $FV_PINSHA). This may be a tampered, swapped, or corrupted script — it is never executed unverified, especially since this scan typically runs as root." \
                    "re-fetch flrtvc.ksh (tools/refresh-data.py fetch-flrtvc, itself checksum-verified) and re-run; if IBM genuinely shipped a new version, verify it by hand and update tools/flrtvc-pin.txt deliberately." "ffiec:II.C.10"
              else
                FV_PAYLOAD_READY=1
              fi
            fi
            if [ "$FV_PAYLOAD_READY" -eq 1 ]; then
              FV_TMPLSLPP="$FV_TMPDIR/lslpp.txt"; FV_TMPEMGR="$FV_TMPDIR/emgr.txt"
              FV_TMPOUT="$FV_TMPDIR/out.txt"; FV_TMPERR="$FV_TMPDIR/err.txt"
              # LSLPPQ (colon "lslpp -qcL"), NOT LSLPP (columnar "lslpp -L") — flrtvc.ksh's
              # -l flag requires the colon form (same one --flrt-export already writes to
              # disk); feeding it the columnar form would silently starve every match.
              # EMGRV3 (verbose "emgr -lv3"), NOT EOUT (summary "emgr -l") — flrtvc.ksh's
              # -e flag requires the verbose form its own parseEFIX() greps for, and its
              # own live-capture path consumes RAW emgr -lv3 output (flrtvc.ksh runs
              # exactly that command when -e is absent), so the raw captured EMGRV3 text
              # is byte-format-identical to what parseEFIX demonstrably consumes: real
              # emgr prints the unpadded "EFIX LABEL: <label>" header and the
              # "Description:" block parseEFIX searches for (verified by reading
              # /usr/sbin/emgr db_list_v3 on real AIX 7.1 and 7.2 boxes). No transcoding
              # is done here — inventing one would be re-deriving IBM behavior.
              printf '%s\n' "$LSLPPQ" > "$FV_TMPLSLPP"
              printf '%s\n' "$EMGRV3" > "$FV_TMPEMGR"
              # Write-consistency check (round 6 item 1c): the -l file we hand flrtvc
              # must carry the SAME structurally-valid row count we captured — a short
              # write (disk-full/quota) would truncate the inventory flrtvc sees and,
              # again, make omitted filesets look absent. Refuse on any mismatch.
              FV_WROTE=$(awk -F: 'NF>=6 && $3 ~ /^[0-9]/ {n++} END{print n+0}' "$FV_TMPLSLPP")
              if [ "$FV_WROTE" -ne "$FV_LSLPP_ROWS" ]; then
                add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — the fileset inventory handed to flrtvc.ksh was truncated on write ($FV_WROTE of $FV_LSLPP_ROWS rows)" \
                    "The -l input written for flrtvc.ksh has fewer valid rows than were captured — a short write would make omitted filesets look absent and produce a false clean result." \
                    "check free space/quota in ${TMPDIR:-/tmp} and re-run." "ffiec:II.C.10"
              else
                "$FV_KSH93" "$FV_TMPKSH" -s -f "$FV_RUN_APARCSV" -l "$FV_TMPLSLPP" -e "$FV_TMPEMGR" -d '|' \
                    > "$FV_TMPOUT" 2>"$FV_TMPERR"
                FVEXIT=$?
                FV_REPORT_FILE="$FV_TMPOUT"
                FV_INVOKED=1
              fi
            fi
          fi
        fi
      fi
    fi
  elif [ -n "$FLRTVC_REPORT" ]; then
    # Path 2 (fallback): parse a report generated elsewhere.
    if [ ! -r "$FLRTVC_REPORT" ]; then
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — cannot read $FLRTVC_REPORT" \
          "The --flrtvc-report file could not be read — exposure was not evaluated." "check the path and permissions of the report file." "ffiec:II.C.10"
    else
      FV_REPORT_FILE="$FLRTVC_REPORT"
    fi
  else
    if [ "$FV_BUNDLE_ANY" -eq 1 ] \
        && [ "${AIXRAY_NO_BUNDLED_FLRTVC:-0}" != "1" ]; then
      FLRTVC_DATA_SOURCE="bundled"
      FLRTVC_DATA_VERSION=$flrtvc_ksh_version
      if [ "$(valid_ymd "$apar_csv_vintage")" -eq 1 ]; then
        FV_META_AGE=$(( TODAY_J - $(d2j "$apar_csv_vintage") ))
        if [ "$FV_META_AGE" -ge 0 ]; then
          FLRTVC_DATA_VINTAGE=$apar_csv_vintage
          FLRTVC_DATA_AGE=$FV_META_AGE
        fi
      fi
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — bundled FLRTVC embed slots are incomplete" \
          "A partial delivery artifact is not a trustworthy full sweep; all payload, SHA, version, and vintage slots are required together, so nothing embedded was decoded or executed." \
          "discard and rebuild the local delivery artifact with tools/refresh-data.py bundle." "ffiec:II.C.10"
    else
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — no flrtvc.ksh invocation or report supplied" \
          "Full CVE/APAR exposure was NOT evaluated — the embedded security-APAR seed above covers only a small curated set, not IBM's own FLRTVC engine. Absence of a result must never read as clean." \
          "fetch apar.csv + flrtvc.ksh (tools/refresh-data.py) and re-run with --flrtvc-ksh + --flrtvc-apar-csv (preferred), or supply a pre-generated --flrtvc-report." "ffiec:II.C.10"
    fi
  fi

  if [ -n "$FV_REPORT_FILE" ]; then
    FV_LINE1=$(awk 'NR==1{print; exit}' "$FV_REPORT_FILE")
    FV_LINE2=$(awk 'NR==2{print; exit}' "$FV_REPORT_FILE")
    FV_STRUCT_OK=0
    case "$FV_LINE1" in "# FLRTVC Script executed"*) FV_STRUCT_OK=1;; esac
    case "$FV_LINE1" in
      *"Version:"*)
        FV_REPORT_VERSION=$(printf '%s' "$FV_LINE1" | awk '{sub(/^.*Version:[ \t]*/,""); print}')
        [ -n "$FV_REPORT_VERSION" ] && FLRTVC_DATA_VERSION=$FV_REPORT_VERSION
        ;;
    esac

    # Vintage: line 2 SPECIFICALLY ("# This report is based on APAR file dated : YYYY.MM.DD"),
    # not "any line shaped like a date" — and must be a REAL calendar date (valid_ymd), not
    # just digit-shaped (a Feb-31-style impossible date must never silently pass).
    FVDATE=$(printf '%s' "$FV_LINE2" | awk -F': ' 'NF>=2{print $NF}' | tr -d ' ' | tr '.' '-')
    FVAGE=""
    if [ "$(valid_ymd "$FVDATE")" -eq 1 ]; then
      CAND=$(( TODAY_J - $(d2j "$FVDATE") ))
      [ "$CAND" -ge 0 ] && FVAGE="$CAND"
    fi
    if [ -n "$FVAGE" ]; then
      FLRTVC_DATA_VINTAGE=$FVDATE
      FLRTVC_DATA_AGE=$FVAGE
    fi
    [ -z "$FVAGE" ] && FVDATE="unknown/invalid"

    if [ "$FV_INVOKED" -eq 0 ]; then
      # Path 2 only: completion proof comes from the trailer an admin-side wrapper
      # appended after capturing flrtvc.ksh's OWN exit status. Real AIX awk does not
      # retain $0 into an END block — track it in a variable, never 'END{print}'.
      FV_LASTLINE=$(awk '{l=$0} END{print l}' "$FV_REPORT_FILE")
      case "$FV_LASTLINE" in
        "# FLRTVC_EXIT="[0-9]*) FVEXIT=${FV_LASTLINE##*=};;
      esac
    fi
    if [ "$FV_INVOKED" -eq 1 ] && [ "$FV_INVOKE_MODE" = "bundled" ]; then
      ATTRIB="path 0 — bundled embedded data; AIXray invoked flrtvc.ksh itself, offline"
    elif [ "$FV_INVOKED" -eq 1 ]; then
      ATTRIB="path 1 — external --flrtvc-* files; AIXray invoked flrtvc.ksh itself, offline"
    else
      ATTRIB="path 2 — parsed from an externally supplied --flrtvc-report; the invocation itself could not be directly verified"
    fi

    if [ "$FV_STRUCT_OK" -eq 0 ]; then
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — output does not look like a flrtvc.ksh report ($ATTRIB)" \
          "Line 1 doesn't match flrtvc.ksh's own banner — this may be the wrong file/tool, or a truncated/corrupted run. A comparison against unverified structure is not trustworthy." \
          "re-generate the report with flrtvc.ksh (docs/DATA-REFRESH.md) and re-run." "ffiec:II.C.10"
    elif [ -z "$FVAGE" ]; then
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — report vintage is unparseable or in the future ($FVDATE)" \
          "Line 2's apar.csv date is missing, not a real calendar date, or clock-skewed ahead of this run — not a basis for a clean result." \
          "re-fetch a fresh apar.csv and re-run." "ffiec:II.C.10"
    elif [ -z "$FVEXIT" ] || { [ "$FVEXIT" != "0" ] && [ "$FVEXIT" != "2" ]; }; then
      add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — flrtvc.ksh did not report a successful, complete run (exit=${FVEXIT:-missing}; $ATTRIB)" \
          "flrtvc.ksh's own exit status was missing or showed an error/unexpected code — the scan may not have finished. A non-empty report is not proof of a completed run." \
          "re-run flrtvc.ksh (directly via --flrtvc-ksh, or capture its real exit status into the FLRTVC_EXIT trailer for --flrtvc-report) and re-run." "ffiec:II.C.10"
    else
      # Parse flrtvc.ksh's own compact report. Every row it prints is already IBM's
      # authoritative decision (installed-vs-vulnerable-range match, and any already-fixed
      # or non-deprecated-efix-covered row already excluded by flrtvc.ksh itself) — this
      # loop enumerates CVEs and validates structure; it does not re-decide exposure.
      RESULT=$(awk -F'|' -v hdr="$FLRTVC_HEADER" '
        # is_fixedin_placeholder: true for empty, a known IBM non-answer phrase, or
        # anything containing whitespace. A real fix-level token — dotted VRMF
        # "7.2.5.200", or the equally-real IBM dash TL-SP form "7100-05-10" /
        # "7200-05-03-2136" — is ALWAYS a single token; the IBM placeholder PHRASES
        # ("See Bulletin", "See advisory") always contain a space. A prior version used
        # a narrow dotted-VRMF-only regex that silently discarded every real dash-format
        # Fixed In value as null (Codex review round 3, item 1 — verified against real
        # flrtvc.ksh output: 32 of 175 exposures on the AIX 7.1 lab box carried a real
        # dash-format fix level that was being thrown away). fixed_at_or_above is
        # SOURCED VERBATIM here — never re-derived, never re-shaped to a "preferred" format.
        function is_fixedin_placeholder(v,  lv){
          if(v=="")return 1
          if(v ~ /[ \t]/)return 1
          lv=tolower(v)
          if(lv=="n/a" || lv=="tbd" || lv=="none" || lv=="unknown")return 1
          return 0
        }
        function clean(s){ gsub(/[\t\r\n]/," ",s); return s }
        function trim(s){ sub(/^[ \t]+/,"",s); sub(/[ \t]+$/,"",s); return s }
        function valid_cvss(s){
          return s ~ /^[0-9]+([.][0-9]+)?$/ && (s+0)>=0 && (s+0)<=10
        }
        BEGIN{ nexp=0; nhiper=0; nrow=0; nmalformed=0; header_seen=0; clean_seen=0; gncve=0; gnapar=0 }
        NR<=3{next}
        $0 ~ /^# FLRTVC_EXIT=/{next}
        $0=="No vulnerabilities" || $0=="All vulnerabilities fixed."{clean_seen=1; next}
        NR==4{ if($0==hdr) header_seen=1; next }
        NF==0{next}
        {
          nrow++
          if(NF<13){ nmalformed++; next }
          fileset=$1; installed=$2; type=$3; efixinst=$4
          unsafever=$6; aparsfield=$7; bulletin=$8; cvssfield=$10; reboot=$11; fixedin=$13
          if(fileset=="" || aparsfield==""){ nmalformed++; next }
          # apars: ALL non-CVE tokens from the row (not just the first — a prior version
          # kept only aa[1], silently dropping additional ifix/APAR identifiers when a row
          # listed several, Codex review round 3 item 4). These are mixed ifix-label/
          # APAR-number tokens straight from the "APARs" column as printed — never labeled
          # "apar" (singular) here, since many are ifix labels (e.g. "3013ma"), not APAR numbers.
          na=split(aparsfield,aa,/[\/ ]+/)
          ncve=0; napar=0
          for(j=1;j<=na;j++){
            if(aa[j] ~ /^CVE-[0-9]/){
              if(seenrow[aa[j]]!=nrow){ seenrow[aa[j]]=nrow; ncve++; cvelist[ncve]=aa[j] }
              # global (whole-report, not per-row) distinct-CVE count — used ONLY to label
              # the exposure-record count honestly (§62 finding #15: "175 exposures" was
              # being read as "175 distinct CVEs" when a CVE can recur across several
              # fileset rows). Never affects nexp/ncve or the FAIL/PASS decision above.
              if(!(aa[j] in gcveseen)){ gcveseen[aa[j]]=1; gncve++ }
            }
            else if(aa[j]!=""){
              dup=0; for(k=1;k<=napar;k++) if(aparlist[k]==aa[j]) dup=1
              if(!dup){ napar++; aparlist[napar]=aa[j] }
              if(!(aa[j] in gaparseen)){ gaparseen[aa[j]]=1; gnapar++ }
            }
          }
          apars=""; for(j=1;j<=napar;j++) apars=apars (j>1?";":"") aparlist[j]
          original_ncve=ncve
          cvssfield=trim(cvssfield)
          bare_cvss=(original_ncve==1 && valid_cvss(cvssfield))
          map_complete=0
          if(original_ncve==0){
            map_complete=(cvssfield=="")
          } else if(bare_cvss){
            map_complete=1
          } else {
            map_complete=1
            ncv=split(cvssfield,cvarr,/[[:space:]]+/)
            if(cvssfield=="" || ncv!=original_ncve)map_complete=0
            for(m=1;m<=ncv;m++){
              p2=index(cvarr[m],":")
              key=(p2>0?substr(cvarr[m],1,p2-1):"")
              value=(p2>0?substr(cvarr[m],p2+1):"")
              inrow=0
              for(q=1;q<=original_ncve;q++)if(cvelist[q]==key)inrow=1
              mapkey=nrow SUBSEP key
              if(p2==0 || !inrow || !valid_cvss(value) || mapseen[mapkey]++)map_complete=0
            }
          }
          if(ncve==0){ ncve=1; cvelist[1]="" }
          fx=""; if(!is_fixedin_placeholder(fixedin)) fx=fixedin
          rb=tolower(reboot)
          for(c2=1;c2<=ncve;c2++){
            cve=cvelist[c2]
            nexp++
            if(type=="hiper")nhiper++
            if(cve!="")name=cve; else if(napar>0)name=aparlist[1]; else name=fileset
            if(nexp<=5)ex[nexp]=name
            cvss=""; cvss_known=(cve=="" && cvssfield=="" ? 1 : 0)
            if(cve!="" && bare_cvss){
              cvss=cvssfield; cvss_known=1
            } else if(cve!=""){
              matches=0
              ncv=split(cvssfield,cvarr,/[[:space:]]+/)
              for(m=1;m<=ncv;m++){
                p2=index(cvarr[m],":")
                if(p2>0 && substr(cvarr[m],1,p2-1)==cve){
                  matches++
                  candidate=substr(cvarr[m],p2+1)
                  if(valid_cvss(candidate))cvss=candidate
                }
              }
              if(matches==1 && cvss!="")cvss_known=1
            }
            printf "%s\t%d\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%d\t%d\n", clean(cve), (type=="hiper"?1:0), clean(fileset), clean(installed), clean(unsafever), clean(fx), clean(apars), clean(efixinst), clean(bulletin), cvss, rb, cvss_known, map_complete
          }
        }
        END{
          names=""; for(i=1;i<=nexp && i<=5;i++) names=names (i>1?", ":"") ex[i]
          printf "%d\t%d\t%d\t%d\t%d\t%d\t%s\t%d\t%d\n", nexp, nhiper, nrow, nmalformed, header_seen, clean_seen, names, gncve+0, gnapar+0
        }
      ' "$FV_REPORT_FILE")
      # Same "all lines but the last are detail; the last is the summary" convention as
      # every other multi-row parse in this script — see the NOTE at the awk-END-$0
      # comment above; SUMLINE never uses a bare 'END{print}'.
      SUMLINE=$(printf '%s\n' "$RESULT" | awk '{s=$0} END{print s}')
      DETAILLINES=$(printf '%s\n' "$RESULT" | awk 'NR>1{print h} {h=$0}')
      FVNEXP=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $1+0}')
      FVNHIPER=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $2+0}')
      FVNROW=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $3+0}')
      FVNMALFORMED=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $4+0}')
      FVHEADERSEEN=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $5+0}')
      FVCLEANSEEN=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $6+0}')
      FVNAMES=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $7}')
      # Distinct-identifier counts (review-queue #62 finding #4) — labeling only, never
      # used to gate FAIL/PASS/WARN: FVNEXP is an EXPOSURE-RECORD count (one row can carry
      # more than one CVE, and the same CVE can recur on a different fileset's row), so it
      # must never be presented as if it equalled "N distinct CVEs."
      FVNCVE=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $8+0}')
      FVNAPAR=$(printf '%s' "$SUMLINE" | awk -F'\t' '{print $9+0}')

      if [ -z "$SUMLINE" ] || [ "${FVHEADERSEEN:-0}" -eq 0 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — report column header does not match flrtvc.ksh's expected schema ($ATTRIB)" \
            "The report's column-header row (line 4) doesn't match flrtvc.ksh's own compact-report format — this may be a different tool's output, a truncated file, or a version mismatch. A comparison against unverified structure is not trustworthy." \
            "re-generate the report with flrtvc.ksh (no -q; the header row is required) and re-run." "ffiec:II.C.10"
      elif [ "$FVEXIT" = "0" ] && [ "${FVNROW:-0}" -gt 0 ]; then
        # MUST be checked before the generic "FVNEXP>0 -> FAIL" branch below: exit 0
        # claims a clean result, but ANY extra row in the body — whether it happens to
        # parse as a well-formed exposure or not — is a structural contradiction a
        # corrupt/truncated report can produce (Codex review round 3, item 3: "No
        # vulnerabilities" + a real parseable row + exit=0 must never slip through as
        # PASS just because the row itself looked well-formed).
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — exit 0 (clean) but the body also contains $FVNROW unexplained row(s) ($ATTRIB)" \
            "A clean exit should mean the body is ONLY the clean-exit text — a corrupt or truncated report can contain both that text and leftover/garbled or even well-formed row data. That contradiction is not a basis for a clean PASS, even though the clean-exit phrase is present." \
            "re-generate the report and re-run; report this as a bug if it persists." "ffiec:II.C.10"
      elif [ "$FVEXIT" = "2" ] && [ "${FVCLEANSEEN:-0}" -eq 1 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — contradictory report: exit=2 (vulnerabilities found) but the body also contains the clean-exit text ($ATTRIB)" \
            "This is a structural contradiction the report cannot resolve honestly — the exit code and the body text disagree about whether vulnerabilities were found." \
            "re-generate the report and re-run; report this as a bug if it persists." "ffiec:II.C.10"
      elif [ "$FVEXIT" = "2" ] && [ "${FVNROW:-0}" -eq 0 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — flrtvc.ksh reported vulnerabilities (exit 2) but the report contains 0 parseable rows ($ATTRIB)" \
            "This is a structural contradiction — the exit code claims exposure was found but no data row was recovered from the report. Not a basis for either a clean or a failing result." \
            "re-generate the report and re-run; report this as a bug if it persists." "ffiec:II.C.10"
      elif [ "$FVEXIT" = "2" ] && [ "${FVNEXP:-0}" -eq 0 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — $FVNMALFORMED of $FVNROW reported row(s) could not be parsed (missing fileset or CVE/APAR; $ATTRIB)" \
            "flrtvc.ksh reported vulnerabilities, but every row it printed was missing a fileset or a CVE/APAR identifier once parsed — nothing usable was recovered. Not a clean result." \
            "inspect the report file for corruption/truncation and re-generate it." "ffiec:II.C.10"
      elif [ "${FVNEXP:-0}" -gt 0 ]; then
        HIPERNOTE=""
        [ "${FVNHIPER:-0}" -gt 0 ] && HIPERNOTE=" ($FVNHIPER HIPER — IBM's High Impact PERvasive, highest-urgency class)"
        MALNOTE=""
        [ "${FVNMALFORMED:-0}" -gt 0 ] && MALNOTE=" ($FVNMALFORMED additional reported row(s) could not be parsed and are not included in this count.)"
        STALENOTE=""
        if [ "$FVAGE" -gt 45 ]; then
          STALENOTE=" Note: the underlying apar.csv was $FVAGE days old (vintage $FVDATE) when this report was generated — IBM refreshes roughly monthly; re-generate for full current confidence (a real exposure found on stale data stays real; it does not get more current by re-checking, but a wider gap may exist)."
        fi
        # Believability review 2026-07-13 (review-queue #62, finding #4/#15): $FVNEXP is an
        # EXPOSURE-RECORD count (one flrtvc.ksh row can list more than one CVE, and the same
        # CVE can recur on a different fileset's row) — it is neither a distinct-CVE count
        # nor a distinct-APAR count, and reporting "$FVNEXP CVE/APAR exposure(s)" alone reads
        # as if it were "$FVNEXP distinct CVEs." Report the record count AND the two real,
        # distinct identifier counts separately and honestly (this is a label/rendering
        # fix only — the exposure-record count and the underlying FAIL decision are
        # unchanged).
        IDBREAKDOWN=""
        if [ "${FVNCVE:-0}" -gt 0 ] || [ "${FVNAPAR:-0}" -gt 0 ]; then
          IDBREAKDOWN=" — $FVNCVE distinct CVE(s), $FVNAPAR distinct APAR/ifix identifier(s) (an identifier can appear on more than one row, so these do not sum to the exposure-record count)"
        fi
        FV_LADDER_COUNTS=$(printf '%s\n' "$DETAILLINES" | awk -F'\t' '
          NF>=13 {
            if($12!="1") unscored++
            else if($10=="" || $10+0==0) none++
            else if($10+0>=9) critical++
            else if($10+0>=7) high++
            else if($10+0>=4) medium++
            else low++
          }
          END{printf "Critical %d; High %d; Medium %d; Low %d; None %d; Unscored %d",critical+0,high+0,medium+0,low+0,none+0,unscored+0}
        ')
        add patch apar_scan "FLRT APAR exposure scan" FAIL high "CVSS ladder: Known-Exploited NOT_ASSESSED; $FV_LADDER_COUNTS — $FVNEXP exposure record(s)$HIPERNOTE$IDBREAKDOWN: $FVNAMES" \
            "Published fixes you don't have, per IBM's own FLRTVC engine ($ATTRIB) — this box matches $FVNEXP exposure record(s) ($FVNCVE distinct CVE(s), $FVNAPAR distinct APAR/ifix identifier(s)) whose fix exists and is not installed here.$MALNOTE$STALENOTE" \
            "apply the listed APAR/ifix from IBM Fix Central (the bulletin/download URLs are in the JSON exposures[]); re-scan after patching." "ffiec:II.C.10"
        FV_PROVENANCE_REAL=1
        F_EXPOSURES[$((NFIND-1))]="$DETAILLINES"
      elif [ "${FVCLEANSEEN:-0}" -eq 0 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — flrtvc.ksh reported no vulnerabilities (exit 0) but the report body is not the expected clean-exit text ($ATTRIB)" \
            "Exit 0 should mean the report body reads \"No vulnerabilities\" or \"All vulnerabilities fixed.\" — neither was found, so this is not confidently a clean result." \
            "re-generate the report and re-run; report this as a bug if it persists." "ffiec:II.C.10"
      elif [ "$FVAGE" -gt 45 ]; then
        add patch apar_scan "FLRT APAR exposure scan" WARN high "not assessed — underlying apar.csv was $FVAGE days old (vintage $FVDATE) when this report was generated" \
            "0 exposures were found, but the apar.csv this report was generated against predates IBM's roughly-monthly refresh cadence by a meaningful margin — a clean result against stale data is not a current-confidence PASS." \
            "re-fetch today's apar.csv, re-generate the report, and re-scan before treating this as clean." "ffiec:II.C.10"
      else
        # Disclose the captured fileset count (round 6 item 1): a clean result is clean
        # AGAINST THE INVENTORY WE CAPTURED — completeness of that inventory cannot be
        # proven from the inventory itself, so the PASS states its assumption rather
        # than silently implying "complete inventory verified". (Path 2 reports carry
        # no capture count here, so the clause is invoke-mode only.)
        # Disclosure is invoke-mode only: FV_LSLPP_ROWS exists only when AIXray captured
        # the inventory itself (path 1). Keep every reference to it INSIDE this guard —
        # under set -u a bare reference on the path-2 report branch would abort the run.
        FV_CAPNOTE=""; FV_CAPMEAN=""
        if [ "$FV_INVOKED" -eq 1 ]; then
          FV_CAPNOTE=" against the $FV_LSLPP_ROWS filesets captured from this box (NOT an independently verified-complete inventory)"
          FV_CAPMEAN=" IMPORTANT: this clean result is bounded by the inventory captured here — AIXray applies a plausibility floor (row count + base-fileset family) but cannot prove from the capture alone that no installed fileset was omitted, and flrtvc.ksh emits no parsed-fileset count to cross-check. Treat a PASS as \"no exposures among the $FV_LSLPP_ROWS filesets scanned,\" not \"this box is proven exposure-free.\""
        fi
        add patch apar_scan "FLRT APAR exposure scan" PASS high "0 exposures (IBM FLRTVC, report vintage $FVDATE, $ATTRIB)$FV_CAPNOTE" \
            "No exposures found by IBM's own FLRTVC engine$FV_CAPNOTE.$FV_CAPMEAN" "n/a" "ffiec:II.C.10"
        FV_PROVENANCE_REAL=1
      fi
    fi
  fi
  # FV_CLEANUP is the private mode-700 scratch directory created for the invoke-mode
  # path (never a bare glob/file list). Round 8 item 1 (critical): disarm the
  # signal+EXIT cleanup traps and invalidate FV_MADE/FV_TMPDIR FIRST, BEFORE calling
  # rm -rf — not after. The round-7 code did rm -rf THEN disarmed: if this pathname
  # is recreated (predictable name, another actor or a later reuse) and a signal
  # lands in the window between the rm completing and the trap being cleared, the
  # STALE trap (still referencing the old FV_TMPDIR value) would rm -rf whatever now
  # occupies that path — one AIXray no longer owns. Disarming first closes that:
  # once the traps are cleared and FV_MADE/FV_TMPDIR are blanked, nothing running
  # afterward (however long the rm itself takes) can reference this path again. An
  # abort mid-rm (default signal disposition, no trap installed) can still leave the
  # scratch dir's own debris behind — acceptable; deleting a path we no longer own
  # is not.
  if [ -n "$FV_CLEANUP" ]; then
    trap - EXIT HUP INT TERM
    FV_MADE=""
    FV_TMPDIR=""
    rm -rf "$FV_CLEANUP"
  fi

  # data_freshness — how old is this scan's embedded reference data (DATA_VINTAGE vs today)?
  DVJ=$(d2j "$DATA_VINTAGE"); DVAGE=$(( TODAY_J - DVJ ))
  [ "$DVAGE" -lt 0 ] && DVAGE=0
  if [ "$DVAGE" -gt 180 ]; then
    add patch data_freshness "Reference data freshness" WARN high "reference data $DVAGE day(s) old (vintage $DATA_VINTAGE)" \
        "this scan's reference data is over 6 months old — EOS dates, APARs and firmware levels have moved since" \
        "download the current AIXray release; data updates ship whenever IBM publishes relevant bulletins."
  elif [ "$DVAGE" -gt 90 ]; then
    add patch data_freshness "Reference data freshness" WARN med "reference data $DVAGE day(s) old (vintage $DATA_VINTAGE)" \
        "this scan's reference data is over 3 months old — EOS dates, APARs and firmware levels may have moved since" \
        "download the current AIXray release; data updates ship whenever IBM publishes relevant bulletins."
  else
    add patch data_freshness "Reference data freshness" PASS low "reference data $DVAGE day(s) old" \
        "reference data $DVAGE day(s) old — EOS dates, APARs and firmware levels reflect IBM data as of $DATA_VINTAGE." "n/a"
  fi
}

# ---- C. Storage & capacity -------------------------------------------------------------
# ---- storage depth references (refresh: spec 03) --------------------------------------
# Sources: IBM AIX 7.3 LVM & filesystem docs (lsvg/lslv/lsfs/lsps) + live verification on
# an AIX 7.3 LPAR. Physical-partition geometry: mkvg auto-sizes the PP so a disk stays at
# or under ~1016 PPs (the classic per-PV factor); thousands of PPs per disk means the PP
# was set too small (allocation-map bloat, factor forced up). lsfs -q reports "lv size" and
# "fs size" in 512-byte blocks (2048 blocks = 1 MB). Mount options come from `mount`; a vfs
# of "jfs" is the pre-JFS2 legacy filesystem (no >2 TB, weaker concurrency). Paging
# anti-patterns: more than one paging space on one PV (no I/O parallelism), and paging
# confined to rootvg while another VG is online (contends with OS I/O). Modern AIX takes a
# firmware-assisted dump to a dedicated dump device, so paging < RAM is not itself a dump
# risk (informational only).
STOR_PP_PER_PV_HI=3048   # PPs per disk above this => PP size too small (3x the 1016 factor)
STOR_HUGE_PP_MB=512      # PP size (MB) at/above this on a small VG => coarse allocation
STOR_SMALL_VG_PPS=64     # ... "small VG" = fewer than this many total PPs
STOR_SLACK_PCT=10        # fs_lv_slack: warn if unused LV space >= this % of the LV, and
STOR_SLACK_MB=512        # ... >= this many MB in absolute terms
# IBM documents 4 PB as AIX 7.3's architectural JFS2 filesystem maximum.  Use that
# generous ceiling (2^32 MB) so an over-range df token cannot saturate awk's %d.
STOR_FACT_MAX_FS_MB=4294967296
# df rounds %Used to a display percentage.  Permit one point of rounding/reporting
# tolerance, but treat values outside 0..101 as unreadable rather than observed.
STOR_FACT_MAX_USED_PCT=101

function checks_storage {
  typeset DFRAW DFG DFRC DFROWS DFPARSE_OK DFNOTE M U OTH LSPS LSPSRC LSPS_OK LSPSWHY NPS MAXU MAXU_FACT VGL VGLRC VGL_OK VGLWHY VG LVOUT LVRC PVOUT PVRC S MP STALE MISSPV VG_STALE_GAP VG_PVS_GAP ROOTVG_LVL_OK VG_PVLIST VG_PVLIST_RC VG_PVLIST_OK VG_PVLIST_WHY LSP RC BAD DIS SINGLE NP ND
  typeset INHI NVG ALLROOT DUPPV PGNOTE VGO TOT FRE P WORSTP LOWVG ANYLOW LSADP FCS A FST LF LS CRC FCBAD FCTXT
  typeset FCNR FCN FCUR FRC VSCSI VSNOTE FSO NFAIL NWARN NBAD FAILLIST WARNLIST REPOLIST BADLIST OBS PHYS
  typeset INODESTATE INBAD INSEV
  typeset GWORST GEOOBS GEOVG GSUM PPSZ TPP TPV PPPV VGSZMB REALMB VGORC FACTVGBAD FACTVGSEEN WORSTFSFACT MAXINODEFACT UCLASS
  typeset LVPFLAG LVPMIR CPY LVNAME LVLPS LVPPS LVPVS LSLVO IPOL SEPPV LVPEXTRA
  typeset LSFSQ SLKMP SLKBLK SLKLV SLKFS SLKMB SLKPCT JFSLEG MNT TMPSEP NJFS2 ATIMEN NOLOG
  typeset PLNPS PLDUP PLROOT PLTOTMB PLOBS PLNOTE

  # Pre-join df -g continuation lines once, where DFG is captured: a long
  # Filesystem name (NFS/mapped) wraps onto its own line (NF==1) and its numbers
  # land on the next line — column parsing keys on $4 ~ /%/ and $NF==mount, so an
  # un-joined wrap silently drops the row. Rejoin the held name onto its numbers.
  DFRAW=$(aix df_g df -g); DFRC=$?
  if [ "$DFRC" -eq 0 ] && [ -n "$DFRAW" ]; then FACT_STORAGE_DF_READ=1; fi
  DFG=$(printf '%s\n' "$DFRAW" | awk '
    NR==1 { print; next }
    hold != "" { print hold " " $0; hold=""; next }
    NF==1 { hold=$1; next }
    { print }')
  # Structured filesystem rows are a deterministic, mount-sorted reparse of the
  # same df capture. Pseudo filesystems with '-' capacity are not numeric facts.
  DFROWS=0; DFPARSE_OK=0
  if [ "$DFRC" -eq 0 ]; then
    FACT_STORAGE_FS_USED_UNREAD=0; FACT_STORAGE_FS_IUSED_UNREAD=0
    FACT_STORAGE_FS_ROWS=$(printf '%s\n' "$DFG" | awk -v max_mb="$STOR_FACT_MAX_FS_MB" -v max_pct="$STOR_FACT_MAX_USED_PCT" '
      function nfmt(v, s){
        if(v>max_mb){bad_size=1; return ""}
        if(v==int(v)) return sprintf("%d",v)
        s=sprintf("%.6f",v); sub(/0+$/,"",s); sub(/[.]$/,"",s); return s
      }
      NR>1 && $4 ~ /^-?[0-9][0-9]*([.][0-9][0-9]*)?%$/ {
        pct=$4; sub(/%$/,"",pct)
        if(substr(pct,1,1)=="-" || pct+0>max_pct) bad_used=1
      }
      NR>1 && $2 ~ /^[0-9][0-9]*([.][0-9][0-9]*)?$/ {
          size=nfmt($2*1024)
          if(size=="") next
          u="?"; i="?"
          if($4 ~ /^-?[0-9][0-9]*([.][0-9][0-9]*)?%$/){
            uraw=$4; sub(/%$/,"",uraw)
            if(substr(uraw,1,1)!="-" && uraw+0<=max_pct) u=nfmt(uraw+0)
          } else bad_used_token=1
          if($6 ~ /^-?[0-9][0-9]*([.][0-9][0-9]*)?%$/){
            iraw=$6; sub(/%$/,"",iraw)
            if(substr(iraw,1,1)=="-" || iraw+0>max_pct) bad_iused=1
            else i=nfmt(iraw+0)
          } else bad_iused=1
          printf "%s\t%s\t%s\t%s\n",$NF,size,u,i
        }
      END{
        if(bad_size) print "__AIXRAY_INVALID_FS_SIZE__"
        if(bad_used) print "__AIXRAY_INVALID_FS_USED_PCT__"
        if(bad_used_token) print "__AIXRAY_INVALID_FS_USED_TOKEN__"
        if(bad_iused) print "__AIXRAY_INVALID_FS_IUSED_PCT__"
      }' | sort)
    # Preserve whether parsing produced any data rows before the facts validator
    # may clear them wholesale for an invalid token.  Those malformed-row cases
    # retain their dedicated unreadable findings; a genuinely rowless capture
    # must not enter any finding loop at all.
    DFROWS=$(printf '%s\n' "$FACT_STORAGE_FS_ROWS" |
      awk '$0 !~ /^__AIXRAY_INVALID_FS_/ && NF {n++} END{print n+0}')
    case "$FACT_STORAGE_FS_ROWS" in
      *"__AIXRAY_INVALID_FS_SIZE__"*|*"__AIXRAY_INVALID_FS_USED_PCT__"*)
        FACT_STORAGE_FS_ROWS="";;
      *)
        case "$FACT_STORAGE_FS_ROWS" in
          *"__AIXRAY_INVALID_FS_USED_TOKEN__"*) FACT_STORAGE_FS_USED_UNREAD=1;;
        esac
        case "$FACT_STORAGE_FS_ROWS" in
          *"__AIXRAY_INVALID_FS_IUSED_PCT__"*) FACT_STORAGE_FS_IUSED_UNREAD=1;;
        esac
        FACT_STORAGE_FS_ROWS=$(printf '%s\n' "$FACT_STORAGE_FS_ROWS" |
          awk '$0 !~ /^__AIXRAY_INVALID_FS_/ {print}')
        DFPARSE_OK=1
        ;;
    esac
  fi
  if [ -n "$FACT_STORAGE_FS_ROWS" ]; then
    if [ "$FACT_STORAGE_FS_USED_UNREAD" -eq 0 ]; then
      WORSTFSFACT=$(printf '%s\n' "$FACT_STORAGE_FS_ROWS" | awk -F'\t' 'NR==1 || $3+0>mx{mx=$3+0; out=$3} END{print out}')
      if valid_json_number "$WORSTFSFACT"; then
        FACT_STORAGE_WORST_FS_PCT="$WORSTFSFACT"
        FACT_STORAGE_WORST_FS_MOUNT=$(printf '%s\n' "$FACT_STORAGE_FS_ROWS" | awk -F'\t' 'NR==1 || $3+0>mx{mx=$3+0; out=$1} END{print out}')
      fi
    fi
    if [ "$FACT_STORAGE_FS_IUSED_UNREAD" -eq 0 ]; then
      MAXINODEFACT=$(printf '%s\n' "$FACT_STORAGE_FS_ROWS" | awk -F'\t' 'NR==1 || $4+0>mx{mx=$4+0; out=$4} END{print out}')
      if valid_json_number "$MAXINODEFACT"; then FACT_STORAGE_MAX_INODE="$MAXINODEFACT"; fi
    fi
  fi
  # A failed, empty, or rowless capture is not evidence.  Use the structured
  # facts' parsed-row gate for every df-derived finding too: rc=0 with zero rows
  # must never fall through to a clean assessment any more than rc!=0 may.
  if [ "$FACT_STORAGE_DF_READ" -ne 1 ] || [ "$DFROWS" -eq 0 ] || [ "$DFPARSE_OK" -ne 1 ]; then
    if [ "$DFRC" -ne 0 ]; then
      OBS="not assessed — df -g capture failed (rc=$DFRC)"
      DFNOTE="df -g did not complete successfully; its stdout was not used as evidence"
    elif [ "$FACT_STORAGE_DF_READ" -ne 1 ]; then
      OBS="not assessed — df -g capture empty (rc=0)"
      DFNOTE="df -g completed with no output; zero filesystem rows were available as evidence"
    elif [ "$DFPARSE_OK" -ne 1 ]; then
      OBS="not assessed — df -g capture unparseable (rc=0)"
      DFNOTE="df -g contained an invalid or implausible filesystem row, so its filesystem table could not be parsed reliably"
    else
      OBS="not assessed — df -g contained no parseable data rows (rc=0)"
      DFNOTE="df -g completed without any parseable data rows; zero filesystem rows were available as evidence"
    fi
    for M in / /var /tmp; do
      add storage "fs_$M" "Filesystem $M" NOT_ASSESSED high \
          "$OBS" \
          "Filesystem use could not be assessed because $DFNOTE." \
          "rerun 'df -g' successfully, then rerun AIXray before treating filesystem capacity as healthy."
    done
    add storage fs_other "Other filesystems" NOT_ASSESSED med \
        "$OBS" \
        "Other-filesystem use could not be assessed because $DFNOTE." \
        "rerun 'df -g' successfully, then rerun AIXray before treating other filesystems as healthy."
    add storage fs_inodes "Inode usage (JFS2)" NOT_ASSESSED med \
        "$OBS" \
        "Inode use could not be assessed because $DFNOTE." \
        "rerun 'df -g' successfully, then rerun AIXray before relying on inode headroom."
  else
  for M in / /var /tmp; do
    U=$(printf '%s\n' "$DFG" | awk -v m="$M" '
      $NF==m {
        raw=$4
        if(raw !~ /%$/ || raw=="%") print "__AIXRAY_UNREADABLE__"
        else {sub(/%$/,"",raw); print raw}
        exit
      }')
    if [ -z "$U" ]; then
      add storage "fs_$M" "Filesystem $M" NOT_ASSESSED high \
          "not assessed — no complete df -g row for $M" \
          "Filesystem use could not be assessed because df -g did not contain a complete row for $M; the capture may be incomplete or the mount may be absent." \
          "verify 'df -g $M' returns a complete row, then rerun AIXray before relying on this filesystem assessment."
      continue
    fi
    UCLASS=$(printf '%s\n' "$U" | awk -v max_pct="$STOR_FACT_MAX_USED_PCT" '
      NR==1 && $0 ~ /^-?[0-9]+([.][0-9]+)?$/ {
        seen=1; u=$0+0
        if(substr($0,1,1)=="-" || u>max_pct) print "unreadable"
        else if(u>=90) print "fail"
        else if(u>=80) print "warn"
        else print "pass"
      }
      END{if(!seen) print "unreadable"}')
    if [ "$UCLASS" = unreadable ]; then
      add storage "fs_$M" "Filesystem $M" NOT_ASSESSED low "not assessed — unreadable %Used" \
          "Filesystem use not assessed — df returned an unreadable or implausible %Used token." \
          "check 'df -g $M' manually and correct the reporting source before relying on this result."
    elif [ "$UCLASS" = fail ]; then
      add storage "fs_$M" "Filesystem $M" FAIL high "${U}% used" \
          "Critically low free space — a full $M stops logging, spooling, even login." \
          "free space now or extend the filesystem (chfs -a size=+1G $M); add an 80% alert."
    elif [ "$UCLASS" = warn ]; then
      add storage "fs_$M" "Filesystem $M" WARN med "${U}% used" \
          "Getting tight — risk of a fill-up outage." "clean up or extend; set an 80% alert."
    else
      add storage "fs_$M" "Filesystem $M" PASS low "${U}% used" "Healthy free space." "n/a"
    fi
  done
  # Other filesystems >=90%. inst.images mounts are deliberately-full install
  # repos (informational, not a FAIL). /usr is sized tight on AIX, so >=90% is a
  # WARN and only >=98% a FAIL; every other non-system mount >=90% is a FAIL.
  FSO=$(printf '%s\n' "$DFG" | awk -v max_pct="$STOR_FACT_MAX_USED_PCT" '
    NR>1 && $2 ~ /^[0-9][0-9]*([.][0-9][0-9]*)?$/ {
      m=$NF
      if (m=="/"||m=="/var"||m=="/tmp") next
      raw=$4
      if (raw !~ /^-?[0-9][0-9]*([.][0-9][0-9]*)?%$/) {
        bad=bad (bn++?", ":"") m; nbad++; next
      }
      p=raw; sub(/%$/,"",p)
      if (substr(p,1,1)=="-" || p+0>max_pct) {
        bad=bad (bn++?", ":"") m; nbad++; next
      }
      p=p+0
      if (p<90) next
      if (index(m,"inst.images")>0) { repo=repo (rn++?", ":"") m " " p "%"; next }
      if (m=="/usr" && p<98) { warn=warn (wn++?", ":"") m " " p "%"; nwarn++ }
      else { fail=fail (fn++?", ":"") m " " p "%"; nfail++ }
    }
    END{ printf "%d\t%d\t%s\t%s\t%s\t%d\t%s", nfail+0, nwarn+0, fail, warn, repo, nbad+0, bad }')
  NFAIL=$(printf '%s' "$FSO" | awk -F'\t' '{print $1+0}')
  NWARN=$(printf '%s' "$FSO" | awk -F'\t' '{print $2+0}')
  FAILLIST=$(printf '%s' "$FSO" | awk -F'\t' '{print $3}')
  WARNLIST=$(printf '%s' "$FSO" | awk -F'\t' '{print $4}')
  REPOLIST=$(printf '%s' "$FSO" | awk -F'\t' '{print $5}')
  NBAD=$(printf '%s' "$FSO" | awk -F'\t' '{print $6+0}')
  BADLIST=$(printf '%s' "$FSO" | awk -F'\t' '{print $7}')
  if [ "$NBAD" -gt 0 ]; then
    OBS="not assessed — unreadable %Used: $BADLIST"
    [ -n "$FAILLIST" ] && OBS="$OBS; critical: $FAILLIST"
    [ -n "$WARNLIST" ] && OBS="$OBS; watch: $WARNLIST"
    [ -n "$REPOLIST" ] && OBS="$OBS; repo (informational): $REPOLIST"
    add storage fs_other "Other filesystems" NOT_ASSESSED med "$OBS" \
        "Other-filesystem use was not assessed completely — df returned an unreadable or implausible %Used token for: $BADLIST." \
        "check 'df -g' manually for the named mount(s) and correct the reporting source before treating other filesystems as healthy."
  elif [ "$NFAIL" -gt 0 ]; then
    OBS="$FAILLIST"
    [ -n "$WARNLIST" ] && OBS="$OBS; watch: $WARNLIST"
    [ -n "$REPOLIST" ] && OBS="$OBS; repo (informational): $REPOLIST"
    add storage fs_other "Other filesystems" FAIL med "$OBS" \
        "One or more non-system filesystems are critically full." "free space or extend them; add monitoring."
  elif [ "$NWARN" -gt 0 ]; then
    OBS="$WARNLIST"
    [ -n "$REPOLIST" ] && OBS="$OBS; repo (informational): $REPOLIST"
    add storage fs_other "Other filesystems" WARN med "$OBS" \
        "/usr is often sized tight on AIX — over 90% is worth watching, but only critical at 98%." \
        "review /usr growth (installed filesets; clear /usr/sys/inst.images repos); extend it if it keeps climbing."
  else
    OBS="none above 90%"
    [ -n "$REPOLIST" ] && OBS="$OBS; repo (informational): $REPOLIST"
    add storage fs_other "Other filesystems" PASS low "$OBS" "No other filesystem is critically full." "n/a"
  fi

  # fs_inodes — JFS2 inode headroom (df -g column 6, %Iused)
  INODESTATE=$(printf '%s\n' "$DFG" | awk -v max_pct="$STOR_FACT_MAX_USED_PCT" '
    NR>1 && $2 ~ /^[0-9][0-9]*([.][0-9][0-9]*)?$/ {
      if($6 ~ /^-?[0-9][0-9]*([.][0-9][0-9]*)?%$/){
        raw=$6; sub(/%$/,"",raw)
        if(substr(raw,1,1)=="-" || raw+0>max_pct)
          bad=bad (bn++?", ":"") $NF
        else if(raw+0>=90)
          hi=hi (hn++?", ":"") $NF " " $6
      } else bad=bad (bn++?", ":"") $NF
    }
    END{printf "%s\t%s",hi,bad}')
  INHI=$(printf '%s' "$INODESTATE" | awk -F'\t' '{print $1}')
  INBAD=$(printf '%s' "$INODESTATE" | awk -F'\t' '{print $2}')
  if [ -n "$INBAD" ]; then
    OBS="unreadable %Iused: $INBAD"
    [ -n "$INHI" ] && OBS="$INHI; $OBS"
    if [ -n "$INHI" ]; then INSEV=med; else INSEV=low; fi
    add storage fs_inodes "Inode usage (JFS2)" NOT_ASSESSED "$INSEV" "not assessed — $OBS" \
        "Inode use not assessed for every real filesystem — df returned an unreadable or implausible %Iused token for: $INBAD." \
        "check 'df -g' manually for the named mount(s) and correct the reporting source before relying on inode headroom."
  elif [ -n "$INHI" ]; then
    add storage fs_inodes "Inode usage (JFS2)" WARN med "$INHI" \
        "One or more JFS2 filesystems are past 90% inodes used. JFS2 grows inodes dynamically, so sustained 90%+ is usually fine — but it is still worth a look." \
        "check the mount for a flood of tiny files (find <mount> -xdev | wc -l); clean up or plan to extend if it keeps climbing."
  else
    add storage fs_inodes "Inode usage (JFS2)" PASS low "no filesystem above 90% inodes" \
        "JFS2 inode usage has headroom on every filesystem." "n/a"
  fi
  fi

  # online volume groups (used by paging layout, vg_capacity, and the VG loop below)
  VGL=$(aix lsvg_o lsvg -o); VGLRC=$?
  VGL_OK=0; VGLWHY=""
  if [ "$VGLRC" -ne 0 ]; then
    VGLWHY="not assessed — lsvg -o capture failed (rc=$VGLRC)"
  elif [ -z "$VGL" ]; then
    VGLWHY="not assessed — lsvg -o capture empty (rc=0)"
  elif printf '%s\n' "$VGL" | awk '
      NF {
        n++
        if (NF != 1 || $1 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) bad=1
      }
      END { if (n == 0 || bad) exit 1 }
    '
  then
    VGL_OK=1
    FACT_STORAGE_VG_READ=1
  else
    VGLWHY="not assessed — lsvg -o capture unparseable (rc=0)"
  fi
  if [ "$VGL_OK" -eq 1 ]; then
    NVG=$(printf '%s\n' "$VGL" | awk 'NF{n++} END{print n+0}')
  else
    VGL=""; NVG=0
  fi

  # paging space
  LSPS=$(aix lsps_a lsps -a); LSPSRC=$?
  LSPS_OK=0; LSPSWHY=""
  if [ "$LSPSRC" -ne 0 ]; then
    LSPSWHY="not assessed — lsps -a capture failed (rc=$LSPSRC)"
  elif [ -z "$LSPS" ]; then
    LSPSWHY="not assessed — lsps -a capture empty (rc=0)"
  elif printf '%s\n' "$LSPS" | awk -v max_pct="$STOR_FACT_MAX_USED_PCT" '
      NR == 1 {
        if ($1 != "Page" || $2 != "Space" || $3 != "Physical" ||
            $4 != "Volume" || $5 != "Volume" || $6 != "Group" ||
            $7 != "Size" || $8 != "%Used" || $9 != "Active" ||
            $10 != "Auto" || $11 != "Type" || $12 != "Chksum") bad=1
        next
      }
      NF {
        n++
        if (NF < 9 ||
            $1 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/ ||
            $2 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/ ||
            $3 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/ ||
            $4 !~ /^[0-9][0-9]*(MB|GB)$/ ||
            $5 !~ /^[0-9][0-9]*$/ || $5 + 0 > max_pct ||
            $6 !~ /^(yes|no)$/ || $7 !~ /^(yes|no)$/ ||
            $8 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/ ||
            $9 !~ /^[0-9][0-9]*$/) bad=1
      }
      END { if (n == 0 || bad) exit 1 }
    '
  then
    LSPS_OK=1
    FACT_PAGING_READ=1
  else
    LSPSWHY="not assessed — lsps -a capture unparseable (rc=0)"
  fi
  if [ "$LSPS_OK" -eq 1 ]; then
    NPS=$(printf '%s\n' "$LSPS" | awk 'NR>1 && NF>1 {n++} END{print n+0}')
    MAXU=$(printf '%s\n' "$LSPS" | awk 'NR>1 && NF>1 {u=$5+0; if (u>mx) mx=u} END{print mx+0}')
    ALLROOT=$(printf '%s\n' "$LSPS" | awk 'NR>1 && NF>1 {t++; if ($3=="rootvg") r++} END{print (t>0 && r==t)?1:0}')
    DUPPV=$(printf '%s\n' "$LSPS" | awk 'NR>1 && NF>1 {c[$2]++} END{d=0; for (k in c) if (c[k]>1) d=1; print d}')
    NPS=$(printf '%s\n' "$LSPS" | awk 'NR>1 && NF>1{n++} END{if(n>0)print n}')
    if valid_json_number "$NPS"; then FACT_PAGING_SPACES="$NPS"; fi
    if [ -n "$FACT_PAGING_SPACES" ]; then
      MAXU_FACT=$(printf '%s\n' "$LSPS" | awk '
        NR>1 && NF>1 {n++; if($5 !~ /^[0-9][0-9]*$/) bad=1; else if(!seen || $5+0>mx){mx=$5+0; out=$5; seen=1}}
        END{if(n>0 && !bad && seen)print out}')
      if valid_json_number "$MAXU_FACT"; then FACT_PAGING_MAX="$MAXU_FACT"; fi
      [ "$ALLROOT" -eq 1 ] && FACT_PAGING_ROOT=true || FACT_PAGING_ROOT=false
      [ "$DUPPV" -eq 1 ] && FACT_PAGING_DUP=true || FACT_PAGING_DUP=false
    fi
    PGNOTE=""
    if [ "${NVG:-0}" -gt 1 ] && [ "$ALLROOT" -eq 1 ]; then
      PGNOTE=" Every paging space sits in rootvg while another VG is online — spreading paging onto another VG's disks avoids a rootvg I/O bottleneck."
    elif [ "$DUPPV" -eq 1 ]; then
      PGNOTE=" Multiple paging spaces share one physical volume — they contend for the same disk, so the extra space buys little."
    fi
    if [ "$MAXU" -ge 70 ]; then
      add storage paging "Paging space" FAIL high "$NPS space(s), ${MAXU}% used" \
          "The box is paging heavily — performance is suffering now, and paging-space-full kills processes.$PGNOTE" \
          "find the memory consumer (svmon -P | head); add RAM or paging space as a stopgap."
    elif [ "$MAXU" -ge 40 ]; then
      add storage paging "Paging space" WARN med "$NPS space(s), ${MAXU}% used" \
          "Sustained paging use signals memory pressure.$PGNOTE" "investigate memory consumers; review sizing."
    else
      add storage paging "Paging space" PASS low "$NPS space(s), ${MAXU}% used" "Memory pressure is low.$PGNOTE" "n/a"
    fi
  else
    add storage paging "Paging space" NOT_ASSESSED med "$LSPSWHY" \
        "Paging-space use could not be assessed because lsps -a failed, returned no evidence, or did not match the expected AIX output shape." \
        "run 'lsps -a' manually, then rerun AIXray before treating paging-space use as healthy."
  fi

  # volume groups: stale copies + missing disks. Each verdict has its own
  # completeness state: an empty accumulator is clean evidence only after every
  # required command completed and every capture matched its stable AIX shape.
  STALE=""; MISSPV=""; VG_STALE_GAP=""; VG_PVS_GAP=""
  ROOTVG_LVL=""; ROOTVG_LVL_RC=1; ROOTVG_LVL_OK=0
  if [ "${VGL_OK:-0}" -ne 1 ]; then
    VG_STALE_GAP="${VGLWHY:-not assessed — lsvg -o capture unavailable}"
    VG_PVS_GAP="$VG_STALE_GAP"
  fi

  VG_PVLIST=$(aix lspv lspv); VG_PVLIST_RC=$?
  VG_PVLIST_OK=0; VG_PVLIST_WHY=""
  if [ "$VG_PVLIST_RC" -ne 0 ]; then
    VG_PVLIST_WHY="lspv capture failed (rc=$VG_PVLIST_RC)"
  elif [ -z "$VG_PVLIST" ]; then
    VG_PVLIST_WHY="lspv capture empty (rc=0)"
  elif printf '%s\n' "$VG_PVLIST" | awk '
      NF {
        n++
        if (NF < 3 || NF > 4 || $1 !~ /^hdisk[0-9][0-9]*$/ ||
            $2 !~ /^(none|[0-9A-Fa-f]{16,})$/ ||
            $3 !~ /^[A-Za-z0-9_.-]+$/ ||
            (NF == 4 && $4 !~ /^[A-Za-z0-9_.-]+$/)) bad=1
      }
      END { if (n == 0 || bad) exit 1 }
    '
  then
    VG_PVLIST_OK=1
  else
    VG_PVLIST_WHY="lspv capture unparseable (rc=0)"
  fi
  if [ "$VG_PVLIST_OK" -ne 1 ]; then
    VG_PVS_GAP="${VG_PVS_GAP}${VG_PVS_GAP:+; }$VG_PVLIST_WHY"
  fi

  if [ "${VGL_OK:-0}" -eq 1 ]; then
  for VG in $VGL; do
    LVOUT=$(aix "lsvg_l_$VG" lsvg -l "$VG"); LVRC=$?
    [ "$VG" = "rootvg" ] && { ROOTVG_LVL="$LVOUT"; ROOTVG_LVL_RC=$LVRC; }
    if [ "$LVRC" -ne 0 ]; then
      VG_STALE_GAP="${VG_STALE_GAP}${VG_STALE_GAP:+; }$VG lsvg -l capture failed (rc=$LVRC)"
    elif [ -z "$LVOUT" ]; then
      VG_STALE_GAP="${VG_STALE_GAP}${VG_STALE_GAP:+; }$VG lsvg -l capture empty (rc=0)"
    elif printf '%s\n' "$LVOUT" | awk -v vg="$VG" '
        NR == 1 { if ($1 != vg ":") bad=1; next }
        NR == 2 {
          if ($1 != "LV" || $2 != "NAME" || $3 != "TYPE" ||
              $4 != "LPs" || $5 != "PPs" || $6 != "PVs") bad=1
          next
        }
        NF {
          n++
          if (NF < 7 || $1 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/ ||
              $2 !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/ ||
              $3 !~ /^[1-9][0-9]*$/ || $4 !~ /^[1-9][0-9]*$/ ||
              $5 !~ /^[1-9][0-9]*$/ ||
              $6 !~ /^(open|closed)\/(syncd|stale)$/) bad=1
        }
        END { if (n == 0 || bad) exit 1 }
      '
    then
      [ "$VG" = "rootvg" ] && ROOTVG_LVL_OK=1
      S=$(printf '%s\n' "$LVOUT" | awk '$6 ~ /\/stale$/ {printf "%s%s",(n++?",":""),$1}')
      [ -n "$S" ] && STALE="$STALE $VG($S)"
    else
      VG_STALE_GAP="${VG_STALE_GAP}${VG_STALE_GAP:+; }$VG lsvg -l capture unparseable (rc=0)"
    fi

    PVOUT=$(aix "lsvg_p_$VG" lsvg -p "$VG"); PVRC=$?
    if [ "$PVRC" -ne 0 ]; then
      VG_PVS_GAP="${VG_PVS_GAP}${VG_PVS_GAP:+; }$VG lsvg -p capture failed (rc=$PVRC)"
    elif [ -z "$PVOUT" ]; then
      VG_PVS_GAP="${VG_PVS_GAP}${VG_PVS_GAP:+; }$VG lsvg -p capture empty (rc=0)"
    elif printf '%s\n' "$PVOUT" | awk -v vg="$VG" '
        NR == 1 { if ($1 != vg ":") bad=1; next }
        NR == 2 {
          if ($1 != "PV_NAME" || $2 != "PV" || $3 != "STATE" ||
              $4 != "TOTAL" || $5 != "PPs") bad=1
          next
        }
        NF {
          n++
          if (NF < 5 || $1 !~ /^hdisk[0-9][0-9]*$/ ||
              $2 !~ /^(active|missing|removed)$/ ||
              $3 !~ /^[0-9][0-9]*$/ || $4 !~ /^[0-9][0-9]*$/) bad=1
        }
        END { if (n == 0 || bad) exit 1 }
      '
    then
      MP=$(printf '%s\n' "$PVOUT" | awk '$2=="missing" || $2=="removed" {printf "%s%s",(n++?",":""),$1}')
      [ -n "$MP" ] && MISSPV="$MISSPV $VG($MP)"
    else
      VG_PVS_GAP="${VG_PVS_GAP}${VG_PVS_GAP:+; }$VG lsvg -p capture unparseable (rc=0)"
    fi
  done
  fi
  if [ -n "$VG_STALE_GAP" ]; then
    add storage vg_stale "LV mirror sync" NOT_ASSESSED high "not assessed — $VG_STALE_GAP" \
        "LV mirror synchronization could not be assessed because one or more lsvg captures failed, were empty, or were unparseable." \
        "run 'lsvg -o' and 'lsvg -l <vg>' manually for every online VG, then rerun AIXray."
  elif [ -n "$STALE" ]; then
    add storage vg_stale "LV mirror sync" FAIL high "stale:$STALE" \
        "Mirror copies are out of sync — you believe you are protected and you are not." \
        "check the underlying disk first (errpt, lsvg -p), then resync with 'syncvg -v <vg>'."
  else
    add storage vg_stale "LV mirror sync" PASS low "no stale partitions" "All logical volume copies are in sync." "n/a"
  fi
  if [ -n "$VG_PVS_GAP" ]; then
    add storage vg_pvs "Volume group disks" NOT_ASSESSED high "not assessed — $VG_PVS_GAP" \
        "Volume-group disk state could not be assessed because lsvg or lspv evidence failed, was empty, unparseable, or internally incomplete." \
        "run 'lsvg -o', 'lsvg -p <vg>', and 'lspv' manually, then rerun AIXray."
  elif [ -n "$MISSPV" ]; then
    add storage vg_pvs "Volume group disks" FAIL high "missing:$MISSPV" \
        "A disk the volume group expects is gone — data redundancy or capacity is already degraded." \
        "identify the disk (lsvg -p, errpt), engage storage/hardware support before the next failure."
  else
    add storage vg_pvs "Volume group disks" PASS low "all PVs active" "Every volume group disk is present and active." "n/a"
  fi

  # hd5_sizing — boot-image LV sizing (docs/aixray-spec-v2.md Sec 5 cap-filesets row): target
  # 64 MB (current IBM guidance), older 32 MB guidance cited alongside so a 32 MB hd5 on an older
  # box is not treated as automatically fine. hd5's own LP count comes from the SAME 'lsvg -l
  # rootvg' capture the vg_stale/vg_pvs checks above already made (ROOTVG_LVL, no duplicate
  # command); PP size comes from 'lsvg rootvg'. Live-verified on both real lab boxes, 2026-07-13:
  # lab-host-02 (7.2) hd5 = 2 LPs x 32 MB PP = 64 MB (current target, PASS); lab-host-03 (7.1) hd5 =
  # 1 LP x 32 MB PP = 32 MB (the older-guidance size exactly — a genuine, real WARN case, not a
  # hypothetical).
  RVGOUT=$(aix lsvg_rootvg lsvg rootvg); RVGOUT_RC=$?
  # NOTE: 'lsvg <vg>'s "PP SIZE:" shares its output line with "VG STATE:" (two
  # colon-separated key:value pairs on one row) -- a naive '-F: {print $2}' split
  # grabs the WRONG middle field ("...active...PP SIZE", no digits at all), a
  # real bug caught live against lab-host-02 during this check's own build (round 1
  # self-review: HD5LPS parsed correctly but PPSZ silently came back empty,
  # correctly degrading to WARN "unreadable" rather than a wrong number — but
  # still wrong, fixed here with a targeted sed extraction instead of a
  # positional colon-field assumption).
  PPSZ=$(printf '%s\n' "$RVGOUT" | sed -n 's/.*PP SIZE: *\([0-9][0-9]*\).*/\1/p' | head -1)
  HD5LPS=$(printf '%s\n' "$ROOTVG_LVL" | awk '$1=="hd5"{print $3; exit}')
  # hd5's own PV count from the SAME already-validated 'lsvg -l rootvg' row (field 5,
  # PVs) -- the independent completeness cross-check for the 'lslv -m hd5' mirror map
  # below (Codex primary review round 4, 2026-07-14, HIGH: HD5PVS was derived SOLELY
  # from whichever 'lslv -m' columns survived capture, with no completeness check at
  # all -- a capture truncated to lose the PP2/PV2 columns hid a mirror copy entirely,
  # and if the still-visible copy happened to be contiguous this reached a false PASS
  # built on a mirror map that was never actually complete).
  HD5PVCNT=$(printf '%s\n' "$ROOTVG_LVL" | awk '$1=="hd5"{print $5; exit}')
  # Both source commands must have actually SUCCEEDED, not just produced a value that
  # happens to parse -- a failed 'lsvg rootvg' or 'lsvg -l rootvg' invocation that
  # nonetheless leaves plausible-looking stale/partial text behind must never be trusted
  # into a confident PASS/WARN/FAIL size verdict (Codex primary review, M5, round 2,
  # finding #4: this check recorded ROOTVG_LVL_RC via the shared vg_stale/vg_pvs capture
  # above but never actually checked it here; 'lsvg rootvg's own rc was not recorded at
  # all). Same failed-source-to-verdict laundering class already fixed for the UAK checks
  # and multibos_residue in this same milestone.
  # A zero LP count or zero PP size is structurally invalid capture data (Codex primary
  # review, 2026-07-14, LOW: the digits-only check below happily accepted "0", computing
  # HD5MB=0 and reaching a confident FAIL "0MB" -- a corrupt/garbled capture reporting
  # zero is not trustworthy evidence hd5 is actually zero-sized) -- treated the same as
  # non-numeric: never trusted into a size verdict.
  if [ "$ROOTVG_LVL_RC" -eq 0 ] && [ "$ROOTVG_LVL_OK" -eq 1 ] &&
     [ "$RVGOUT_RC" -eq 0 ] && [ -n "$PPSZ" ] && [ -n "$HD5LPS" ]; then
    case "$PPSZ$HD5LPS" in
      *[!0-9]*) HD5MB="";;
      *) [ "$PPSZ" -gt 0 ] && [ "$HD5LPS" -gt 0 ] && HD5MB=$(( PPSZ * HD5LPS )) || HD5MB="";;
    esac
  else
    HD5MB=""
  fi
  # Contiguity — size alone is NOT "upgrade-ready": both the spec (aixray-spec-v2.md Sec 5
  # cap-filesets row) and the sourced rule (upgrade-readiness-checks.md Sec 4) require hd5's
  # PPs to be CONTIGUOUS; noncontiguity is explicitly "not ready" regardless of total size
  # (Codex primary review, M5, HIGH finding #1: the size math above was being trusted into a
  # PASS with no contiguity check at all). 'lslv -m hd5' identifies which disk(s) hd5's
  # copies land on; 'lspv -M <hdiskN>' then independently confirms those PPs form a
  # contiguous run on that disk. Never a PASS on inconclusive or noncontiguous evidence: no
  # readable PV/contiguity signal degrades to WARN "not assessed," never PASS.
  #
  # Multi-copy guard (Codex primary review, 2026-07-14, HIGH finding #2): a MIRRORED hd5
  # has a full copy of every LP on EACH of its PVs (real 'lslv -m hd5' rows carry PP1/PV1,
  # PP2/PV2, PP3/PV3 column pairs, one pair per mirror copy) -- checking only copy 1's PV
  # (the prior version's HD5PV, singular) let a genuinely noncontiguous SECOND copy still
  # report an unscoped "contiguous" PASS, since copy 1 alone can look fine. Every PV any
  # row names for hd5 is enumerated (deduplicated, first-seen order) and independently
  # contiguity-checked below; the combined verdict is never better than the worst
  # individually-confirmed copy.
  LSLVM=$(aix lslv_m_hd5 lslv -m hd5); LSLVM_RC=$?
  HD5PVS=""
  if [ "$LSLVM_RC" -eq 0 ] && [ -n "$LSLVM" ]; then
    # skip the 'hd5:<mountpt>' header (line 1) and the 'LP PP1 PV1 ...' column-header row
    # (line 2); a real data row's own PP1 (field 2) must be numeric. Every odd field from 3
    # onward (PV1, PV2, PV3 -- whichever mirror-copy columns this row actually carries) is a
    # candidate PV; deduplicated across every row via the second awk's !seen[] idiom.
    HD5PVS=$(printf '%s\n' "$LSLVM" | awk 'NR>2 && NF>=3 && $2 ~ /^[0-9]+$/ {
        for (i=3; i<=NF; i+=2) if ($i != "" && $i != "-") print $i
      }' | awk '!seen[$0]++')
  fi
  # The mirror-map token is about to become both a fixture/command key and customer-
  # visible PASS evidence, so validate it before either use. AIX PV device names for this
  # supported path are hdisk plus a nonempty decimal index. The independently captured
  # `lspv` device list is required, must be usable, and must contain every shaped name;
  # two colluding files cannot invent NOT_A_PV!/hdisk9 and make it trusted by spelling it
  # consistently in `lslv -m` and `lspv -M`.
  HD5PVBAD=""; HD5PVLIST=""; HD5PVLIST_RC=127
  if [ -n "$HD5PVS" ]; then
    HD5PVLIST="$VG_PVLIST"; HD5PVLIST_RC=$VG_PVLIST_RC
    # Feed the extracted values as literal lines. An unquoted `for ... in $HD5PVS`
    # lets the launch directory pathname-expand an attacker-controlled token such as
    # hdisk* into a trusted hdisk0 before the validation below ever sees it.
    while IFS= read -r HPVC; do
      [ -n "$HPVC" ] || continue
      HPVWHY=""; HDISKNUM=${HPVC#hdisk}
      case "$HPVC" in
        hdisk[0-9]*) case "$HDISKNUM" in ''|*[!0-9]*) HPVWHY="not a valid hdisk device name";; esac ;;
        *) HPVWHY="not a valid hdisk device name" ;;
      esac
      if [ -z "$HPVWHY" ]; then
        if [ "${VG_PVLIST_OK:-0}" -ne 1 ]; then
          HPVWHY="could not be checked because the captured lspv device list failed, was empty, or was unparseable"
        else
          printf '%s\n' "$HD5PVLIST" | awk -v want="$HPVC" '$1==want{found=1} END{exit !found}' || \
            HPVWHY="not present in the captured lspv device list"
        fi
      fi
      [ -n "$HPVWHY" ] && HD5PVBAD="${HD5PVBAD}${HD5PVBAD:+, }$HPVC ($HPVWHY)"
    done <<EOF
$HD5PVS
EOF
  fi
  HD5MAPBAD=""; HD5PVQUERY="$HD5PVS"
  if [ -n "$HD5PVBAD" ]; then
    HD5MAPBAD="'lslv -m hd5' contains an invalid or independently unrecognized PV token: $HD5PVBAD"
    HD5PVQUERY=""
  fi
  HD5CONTIG=""
  HD5FOUNDCNT=""
  HD5OKPV=""; HD5BADPV=""; HD5INCPV=""; HD5NOSIGPV=""; HD5INCDETAIL=""
  # Mirror-map completeness cross-check (Codex primary review round 4, 2026-07-14,
  # HIGH): the PV set parsed out of 'lslv -m hd5' must agree with the PV count
  # 'lsvg -l rootvg' independently states for hd5 (HD5PVCNT, field 5 of the same
  # already-rc-validated capture the LP count comes from). Fewer PVs seen = the map
  # was truncated and a whole mirror copy may be invisible; more = garbled. Either
  # way the map cannot be trusted into a PASS -- it is routed to the same detected-
  # assessment-gap NOT_ASSESSED outcome as a truncated 'lspv -M' capture (an
  # explicitly noncontiguous VISIBLE copy still wins, below: a real noncontiguity
  # signal is actionable regardless of what else the map failed to show).
  if [ -n "$HD5PVS" ]; then
    # Count the parsed records without subjecting untrusted values to a second shell
    # word-splitting/pathname-expansion pass. Only validated hdiskN values flow into
    # HD5PVQUERY and its per-PV command loop below.
    HD5PVSEEN=$(printf '%s\n' "$HD5PVS" | awk 'NF {n++} END {print n+0}')
    case "$HD5PVCNT" in
      ''|*[!0-9]*)
        HD5MAPBAD="hd5's own PV count could not be read from 'lsvg -l rootvg' (got '$HD5PVCNT'), so the 'lslv -m hd5' mirror map cannot be confirmed complete" ;;
      *)
        if [ "$HD5PVSEEN" -ne "$HD5PVCNT" ]; then
          HD5MAPBAD="'lslv -m hd5' shows $HD5PVSEEN PV(s) but 'lsvg -l rootvg' says hd5 spans $HD5PVCNT -- the mirror map looks truncated or garbled and may hide an entire copy"
        fi ;;
    esac
  fi
  if [ -n "$HD5PVS" ]; then
    for HPV in $HD5PVQUERY; do
      LSPVM=$(aix "lspv_M_$HPV" lspv -M "$HPV"); LSPVM_RC=$?
      if [ "$LSPVM_RC" -eq 0 ] && [ -n "$LSPVM" ]; then
        # Live-verified against real 'lspv -M' output on lab-host-02/lab-host-03, 2026-07-13: it
        # emits ONE PP per line (never a merged 'N-M' range) -- an earlier version of this
        # check wrongly assumed 'lspv -M' merges each LV's own consecutive PPs into a single
        # line and counted LINES naming hd5 as the contiguity signal; on real output that
        # miscounted a genuinely contiguous 2-PP hd5 (one line per PP) as "2 blocks" ==
        # noncontiguous -- a false FAIL-shaped WARN caught only by running against the real
        # lab boxes before shipping (exactly the failure mode 'prove before deploy' exists to
        # catch). Fixed here to build the actual SET of PP numbers hd5 owns on this disk
        # (expanding any 'N-M' range token defensively, in case a future AIX/lspv variant does
        # merge) and check that set has no gaps between its min and max -- the literal
        # "consecutive PPs" test the spec/sourced rule describe. Exact field-token match on
        # 'hd5' (never a substring match that would also catch a real 'hd50'-named LV); any
        # unparsable PP token on a matching line is treated as inconclusive, never guessed at.
        #
        # Capture-completeness guard (false-clean, cardinal-sin class, 2026-07-14): the above
        # rebuild-the-set logic only ever sees whatever lines actually made it into $LSPVM --
        # if the 'lspv -M' capture itself is TRUNCATED mid-stream (cut off after some but not
        # all of hd5's own PP lines, rc=0 nonetheless -- the exact failure mode this codebase's
        # own fixture-replay convention and a flaky/interrupted real capture can both produce),
        # the partial SET this builds can look trivially "contiguous" (a subset of a
        # noncontiguous layout, or simply too few PPs to show the real gap) and this used to
        # report "yes" -- a false PASS built on data that was never actually complete. We
        # already independently know hd5's true PP-per-copy count on this PV from the
        # already-validated 'lsvg -l rootvg' capture (HD5LPS, same source vg_stale/vg_pvs
        # above rely on) -- cross-check the count of DISTINCT PPs this capture actually shows
        # for hd5 against HD5LPS; anything other than an exact match means the capture cannot
        # be trusted to have shown the whole picture (fewer PPs = truncated before showing them
        # all; more PPs = a garbled/duplicated capture, equally untrustworthy) and is reported
        # as its own "incomplete" outcome, never silently folded into "yes" or "no". Also
        # requires the field immediately AFTER 'hd5' (its own per-copy LP-index marker,
        # 'hd5:N') to be present and numeric, and tracks the SET of those LP-index markers
        # separately from the physical PP set (Codex primary review, 2026-07-14, HIGH finding
        # #1: a row truncated right after the bare 'hd5' token, with no trailing LP-index
        # field at all, was silently accepted as a valid match; and two DIFFERENT physical PPs
        # both mislabeled as hd5's SAME LP index, with hd5's other LP index never appearing at
        # all, still produced the expected PHYSICAL-PP count and a spuriously "contiguous"
        # PASS -- reproduced live against a synthetic capture. Requiring the LP-index set's own
        # size to also equal the expected count closes both).
        # Row grammar is validated per line, never token-scanned (Codex primary review
        # round 4, 2026-07-14, HIGH: the previous version searched for an 'hd5' token at
        # ANY field position with numeric neighbors, so a garbled line like
        # 'garbage 1 hd5 1' -- valid-shaped tokens in coincidentally-right positions on a
        # line that matches no lspv -M row grammar at all -- was counted as a real PP and
        # could satisfy the completeness guard into a PASS). IBM documents 'lspv -M'
        # rows as 'PVname:PPnum[-PPnum] [LVname:LPnum[:Copynum] [PPstate]]': every
        # nonempty line must therefore start with EXACTLY the PV this capture was taken
        # from ($1 == pv) followed by a numeric PP token ($2); hd5 is only ever accepted
        # at the LVname position ($3), with its numeric LP index at $4. Any nonempty
        # line violating that grammar marks the WHOLE capture untrustworthy ("bad" --
        # the NOT_ASSESSED route), never skipped past.
        RES=$(printf '%s\n' "$LSPVM" | awk -F'[ \t:]+' -v want="$HD5LPS" -v pv="$HPV" '
            NF == 0 { next }
            {
              if ($1 != pv) { badpp=1; exit }
              pp=$2
              if (pp ~ /^[0-9]+-[0-9]+$/) { split(pp,r,"-"); lo=r[1]+0; hi=r[2]+0 }
              else if (pp ~ /^[0-9]+$/) { lo=pp+0; hi=pp+0 }
              else { badpp=1; exit }
              if (pp !~ /^[1-9][0-9]*$/ && pp !~ /^[1-9][0-9]*-[1-9][0-9]*$/) badindex=1
              if (NF >= 3 && $3 == "hd5") {
                lp=$4
                if (lp !~ /^[0-9]+$/) { badpp=1; exit }
                if (lp !~ /^[1-9][0-9]*$/) badindex=1
                for (p=lo; p<=hi; p++) seen[p]=1
                lpseen[lp]=1
                found=1
              }
            }
            END {
              if (badpp) { print "bad:0"; exit }
              if (badindex) { print "bad:0"; exit }
              if (!found) { print "none:0"; exit }
              cnt=0; for (p in seen) cnt++
              lpcnt=0; for (l in lpseen) lpcnt++
              lpbad=0
              if (want ~ /^[1-9][0-9]*$/) for (l=1; l<=want+0; l++) if (!(l in lpseen)) lpbad=1
              if (want !~ /^[1-9][0-9]*$/ || cnt != want+0 || lpcnt != want+0 || lpbad) { print "incomplete:" cnt; exit }
              mn=""; mx=""
              for (p in seen) { if (mn=="" || p<mn) mn=p; if (mx=="" || p>mx) mx=p }
              ok=1
              for (p=mn; p<=mx; p++) if (!(p in seen)) ok=0
              print (ok ? "yes:" cnt : "no:" cnt)
            }')
      else
        RES="none:0"
      fi
      RSTAT="${RES%%:*}"; RCNT="${RES#*:}"
      case "$RSTAT" in
        yes) HD5OKPV="$HD5OKPV$HPV "; HD5FOUNDCNT="$RCNT" ;;
        no) HD5BADPV="$HD5BADPV$HPV " ;;
        incomplete|bad)
          HD5INCPV="$HD5INCPV$HPV "
          HD5INCDETAIL="${HD5INCDETAIL}${HD5INCDETAIL:+, }$HPV ($RCNT/$HD5LPS PPs)"
          ;;
        none) HD5NOSIGPV="$HD5NOSIGPV$HPV " ;;
      esac
    done
    # Precedence across every copy checked: an explicitly detected noncontiguous copy
    # always wins (the strongest, most actionable signal, regardless of what any other
    # copy showed) -- then a detected incomplete/malformed capture on any copy (never a
    # silent PASS built on partial evidence from a DIFFERENT, clean-looking copy) -- only
    # if every copy this tool found a PV for was independently confirmed contiguous AND
    # no copy came back with zero usable signal does this reach an actual PASS; anything
    # else falls through to the existing "contiguity not assessed" WARN.
    # An untrustworthy mirror map (HD5MAPBAD) joins the incomplete route with its own
    # detail -- a PASS must never be built on a map that may be hiding a whole copy.
    # An explicitly noncontiguous VISIBLE copy still wins (real, actionable signal).
    if [ -n "$HD5MAPBAD" ]; then
      HD5INCDETAIL="${HD5INCDETAIL}${HD5INCDETAIL:+; }$HD5MAPBAD"
    fi
    if [ -n "$HD5BADPV" ]; then
      HD5CONTIG="no"
    elif [ -n "$HD5INCPV" ] || [ -n "$HD5MAPBAD" ]; then
      HD5CONTIG="incomplete"
    elif [ -n "$HD5OKPV" ] && [ -z "$HD5NOSIGPV" ]; then
      HD5CONTIG="yes"
    else
      HD5CONTIG=""
    fi
  fi
  if [ -n "$HD5MB" ]; then
    if [ "$HD5MB" -ge 64 ]; then
      case "$HD5CONTIG" in
        yes)
          add storage hd5_sizing "Boot logical volume (hd5) size" PASS low "${HD5MB}MB (${HD5LPS} LP x ${PPSZ}MB), contiguous on $(printf '%s' "$HD5OKPV" | sed 's/ $//;s/ /, /g')" \
              "hd5 meets IBM's current 64MB boot-image sizing guidance and its physical partitions are contiguous on disk (every copy checked: $(printf '%s' "$HD5OKPV" | sed 's/ $//;s/ /, /g'))." "n/a"
          ;;
        no)
          add storage hd5_sizing "Boot logical volume (hd5) size" WARN med "${HD5MB}MB (${HD5LPS} LP x ${PPSZ}MB), NONCONTIGUOUS on $(printf '%s' "$HD5BADPV" | sed 's/ $//;s/ /, /g')" \
              "hd5 meets the 64MB size target, but at least one of its copies is NOT contiguous on disk ('lspv -M' shows hd5's PPs split across separate, non-adjacent runs on $(printf '%s' "$HD5BADPV" | sed 's/ $//;s/ /, /g')). IBM's own upgrade-readiness guidance treats a noncontiguous hd5 as NOT upgrade-ready regardless of its total size — a boot-image rebuild needs EVERY copy in one contiguous run of space." \
              "reorganize hd5 onto contiguous PPs (e.g. 'reorgvg rootvg', or recreate hd5 via a supported boot-LV rebuild procedure) before the next TL/SP update or migration."
          ;;
        incomplete)
          # A truncated/garbled 'lspv -M' capture must never be laundered into a PASS via a
          # coincidentally-contiguous-looking partial PP set (see the guard comment above) --
          # this is a detected assessment gap, not merely "we lack a signal," so it is
          # reported as NOT_ASSESSED rather than folded into the generic WARN "contiguity not
          # assessed" fallback below (never PASS, per the no-false-clean rule).
          add storage hd5_sizing "Boot logical volume (hd5) size" NOT_ASSESSED low "${HD5MB}MB (${HD5LPS} LP x ${PPSZ}MB), TRUNCATED/INCONSISTENT ($HD5INCDETAIL)" \
              "hd5 meets the 64MB size target, but 'lspv -M' returned an incomplete or internally inconsistent picture of hd5's physical partitions on at least one of its copies (expected ${HD5LPS} distinct PPs and ${HD5LPS} distinct LP-index markers per copy, independently confirmed via 'lsvg -l rootvg': $HD5INCDETAIL) — this looks like a truncated, duplicated, or otherwise garbled capture, not a genuine reading, and contiguity (required by IBM's own upgrade-readiness guidance regardless of size) cannot be confirmed from it. This tool will not assert upgrade-ready, or PASS, on incomplete evidence." \
              "re-run 'lslv -m hd5' and 'lspv -M <hdiskN>' manually for every copy and confirm all ${HD5LPS} of hd5's physical partitions are captured and contiguous on each before relying on this as upgrade-ready."
          ;;
        *)
          add storage hd5_sizing "Boot logical volume (hd5) size" WARN low "${HD5MB}MB (${HD5LPS} LP x ${PPSZ}MB), contiguity not assessed" \
              "hd5 meets the 64MB size target, but its physical-partition contiguity could not be independently confirmed ('lslv -m hd5' and/or 'lspv -M <hdiskN>' did not return a usable result). IBM's guidance requires hd5's PPs to be CONTIGUOUS, not just large enough — this tool will not assert upgrade-ready from size alone." \
              "run 'lslv -m hd5' and 'lspv -M <hdiskN>' manually to confirm hd5's PPs are contiguous before relying on this as upgrade-ready."
          ;;
      esac
    elif [ "$HD5MB" -ge 32 ]; then
      add storage hd5_sizing "Boot logical volume (hd5) size" WARN med "${HD5MB}MB (${HD5LPS} LP x ${PPSZ}MB)" \
          "hd5 meets IBM's OLDER 32MB guidance but not the current 64MB target — a boot-image rebuild (bosboot, run automatically by most maintenance paths) can fail to fit on an undersized hd5, most likely discovered mid-update." \
          "grow hd5 to 64MB before the next TL/SP update ('chvg -bu' as needed, then extend hd5 via a supported procedure — plan this in a maintenance window, not during an update)."
    else
      add storage hd5_sizing "Boot logical volume (hd5) size" FAIL high "${HD5MB}MB (${HD5LPS} LP x ${PPSZ}MB)" \
          "hd5 is undersized even against IBM's older 32MB guidance — a boot-image rebuild is at real risk of failing to fit." \
          "grow hd5 before the next TL/SP update; do not wait for an update to force the issue."
    fi
  else
    add storage hd5_sizing "Boot logical volume (hd5) size" WARN low "unreadable" \
        "Could not read hd5's LP count ('lsvg -l rootvg', rc=$ROOTVG_LVL_RC) or rootvg's PP size ('lsvg rootvg', rc=$RVGOUT_RC)." \
        "check 'lsvg -l rootvg' and 'lsvg rootvg' manually."
  fi

  # multibos_residue — leftover standby-BOS state from a prior multibos operation (docs/aixray-
  # spec-v2.md Sec 5 cap-filesets row; the multibos+nimadm version-dependent interaction, Sec 4,
  # is Blueprint sequencing's concern — this check only detects PRESENCE, informational, never a
  # verdict on whether it's safe to proceed with a specific migration method). Sourced two ways,
  # both IBM-documented: 'bos_'-prefixed LV names in the SAME rootvg LV list already captured
  # above (ROOTVG_LVL), and a mounted '/bos_inst' filesystem. Live-verified clean (neither present
  # — a real, not hypothetical, stock-image negative) on both lab-host-02 and lab-host-03, 2026-07-13.
  # Presence is only trusted from a source that itself SUCCEEDED -- gating BOSLV/BOSMNT
  # on their own rc BEFORE using them as signal (rather than gating the overall verdict
  # afterward) closes a failed-source-to-verdict path Codex's confirming review caught:
  # a failed 'lsvg -l rootvg' or 'mount' capture that nonetheless leaves plausible partial
  # text behind must never be able to manufacture a confident "present" finding (Codex
  # primary review, M5, round 3, new-bug finding on multibos_residue).
  BOSLV=""
  [ "$ROOTVG_LVL_RC" -eq 0 ] && BOSLV=$(printf '%s\n' "$ROOTVG_LVL" | awk '$1 ~ /^bos_/{printf "%s%s",(n++?",":""),$1}')
  MNT_MULTIBOS=$(aix mount mount); MOUNT_RC=$?
  # Exact whitespace-delimited field match, not a substring search across the whole line
  # (Codex primary review, M5, round 2, finding #8): an unanchored '/bos_inst' pattern
  # also matches '/bos_inst.old', '/bos_inst_backup', or the string appearing in some
  # other column (e.g. the options field) -- none of which is the real "mounted over"
  # path this check is actually looking for. Search starts at field 2, never field 1:
  # in 'mount' output the FIRST field is always either the remote node or the local
  # mounted-FROM device/path, never the mounted-over path -- so field 1 can never be a
  # legitimate "mounted over /bos_inst" match regardless of node-column shift between
  # local and NFS-mounted rows (Codex primary review, M5, round 3, finding #8 residual).
  BOSMNT=""
  [ "$MOUNT_RC" -eq 0 ] && BOSMNT=$(printf '%s\n' "$MNT_MULTIBOS" | awk '{for (i=2;i<=NF;i++) if ($i=="/bos_inst") {print; exit}}')
  # Structural validation, not just rc+nonemptiness -- a nonempty rc=0 capture that doesn't
  # even resemble real 'lsvg -l'/'mount' output (garbled, truncated, or the wrong command
  # entirely) must never be trusted into a confident "none" PASS just because it happened to
  # contain no bos_/bos_inst token (Codex primary review, M5, HIGH finding #3: reproduced
  # in-memory with garbled rootvg+mount captures -- output was 'multibos_residue PASS none').
  # Recognizable shape checked here is deliberately minimal, not a full re-parse: 'lsvg -l's
  # own 'rootvg:' vg-name header line plus its 'LV NAME'/'TYPE' column header; 'mount's own
  # 'mounted over' column header -- both are stable, documented output shapes on a real box.
  # Header-shape alone is not enough: a capture truncated right after its header line(s)
  # (present, rc=0, non-empty, and header-shape-valid) still passes the shape check above
  # while carrying ZERO of the actual LV/mount data rows that would show real residue --
  # reproduced live (a headers-only 'lsvg -l rootvg'/'mount' capture rendered PASS "none").
  # A bare LINE-COUNT floor (an earlier version of this fix) is insufficient on its own
  # (Codex primary review, 2026-07-14, HIGH: any fixed count is defeated by truncating
  # one row LATER -- e.g. after 3 ordinary LVs but before a later bos_-prefixed one).
  # Tightened to validate the SPECIFIC mandatory rows every supported real AIX capture has:
  # rootvg's hd5/hd6/hd8/hd4/hd2/hd9var rows, including their real type, positive LP/PP/PV
  # columns, state token and mount point; plus mount's /dev/hd4->/, /dev/hd2->/usr and
  # /dev/hd9var->/var rows, including jfs2 and real date/time columns. This raises the bar
  # from bare-token presence to actual per-row command grammar.
  # Disclosed, not silently accepted as a full fix (same honesty standard as this
  # codebase's own FLRT apar_scan floor, which documents itself as "a bound-and-disclose
  # floor against failed/truncated captures, not a completeness proof"): a capture
  # truncated AFTER all the mandatory rows above but BEFORE a real bos_/bos_inst residue
  # row remains accepted-open. Likewise, this is structural plausibility, not source
  # authentication: a deliberately fabricated payload that reproduces every full valid-
  # shaped mandatory row (not merely bare tokens or coincidental words) can still satisfy
  # it. Both residuals require a true completion/authenticity signal (checksum, independent
  # expected row count, or terminating sentinel) that this capture model does not provide.
  ROOTVG_ROWS_OK=0
  if [ "$ROOTVG_LVL_RC" -eq 0 ]; then
    printf '%s\n' "$ROOTVG_LVL" | awk '
        function pos(v){return v ~ /^[1-9][0-9]*$/}
        function state(v){return v=="open/syncd"||v=="open/stale"||v=="closed/syncd"||v=="closed/stale"}
        $1=="hd5"{n5++; if(NF==7&&$2=="boot"&&pos($3)&&pos($4)&&pos($5)&&state($6)&&$7=="N/A")h5++; else bad=1}
        $1=="hd6"{n6++; if(NF==7&&$2=="paging"&&pos($3)&&pos($4)&&pos($5)&&state($6)&&$7=="N/A")h6++; else bad=1}
        $1=="hd8"{n8++; if(NF==7&&$2=="jfs2log"&&pos($3)&&pos($4)&&pos($5)&&state($6)&&$7=="N/A")h8++; else bad=1}
        $1=="hd4"{n4++; if(NF==7&&$2=="jfs2"&&pos($3)&&pos($4)&&pos($5)&&state($6)&&$7=="/")h4++; else bad=1}
        $1=="hd2"{n2++; if(NF==7&&$2=="jfs2"&&pos($3)&&pos($4)&&pos($5)&&state($6)&&$7=="/usr")h2++; else bad=1}
        $1=="hd9var"{n9++; if(NF==7&&$2=="jfs2"&&pos($3)&&pos($4)&&pos($5)&&state($6)&&$7=="/var")h9++; else bad=1}
        END{exit !(h5==1&&h6==1&&h8==1&&h4==1&&h2==1&&h9==1&&n5==1&&n6==1&&n8==1&&n4==1&&n2==1&&n9==1&&!bad)}' && ROOTVG_ROWS_OK=1
  fi
  MOUNT_ROWS_OK=0
  if [ "$MOUNT_RC" -eq 0 ]; then
    printf '%s\n' "$MNT_MULTIBOS" | awk '
        function month(v){return v=="Jan"||v=="Feb"||v=="Mar"||v=="Apr"||v=="May"||v=="Jun"||v=="Jul"||v=="Aug"||v=="Sep"||v=="Oct"||v=="Nov"||v=="Dec"}
        function dated(mon,day,tim){if(!month(mon)||day !~ /^[0-9][0-9]*$/||day+0<1||day+0>31)return 0; split(tim,hm,":"); return tim ~ /^[0-9][0-9]:[0-9][0-9]$/&&hm[1]+0<24&&hm[2]+0<60}
        $1=="/dev/hd4"{n4++; if(NF>=7&&$2=="/"&&$3=="jfs2"&&dated($4,$5,$6))h4++; else bad=1}
        $1=="/dev/hd2"{n2++; if(NF>=7&&$2=="/usr"&&$3=="jfs2"&&dated($4,$5,$6))h2++; else bad=1}
        $1=="/dev/hd9var"{n9++; if(NF>=7&&$2=="/var"&&$3=="jfs2"&&dated($4,$5,$6))h9++; else bad=1}
        END{exit !(h4==1&&h2==1&&h9==1&&n4==1&&n2==1&&n9==1&&!bad)}' && MOUNT_ROWS_OK=1
  fi
  ROOTVG_LVL_OK=0
  if [ "$ROOTVG_LVL_RC" -eq 0 ]; then
    printf '%s\n' "$ROOTVG_LVL" | awk '
        NR==1 && $0 ~ /^rootvg:/ {h1=1}
        $0 ~ /LV NAME/ && $0 ~ /TYPE/ {h2=1}
        END{exit !(h1&&h2)}' && ROOTVG_LVL_OK=1
  fi
  MOUNT_OK=0
  if [ "$MOUNT_RC" -eq 0 ]; then
    printf '%s\n' "$MNT_MULTIBOS" | awk '$0 ~ /mounted over/{h=1} END{exit !h}' && MOUNT_OK=1
  fi
  if [ -n "$BOSLV" ] || [ -n "$BOSMNT" ]; then
    add storage multibos_residue "multibos/alt_disk standby-BOS residue" WARN med "present: ${BOSLV:-none} ${BOSMNT:+ /bos_inst mounted}" \
        "A standby Base Operating System from a prior 'multibos' operation is still present. Through AIX 7.1 NIM masters this ALWAYS blocks nimadm (full removal required first); from 7.2 NIM masters it's supported per-scenario but changes the required sequencing (mount/unmount the standby first, depending on boot state) — never assume it's safe to ignore." \
        "confirm this is intentional; if not, remove it ('multibos -R', then manual /bos_inst cleanup if it survives) before running nimadm — check the NIM master's own oslevel first to know which rule applies."
  elif [ "$ROOTVG_LVL_RC" -ne 0 ] || [ "$MOUNT_RC" -ne 0 ] || [ -z "$ROOTVG_LVL" ] || [ -z "$MNT_MULTIBOS" ]; then
    # EITHER source failing/empty is enough to WARN, not just both together -- these are
    # two DIFFERENT, complementary residue signals (a bos_-prefixed LV vs a mounted
    # /bos_inst), and a real box always returns nonempty output for both a successful
    # 'lsvg -l rootvg' (rootvg always has LVs) and 'mount' (always at least '/'). PASSing
    # when only ONE source actually returned clean data was the exact NOT_ASSESSED-
    # laundered-into-a-verdict class this repo's own discipline forbids -- caught only
    # because Codex's primary review on this milestone checked the individual-source
    # failure case explicitly, not just the both-empty case self-review had already
    # covered.
    add storage multibos_residue "multibos/alt_disk standby-BOS residue" WARN low "unreadable" \
        "Could not read 'lsvg -l rootvg' (rc=$ROOTVG_LVL_RC) and/or 'mount' (rc=$MOUNT_RC) to check for multibos/alt_disk residue -- both sources must be readable to assert none is present." \
        "check 'lsvg -l rootvg' (bos_-prefixed LVs) and 'mount' (/bos_inst) manually."
  elif [ "$ROOTVG_LVL_OK" -ne 1 ] || [ "$MOUNT_OK" -ne 1 ] || [ "$ROOTVG_ROWS_OK" -ne 1 ] || [ "$MOUNT_ROWS_OK" -ne 1 ]; then
    add storage multibos_residue "multibos/alt_disk standby-BOS residue" WARN low "not assessed" \
        "'lsvg -l rootvg' and/or 'mount' returned rc=0 with nonempty output, but that output either does not match the command's stable header shape or does not contain one complete, valid-shaped copy of every mandatory base row (rootvg hd5/hd6/hd8/hd4/hd2/hd9var rows valid: $ROOTVG_ROWS_OK; mount /dev/hd4->/, /dev/hd2->/usr, /dev/hd9var->/var rows with vfs/date columns valid: $MOUNT_ROWS_OK) -- a garbled, truncated, bare-token/token-coincidence, or wrong-command capture must never be trusted into asserting NO residue is present." \
        "run 'lsvg -l rootvg' and 'mount' manually and check for bos_-prefixed LVs or a mounted /bos_inst filesystem."
  else
    add storage multibos_residue "multibos/alt_disk standby-BOS residue" PASS low "none" \
        "No leftover multibos standby-BOS state (bos_-prefixed LVs or a mounted /bos_inst)." "n/a"
  fi

  # vg_capacity — free PPs headroom per online VG
  WORSTP=101; LOWVG=""; ANYLOW=0; FACTVGBAD=0; FACTVGSEEN=0
  [ "$VGLRC" -ne 0 ] && FACTVGBAD=1
  for VG in $VGL; do
    VGO=$(aix "lsvg_$VG" lsvg "$VG"); VGORC=$?
    TOT=$(printf '%s\n' "$VGO" | awk '{for(i=1;i<NF;i++)if($i=="TOTAL"&&$(i+1)=="PPs:")print $(i+2)}')
    FRE=$(printf '%s\n' "$VGO" | awk '{for(i=1;i<NF;i++)if($i=="FREE"&&$(i+1)=="PPs:")print $(i+2)}')
    if [ "$VGORC" -ne 0 ]; then FACTVGBAD=1; fi
    case "$TOT" in ''|*[!0-9]*) FACTVGBAD=1; continue;; esac
    case "$FRE" in ''|*[!0-9]*) FACTVGBAD=1; continue;; esac
    if [ "$TOT" -eq 0 ]; then FACTVGBAD=1; continue; fi
    FACTVGSEEN=1
    P=$(( FRE * 100 / TOT ))
    if [ "$P" -lt "$WORSTP" ]; then WORSTP=$P; LOWVG=$VG; fi
    [ "$P" -lt 5 ] && ANYLOW=1
  done
  if [ "$WORSTP" -le 100 ]; then
    if [ "$VGLRC" -eq 0 ] && [ "$FACTVGBAD" -eq 0 ] && [ "$FACTVGSEEN" -eq 1 ] &&
       valid_json_number "$WORSTP"; then
      FACT_STORAGE_WORST_VG_PCT="$WORSTP"
      FACT_STORAGE_WORST_VG="$LOWVG"
    fi
    if [ "$ANYLOW" -eq 1 ]; then
      add storage vg_capacity "Volume group free space" WARN med "$LOWVG ${WORSTP}% free" \
          "A volume group is under 5% free — no headroom to extend a filesystem in an emergency." \
          "free space or add a PV to the tight VG (extendvg <vg> hdiskN) before you need to grow a filesystem."
    else
      add storage vg_capacity "Volume group free space" PASS low "worst: $LOWVG ${WORSTP}% free" \
          "Every online volume group has room to extend a filesystem." "n/a"
    fi
  fi

  # MPIO path health
  LSP=$(aix lspath lspath); RC=$?
  if [ "$RC" -ne 0 ] || [ -z "$LSP" ]; then
    add storage mpio "MPIO path health" PASS low "no MPIO paths reported" \
        "No multipath I/O configured (common with single-path virtual SCSI)." \
        "if this box should have redundant SAN paths, that is a gap worth closing."
  else
    BAD=$(printf '%s\n' "$LSP" | awk '$1=="Failed" || $1=="Missing" {n++} END{print n+0}')
    DIS=$(printf '%s\n' "$LSP" | awk '$1=="Disabled" || $1=="Defined" {n++} END{print n+0}')
    # single-path disks: exclude disks whose only path parent is vscsi* — vSCSI
    # redundancy lives on the VIOS and is invisible in-LPAR. NPIV/fscsi single-path
    # still counts. Emit "<real-single> <vscsi-single>".
    SPVS=$(printf '%s\n' "$LSP" | awk '{c[$2]++; par[$2]=$3} END{sp=0;vs=0; for(d in c){if(c[d]==1){ if(par[d] ~ /^vscsi/) vs++; else sp++}} print sp, vs}')
    SINGLE=${SPVS%% *}; VSCSI=${SPVS##* }
    NP=$(printf '%s\n' "$LSP" | awk 'END{print NR}')
    ND=$(printf '%s\n' "$LSP" | awk '{c[$2]++} END{n=0; for (d in c) n++; print n}')
    if [ "$BAD" -gt 0 ]; then
      add storage mpio "MPIO path health" FAIL high "$BAD failed/missing of $NP paths" \
          "Path redundancy is already lost — the next path failure is an outage." \
          "chase the failed path (cables, fabric, fscsi); re-enable with 'chpath'; verify with 'lspath'."
    elif [ "$DIS" -gt 0 ] || [ "$SINGLE" -gt 0 ]; then
      VSNOTE=""; [ "${VSCSI:-0}" -gt 0 ] && VSNOTE="; $VSCSI vSCSI disk(s) (path redundancy managed on the VIOS)"
      add storage mpio "MPIO path health" WARN med "$NP paths / $ND disks; $DIS disabled, $SINGLE single-path disk(s)$VSNOTE" \
          "Some disks are one path failure away from I/O loss." \
          "re-enable disabled paths; give single-path disks a second path if the storage design allows."
    else
      VSNOTE=""; [ "${VSCSI:-0}" -gt 0 ] && VSNOTE=" ($VSCSI vSCSI disk(s) — path redundancy managed on the VIOS)"
      add storage mpio "MPIO path health" PASS low "$NP paths / $ND disks, all enabled$VSNOTE" "Full path redundancy." "n/a"
    fi
  fi

  # MPIO path health-check policy. Reuse ck-mpio-paths' lspath capture in the
  # monolith; a standalone S1 artifact takes the same read when no shared
  # capture has been populated.
  if [ "${LSP+set}" = set ]; then
    HCK_LSP=$LSP
    HCK_LSP_RC=${RC:-0}
  else
    HCK_LSP=$(aix lspath lspath)
    HCK_LSP_RC=$?
  fi

  if [ "$HCK_LSP_RC" -ne 0 ]; then
    add storage mpio_hcheck "MPIO health-check probing" NOT_ASSESSED high \
        "not assessed — lspath capture failed (rc=$HCK_LSP_RC)" \
        "MPIO disks could not be identified from a successful lspath read, so no health-check policy claim is made." \
        "resolve the lspath read failure and rerun the diagnostic."
  else
    # Preserve capture order for deterministic output. Only hdisk names with
    # multiple lspath rows are eligible; single-path and non-hdisk rows never
    # become lsattr arguments.
    HCK_DISKS=$(printf '%s\n' "$HCK_LSP" | awk '
      $2 ~ /^hdisk[0-9]+$/ {
        if (!($2 in count)) order[++disks]=$2
        count[$2]++
      }
      END {
        for (i=1; i<=disks; i++)
          if (count[order[i]] > 1) print order[i]
      }
    ')
    HCK_TOTAL=$(printf '%s\n' "$HCK_DISKS" | awk 'NF {n++} END {print n+0}')
    HCK_SHOWN=0
    HCK_APPLICABLE=0
    HCK_NOT_APPLICABLE=0
    HCK_UNREADABLE=0
    HCK_STATUS=PASS
    HCK_SEVERITY=low
    HCK_TABLE="disk interval mode"

    for HCK_DISK in $HCK_DISKS; do
      HCK_ATTR=$(aix "lsattr_hcheck_$HCK_DISK" lsattr -El "$HCK_DISK" \
        -a hcheck_interval -a hcheck_mode)
      HCK_ATTR_RC=$?
      HCK_INTERVAL=$(printf '%s\n' "$HCK_ATTR" | \
        awk '$1 == "hcheck_interval" {print $2; exit}')
      HCK_MODE_VALUE=$(printf '%s\n' "$HCK_ATTR" | \
        awk '$1 == "hcheck_mode" {print $2; exit}')
      HCK_MODE=$HCK_MODE_VALUE
      [ -n "$HCK_MODE" ] || HCK_MODE=not-reported

      if [ -z "$HCK_INTERVAL" ] && [ "$HCK_ATTR_RC" -ne 0 ] && \
          [ -z "$HCK_MODE_VALUE" ]; then
        HCK_UNREADABLE=$((HCK_UNREADABLE + 1))
        HCK_ROW="$HCK_DISK unreadable (lsattr rc=$HCK_ATTR_RC) $HCK_MODE"
        if [ "$HCK_STATUS" = PASS ]; then
          HCK_STATUS=NOT_ASSESSED
          HCK_SEVERITY=high
        fi
      elif [ -z "$HCK_INTERVAL" ]; then
        HCK_NOT_APPLICABLE=$((HCK_NOT_APPLICABLE + 1))
        HCK_ROW="$HCK_DISK n/a $HCK_MODE (attribute not applicable)"
      else
        HCK_APPLICABLE=$((HCK_APPLICABLE + 1))
        case "$HCK_INTERVAL" in
          *[!0-9]*)
            HCK_UNREADABLE=$((HCK_UNREADABLE + 1))
            HCK_ROW="$HCK_DISK unreadable $HCK_MODE"
            if [ "$HCK_STATUS" = PASS ]; then
              HCK_STATUS=NOT_ASSESSED
              HCK_SEVERITY=high
            fi
            ;;
          *)
            HCK_ROW="$HCK_DISK $HCK_INTERVAL $HCK_MODE"
            HCK_INTERVAL_CLASS=$(awk -v interval="$HCK_INTERVAL" 'BEGIN {
              if (interval + 0 == 0) print "disabled"
              else if (interval + 0 > 300) print "slow"
              else print "sane"
            }')
            case "$HCK_INTERVAL_CLASS" in
              disabled)
                HCK_STATUS=FAIL
                HCK_SEVERITY=high
                ;;
              slow)
                if [ "$HCK_STATUS" != FAIL ]; then
                  HCK_STATUS=WARN
                  HCK_SEVERITY=low
                fi
                ;;
            esac
            ;;
        esac
      fi

      if [ "$HCK_SHOWN" -lt 50 ]; then
        HCK_TABLE="$HCK_TABLE | $HCK_ROW"
        HCK_SHOWN=$((HCK_SHOWN + 1))
      fi
    done

    HCK_OBSERVED="MPIO disks=$HCK_TOTAL; showing $HCK_SHOWN of $HCK_TOTAL; applicable=$HCK_APPLICABLE; attribute not applicable=$HCK_NOT_APPLICABLE; unreadable=$HCK_UNREADABLE; table: $HCK_TABLE"
    HCK_OMITTED=$((HCK_TOTAL - HCK_SHOWN))
    if [ "$HCK_OMITTED" -eq 1 ]; then
      HCK_OBSERVED="$HCK_OBSERVED; 1 row omitted by 50-disk cap"
    elif [ "$HCK_OMITTED" -gt 1 ]; then
      HCK_OBSERVED="$HCK_OBSERVED; $HCK_OMITTED rows omitted by 50-disk cap"
    fi

    case "$HCK_STATUS" in
      FAIL)
        HCK_MEANING="At least one multipath disk has health-check probing disabled; configured path redundancy is not being actively verified before failover is needed."
        HCK_FIX="set a nonzero hcheck_interval through the approved storage change process (typically 60 seconds), then verify the policy with the read-only lsattr command."
        ;;
      WARN)
        HCK_MEANING="At least one multipath disk waits more than 300 seconds between path health probes, delaying detection of a dead path."
        HCK_FIX="review the storage driver's supported policy and reduce hcheck_interval through the approved change process; 60 seconds is typical."
        ;;
      NOT_ASSESSED)
        HCK_MEANING="At least one multipath disk's hcheck_interval could not be read or parsed, so no complete health-check policy verdict is claimed."
        HCK_FIX="resolve the lsattr read failure or malformed value and rerun the read-only diagnostic."
        ;;
      *)
        HCK_MEANING="Every applicable multipath disk reports a nonzero health-check interval no greater than 300 seconds."
        HCK_FIX="n/a"
        ;;
    esac

    add storage mpio_hcheck "MPIO health-check probing" \
        "$HCK_STATUS" "$HCK_SEVERITY" "$HCK_OBSERVED" \
        "$HCK_MEANING" "$HCK_FIX"
  fi

  # fc_errors — Fibre Channel adapter error counters (cumulative since boot)
  LSADP=$(aix lsdev_adapter lsdev -c adapter)
  FCS=$(printf '%s\n' "$LSADP" | awk '$1 ~ /^fcs[0-9]+$/ {print $1}')
  if [ -n "$FCS" ]; then
    FCBAD=0; FCTXT=""; FCNR=0; FCN=0; FCUR=0
    for A in $FCS; do
      FCN=$((FCN+1))
      FST=$(aix "fcstat_$A" fcstat "$A"); FRC=$?
      # $2+0 keeps the sign: virtual FC (PowerVS/NPIV) reports counters as -1 = "not available".
      # END-emitted "NA" marks a counter line that was ABSENT (distinct from a zero value).
      LF=$(printf '%s\n' "$FST" | awk -F: '/Link Failure Count/{print $2+0; f=1; exit} END{if(!f)print "NA"}')
      LS=$(printf '%s\n' "$FST" | awk -F: '/Loss of Sync Count/{print $2+0; f=1; exit} END{if(!f)print "NA"}')
      CRC=$(printf '%s\n' "$FST" | awk -F: '/Invalid CRC Count/{print $2+0; f=1; exit} END{if(!f)print "NA"}')
      # unreadable: fcstat failed, or NONE of the three counter lines were present.
      # This must not synthesize a clean PASS the way "$2+0 of empty = 0" used to.
      if [ "$FRC" -ne 0 ] || { [ "$LF" = NA ] && [ "$LS" = NA ] && [ "$CRC" = NA ]; }; then
        FCTXT="$FCTXT${FCTXT:+; }$A: counters unreadable"
        FCUR=$((FCUR+1))
        continue
      fi
      [ "$LF" = NA ] && LF=0; [ "$LS" = NA ] && LS=0; [ "$CRC" = NA ] && CRC=0
      if [ "$CRC" -lt 0 ] && [ "$LF" -lt 0 ] && [ "$LS" -lt 0 ]; then
        FCTXT="$FCTXT${FCTXT:+; }$A: counters not reported (virtual FC)"
        FCNR=$((FCNR+1))
        continue
      fi
      [ "$CRC" -lt 0 ] && CRC=0
      [ "$LF" -lt 0 ] && LF=0
      [ "$LS" -lt 0 ] && LS=0
      FCTXT="$FCTXT${FCTXT:+; }$A: CRC ${CRC:-0}, link-fail ${LF:-0}, loss-sync ${LS:-0}"
      { [ "${CRC:-0}" -gt 0 ] || [ "${LF:-0}" -gt 10 ]; } && FCBAD=1
    done
    if [ "$FCBAD" -eq 1 ]; then
      add storage fc_errors "Fibre Channel adapter errors" WARN med "$FCTXT" \
          "A Fibre Channel adapter reports CRC errors or repeated link failures. These counts are cumulative since boot, so confirm whether they are still climbing." \
          "check SAN cabling, the SFP, and the switch port for the flagged adapter; compare 'fcstat <fcs>' over time."
    elif [ "$FCUR" -gt 0 ]; then
      add storage fc_errors "Fibre Channel adapter errors" WARN low "$FCTXT" \
          "One or more FC adapters returned no readable error counters — a clean pass cannot be claimed for them (a healthy adapter reports zeros, not nothing)." \
          "run 'fcstat <fcs>' as root; on virtual FC the counters live on the VIOS."
    elif [ "$FCNR" -eq "$FCN" ]; then
      # Believability review 2026-07-13 (review-queue #62, finding #9): this used to PASS
      # here — but "counters not reported" means the CRC/link-failure observation was
      # never captured at all (virtual FC never exposes it in-LPAR), the same gap the
      # FCUR>0 branch above already correctly treats as NOT a clean pass. A missing
      # observation must render NOT_ASSESSED, never PASS, regardless of WHY it is missing.
      add storage fc_errors "Fibre Channel adapter errors" NOT_ASSESSED low "$FCTXT" \
          "Virtual FC adapters do not expose error counters inside the LPAR, so CRC/link-failure health could not be observed from here at all — this is not evidence of a clean adapter, just an architectural blind spot. Check path health on the VIOS side." "n/a"
    else
      add storage fc_errors "Fibre Channel adapter errors" PASS low "$FCTXT" \
          "No CRC or excessive link errors on the FC adapters (cumulative since boot)." "n/a"
    fi
  fi

  # ==================== LEVEL 2/3 STORAGE DEPTH (grouped findings) ======================
  # Each check states its veteran signal in the comment. Tuning-level findings default to
  # WARN/informational unless something is genuinely broken (see docs/DEPTH-STANDARD.md).
  REALMB=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/Memory Size/{v=$2; sub(/[ 	]*MB.*/,"",v); print v+0; exit}')

  # vg_geometry — PP size vs VG size: is the physical-partition map laid out sanely?
  # Veteran signal: a big VG carved with a tiny PP (thousands of PPs per disk) bloats the
  # allocation map and marches toward the per-PV PP ceiling; a huge PP on a small VG wastes
  # space in coarse allocation units. A sane VG keeps a few hundred-to-~1016 PPs per disk.
  GWORST=PASS; GEOOBS=""; GEOVG=""; GSUM=""
  for VG in $VGL; do
    set -- $(printf '%s\n' "$(aix "lsvg_$VG" lsvg "$VG")" | awk '
      /PP SIZE:/   {for(i=1;i<=NF;i++) if($i=="SIZE:"  && $(i-1)=="PP")    pp=$(i+1)+0}
      /TOTAL PPs:/ {for(i=1;i<=NF;i++) if($i=="PPs:"   && $(i-1)=="TOTAL") tp=$(i+1)+0}
      /TOTAL PVs:/ {for(i=1;i<=NF;i++) if($i=="PVs:"   && $(i-1)=="TOTAL") tv=$(i+1)+0}
      END{print pp+0, tp+0, tv+0}')
    PPSZ=${1:-0}; TPP=${2:-0}; TPV=${3:-0}
    [ "$TPV" -le 0 ] && continue
    [ "$TPP" -le 0 ] && continue
    PPPV=$(( TPP / TPV ))
    VGSZMB=$(( TPP * PPSZ ))
    GSUM="${GSUM}${GSUM:+; }$VG ${PPSZ}MB PP, ${PPPV} PP/disk"
    if [ "$PPPV" -gt "$STOR_PP_PER_PV_HI" ]; then
      GWORST=WARN; GEOVG=$VG
      GEOOBS="$VG: ${PPPV} PPs per disk at a ${PPSZ}MB PP (VG ~$(( VGSZMB/1024 ))GB) — PP size too small"
    elif [ "$PPSZ" -ge "$STOR_HUGE_PP_MB" ] && [ "$TPP" -lt "$STOR_SMALL_VG_PPS" ]; then
      if [ "$GWORST" = PASS ]; then
        GWORST=WARN; GEOVG=$VG
        GEOOBS="$VG: ${PPSZ}MB PP on a ${TPP}-PP VG — coarse allocation unit, wastes space on small LVs"
      fi
    fi
  done
  if [ "$GWORST" = WARN ]; then
    add storage vg_geometry "Volume group geometry" WARN low "$GEOOBS" \
        "A volume group's physical-partition size does not fit its size: either a tiny PP on a large VG (a bloated allocation map that crowds the per-disk PP ceiling and slows LVM operations) or a huge PP on a small VG (coarse units that round every small LV up and waste space). It works, but it is not how you would lay it out from scratch." \
        "PP size is fixed at mkvg time — to change it you recreate the VG (back up with savevg, recreate with 'mkvg -s <ppsize>', restore). Do it opportunistically at the next migration; it is not urgent." "ffiec:II.C.11"
  else
    add storage vg_geometry "Volume group geometry" PASS low "${GSUM:-no online VGs}" \
        "Physical-partition geometry is sane on every online VG — the PP size fits the VG size, so the allocation map is neither bloated (tiny PP) nor wasteful (huge PP)." "n/a"
  fi

  # lv_policy — mirrored LVs whose copies share a disk (false protection).
  # Veteran signal: COPIES>1 but the copies land on ONE physical volume (PVs < copies, or
  # inter-policy minimum with copies not forced onto separate PVs) = a mirror that does not
  # survive a disk failure. Detected from lsvg -l (copies = PPs/LPs, PVs = disks the LV spans),
  # enriched from lslv (INTER-POLICY, "EACH LP COPY ON A SEPARATE PV ?") for the flagged LVs.
  # mirrored LVs, one per line "vg lv copies pvs" (copies = PPs/LPs, integer only)
  LVPMIR=$(for VG in $VGL; do
      printf '%s\n' "$(aix "lsvg_l_$VG" lsvg -l "$VG")" | awk -v vg="$VG" '
        NR>2 && NF>=5 { lps=$3+0; pps=$4+0; pvs=$5+0
          if(lps>0 && pps%lps==0){ cpy=pps/lps; if(cpy>=2) print vg, $1, cpy, pvs } }'
    done)
  LVPMIR=${LVPMIR:-}
  # flag the mirrored LVs whose copies do NOT span enough disks (copies share a PV); the
  # subshell's stdout is captured, so no temp file and no write to disk (read-only posture).
  LVPFLAG=$(printf '%s\n' "$LVPMIR" | while read VG LVNAME CPY LVPVS; do
      [ -n "$VG" ] || continue
      [ "$LVPVS" -lt "$CPY" ] || continue
      LVPEXTRA=""
      LSLVO=$(aix "lslv_$LVNAME" lslv "$LVNAME")
      if [ -n "$LSLVO" ]; then
        IPOL=$(printf '%s\n' "$LSLVO" | awk '/INTER-POLICY:/{print $2; exit}')
        SEPPV=$(printf '%s\n' "$LSLVO" | awk '/EACH LP COPY ON A SEPARATE PV/{print $NF; exit}')
        [ -n "$IPOL" ] && LVPEXTRA=" [inter-policy $IPOL, separate-PV ${SEPPV:-?}]"
      fi
      printf '%s/%s (%s copies on %s disk)%s\n' "$VG" "$LVNAME" "$CPY" "$LVPVS" "$LVPEXTRA"
    done | awk 'NF{printf "%s%s",(n++?"; ":""),$0}')
  LVPMIR=$(printf '%s\n' "$LVPMIR" | awk 'NF{n++} END{print n+0}')
  if [ -n "$LVPFLAG" ]; then
    add storage lv_policy "LV mirror placement" FAIL high "$LVPFLAG" \
        "A mirrored logical volume has all its copies on ONE physical volume — the mirror looks like protection but does not survive a disk failure, because both copies die with that disk. Usually the result of inter-policy 'minimum' without forcing copies onto separate PVs." \
        "move one copy to another disk so the copies are physically separate: 'migratepv -l <lv> <fromdisk> <todisk>', or drop and re-add the copy with 'rmlvcopy'/'mklvcopy <lv> 2 <otherdisk>'; set the LV to require separate PVs (chlv -s y)." "ffiec:II.C.11"
  elif [ "${LVPMIR:-0}" -gt 0 ]; then
    add storage lv_policy "LV mirror placement" PASS low "$LVPMIR mirrored LV(s), copies on separate disks" \
        "Every mirrored logical volume keeps its copies on separate physical volumes — the mirrors are real protection that survives a single-disk failure." "n/a"
  else
    add storage lv_policy "LV mirror placement" PASS low "no mirrored LVs" \
        "No logical volume is mirrored in-LPAR — single-copy LVs here rely on the SAN/VIOS for redundancy (in-LPAR mirroring is separate and not configured)." "n/a"
  fi

  # fs_lv_slack — filesystem size vs the LV it lives on (lsfs -q: fs size vs lv size).
  # Veteran signal: lv size >> fs size = partitions allocated to the LV that the filesystem
  # was never grown into — space you are paying for (and cannot use) until you chfs it up.
  LSFSQ=$(aix lsfs_q lsfs -q)
  set -- $(printf '%s\n' "$LSFSQ" | awk '
    /^[ 	]*\(lv size:/ {
      s=$0; gsub(/[(),:]/," ",s); n=split(s,a," "); lv=0; fs=0
      for(i=1;i<n;i++){ if(a[i]=="lv"&&a[i+1]=="size"){lv=a[i+2]+0}; if(a[i]=="fs"&&a[i+1]=="size"){fs=a[i+2]+0} }
      if(lv>0 && lv>fs){ slk=lv-fs; if(slk>ws){ws=slk; wmp=mp; wlv=lv; wfs=fs} }
      next
    }
    $1 ~ /^\/dev\// && NF>=5 { mp=$3; next }
    END{ printf "%s %d %d %d", (wmp==""?"none":wmp), ws+0, wlv+0, wfs+0 }')
  SLKMP=${1:-none}; SLKBLK=${2:-0}; SLKLV=${3:-0}; SLKFS=${4:-0}
  SLKMB=$(( SLKBLK / 2048 ))
  SLKPCT=0; [ "${SLKLV:-0}" -gt 0 ] && SLKPCT=$(( SLKBLK * 100 / SLKLV ))
  if [ "$SLKMB" -ge "$STOR_SLACK_MB" ] && [ "$SLKPCT" -ge "$STOR_SLACK_PCT" ]; then
    add storage fs_lv_slack "Filesystem vs LV sizing" WARN low "$SLKMP: LV $(( SLKLV/2048 ))MB, FS $(( SLKFS/2048 ))MB — ${SLKMB}MB (${SLKPCT}%) allocated but unused" \
        "The logical volume under $SLKMP has partitions the filesystem was never grown into — ${SLKMB}MB is allocated to the LV but the JFS2 filesystem stops short of it, so you are holding that disk space without being able to use it. Often left behind after an 'extendlv' with no matching 'chfs'." \
        "grow the filesystem into the LV it already owns: 'chfs -a size=${SLKLV} $SLKMP' (size in 512-byte blocks), or trim the LV if the space was allocated by mistake." "ffiec:II.C.11"
  else
    add storage fs_lv_slack "Filesystem vs LV sizing" PASS low "no filesystem lags its LV by ${STOR_SLACK_MB}MB+" \
        "Every JFS2 filesystem is grown into the logical volume it sits on — no allocated-but-unusable slack between the LV and the filesystem." "n/a"
  fi

  # jfs_legacy — any pre-JFS2 (vfs "jfs") filesystems still in use (lsfs -q vfs column).
  # Veteran signal: JFS predates JFS2 — no filesystems over 2 TB, no online shrink, weaker
  # concurrency and no inline log; a JFS mount on a modern box is technical debt to migrate.
  JFSLEG=$(printf '%s\n' "$LSFSQ" | awk '$1 ~ /^\/dev\// && NF>=5 && $4=="jfs" {printf "%s%s",(n++?", ":""),$3}')
  if [ -n "$JFSLEG" ]; then
    add storage jfs_legacy "Legacy JFS filesystems" WARN low "jfs (not jfs2): $JFSLEG" \
        "One or more filesystems are still legacy JFS, not JFS2 — JFS caps at 2 TB, has no online shrink, weaker concurrency and no inline log. It still works, but it is a dead-end filesystem type on current AIX." \
        "plan a migration to JFS2 (create a JFS2 filesystem and copy the data, e.g. with 'cplv'/backup-restore during a window); there is no in-place JFS-to-JFS2 conversion." "ffiec:II.C.11"
  else
    add storage jfs_legacy "Legacy JFS filesystems" PASS low "all filesystems are JFS2" \
        "No legacy JFS filesystems — everything is JFS2, the current AIX filesystem." "n/a"
  fi

  # mount_options — structural mount hygiene from `mount`.
  # Veteran signal: /tmp not its own filesystem (a runaway /tmp then fills root); a JFS2 mount
  # with no log (crash-recovery and write ordering suffer). Performance options (noatime,
  # cio/dio, rbrw) are workload-specific — you cannot know app intent, so they are reported
  # as informational context, not a finding, to avoid crying wolf on a normal default mount.
  MNT=$(aix mount mount)
  set -- $(printf '%s\n' "$MNT" | awk '
    $1 ~ /^\// {
      mp=$2; vfs=$3; opt=$NF
      if(mp=="/tmp") tmp=1
      if(vfs=="jfs2"){ j++
        if(index(opt,"log=")==0) nolog=nolog (nn++?",":"") mp
        if(index(opt,"noatime")==0) at++ }
    }
    END{ printf "%d %d %d %s", tmp+0, j+0, at+0, (nolog==""?"none":nolog) }')
  TMPSEP=${1:-0}; NJFS2=${2:-0}; ATIMEN=${3:-0}; NOLOG=${4:-none}
  if [ "$TMPSEP" -ne 1 ]; then
    add storage mount_options "Mount options" WARN med "/tmp is not a separate filesystem" \
        "/tmp is not mounted as its own filesystem, so it shares space with / — a runaway process that fills /tmp then fills the root filesystem, which can stop logins and logging system-wide." \
        "give /tmp its own logical volume and filesystem (crfs -v jfs2 -m /tmp ...), or confirm this is intentional on a minimal build." "ffiec:II.C.11"
  elif [ "$NOLOG" != none ]; then
    add storage mount_options "Mount options" WARN low "jfs2 without a log: $NOLOG" \
        "A JFS2 filesystem is mounted with no log device — without a JFS2 log, crash recovery falls back to a full fsck and write ordering is weaker, so a crash risks a long recovery or metadata inconsistency." \
        "give it a jfs2log LV or use an inline log ('chfs -a logname=INLINE $NOLOG' after adding inline-log space); verify with 'mount'." "ffiec:II.C.11"
  else
    add storage mount_options "Mount options" PASS low "/tmp separate; $NJFS2 jfs2 mount(s), all logged; $ATIMEN using default atime" \
        "Mount hygiene is sound: /tmp is its own filesystem and every JFS2 mount has a log. Performance options (noatime for read-heavy mounts, cio/dio for databases, rbrw) are workload-specific and left to the app owner — atime-on is the AIX default and fine unless a mount is known read-heavy." "n/a"
  fi

  # paging_parity — multi-space size and active-state correctness. AIX VMM
  # round-robins across active paging spaces, so unequal sizes stop balanced
  # interleaving when the smallest space fills.
  if [ "${LSPS_OK:-0}" -ne 1 ]; then
    add storage paging_parity "Paging space parity" NOT_ASSESSED med \
        "${LSPSWHY:-not assessed — lsps -a capture unavailable}" \
        "Paging-space parity could not be assessed because lsps -a failed, returned no evidence, or did not match the expected AIX output shape." \
        "run 'lsps -a' manually, then rerun AIXray before treating multi-space paging as balanced."
  else
    PPAR_COUNT=$(printf '%s\n' "$LSPS" | awk 'NR>1 && NF>1 {n++} END {print n+0}')
    if [ "$PPAR_COUNT" -gt 1 ]; then
      PPAR_TABLE=$(printf '%s\n' "$LSPS" | awk '
        BEGIN { print "NAME | PV | SIZE | ACTIVE" }
        NR>1 && NF>1 { print $1 " | " $2 " | " $4 " | " $6 }
      ')
      PPAR_META=$(printf '%s\n' "$LSPS" | awk '
        NR>1 && NF>1 {
          n++
          name[n]=$1
          raw_size[n]=$4
          active[n]=$6
          size=$4
          if (size ~ /MB$/) {
            sub(/MB$/, "", size)
          } else if (size ~ /GB$/) {
            sub(/GB$/, "", size)
            size=size*1024
          }
          size_mb[n]=size+0
          size_count[size_mb[n]]++
          if (n == 1 || size_mb[n] < smallest) smallest=size_mb[n]
        }
        END {
          baseline=smallest
          baseline_count=size_count[smallest]
          for (size in size_count) {
            numeric_size=size+0
            if (size_count[size] > baseline_count ||
                (size_count[size] == baseline_count && numeric_size < baseline)) {
              baseline=numeric_size
              baseline_count=size_count[size]
            }
          }
          odd=""
          inactive=""
          wasted=0
          for (i=1; i<=n; i++) {
            wasted+=size_mb[i]-smallest
            if (size_mb[i] != baseline) {
              if (odd != "") odd=odd ", "
              odd=odd name[i] " (" raw_size[i] ")"
            }
            if (active[i] != "yes") {
              if (inactive != "") inactive=inactive ", "
              inactive=inactive name[i]
            }
          }
          printf "%d\t%d\t%s\t%s\n", smallest+0, wasted+0, odd, inactive
        }
      ')
      PPAR_MIN_MB=$(printf '%s\n' "$PPAR_META" | awk -F '\t' '{print $1}')
      PPAR_WASTE_MB=$(printf '%s\n' "$PPAR_META" | awk -F '\t' '{print $2}')
      PPAR_ODD=$(printf '%s\n' "$PPAR_META" | awk -F '\t' '{print $3}')
      PPAR_INACTIVE=$(printf '%s\n' "$PPAR_META" | awk -F '\t' '{print $4}')

      if [ "$PPAR_WASTE_MB" -eq 0 ] && [ -z "$PPAR_INACTIVE" ]; then
        add storage paging_parity "Paging space parity" PASS med "$PPAR_TABLE" \
            "All $PPAR_COUNT paging spaces are active and exactly ${PPAR_MIN_MB}MB, so VMM can round-robin them without an early size cap." \
            "n/a"
      else
        PPAR_ISSUES=""
        if [ "$PPAR_WASTE_MB" -gt 0 ]; then
          PPAR_ISSUES="odd size: $PPAR_ODD; wasted delta: ${PPAR_WASTE_MB}MB above the smallest defined paging-space size (${PPAR_MIN_MB}MB)"
        fi
        if [ -n "$PPAR_INACTIVE" ]; then
          [ -z "$PPAR_ISSUES" ] \
            || PPAR_ISSUES="$PPAR_ISSUES; "
          PPAR_ISSUES="${PPAR_ISSUES}inactive: $PPAR_INACTIVE"
        fi
        PPAR_OBSERVED="$PPAR_TABLE
Issues: $PPAR_ISSUES"
        add storage paging_parity "Paging space parity" WARN med "$PPAR_OBSERVED" \
            "Multiple defined paging spaces are not balanced: inactive spaces do not participate in VMM round-robin, and unequal sizes leave capacity outside the smallest-space parity baseline." \
            "make every defined paging space exactly the same size and active during an approved change window."
      fi
    else
      add storage paging_parity "Paging space parity" PASS med \
          "single paging space defined; multi-space parity not applicable" \
          "Only one paging space is defined, so there is no second space whose size or active state could be out of parity." \
          "n/a"
    fi
  fi

  # paging_layout — paging-space PLACEMENT, distinct from the %-used capacity check above.
  # Veteran signal: >1 paging space on ONE physical volume (they contend for the same disk —
  # no parallelism, the classic anti-pattern); paging confined to rootvg while another VG is
  # online (contends with OS I/O). Total paging vs RAM is informational (fw-assisted dump
  # uses a dedicated dump device, so paging < RAM is not a dump risk on modern AIX).
  if [ "${LSPS_OK:-0}" -ne 1 ]; then
    add storage paging_layout "Paging space layout" NOT_ASSESSED low "${LSPSWHY:-not assessed — lsps -a capture unavailable}" \
        "Paging-space placement could not be assessed because lsps -a failed, returned no evidence, or did not match the expected AIX output shape." \
        "run 'lsps -a' manually, then rerun AIXray before treating paging-space placement as healthy." "ffiec:II.C.11"
  elif [ "${VGL_OK:-0}" -ne 1 ]; then
    add storage paging_layout "Paging space layout" NOT_ASSESSED low "${VGLWHY:-not assessed — lsvg -o capture unavailable}" \
        "Paging-space placement could not be assessed completely because the online volume-group list was unavailable or unparseable." \
        "run 'lsvg -o' manually, then rerun AIXray before treating cross-VG paging placement as healthy." "ffiec:II.C.11"
  else
    set -- $(printf '%s\n' "$LSPS" | awk '
      NR>1 && NF>1 {
        n++; c[$2]++; if($3=="rootvg") r++
        s=$4; sub(/MB$/,"",s); if(s ~ /GB$/){sub(/GB$/,"",s); s=s*1024}; tot+=s+0
      }
      END{ dup=0; for(k in c) if(c[k]>1) dup=1; printf "%d %d %d %d", n+0, dup, (n>0 && r==n)?1:0, tot+0 }')
    PLNPS=${1:-0}; PLDUP=${2:-0}; PLROOT=${3:-0}; PLTOTMB=${4:-0}
    PLNOTE=""
    [ "${REALMB:-0}" -gt 0 ] && [ "$PLTOTMB" -gt 0 ] && PLNOTE=" Total paging ${PLTOTMB}MB vs ${REALMB}MB RAM."
    if [ "$PLDUP" -eq 1 ]; then
      add storage paging_layout "Paging space layout" WARN med "$PLNPS paging space(s), more than one on a single disk$PLNOTE" \
          "More than one paging space sits on the same physical volume — they cannot page in parallel because they contend for the one disk, so the second space buys capacity but no throughput. Paging is exactly when you want parallel spindles." \
          "put each paging space on a separate physical volume: remove the extra ('swapoff' then 'rmps'), recreate it on another PV with 'mkps -a <vg> <hdisk>'." "ffiec:II.C.11"
    elif [ "$PLROOT" -eq 1 ] && [ "${NVG:-1}" -gt 1 ]; then
      add storage paging_layout "Paging space layout" WARN low "all $PLNPS paging space(s) in rootvg while another VG is online$PLNOTE" \
          "All paging space is in rootvg even though another volume group is online — paging then competes with OS and filesystem I/O on the rootvg disks. Moving paging onto a data VG's spindles keeps a paging burst from starving the OS." \
          "add a paging space on another VG's disk ('mkps -a <datavg> <hdisk>') and shrink or remove the rootvg one once the new space is active." "ffiec:II.C.11"
    else
      add storage paging_layout "Paging space layout" PASS low "$PLNPS paging space(s), no single-disk contention$PLNOTE" \
          "Paging-space placement is fine — no two paging spaces share a disk, and there is no cross-VG contention to relieve. (Utilisation is checked separately under Paging space.)" "n/a"
    fi
  fi
}

# ---- E. Errors & events ----------------------------------------------------------------
# ---- errors depth references (errpt reference — refresh: spec 03) ----------------------
# The labels below are well-known AIX error-log LABELs from the IBM errpt catalog (the error
# record template repository, `errpt -t`), cross-checked against a live AIX 7.3 LPAR and the
# predefined errnotify ODM stanzas that ship with the OS. A veteran reads the LABEL and knows
# the subsystem in trouble instantly; this maps the critical ones to a plain-English meaning.
# errpt summary columns are IDENTIFIER TIMESTAMP T(ype) C(lass) RESOURCE DESCRIPTION; the
# `errpt -a` stanza form carries LABEL / IDENTIFIER / Class / Type / Resource Name, which is
# what the decode and signature checks parse. Class H=hardware S=software O=operator
# U=undetermined; Type PERM=permanent (unrecovered), TEMP=recovered after retries,
# PEND=impending failure, INFO=informational, UNKN=unknown.
# label | plain-English meaning + what to do
CRIT_ERRIDS="
SC_DISK_ERR1|disk operation error (adapter or drive) — investigate the drive and its path
SC_DISK_ERR2|permanent disk hardware error (drive or SAN path) — PERM means replace or repair
SC_DISK_ERR3|disk command/adapter error — I/O to the drive is failing
SC_DISK_ERR4|disk media / bad-block error — sectors going bad; recurring means replace the disk
DISK_ERR1|disk heavily worn — plan a replacement
DISK_ERR2|disk error (often loss of electrical power) — investigate
DISK_ERR3|disk error (often loss of electrical power) — investigate
DISK_ERR4|bad blocks on disk — more than one in a week means replace the disk
SCSI_ERR1|SCSI adapter hardware error
SCSI_ERR10|SCSI adapter/bus error — cabling, termination, or the adapter itself
SCSI_ARRAY_ERR6|RAID array error — a member disk or the array itself degraded
SCSI_ARRAY_ERR7|RAID array error — a member disk or the array itself degraded
FCS_ERR10|Fibre Channel adapter error — SAN link or path degrading
LVM_SA_QUORCLOSE|volume group lost quorum and was forced offline — an LVM disk dropped
LVM_SA_STALEPP|a mirror copy went stale — the mirror is out of sync
LVM_SA_PVMISS|a physical volume in a volume group went missing
LVM_IO_FAIL|LVM detected an I/O failure to a disk
EPOW_SUS|environmental/power event (EPOW) — power, thermal, or fan; call IBM service
EPOW_RES_CHRP|environmental/power event on the platform — check power and cooling
SCAN_ERROR_CHRP|processor/memory scan error (often correctable ECC over threshold) — a DIMM or CPU is degrading
FIRMWARE_EVENT|platform firmware logged a service event — check the service processor
DMPCHK_SMALL|the configured dump device is too small for a full dump — a panic will truncate it
FWDMP_IFAIL|firmware-assisted dump initialization failed — a panic may not capture a usable dump
"
ERR_CRIT_RECUR=3           # a critical LABEL seen >= this many times = actively recurring => FAIL
ERRDEMON_LOG_MIN=1048576   # default errlog size cap (bytes); a cap set below this = shrunk log

# errnotify_decode — the ONE place that classifies errnotify ODM en_method entries into
# custom (site-script) vs default (AIX-shipped, /usr/{lib,lpp,sbin}) methods. Believability
# review 2026-07-13 (review-queue #62, finding #7): checks_errors's errnotify_methods and
# checks_monitoring's errpt_notify used to read the SAME odmget errnotify data with TWO
# DIFFERENT, independently-invented heuristics — errnotify_methods decoded en_method paths
# (the real signal for "can this actually page a human"), while errpt_notify used a raw
# stanza-COUNT threshold (>6 stanzas = "custom methods exist"), which disagree whenever a
# box carries more than 6 stanzas that are all still default/diagela methods (or, in the
# other direction, fewer than 7 stanzas where one genuinely is a custom site script). Both
# checks now call this single decode so they can never again drift into a contradictory
# verdict about the exact same on-box fact. Output: "custc<TAB>defc<TAB>diag<TAB>custlist".
function errnotify_decode {
  aix odmget_errnotify odmget errnotify | awk '
    /en_method[ \t]*=/{
      m=$0; sub(/^[^"]*"/,"",m); sub(/"[^"]*$/,"",m)
      if(m=="") next
      if(m ~ /^\/usr\/(lib|lpp|sbin)\//){ defc++; if(m ~ /diagela/) diag=1 }
      else { custc++; cust=cust (cn++?"; ":"") m }
    }
    END{ printf "%d\t%d\t%d\t%s", custc+0, defc+0, diag+0, cust }'
}

function checks_errors {
  typeset C7 C30 ER EH N INFO OBSN TOP RES SD RC PRIM VM
  typeset ERDRUN ERDL ERDSZ ERDDUP ERA CRITFLAT DECODE DWORST DNONI DTOP DCRIT
  typeset SIGS SHI SLIST ENDEC ENCUST ENDEF ENDIAG ENLIST DIAGN
  typeset DHIS DSTAT DDATE DOK

  C7=$(errpt_cutoff 7); C30=$(errpt_cutoff 30)

  # errpt is not root-gated, but a nonzero rc means the log was unreadable — that
  # must WARN, never masquerade as "0 entries" clean. Count only non-informational
  # entries: the T (type) column is field 3 of the summary lines — exclude T=I,
  # keep P/T/U/PEND.
  ER=$(aix errpt_7d errpt -s "$C7"); RC=$?
  if [ "$RC" -ne 0 ]; then
    add errors errpt_recent "Error log (7 days)" WARN med "error log unreadable (rc $RC)" \
        "Could not read the error log ('errpt') — a WARN, not a clean pass; a failing box can also fail to report." \
        "run 'errpt' as root and check the error-logging daemon (errdemon)."
  else
    N=$(printf '%s' "$ER" | awk 'NR>1 && $3!="I"{n++} END{print n+0}')
    INFO=$(printf '%s' "$ER" | awk 'NR>1 && $3=="I"{n++} END{print n+0}')
    TOP=$(printf '%s' "$ER" | awk 'NR>1 && $3!="I"{c[$1]++} END{mx=0; for (k in c) if (c[k]>mx) {mx=c[k]; id=k} if (mx>1) printf "recurring %s x%d", id, mx}')
    OBSN="$N error entries"; [ "${INFO:-0}" -gt 0 ] && OBSN="$OBSN ($INFO informational ignored)"
    if [ "$N" -eq 0 ]; then
      add errors errpt_recent "Error log (7 days)" PASS low "$OBSN" "A quiet error log — most outages announce themselves here first." "n/a"
    elif [ "$N" -le 25 ]; then
      add errors errpt_recent "Error log (7 days)" WARN med "$OBSN${TOP:+ ($TOP)}" \
          "Errors are the box telling you something — read them before they escalate." \
          "review 'errpt -a' for these entries; fix or explain each recurring one."
    else
      add errors errpt_recent "Error log (7 days)" FAIL high "$OBSN${TOP:+ ($TOP)}" \
          "A noisy error log — something is actively wrong or flapping." \
          "triage 'errpt' now, most recent and most frequent first."
    fi
  fi

  EH=$(aix errpt_hw errpt -d H -T PERM -s "$C30"); RC=$?
  if [ "$RC" -ne 0 ]; then
    add errors errpt_hw "Permanent hardware errors (30 days)" WARN med "error log unreadable (rc $RC)" \
        "Could not read the hardware error log ('errpt -d H -T PERM') — a WARN, not a clean pass." \
        "run 'errpt -d H -T PERM' as root; check the error-logging daemon (errdemon)."
  else
    N=$(printf '%s' "$EH" | awk 'NR>1{n++} END{print n+0}')
    if [ "$N" -gt 0 ]; then
      RES=$(printf '%s' "$EH" | awk 'NR==2{print $5}')
      add errors errpt_hw "Permanent hardware errors (30 days)" FAIL high "$N entries (latest: ${RES:-unknown})" \
          "A component logged a permanent hardware error — something is failing now, before it fails hard." \
          "run 'errpt -a -d H -T PERM', identify the resource, engage hardware support."
    else
      add errors errpt_hw "Permanent hardware errors (30 days)" PASS high "none" "No permanent hardware errors logged." "n/a"
    fi
  fi

  SD=$(aix sysdumpdev_l sysdumpdev -l); RC=$?
  if [ "$RC" -ne 0 ] || [ -z "$SD" ]; then
    nr_warn errors sysdump "System dump device" "the system dump configuration" "sysdumpdev -l"
  else
    PRIM=$(printf '%s\n' "$SD" | awk '$1=="primary"{print $2; exit}')
    if [ "$PRIM" = "/dev/sysdumpnull" ] || [ -z "$PRIM" ]; then
      add errors sysdump "System dump device" FAIL med "primary: ${PRIM:-none}" \
          "If this box panics it cannot capture a dump — root-cause becomes guesswork." \
          "configure a dump device sized for this LPAR ('sysdumpdev -e', then -P -p /dev/<dumplv>)."
    else
      add errors sysdump "System dump device" PASS low "primary: $PRIM" "A panic here can be diagnosed." "n/a"
    fi
  fi

  VM=$(aix find_vmcore_30d find /var/adm/ras -name 'vmcore*' -mtime -30 -print)
  if [ -n "$VM" ]; then
    add errors crash_evidence "Recent crash evidence" WARN high "$(printf '%s\n' "$VM" | awk 'END{print NR}') dump file(s) in /var/adm/ras" \
        "This system crashed recently — was the dump analyzed and the cause fixed?" \
        "analyze with 'kdb' or send to IBM support; do not delete until root-caused."
  else
    add errors crash_evidence "Recent crash evidence" PASS low "none in 30 days" "No recent crash dumps found." "n/a"
  fi

  # ==================== LEVEL 2/3 ERRORS DEPTH (grouped findings) =======================
  # Each check states its veteran signal in the comment. Tuning/informational findings default
  # to WARN unless something is genuinely broken; real pre-failure signatures FAIL high. See
  # docs/DEPTH-STANDARD.md.

  # errdemon_health — is the error-logging daemon running, and is the errlog sized sanely?
  # Veteran signal: if errdemon is DOWN the error log is FROZEN — no new hardware or software
  # error is recorded, so every other check here (recent errors, hardware errors, pre-failure
  # signatures) is blind. That is why this gates the category. The errlog is a fixed-size
  # circular file (errdemon -l "Log Size", default 1 MB); once full it overwrites the oldest
  # entries, it does not stop logging — but a cap set BELOW the default shortens history.
  ERDRUN=$(printf '%s\n' "$(aix ps_e ps -e -o comm)" | awk '/errdemon/{n++} END{print n+0}')
  if [ "${ERDRUN:-0}" -eq 0 ]; then
    add errors errdemon_health "Error-logging daemon" FAIL high "errdemon not running" \
        "The error-logging daemon (errdemon) is not running, so the AIX error log is frozen: no new hardware or software error is being recorded, and every other check in this category — recent errors, permanent hardware errors, pre-failure signatures — is blind." \
        "start it: run '/usr/lib/errdemon' as root, then confirm new entries appear ('errpt') and the daemon is up ('ps -ef | grep errdemon')."
  else
    ERDL=$(aix errdemon_l /usr/lib/errdemon -l); RC=$?
    if [ "$RC" -ne 0 ] || [ -z "$ERDL" ]; then
      # Believability review 2026-07-13 (review-queue #62, finding #9): this used to PASS
      # here — but whether the errlog is capped below the 1 MB default (the actual
      # question this check asks) was never observed; only "the daemon is running" was.
      # A PASS that only proves part of what it claims is exactly the no-false-clean
      # anti-pattern: the log-size observation is missing, so the finding must be
      # NOT_ASSESSED, never PASS (the daemon-running fact alone is a WARN-worthy partial
      # read, not a clean bill of health for errlog sizing).
      add errors errdemon_health "Error-logging daemon" NOT_ASSESSED low "errdemon running; log-size configuration not read (needs root)" \
          "The error-logging daemon is up, so errors are being captured. Its log-size configuration could not be read (needs root), so whether the errlog is capped below the 1 MB default is unknown — re-run as root to confirm." "re-run aixray as root, or inspect 'errdemon -l' manually."
    else
      ERDSZ=$(printf '%s\n' "$ERDL" | awk '/Log Size/{for(i=1;i<=NF;i++) if($i ~ /^[0-9]+$/){print $i; exit}}')
      ERDDUP=$(printf '%s\n' "$ERDL" | awk '/Duplicate Removal/{print $NF}')
      : ${ERDSZ:=0}
      if [ "$ERDSZ" -gt 0 ] && [ "$ERDSZ" -lt "$ERRDEMON_LOG_MIN" ]; then
        add errors errdemon_health "Error-logging daemon" WARN low "errdemon running; errlog capped at ${ERDSZ} bytes (below the ${ERRDEMON_LOG_MIN}-byte default)" \
            "The error daemon is up, but the circular error log is capped below the 1 MB default — on a chatty box the oldest entries roll off sooner, so a fault that logged a few days ago may already be gone when you look." \
            "raise the errlog size as root: '/usr/lib/errdemon -s ${ERRDEMON_LOG_MIN}' (or larger); it takes effect immediately."
      else
        add errors errdemon_health "Error-logging daemon" PASS low "errdemon running; errlog ${ERDSZ} bytes, duplicate-removal ${ERDDUP:-?}" \
            "The error-logging daemon is up and the errlog is at or above the 1 MB default, so errors are captured with a reasonable history window. (The errlog is a fixed-size circular file — once full it overwrites the oldest entries, it never stops logging.)" "n/a"
      fi
    fi
  fi

  # errpt_decode — do not just COUNT recent errors, DECODE the recurring ones. Group the
  # non-informational `errpt -a` stanzas by LABEL and match against the embedded critical-label
  # table. Veteran signal: a veteran reads the LABEL (SC_DISK_ERR4, EPOW_SUS, LVM_SA_QUORCLOSE)
  # and instantly knows the subsystem in trouble; the plain-English decode plus class/type puts
  # that judgment in the report. (errpt_recent above counts; this decodes what they mean.)
  ERA=$(aix errpt_a7 errpt -a -s "$C7")
  # Feed the label table as leading input lines (terminated by a marker), then the errpt data:
  # AIX awk caps a -v value at 399 bytes, so the table cannot be passed as one variable — it is
  # loaded record-by-record instead, each label line well under the limit.
  DECODE=$(printf '%s\nAIXRAY_ERASEP\n%s\n' "$CRIT_ERRIDS" "$ERA" | awk -v recur="$ERR_CRIT_RECUR" '
    function rec(){
      if(!have) return
      have=0
      if(typ=="INFO") return
      cnt[lab]++; cls_[lab]=cls; typ_[lab]=typ; res_[lab]=res
      if(typ=="PERM") perm[lab]=1
    }
    !seent && $0=="AIXRAY_ERASEP"{ seent=1; next }
    !seent{ p=index($0,"|"); if(p>0){ C[substr($0,1,p-1)]=substr($0,p+1) } next }
    $1=="LABEL:"{ rec(); lab=$2; have=1; cls=""; typ=""; res="" }
    $1=="IDENTIFIER:"{ id=$2 }
    $1=="Class:"{ cls=$2 }
    $1=="Type:"{ typ=$2 }
    ($1=="Resource" && $2=="Name:"){ res=$3 }
    END{
      rec()
      worst=0; noni=0; topc=0; topl=""; out=""
      for(k in cnt){
        noni+=cnt[k]
        if(cnt[k]>topc){ topc=cnt[k]; topl=k }
        if(k in C){
          sev=1; if(perm[k] || cnt[k]>=recur) sev=2
          if(sev>worst) worst=sev
          out=out (out==""?"":"; ") k " x" cnt[k] " (" cls_[k] "/" typ_[k] (res_[k]!=""?" "res_[k]:"") "): " C[k]
        }
      }
      printf "%d\t%d\t%s\t%s", worst, noni, (topl==""?"none":topl " x" topc), out
    }')
  DWORST=$(printf '%s' "$DECODE" | awk -F'\t' '{print $1+0}')
  DNONI=$(printf '%s' "$DECODE" | awk -F'\t' '{print $2+0}')
  DTOP=$(printf '%s' "$DECODE" | awk -F'\t' '{print $3}')
  DCRIT=$(printf '%s' "$DECODE" | awk -F'\t' '{print $4}')
  if [ -n "$DCRIT" ]; then
    if [ "$DWORST" -ge 2 ]; then
      add errors errpt_decode "Decoded error labels" FAIL high "$DCRIT" \
          "The error log carries recurring or permanent critical error labels — a veteran reads these and knows exactly which subsystem is failing: $DCRIT." \
          "inspect each with 'errpt -a -j <IDENTIFIER>', run 'diag' against the named resource, and act on the decode above before it escalates."
    else
      add errors errpt_decode "Decoded error labels" WARN med "$DCRIT" \
          "A known-critical error label appeared (not yet recurring or permanent) — worth reading now, not waiting for it to escalate: $DCRIT." \
          "inspect it with 'errpt -a -j <IDENTIFIER>'; if it recurs or turns PERM, treat the named resource as failing."
    fi
  elif [ "${DNONI:-0}" -gt 0 ]; then
    add errors errpt_decode "Decoded error labels" PASS low "$DNONI non-informational error(s); most frequent: $DTOP; none match a known-critical label" \
        "There are non-informational errors, but none decode to a known-critical hardware or LVM label — most are software or operator events. (Counts and triage are under 'Error log' above; this check is the label decode.)" "n/a"
  else
    add errors errpt_decode "Decoded error labels" PASS low "no non-informational errors in 7 days" \
        "Nothing but informational entries in the error log — no labels to decode." "n/a"
  fi

  # errpt_signatures (LEVEL 3) — scan for the classic PRE-FAILURE signatures a veteran watches
  # for: disk media/hardware errors (drive about to fail), SCSI/FC path errors, EPOW power or
  # thermal events, memory/CPU ECC scan errors (a DIMM dying), adapter resets, LVM disk loss
  # (QUORCLOSE/PVMISS), and dump-device faults. Veteran signal: these are the patterns that mean
  # a component is degrading NOW, before it fails hard — the "it caught my disk before it died"
  # check. A genuine signature (PERM, recurring, power/memory/LVM/dump) FAILs high; a single
  # recovered (TEMP) event WARNs.
  SIGS=$(printf '%s\n' "$ERA" | awk '
    function rec(){
      if(!have) return
      have=0
      if(typ=="INFO") return
      fam=""
      if(lab ~ /DISK_ERR/) fam="disk"
      else if(lab ~ /SCSI_ERR|SCSI_ARRAY|FCP_|FSCSI|FCS_ERR|SAS_/) fam="fc_scsi"
      else if(lab ~ /EPOW/) fam="power"
      else if(lab ~ /SCAN_ERROR|CACHE|MEMORY|_MEM/ && cls=="H") fam="memory"
      else if(lab ~ /LVM_SA_QUORCLOSE|LVM_SA_PVMISS|LVM_IO_FAIL/) fam="lvm"
      else if(lab ~ /ADAP/) fam="adapter"
      else if(lab ~ /DMPCHK|FWDMP|FWADUMP|PLAT_DUMP_ERR/) fam="dump"
      if(fam=="") return
      cnt[fam]++; ex[fam]=lab
      if(typ=="PERM") perm[fam]=1
      if(cnt[fam]>1) recur[fam]=1
    }
    BEGIN{
      NM["disk"]="disk pre-failure"; NM["fc_scsi"]="SAN/SCSI path errors"
      NM["power"]="environmental/power (EPOW)"; NM["memory"]="memory/CPU (ECC)"
      NM["lvm"]="LVM disk loss"; NM["adapter"]="adapter reset/error"; NM["dump"]="dump-device fault"
    }
    $1=="LABEL:"{ rec(); lab=$2; have=1; cls=""; typ="" }
    $1=="Class:"{ cls=$2 }
    $1=="Type:"{ typ=$2 }
    END{
      rec()
      m=split("disk fc_scsi power memory lvm adapter dump", FO, " ")
      out=""; hi=0
      for(i=1;i<=m;i++){ f=FO[i]; if(f in cnt){
        out=out (out==""?"":"; ") NM[f] ": " ex[f] " x" cnt[f]
        if(perm[f] || recur[f] || f=="power" || f=="memory" || f=="lvm" || f=="dump") hi=1
      }}
      printf "%d\t%s", hi, out
    }')
  SHI=$(printf '%s' "$SIGS" | awk -F'\t' '{print $1+0}')
  SLIST=$(printf '%s' "$SIGS" | awk -F'\t' '{print $2}')
  if [ -n "$SLIST" ]; then
    if [ "$SHI" -eq 1 ]; then
      add errors errpt_signatures "Pre-failure signatures" FAIL high "$SLIST" \
          "The error log carries classic pre-failure hardware signatures — the patterns a veteran watches for that mean a component is degrading now, before it fails hard: $SLIST." \
          "inspect each with 'errpt -a -j <IDENTIFIER>', run 'diag' against the named resource, and engage hardware/SAN support before it fails outright."
    else
      add errors errpt_signatures "Pre-failure signatures" WARN med "$SLIST" \
          "A pre-failure signature appeared, but so far only as a single recovered (TEMP) event — worth watching, not yet an emergency: $SLIST." \
          "keep an eye on it with 'errpt -a -j <IDENTIFIER>'; if it recurs or turns PERM, treat the named resource as failing."
    fi
  else
    add errors errpt_signatures "Pre-failure signatures" PASS high "none in 7 days" \
        "None of the classic pre-failure patterns a veteran hunts for — disk/adapter errors, SAN/SCSI path faults, EPOW power or thermal events, memory ECC errors, LVM disk loss, or dump-device faults — appear in the error log for the last 7 days." "n/a"
  fi

  # errnotify_methods — decode WHAT the errnotify ODM stanzas actually DO, not just how many
  # there are (the monitoring category's errpt_notify reuses this SAME decode — see
  # errnotify_decode's own comment; review-queue #62 finding #7).
  # Veteran signal: a stanza whose en_method runs a SITE script (outside /usr/{lib,lpp,sbin})
  # actually pages or mails a human on a matching error; the default diagela stanzas forward
  # hardware errors to the diagnostics / Service Focal Point (call-home) path. Errors that log
  # but trigger no method tell no one.
  ENDEC=$(errnotify_decode)
  ENCUST=$(printf '%s' "$ENDEC" | awk -F'\t' '{print $1+0}')
  ENDEF=$(printf '%s' "$ENDEC" | awk -F'\t' '{print $2+0}')
  ENDIAG=$(printf '%s' "$ENDEC" | awk -F'\t' '{print $3+0}')
  ENLIST=$(printf '%s' "$ENDEC" | awk -F'\t' '{print $4}')
  DIAGN=""
  [ "$ENDIAG" -gt 0 ] && DIAGN=" AIX's default diagela stanzas also forward hardware errors to the diagnostics / Service Focal Point (call-home) path."
  if [ "$ENCUST" -gt 0 ]; then
    add errors errnotify_methods "Error notification methods" PASS low "$ENCUST custom alert method(s): $ENLIST" \
        "Custom errnotify ODM methods run a site script when a matching error is logged, so critical errors reach a human (page/mail), not just the log.$DIAGN" "n/a"
  elif [ "$ENDIAG" -gt 0 ]; then
    add errors errnotify_methods "Error notification methods" WARN low "default errnotify only (diagela call-home present, no site paging)" \
        "The default diagela stanzas forward hardware errors to the diagnostics / Service Focal Point path (call-home, if enabled on the HMC/service processor), but no stanza runs a site alert script — nothing pages or mails your on-call on a critical or disk error." \
        "add an errnotify ODM stanza (odmadd) whose en_method pages/mails on class=H PERM and disk labels (e.g. SC_DISK_ERR*, LVM_SA_QUORCLOSE)."
  else
    add errors errnotify_methods "Error notification methods" WARN med "no error-notification methods" \
        "No errnotify stanza runs anything — errors log locally and tell no one, so the error log only helps if someone happens to read it." \
        "add an errnotify ODM stanza that mails or pages on PERM hardware and disk errors."
  fi

  # dump_check_history — has a real system dump ever been captured, and did it complete?
  # Distinct from 'sysdump' (is a device configured?) and 'crash_evidence' (is a vmcore present
  # now?). Veteran signal: `sysdumpdev -L` shows the last dump's status — a dump that started but
  # did not complete (usually the dump device is too small) means the next panic loses its
  # forensics too. No dump ever recorded is expected on a box that has not panicked.
  # sysdumpdev -L prints "No previous dumps recorded." to STDERR and exits nonzero when no dump
  # has ever been taken, so merge stderr (2>&1) to keep that message — otherwise aix()'s
  # 2>/dev/null drops it and the no-dump case is indistinguishable from a read failure. The
  # message text, not the exit code, drives the verdict.
  DHIS=$(aix sysdumpdev_last sh -c 'sysdumpdev -L 2>&1')
  if printf '%s\n' "$DHIS" | grep -q 'No previous dumps recorded'; then
    add errors dump_history "System dump history" PASS low "no system dump ever recorded" \
        "The dump device has never captured a dump — expected on a box that has not panicked. It does mean the dump path is configured but unproven; only a real dump proves it works. (Whether a device is configured at all is checked separately under 'System dump device'.)" "n/a"
  elif ! printf '%s\n' "$DHIS" | grep -q 'Dump status'; then
    nr_warn errors dump_history "System dump history" "the system dump history" "sysdumpdev -L"
  else
    DSTAT=$(printf '%s\n' "$DHIS" | awk '/Dump status/{sub(/^[^:]*:[ \t]*/,""); print; exit}')
    DDATE=$(printf '%s\n' "$DHIS" | awk '/Date\/Time/{sub(/^[^:]*:[ \t]*/,""); print; exit}')
    DOK=$(printf '%s\n' "$DHIS" | awk '/completed successfully/{print 1; exit}')
    if [ "${DOK:-0}" = "1" ] || [ "${DSTAT:-x}" = "0" ]; then
      add errors dump_history "System dump history" PASS low "last dump ${DDATE:-recorded}, completed successfully" \
          "A real system dump was captured and completed — the dump device works and produced a usable dump. Confirm it was copied off (the copy directory) and analyzed if the crash was unexpected." "n/a"
    else
      add errors dump_history "System dump history" WARN high "last dump ${DDATE:-recorded}, status ${DSTAT:-unknown} (did not complete)" \
          "The system took a dump but it did not complete — the dump device likely failed to capture the full image (most often it is sized too small). If this box panics again, root-cause is lost with it." \
          "size the dump device to the current estimate ('sysdumpdev -e'); grow the dump LV to at least that, then re-check with 'sysdumpdev -L'."
    fi
  fi
}

# ---- F. Availability & resilience ------------------------------------------------------
# ---- resilience depth references (refresh: spec 03) -----------------------------------
# Sources: IBM AIX 7.3 System Dump / LVM / bosboot / NIM docs + live verification on an
# AIX 7.3 lab LPAR. Facts this category's depth relies on:
#   sysdumpdev -e estimates the dump size (bytes) from CURRENT memory use; the primary dump
#   DEVICE (an LV named by 'sysdumpdev -l') must be at least that or the next panic truncates
#   the dump and the forensics are lost. On reboot AIX COPIES the captured dump off the device
#   to the "copy directory" (sysdumpdev -l) before that device is reused — if the copy dir's
#   filesystem cannot hold a dump of the estimated size, the image is lost even though the
#   device captured it (same forensic loss, one step later). The dump estimate already reflects
#   fw-assisted/compressed dumps, so it is the right yardstick for both device and copy dir.
#   After a kernel/TL update the boot image on hd5 must be rebuilt (bosboot) or the box may
#   boot the pre-update kernel or fail to boot; AIXray is READ-ONLY so it cannot run or inspect
#   bosboot, and the /dev/hd5 node timestamp reflects device access (not the image build), so
#   bosboot_currency compares the kernel fileset (bos.mp64) install date to the last boot as a
#   proxy and says so. A NIM client (/etc/niminfo present) usually holds its mksysb/lpp_source
#   resources on the NIM master named in that file.
RES_DUMP_MARGIN_NUM=5    # dump device is "comfortable" only if size >= estimate * NUM/DEN
RES_DUMP_MARGIN_DEN=4    # (1.25x); between 1.0x and 1.25x is adequate-but-tight

# The alt-disk check runs in the findings phase and caches its structured facts
# for the later Contract 1.1 renderer.
# Assess the alt-disk recovery path and emit its graded finding plus the two
# Step-0 recovery facts owned by this one read-only job. Include-safe: the
# assembled scanner calls check_alt_disk_recoverability after the shared aix
# wrapper and finding helper are available, then renders the cached facts.

function alt_disk_json_escape {
  awk '
    {
      value=$0
      gsub(/\\/, "\\\\", value)
      gsub(/"/, "\\\"", value)
      gsub(/\t/, "\\t", value)
      gsub(/\r/, "\\r", value)
      gsub(/[\001-\010\013\014\016-\037]/, "", value)
      if (seen++) printf "\\n"
      printf "%s", value
    }
  '
}

function alt_disk_jstring {
  printf '"%s"' "$(printf '%s' "$1" | alt_disk_json_escape)"
}

function alt_disk_jnullable_string {
  if [ -n "$1" ]; then alt_disk_jstring "$1"; else printf 'null'; fi
}

function alt_disk_jbool {
  case "$1" in
    true|false) printf '%s' "$1";;
    *) printf 'null';;
  esac
}

function alt_disk_jnumber {
  case "$1" in
    ''|*[!0-9]*) printf 'null';;
    *) printf '%s' "$1";;
  esac
}

function alt_disk_jlist {
  typeset ALT_LIST_ITEM ALT_LIST_SEP
  ALT_LIST_SEP=""
  printf '['
  for ALT_LIST_ITEM in $1; do
    printf '%s"%s"' "$ALT_LIST_SEP" "$ALT_LIST_ITEM"
    ALT_LIST_SEP=','
  done
  printf ']'
}

function alt_disk_jnullable_list {
  if [ -n "$1" ]; then alt_disk_jlist "$1"; else printf 'null'; fi
}

function alt_disk_has_nonblank {
  printf '%s\n' "$1" | awk 'NF { found=1 } END { exit(found ? 0 : 1) }'
}

function alt_disk_add_reason {
  if [ -z "$1" ]; then
    printf '%s' "$2"
  elif [ -z "$2" ]; then
    printf '%s' "$1"
  else
    printf '%s; %s' "$1" "$2"
  fi
}

# The check phase owns the measurement.  Cache its rendered fact members so the
# later Contract 1.1 facts renderer cannot re-probe a changing live system and
# disagree with the finding derived from this same assessment.
ALT_DISK_RECOVERY_JSON=""
ALT_DISK_RECOVERY_ASSESSED=0
ALT_DISK_FINDING_ADDED=0
ALT_DISK_FINDING_STATUS=""
ALT_DISK_FINDING_SEVERITY=""
ALT_DISK_FINDING_OBSERVED=""
ALT_DISK_FINDING_MEANING=""
ALT_DISK_FINDING_FIX=""

function alt_disk_append {
  ALT_DISK_RECOVERY_JSON="${ALT_DISK_RECOVERY_JSON}$1"
}

function alt_disk_finding_value {
  if [ -n "$1" ]; then printf '%s' "$1"; else printf 'null'; fi
}

function alt_disk_finding_disks {
  if [ -z "$1" ]; then
    printf '[]'
  else
    printf '%s\n' "$1" | awk '
      NF {
        for (field=1; field<=NF; field++)
          printf "%s%s", (seen++ ? "," : "["), $field
      }
      END { print "]" }
    '
  fi
}

function alt_disk_finding_device_states {
  if [ -n "$1" ]; then printf '[%s]' "$1"; else printf 'null'; fi
}

# Derive the graded finding only from values already used to render
# alt_disk_usability.  The observed field is the sibling finding model's
# evidence carrier, so it names both measured values and the read-only source
# commands that produced them.
function alt_disk_set_finding {
  typeset ALT_FIND_FACT_STATUS ALT_FIND_USABLE ALT_FIND_VG ALT_FIND_DISKS
  typeset ALT_FIND_BOOT ALT_FIND_DEVICE_STATES ALT_FIND_BOOTABLE ALT_FIND_BOOTLIST
  typeset ALT_FIND_OS ALT_FIND_UPDATED ALT_FIND_AGE ALT_FIND_FRESHNESS ALT_FIND_REASON
  typeset ALT_FIND_DISK_JSON ALT_FIND_DISKS_KNOWN ALT_FIND_FIRST
  typeset ALT_FIND_SOURCES ALT_FIND_SOURCE_OVERRIDE
  typeset ALT_FIND_REASON_SUFFIX

  ALT_FIND_FACT_STATUS=$1
  ALT_FIND_USABLE=$2
  ALT_FIND_VG=$3
  ALT_FIND_DISKS=$4
  ALT_FIND_BOOT=$5
  ALT_FIND_DEVICE_STATES=$6
  ALT_FIND_BOOTABLE=$7
  ALT_FIND_BOOTLIST=$8
  ALT_FIND_OS=$9
  ALT_FIND_UPDATED=${10}
  ALT_FIND_AGE=${11}
  ALT_FIND_FRESHNESS=${12}
  ALT_FIND_REASON=${13}
  ALT_FIND_DISKS_KNOWN=${14:-true}
  ALT_FIND_SOURCE_OVERRIDE=${15:-}

  if [ "$ALT_FIND_DISKS_KNOWN" = true ]; then
    ALT_FIND_DISK_JSON=$(alt_disk_finding_disks "$ALT_FIND_DISKS")
  else
    ALT_FIND_DISK_JSON=null
  fi
  ALT_FIND_FIRST=$(printf '%s\n' "$ALT_FIND_DISKS" | awk 'NF { print $1; exit }')
  if [ -n "$ALT_FIND_SOURCE_OVERRIDE" ]; then
    ALT_FIND_SOURCES=$ALT_FIND_SOURCE_OVERRIDE
  else
    ALT_FIND_SOURCES="lspv"
    if [ -n "$ALT_FIND_DISKS" ]; then
      ALT_FIND_SOURCES="$ALT_FIND_SOURCES; lsdev -Cc disk -F \"name:status\""
      ALT_FIND_SOURCES="$ALT_FIND_SOURCES; alt_rootvg_op -q -d $ALT_FIND_FIRST"
      if [ -n "$ALT_FIND_BOOT" ]; then
        ALT_FIND_SOURCES="$ALT_FIND_SOURCES; bootinfo -B $ALT_FIND_BOOT"
        ALT_FIND_SOURCES="$ALT_FIND_SOURCES; bootlist -m normal -o"
      fi
      ALT_FIND_SOURCES="$ALT_FIND_SOURCES; oslevel -s"
      ALT_FIND_SOURCES="$ALT_FIND_SOURCES; cat /var/adm/ras/alt_disk_inst.log"
    fi
  fi
  if [ -n "$ALT_FIND_REASON" ]; then
    ALT_FIND_REASON_SUFFIX="; reason=$ALT_FIND_REASON"
  else
    ALT_FIND_REASON_SUFFIX=""
  fi

  ALT_DISK_FINDING_OBSERVED="status=$ALT_FIND_FACT_STATUS; usable=$(alt_disk_finding_value "$ALT_FIND_USABLE"); volume_group=$(alt_disk_finding_value "$ALT_FIND_VG"); disks=$ALT_FIND_DISK_JSON"
  if [ -n "$ALT_FIND_DISKS" ]; then
    ALT_DISK_FINDING_OBSERVED="$ALT_DISK_FINDING_OBSERVED; boot_disk=$(alt_disk_finding_value "$ALT_FIND_BOOT"); device_states=$(alt_disk_finding_device_states "$ALT_FIND_DEVICE_STATES"); platform_bootable=$(alt_disk_finding_value "$ALT_FIND_BOOTABLE"); in_normal_bootlist=$(alt_disk_finding_value "$ALT_FIND_BOOTLIST"); running_oslevel=$(alt_disk_finding_value "$ALT_FIND_OS"); freshness=$(alt_disk_finding_value "$ALT_FIND_FRESHNESS"); last_updated=$(alt_disk_finding_value "$ALT_FIND_UPDATED"); age_days=$(alt_disk_finding_value "$ALT_FIND_AGE")"
  fi
  ALT_DISK_FINDING_OBSERVED="$ALT_DISK_FINDING_OBSERVED$ALT_FIND_REASON_SUFFIX; source_commands=[$ALT_FIND_SOURCES]"

  case "$ALT_FIND_FACT_STATUS" in
    USABLE)
      if [ "$ALT_FIND_BOOTLIST" = true ] && [ -n "$ALT_FIND_OS" ]; then
        ALT_DISK_FINDING_STATUS=PASS
        ALT_DISK_FINDING_SEVERITY=low
        ALT_DISK_FINDING_MEANING="A current, platform-bootable alternate rootvg clone is measured and present in the normal bootlist."
        ALT_DISK_FINDING_FIX="n/a"
      elif [ "$ALT_FIND_BOOTLIST" = true ]; then
        ALT_DISK_FINDING_STATUS=NOT_ASSESSED
        ALT_DISK_FINDING_SEVERITY=high
        ALT_DISK_FINDING_MEANING="The clone appears current, bootable, and bootlisted, but the running OS level was unreadable; no complete currency grade is claimed."
        ALT_DISK_FINDING_FIX="rerun 'oslevel -s', resolve the read failure, and confirm the clone's documented update baseline before relying on rollback."
      elif [ "$ALT_FIND_BOOTLIST" = false ]; then
        ALT_DISK_FINDING_STATUS=WARN
        ALT_DISK_FINDING_SEVERITY=high
        ALT_DISK_FINDING_MEANING="A current, platform-bootable alternate rootvg clone exists, but it is not in the normal bootlist; rollback requires an explicit, tested bootlist change."
        ALT_DISK_FINDING_FIX="validate and document the rollback procedure; select $ALT_FIND_BOOT with 'bootlist -m normal' only during an approved rollback."
      else
        ALT_DISK_FINDING_STATUS=NOT_ASSESSED
        ALT_DISK_FINDING_SEVERITY=high
        ALT_DISK_FINDING_MEANING="The clone appears current and bootable, but normal-bootlist readiness was unreadable; no complete fast-rollback grade is claimed."
        ALT_DISK_FINDING_FIX="rerun 'bootlist -m normal -o', resolve the read failure, and validate the rollback boot selection."
      fi
      ;;
    NOT_CURRENT|NOT_USABLE)
      ALT_DISK_FINDING_STATUS=WARN
      ALT_DISK_FINDING_SEVERITY=high
      ALT_DISK_FINDING_MEANING="The measured alternate rootvg is not a reliable current fast-rollback path: $ALT_FIND_REASON."
      ALT_DISK_FINDING_FIX="create or refresh an alt_disk_copy clone of rootvg on a platform-bootable alternate disk, then verify its completion and rollback boot selection."
      ;;
    NOT_APPLICABLE)
      ALT_DISK_FINDING_STATUS=WARN
      ALT_DISK_FINDING_SEVERITY=high
      ALT_DISK_FINDING_MEANING="No alternate rootvg clone is configured, so this system has no measured fast-rollback path."
      ALT_DISK_FINDING_FIX="create and regularly refresh an alt_disk_copy clone of rootvg on a platform-bootable alternate disk; verify it with alt_rootvg_op and bootlist."
      ;;
    *)
      ALT_DISK_FINDING_STATUS=NOT_ASSESSED
      ALT_DISK_FINDING_SEVERITY=high
      ALT_DISK_FINDING_MEANING="The alt-disk recovery path could not be assessed from the captured read-only probes; no usability claim is made."
      ALT_DISK_FINDING_FIX="resolve the reported capture failure and rerun the lspv, lsdev, alt_rootvg_op, bootinfo, bootlist, oslevel, and alt_disk_inst.log probes."
      ;;
  esac
}

# Validate every lspv row before any hdisk token can become a capture key or
# command argument. The optional state is retained as one tab-delimited field.
function alt_disk_parse_lspv {
  awk '
    function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
    function pvid(value) {
      return value == "none" ||
        (value ~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/ &&
         substr(value,16,1) != "" && substr(value,17,1) == "")
    }
    function vg(value) {
      return value ~ /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/
    }
    function state_ok(value) {
      return value == "" || value == "active" || value == "missing" ||
        value == "removed" || value == "varied off" || value == "locked"
    }
    /^[ \t]*$/ { next }
    {
      rows++
      state=""
      for (field=4; field<=NF; field++)
        state=state (state=="" ? "" : " ") $field
      if (NF < 3 || !hdisk($1) || !pvid($2) || !vg($3) ||
          !state_ok(state) || seen[$1]++) {
        bad=1
        next
      }
      disk[rows]=$1
      disk_pvid[rows]=$2
      disk_vg[rows]=$3
      disk_state[rows]=state
    }
    END {
      if (bad || rows == 0) exit 1
      for (row=1; row<=rows; row++)
        printf "%s\t%s\t%s\t%s\n", disk[row], disk_pvid[row],
          disk_vg[row], disk_state[row]
    }
  '
}

function alt_disk_parse_lsdev_states {
  awk -F ':' '
    function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF != 2 || !hdisk($1) ||
          ($2 != "Available" && $2 != "Defined" && $2 != "Stopped") ||
          seen[$1]++) {
        bad=1
        next
      }
      disk[rows]=$1
      state[rows]=$2
    }
    END {
      if (bad || rows == 0) exit 1
      for (row=1; row<=rows; row++)
        printf "%s\t%s\n", disk[row], state[row]
    }
  '
}

function alt_disk_positive_integer {
  awk '
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF != 1 || $1 !~ /^[1-9][0-9]*$/) bad=1
      value=$1
    }
    END {
      if (bad || rows != 1) exit 1
      print value
    }
  '
}

function alt_disk_rootvg_pp_size {
  awk '
    {
      for (field=1; field+2<=NF; field++) {
        if ($field == "PP" && $(field+1) == "SIZE:" &&
            $(field+2) ~ /^[1-9][0-9]*$/) {
          matches++
          value=$(field+2)
        }
      }
    }
    END {
      if (matches != 1) exit 1
      print value
    }
  '
}

function alt_disk_rootvg_lp_count {
  awk '
    /^[ \t]*$/ { next }
    nonblank == 0 {
      nonblank++
      if ($0 !~ /^[ \t]*rootvg:[ \t]*$/) bad=1
      next
    }
    nonblank == 1 {
      nonblank++
      if ($1 != "LV" || $2 != "NAME" || $3 != "TYPE" ||
          $4 != "LPs" || $5 != "PPs" || $6 != "PVs") bad=1
      next
    }
    {
      nonblank++
      if (NF < 7 || $1 !~ /^[A-Za-z][A-Za-z0-9_.-]*$/ ||
          $2 !~ /^[A-Za-z][A-Za-z0-9_.-]*$/ ||
          $3 !~ /^[1-9][0-9]*$/ || $4 !~ /^[1-9][0-9]*$/ ||
          $5 !~ /^[1-9][0-9]*$/ || seen[$1]++) {
        bad=1
        next
      }
      rows++
      total += $3
    }
    END {
      if (bad || rows == 0 || total < 1) exit 1
      printf "%.0f\n", total
    }
  '
}

function alt_disk_oslevel_value {
  awk '
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF != 1 ||
          $1 !~ /^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]-[0-9][0-9][0-9][0-9]$/)
        bad=1
      value=$1
    }
    END {
      if (bad || rows != 1) exit 1
      print value
    }
  '
}

function alt_disk_boot_disk_value {
  typeset ALT_BOOT_MEMBERS
  ALT_BOOT_MEMBERS=$(printf '%s\n' "$1" | awk \
    'NF { printf "%s%s", (seen++ ? " " : ""), $1 }')
  awk -v members="$ALT_BOOT_MEMBERS" '
    BEGIN {
      count=split(members, item, " ")
      for (slot=1; slot<=count; slot++) allowed[item[slot]]=1
    }
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF != 1 || $1 !~ /^hdisk[0-9][0-9]*$/ || !allowed[$1]) bad=1
      value=$1
    }
    END {
      if (bad || rows != 1) exit 1
      print value
    }
  '
}

function alt_disk_bootinfo_value {
  awk '
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF != 1 || ($1 != "0" && $1 != "1")) bad=1
      value=$1
    }
    END {
      if (bad || rows != 1) exit 1
      print value
    }
  '
}

function alt_disk_bootlist_membership {
  typeset ALT_BOOTLIST_WANTED
  ALT_BOOTLIST_WANTED=$1
  awk -v wanted="$ALT_BOOTLIST_WANTED" '
    /^[ \t]*$/ { next }
    {
      rows++
      if ($1 !~ /^hdisk[0-9][0-9]*$/) {
        bad=1
        next
      }
      for (field=2; field<=NF; field++)
        if ($field !~ /^[A-Za-z][A-Za-z0-9_]*=[^ \t][^ \t]*$/) bad=1
      if ($1 == wanted) found=1
    }
    END {
      if (bad || rows == 0) exit 1
      print found ? "true" : "false"
    }
  '
}

function alt_disk_valid_ymd {
  typeset ALT_YMD ALT_YEAR ALT_REST ALT_MONTH ALT_DAY ALT_DIM
  ALT_YMD=$1
  case "$ALT_YMD" in
    [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]) ;;
    *) return 1;;
  esac
  ALT_YEAR=${ALT_YMD%%-*}
  ALT_REST=${ALT_YMD#*-}
  ALT_MONTH=${ALT_REST%%-*}
  ALT_DAY=${ALT_REST#*-}
  ALT_MONTH=${ALT_MONTH#0}
  ALT_DAY=${ALT_DAY#0}
  [ -n "$ALT_MONTH" ] || ALT_MONTH=0
  [ -n "$ALT_DAY" ] || ALT_DAY=0
  case "$ALT_MONTH" in
    1|3|5|7|8|10|12) ALT_DIM=31;;
    4|6|9|11) ALT_DIM=30;;
    2)
      if [ $((ALT_YEAR % 400)) -eq 0 ] ||
         { [ $((ALT_YEAR % 4)) -eq 0 ] && [ $((ALT_YEAR % 100)) -ne 0 ]; }; then
        ALT_DIM=29
      else
        ALT_DIM=28
      fi
      ;;
    *) return 1;;
  esac
  [ "$ALT_DAY" -ge 1 ] && [ "$ALT_DAY" -le "$ALT_DIM" ]
}

function alt_disk_d2j {
  typeset ALT_DATE ALT_YEAR ALT_REST ALT_MONTH ALT_DAY ALT_A
  ALT_DATE=$1
  ALT_YEAR=${ALT_DATE%%-*}
  ALT_REST=${ALT_DATE#*-}
  ALT_MONTH=${ALT_REST%%-*}
  ALT_DAY=${ALT_REST#*-}
  ALT_MONTH=${ALT_MONTH#0}
  ALT_DAY=${ALT_DAY#0}
  [ -n "$ALT_MONTH" ] || ALT_MONTH=0
  [ -n "$ALT_DAY" ] || ALT_DAY=0
  ALT_A=$(( (14 - ALT_MONTH) / 12 ))
  ALT_YEAR=$(( ALT_YEAR + 4800 - ALT_A ))
  ALT_MONTH=$(( ALT_MONTH + 12*ALT_A - 3 ))
  echo $(( ALT_DAY + (153*ALT_MONTH + 2)/5 + 365*ALT_YEAR +
    ALT_YEAR/4 - ALT_YEAR/100 + ALT_YEAR/400 - 32045 ))
}

# Print YYYY-MM-DD<TAB>hdiskN for the last completed Phase-3 record whose -d
# target set is exactly the topology-specific disk set supplied by the caller.
function alt_disk_log_completion {
  typeset ALT_LOG_DISKS
  ALT_LOG_DISKS=$(printf '%s\n' "$1" | awk \
    'NF { printf "%s%s", (seen++ ? " " : ""), $1 }')
  awk -v wanted="$ALT_LOG_DISKS" '
    function normalized_targets(line, count, field, start, value) {
      gsub(/"/, " ", line)
      gsub(/\047/, " ", line)
      count=split(line, token, /[ \t]+/)
      start=0
      delete target
      target_count=0
      for (field=1; field<=count; field++) {
        if (token[field] == "-d") {
          start=field+1
          break
        }
      }
      if (!start) return 0
      for (field=start; field<=count; field++) {
        value=token[field]
        if (value == "") continue
        if (substr(value,1,1) == "-") break
        if (value !~ /^hdisk[0-9][0-9]*$/ || target[value]++) return 0
        target_count++
      }
      if (target_count != wanted_count) return 0
      for (value in wanted_set) if (!target[value]) return 0
      return 1
    }
    BEGIN {
      month["Jan"]="01"; month["Feb"]="02"; month["Mar"]="03"
      month["Apr"]="04"; month["May"]="05"; month["Jun"]="06"
      month["Jul"]="07"; month["Aug"]="08"; month["Sep"]="09"
      month["Oct"]="10"; month["Nov"]="11"; month["Dec"]="12"
      wanted_count=split(wanted, wanted_item, " ")
      for (slot=1; slot<=wanted_count; slot++)
        wanted_set[wanted_item[slot]]=1
    }
    $1 ~ /^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)$/ && month[$2] != "" &&
      $3 ~ /^[0-9][0-9]*$/ && $4 ~ /^[0-9][0-9]:[0-9][0-9]:[0-9][0-9]$/ &&
      $6 ~ /^[0-9][0-9][0-9][0-9]$/ {
        day=$3+0
        if (day >= 1 && day <= 31) {
          current_date=sprintf("%04d-%s-%02d", $6+0, month[$2], day)
          record_match=0
        }
        next
      }
    /^cmd:/ {
      record_match=0
      if (current_date != "" && $0 ~ /(^|\/)alt_disk_copy([ \t]|$)/ &&
          normalized_targets($0)) {
        record_match=1
        completed_date=""
        completed_boot=""
      }
      next
    }
    record_match && /^Bootlist is set to the boot disk:[ \t]+hdisk[0-9]/ {
      boot=""
      for (field=1; field<=NF; field++)
        if ($field ~ /^hdisk[0-9][0-9]*$/) { boot=$field; break }
      if (boot != "" && wanted_set[boot]) {
        completed_date=current_date
        completed_boot=boot
      }
    }
    END {
      if (completed_date == "" || completed_boot == "") exit 1
      printf "%s\t%s\n", completed_date, completed_boot
    }
  '
}

function alt_disk_emit_spare_sources {
  alt_disk_append '"source_commands":{'
  alt_disk_append '"inventory":"lspv",'
  alt_disk_append '"rootvg":"lsvg rootvg",'
  alt_disk_append '"rootvg_lvs":"lsvg -l rootvg",'
  alt_disk_append '"device_state":"lsdev -Cc disk -F \"name:status\"",'
  alt_disk_append '"disk_size":"getconf DISK_SIZE /dev/<hdisk>",'
  alt_disk_append '"platform_bootable":"bootinfo -B <hdisk>"}'
}

function alt_disk_emit_alt_sources {
  alt_disk_append '"source_commands":{'
  alt_disk_append '"inventory":"lspv",'
  alt_disk_append '"device_state":"lsdev -Cc disk -F \"name:status\"",'
  alt_disk_append '"boot_disk":"alt_rootvg_op -q -d <hdisk>",'
  alt_disk_append '"platform_bootable":"bootinfo -B <hdisk>",'
  alt_disk_append '"normal_bootlist":"bootlist -m normal -o",'
  alt_disk_append '"running_oslevel":"oslevel -s",'
  alt_disk_append '"completion_log":"cat /var/adm/ras/alt_disk_inst.log"}'
}

function alt_disk_emit_inventory_unreadable {
  typeset ALT_FATAL_REASON ALT_ESCAPED_REASON
  ALT_FATAL_REASON=$1
  ALT_ESCAPED_REASON=$(printf '%s' "$ALT_FATAL_REASON" | alt_disk_json_escape)

  alt_disk_append '"usable_spare":{'
  alt_disk_append "$(printf '"status":"NOT_ASSESSED","eligible":null,"candidate_disk":null,"reason":"%s",' \
    "$ALT_ESCAPED_REASON")"
  alt_disk_append '"rootvg_required_mb":null,"checks":null,'
  alt_disk_emit_spare_sources
  alt_disk_append ',"basis":"not_assessed",'
  alt_disk_append '"unreadable":["eligible","candidate_disk","rootvg_required_mb","checks"],'
  alt_disk_append '"not_applicable":[]},'

  alt_disk_append '"alt_disk_usability":{'
  alt_disk_append "$(printf '"status":"NOT_ASSESSED","usable":null,"volume_group":null,"disks":null,"boot_disk":null,"device_states":null,"platform_bootable":null,"in_normal_bootlist":null,"running_oslevel":null,"last_updated":null,"age_days":null,"freshness":null,"freshness_basis":null,"completion_target_disks":null,"reason":"%s",' \
    "$ALT_ESCAPED_REASON")"
  alt_disk_emit_alt_sources
  alt_disk_append ',"basis":"not_assessed",'
  alt_disk_append '"unreadable":["usable","volume_group","disks","boot_disk","device_states","platform_bootable","in_normal_bootlist","running_oslevel","last_updated","age_days","freshness","freshness_basis","completion_target_disks"],'
  alt_disk_append '"not_applicable":[]}'
  alt_disk_set_finding NOT_ASSESSED "" "" "" "" "" "" "" "" "" "" "" \
    "$ALT_FATAL_REASON" false
}

function alt_disk_emit_no_spare {
  alt_disk_append '"usable_spare":{'
  alt_disk_append '"status":"INELIGIBLE","eligible":false,"candidate_disk":null,'
  alt_disk_append '"reason":"lspv reported no disks with volume group None",'
  alt_disk_append '"rootvg_required_mb":null,"checks":[],'
  alt_disk_emit_spare_sources
  alt_disk_append ',"basis":"observed","unreadable":[],'
  alt_disk_append '"not_applicable":["candidate_disk","rootvg_required_mb"]}'
}

function alt_disk_emit_no_existing {
  alt_disk_append '"alt_disk_usability":{'
  alt_disk_append '"status":"NOT_APPLICABLE","usable":null,"volume_group":null,'
  alt_disk_append '"disks":[],"boot_disk":null,"device_states":[],'
  alt_disk_append '"platform_bootable":null,"in_normal_bootlist":null,'
  alt_disk_append '"running_oslevel":null,"last_updated":null,"age_days":null,'
  alt_disk_append '"freshness":null,"freshness_basis":null,"completion_target_disks":null,'
  alt_disk_append '"reason":"lspv reported no altinst_rootvg or old_rootvg",'
  alt_disk_emit_alt_sources
  alt_disk_append ',"basis":"observed","unreadable":[],'
  alt_disk_append '"not_applicable":["usable","volume_group","boot_disk","platform_bootable","in_normal_bootlist","running_oslevel","last_updated","age_days","freshness","freshness_basis","completion_target_disks"]}'
  alt_disk_set_finding NOT_APPLICABLE "" "" "" "" "" "" "" "" "" "" "" \
    "lspv reported no altinst_rootvg or old_rootvg"
}

function alt_disk_assess_recoverability {
  typeset ALT_LSPV ALT_LSPV_RC ALT_ROWS ALT_PARSE_RC
  typeset ALT_FREE_ROWS ALT_FREE_DISKS ALT_EXISTING_ROWS ALT_EXISTING_DISKS ALT_ROOTVG_DISKS
  typeset ALT_VGS ALT_VG_COUNT ALT_VG
  typeset ALT_LSDEV ALT_LSDEV_RC ALT_LSDEV_ROWS ALT_LSDEV_PARSE_RC ALT_LSDEV_REASON
  typeset ALT_ROOTVG ALT_ROOTVG_RC ALT_ROOTLV ALT_ROOTLV_RC
  typeset ALT_PP_SIZE ALT_PP_RC ALT_LP_COUNT ALT_LP_RC ALT_REQUIRED ALT_ROOT_REASON
  typeset ALT_DISK ALT_PVID ALT_ROW_VG ALT_PV_STATE ALT_DEVICE_STATE ALT_LOOKUP_RC
  typeset ALT_LSPV_STATE ALT_PV_STATE_SAFE
  typeset ALT_STATE_KNOWN ALT_AVAILABLE ALT_SIZE_RAW ALT_SIZE_RC ALT_SIZE ALT_SIZE_PARSE_RC
  typeset ALT_SIZE_KNOWN ALT_SIZE_SUFFICIENT ALT_ROW_ELIGIBLE ALT_ROW_STATUS ALT_ROW_REASON
  typeset ALT_SPARE_BOOTABLE_RAW ALT_SPARE_BOOTABLE_RC ALT_SPARE_BOOTABLE_TOKEN
  typeset ALT_SPARE_BOOTABLE_PARSE_RC ALT_SPARE_BOOTABLE ALT_SPARE_BOOTABLE_REASON
  typeset ALT_ROW_UNREAD ALT_CHECKS ALT_CHECK ALT_ANY_ELIGIBLE ALT_ANY_UNKNOWN
  typeset ALT_SELECTED ALT_SPARE_STATUS ALT_SPARE_ELIGIBLE ALT_SPARE_REASON
  typeset ALT_SPARE_BASIS ALT_SPARE_UNREAD ALT_SPARE_NA ALT_ANY_ROW_GAP
  typeset ALT_DEVICE_ITEMS ALT_DEVICE_ITEM ALT_DEVICE_UNKNOWN ALT_DEVICE_BAD
  typeset ALT_ALT_STATE_BAD ALT_ALT_STATE_REASON ALT_FIRST_DISK
  typeset ALT_BOOT_RAW ALT_BOOT_RC ALT_BOOT_DISK ALT_BOOT_PARSE_RC ALT_BOOT_REASON
  typeset ALT_BOOTABLE_RAW ALT_BOOTABLE_RC ALT_BOOTABLE_TOKEN ALT_BOOTABLE_PARSE_RC
  typeset ALT_PLATFORM_BOOTABLE ALT_BOOTABLE_REASON
  typeset ALT_BOOTLIST ALT_BOOTLIST_RC ALT_IN_BOOTLIST ALT_BOOTLIST_PARSE_RC ALT_BOOTLIST_REASON
  typeset ALT_OS_RAW ALT_OS_RC ALT_RUNNING_OS ALT_OS_PARSE_RC ALT_OS_REASON
  typeset ALT_LOG ALT_LOG_RC ALT_COMPLETION ALT_COMPLETION_RC ALT_LAST_UPDATED ALT_LOG_BOOT
  typeset ALT_TODAY ALT_AGE ALT_FRESHNESS ALT_LOG_REASON ALT_LAST_J ALT_TODAY_J
  typeset ALT_LOG_TARGET_DISKS ALT_FRESHNESS_BASIS
  typeset ALT_USABLE ALT_STATUS ALT_REASON ALT_BASIS ALT_UNREAD ALT_NA
  typeset ALT_ESCAPED ALT_ITEM_STATE ALT_ITEM_AVAILABLE ALT_ITEM_STATUS ALT_ITEM_REASON
  typeset ALT_ITEM_PV_STATE ALT_ITEM_PV_SAFE

  ALT_DISK_RECOVERY_JSON=""
  ALT_DISK_RECOVERY_ASSESSED=1
  FACT_RECOVERY_ALT=""
  ALT_LSPV=$(aix lspv lspv)
  ALT_LSPV_RC=$?
  if [ "$ALT_LSPV_RC" -ne 0 ]; then
    alt_disk_emit_inventory_unreadable "lspv capture failed (rc=$ALT_LSPV_RC)"
    return 0
  fi
  if ! alt_disk_has_nonblank "$ALT_LSPV"; then
    alt_disk_emit_inventory_unreadable "lspv capture empty (rc=0)"
    return 0
  fi
  ALT_ROWS=$(printf '%s\n' "$ALT_LSPV" | alt_disk_parse_lspv)
  ALT_PARSE_RC=$?
  if [ "$ALT_PARSE_RC" -ne 0 ] || [ -z "$ALT_ROWS" ]; then
    alt_disk_emit_inventory_unreadable "lspv capture unparseable (rc=0)"
    return 0
  fi

  ALT_FREE_ROWS=$(printf '%s\n' "$ALT_ROWS" | awk -F '\t' '$3 == "None"')
  ALT_FREE_DISKS=$(printf '%s\n' "$ALT_FREE_ROWS" | awk -F '\t' 'NF { print $1 }')
  ALT_EXISTING_ROWS=$(printf '%s\n' "$ALT_ROWS" |
    awk -F '\t' '$3 == "altinst_rootvg" || $3 == "old_rootvg"')
  ALT_EXISTING_DISKS=$(printf '%s\n' "$ALT_EXISTING_ROWS" |
    awk -F '\t' 'NF { print $1 }')
  if [ -n "$ALT_EXISTING_DISKS" ]; then
    FACT_RECOVERY_ALT=true
  else
    FACT_RECOVERY_ALT=false
  fi
  ALT_ROOTVG_DISKS=$(printf '%s\n' "$ALT_ROWS" | awk -F '\t' '$3 == "rootvg" { print $1 }')

  ALT_LSDEV_ROWS=""
  ALT_LSDEV_REASON=""
  if [ -n "$ALT_FREE_DISKS" ] || [ -n "$ALT_EXISTING_DISKS" ]; then
    ALT_LSDEV=$(aix lsdev_disk_state lsdev -Cc disk -F "name:status")
    ALT_LSDEV_RC=$?
    if [ "$ALT_LSDEV_RC" -ne 0 ]; then
      ALT_LSDEV_REASON="lsdev -Cc disk -F \"name:status\" capture failed (rc=$ALT_LSDEV_RC)"
    elif ! alt_disk_has_nonblank "$ALT_LSDEV"; then
      ALT_LSDEV_REASON="lsdev -Cc disk -F \"name:status\" capture empty (rc=0)"
    else
      ALT_LSDEV_ROWS=$(printf '%s\n' "$ALT_LSDEV" | alt_disk_parse_lsdev_states)
      ALT_LSDEV_PARSE_RC=$?
      if [ "$ALT_LSDEV_PARSE_RC" -ne 0 ] || [ -z "$ALT_LSDEV_ROWS" ]; then
        ALT_LSDEV_ROWS=""
        ALT_LSDEV_REASON="lsdev -Cc disk -F \"name:status\" capture unparseable (rc=0)"
      fi
    fi
  fi

  # ---- New-clone spare eligibility -------------------------------------------------
  if [ -z "$ALT_FREE_DISKS" ]; then
    alt_disk_emit_no_spare
  else
    ALT_ROOT_REASON=""
    ALT_REQUIRED=""
    ALT_ROOTVG=$(aix lsvg_rootvg lsvg rootvg)
    ALT_ROOTVG_RC=$?
    ALT_ROOTLV=$(aix lsvg_l_rootvg lsvg -l rootvg)
    ALT_ROOTLV_RC=$?
    if [ "$ALT_ROOTVG_RC" -ne 0 ]; then
      ALT_ROOT_REASON="lsvg rootvg capture failed (rc=$ALT_ROOTVG_RC)"
    elif ! alt_disk_has_nonblank "$ALT_ROOTVG"; then
      ALT_ROOT_REASON="lsvg rootvg capture empty (rc=0)"
    else
      ALT_PP_SIZE=$(printf '%s\n' "$ALT_ROOTVG" | alt_disk_rootvg_pp_size)
      ALT_PP_RC=$?
      if [ "$ALT_PP_RC" -ne 0 ] || [ -z "$ALT_PP_SIZE" ]; then
        ALT_ROOT_REASON="lsvg rootvg capture unparseable (rc=0; PP SIZE unavailable)"
      fi
    fi
    if [ "$ALT_ROOTLV_RC" -ne 0 ]; then
      ALT_ROOT_REASON=$(alt_disk_add_reason "$ALT_ROOT_REASON" \
        "lsvg -l rootvg capture failed (rc=$ALT_ROOTLV_RC)")
    elif ! alt_disk_has_nonblank "$ALT_ROOTLV"; then
      ALT_ROOT_REASON=$(alt_disk_add_reason "$ALT_ROOT_REASON" \
        "lsvg -l rootvg capture empty (rc=0)")
    else
      ALT_LP_COUNT=$(printf '%s\n' "$ALT_ROOTLV" | alt_disk_rootvg_lp_count)
      ALT_LP_RC=$?
      if [ "$ALT_LP_RC" -ne 0 ] || [ -z "$ALT_LP_COUNT" ]; then
        ALT_ROOT_REASON=$(alt_disk_add_reason "$ALT_ROOT_REASON" \
          "lsvg -l rootvg capture unparseable (rc=0; LP footprint unavailable)")
      fi
    fi
    if [ -z "$ALT_ROOT_REASON" ]; then
      ALT_REQUIRED=$(awk -v pp="$ALT_PP_SIZE" -v lps="$ALT_LP_COUNT" \
        'BEGIN { value=pp*lps; if (value < 1 || value != int(value)) exit 1; printf "%.0f", value }')
      [ -n "$ALT_REQUIRED" ] || ALT_ROOT_REASON="rootvg LP footprint arithmetic failed"
    fi

    ALT_CHECKS=""
    ALT_ANY_ELIGIBLE=0
    ALT_ANY_UNKNOWN=0
    ALT_ANY_ROW_GAP=0
    ALT_SELECTED=""
    while IFS='	' read -r ALT_DISK ALT_PVID ALT_ROW_VG ALT_PV_STATE
    do
      [ -n "$ALT_DISK" ] || continue
      ALT_ROW_REASON=""
      ALT_ROW_UNREAD=""
      case "$ALT_PV_STATE" in
        '') ALT_LSPV_STATE=not_reported; ALT_PV_STATE_SAFE=true;;
        'varied off') ALT_LSPV_STATE=varied_off; ALT_PV_STATE_SAFE=false;;
        *) ALT_LSPV_STATE=$ALT_PV_STATE; ALT_PV_STATE_SAFE=false;;
      esac
      if [ "$ALT_PV_STATE_SAFE" = false ]; then
        ALT_ROW_REASON="$ALT_DISK lspv state is $ALT_PV_STATE, not an unreported free-PV state"
      fi
      ALT_DEVICE_STATE=""
      ALT_STATE_KNOWN=0
      ALT_AVAILABLE=""
      if [ -n "$ALT_LSDEV_REASON" ]; then
        ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" "$ALT_LSDEV_REASON")
        ALT_ROW_UNREAD="device_state available"
      else
        ALT_DEVICE_STATE=$(printf '%s\n' "$ALT_LSDEV_ROWS" | awk -F '\t' \
          -v wanted="$ALT_DISK" '$1 == wanted { print $2; found=1; exit } END { if (!found) exit 1 }')
        ALT_LOOKUP_RC=$?
        if [ "$ALT_LOOKUP_RC" -eq 0 ] && [ -n "$ALT_DEVICE_STATE" ]; then
          ALT_STATE_KNOWN=1
          if [ "$ALT_DEVICE_STATE" = Available ]; then
            ALT_AVAILABLE=true
          else
            ALT_AVAILABLE=false
            ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
              "$ALT_DISK device state is $ALT_DEVICE_STATE, not Available")
          fi
        else
          ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
            "lsdev disk-state capture reported no row for $ALT_DISK (rc=0)")
          ALT_ROW_UNREAD="device_state available"
        fi
      fi

      ALT_SIZE=""
      ALT_SIZE_KNOWN=0
      ALT_SIZE_RAW=$(aix "getconf_disk_size_$ALT_DISK" getconf DISK_SIZE "/dev/$ALT_DISK")
      ALT_SIZE_RC=$?
      if [ "$ALT_SIZE_RC" -ne 0 ]; then
        ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
          "getconf DISK_SIZE /dev/$ALT_DISK capture failed (rc=$ALT_SIZE_RC)")
        ALT_ROW_UNREAD="$ALT_ROW_UNREAD size_mb"
      elif ! alt_disk_has_nonblank "$ALT_SIZE_RAW"; then
        ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
          "getconf DISK_SIZE /dev/$ALT_DISK capture empty (rc=0)")
        ALT_ROW_UNREAD="$ALT_ROW_UNREAD size_mb"
      else
        ALT_SIZE=$(printf '%s\n' "$ALT_SIZE_RAW" | alt_disk_positive_integer)
        ALT_SIZE_PARSE_RC=$?
        if [ "$ALT_SIZE_PARSE_RC" -eq 0 ] && [ -n "$ALT_SIZE" ]; then
          ALT_SIZE_KNOWN=1
        else
          ALT_SIZE=""
          ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
            "getconf DISK_SIZE /dev/$ALT_DISK capture unparseable (rc=0)")
          ALT_ROW_UNREAD="$ALT_ROW_UNREAD size_mb"
        fi
      fi

      ALT_SIZE_SUFFICIENT=""
      if [ -n "$ALT_REQUIRED" ] && [ "$ALT_SIZE_KNOWN" -eq 1 ]; then
        if [ "$ALT_SIZE" -ge "$ALT_REQUIRED" ]; then
          ALT_SIZE_SUFFICIENT=true
        else
          ALT_SIZE_SUFFICIENT=false
          ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
            "$ALT_DISK size ${ALT_SIZE}MB is below rootvg LP footprint ${ALT_REQUIRED}MB")
        fi
      else
        [ -n "$ALT_ROOT_REASON" ] &&
          ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" "$ALT_ROOT_REASON")
        [ -n "$ALT_REQUIRED" ] || ALT_ROW_UNREAD="$ALT_ROW_UNREAD rootvg_required_mb"
        ALT_ROW_UNREAD="$ALT_ROW_UNREAD size_sufficient"
      fi

      ALT_SPARE_BOOTABLE=""
      ALT_SPARE_BOOTABLE_REASON=""
      ALT_SPARE_BOOTABLE_RAW=$(aix "bootinfo_bootable_$ALT_DISK" bootinfo -B "$ALT_DISK")
      ALT_SPARE_BOOTABLE_RC=$?
      if [ "$ALT_SPARE_BOOTABLE_RC" -ne 0 ]; then
        ALT_SPARE_BOOTABLE_REASON="bootinfo -B $ALT_DISK capture failed (rc=$ALT_SPARE_BOOTABLE_RC)"
      elif ! alt_disk_has_nonblank "$ALT_SPARE_BOOTABLE_RAW"; then
        ALT_SPARE_BOOTABLE_REASON="bootinfo -B $ALT_DISK capture empty (rc=0)"
      else
        ALT_SPARE_BOOTABLE_TOKEN=$(printf '%s\n' "$ALT_SPARE_BOOTABLE_RAW" |
          alt_disk_bootinfo_value)
        ALT_SPARE_BOOTABLE_PARSE_RC=$?
        if [ "$ALT_SPARE_BOOTABLE_PARSE_RC" -eq 0 ]; then
          if [ "$ALT_SPARE_BOOTABLE_TOKEN" = 1 ]; then ALT_SPARE_BOOTABLE=true
          else ALT_SPARE_BOOTABLE=false; fi
        else
          ALT_SPARE_BOOTABLE_REASON="bootinfo -B $ALT_DISK capture unparseable (rc=0)"
        fi
      fi
      if [ "$ALT_SPARE_BOOTABLE" = false ]; then
        ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
          "$ALT_DISK is not platform-bootable according to bootinfo -B")
      elif [ -z "$ALT_SPARE_BOOTABLE" ]; then
        ALT_ROW_REASON=$(alt_disk_add_reason "$ALT_ROW_REASON" \
          "$ALT_SPARE_BOOTABLE_REASON")
        ALT_ROW_UNREAD="$ALT_ROW_UNREAD platform_bootable"
      fi

      ALT_ROW_ELIGIBLE=""
      if [ "$ALT_PV_STATE_SAFE" = false ]; then
        ALT_ROW_ELIGIBLE=false
      elif [ "$ALT_STATE_KNOWN" -eq 1 ] && [ "$ALT_AVAILABLE" = false ]; then
        ALT_ROW_ELIGIBLE=false
      elif [ -n "$ALT_SIZE_SUFFICIENT" ] && [ "$ALT_SIZE_SUFFICIENT" = false ]; then
        ALT_ROW_ELIGIBLE=false
      elif [ "$ALT_SPARE_BOOTABLE" = false ]; then
        ALT_ROW_ELIGIBLE=false
      elif [ "$ALT_PV_STATE_SAFE" = true ] &&
           [ "$ALT_STATE_KNOWN" -eq 1 ] && [ "$ALT_AVAILABLE" = true ] &&
           [ "$ALT_SIZE_SUFFICIENT" = true ] && [ "$ALT_SPARE_BOOTABLE" = true ]; then
        ALT_ROW_ELIGIBLE=true
      else
        ALT_ROW_UNREAD="$ALT_ROW_UNREAD eligible"
      fi

      ALT_ROW_UNREAD=$(printf '%s\n' "$ALT_ROW_UNREAD" | awk '
        { for (field=1; field<=NF; field++) if (!seen[$field]++)
            output=output (output=="" ? "" : " ") $field }
        END { print output }')
      if [ "$ALT_ROW_ELIGIBLE" = true ]; then
        ALT_ROW_STATUS=ELIGIBLE
        ALT_ANY_ELIGIBLE=1
        [ -n "$ALT_SELECTED" ] || ALT_SELECTED=$ALT_DISK
      elif [ "$ALT_ROW_ELIGIBLE" = false ]; then
        ALT_ROW_STATUS=INELIGIBLE
      else
        ALT_ROW_STATUS=NOT_ASSESSED
        ALT_ANY_UNKNOWN=1
      fi
      [ -z "$ALT_ROW_UNREAD" ] || ALT_ANY_ROW_GAP=1

      ALT_CHECK=$(printf '%s' '{')
      ALT_CHECK="$ALT_CHECK\"hdisk\":$(alt_disk_jstring "$ALT_DISK"),"
      ALT_CHECK="$ALT_CHECK\"pvid\":$(alt_disk_jstring "$ALT_PVID"),"
      ALT_CHECK="$ALT_CHECK\"vg\":$(alt_disk_jstring "$ALT_ROW_VG"),"
      ALT_CHECK="$ALT_CHECK\"not_in_volume_group\":true,"
      ALT_CHECK="$ALT_CHECK\"lspv_state\":$(alt_disk_jstring "$ALT_LSPV_STATE"),"
      ALT_CHECK="$ALT_CHECK\"pv_state_safe\":$(alt_disk_jbool "$ALT_PV_STATE_SAFE"),"
      ALT_CHECK="$ALT_CHECK\"device_state\":$(alt_disk_jnullable_string "$ALT_DEVICE_STATE"),"
      ALT_CHECK="$ALT_CHECK\"available\":$(alt_disk_jbool "$ALT_AVAILABLE"),"
      ALT_CHECK="$ALT_CHECK\"size_mb\":$(alt_disk_jnumber "$ALT_SIZE"),"
      ALT_CHECK="$ALT_CHECK\"rootvg_required_mb\":$(alt_disk_jnumber "$ALT_REQUIRED"),"
      ALT_CHECK="$ALT_CHECK\"size_sufficient\":$(alt_disk_jbool "$ALT_SIZE_SUFFICIENT"),"
      ALT_CHECK="$ALT_CHECK\"platform_bootable\":$(alt_disk_jbool "$ALT_SPARE_BOOTABLE"),"
      ALT_CHECK="$ALT_CHECK\"eligible\":$(alt_disk_jbool "$ALT_ROW_ELIGIBLE"),"
      ALT_CHECK="$ALT_CHECK\"status\":$(alt_disk_jstring "$ALT_ROW_STATUS"),"
      ALT_CHECK="$ALT_CHECK\"reason\":$(alt_disk_jnullable_string "$ALT_ROW_REASON"),"
      ALT_CHECK="$ALT_CHECK\"unreadable\":$(alt_disk_jlist "$ALT_ROW_UNREAD")}"
      if [ -n "$ALT_CHECKS" ]; then ALT_CHECKS="$ALT_CHECKS,$ALT_CHECK"; else ALT_CHECKS=$ALT_CHECK; fi
    done <<EOF
$ALT_FREE_ROWS
EOF

    ALT_SPARE_UNREAD=""
    ALT_SPARE_NA=""
    if [ "$ALT_ANY_ELIGIBLE" -eq 1 ]; then
      ALT_SPARE_STATUS=ELIGIBLE
      ALT_SPARE_ELIGIBLE=true
      ALT_SPARE_REASON=""
    elif [ "$ALT_ANY_UNKNOWN" -eq 1 ]; then
      ALT_SPARE_STATUS=NOT_ASSESSED
      ALT_SPARE_ELIGIBLE=""
      ALT_SPARE_REASON="one or more free disks could not be fully assessed for clone eligibility"
      ALT_SPARE_UNREAD="eligible candidate_disk"
    else
      ALT_SPARE_STATUS=INELIGIBLE
      ALT_SPARE_ELIGIBLE=false
      ALT_SPARE_REASON="every disk with volume group None failed at least one captured eligibility check"
      ALT_SPARE_NA="candidate_disk"
    fi
    if [ -z "$ALT_REQUIRED" ]; then
      ALT_SPARE_UNREAD="$ALT_SPARE_UNREAD rootvg_required_mb"
    fi
    if [ "$ALT_ANY_ROW_GAP" -eq 1 ] || [ -n "$ALT_SPARE_UNREAD" ]; then
      ALT_SPARE_BASIS=partial
    else
      ALT_SPARE_BASIS=observed
    fi

    alt_disk_append '"usable_spare":{'
    alt_disk_append "$(printf '"status":"%s","eligible":%s,"candidate_disk":%s,"reason":%s,' \
      "$ALT_SPARE_STATUS" "$(alt_disk_jbool "$ALT_SPARE_ELIGIBLE")" \
      "$(alt_disk_jnullable_string "$ALT_SELECTED")" \
      "$(alt_disk_jnullable_string "$ALT_SPARE_REASON")")"
    alt_disk_append "$(printf '"rootvg_required_mb":%s,"checks":[%s],' \
      "$(alt_disk_jnumber "$ALT_REQUIRED")" "$ALT_CHECKS")"
    alt_disk_emit_spare_sources
    alt_disk_append "$(printf ',"basis":"%s","unreadable":%s,"not_applicable":%s}' \
      "$ALT_SPARE_BASIS" "$(alt_disk_jlist "$ALT_SPARE_UNREAD")" \
      "$(alt_disk_jlist "$ALT_SPARE_NA")")"
  fi

  alt_disk_append ','

  # ---- Existing alternate-rootvg rollback usability --------------------------------
  if [ -z "$ALT_EXISTING_DISKS" ]; then
    alt_disk_emit_no_existing
    return 0
  fi

  ALT_VGS=$(printf '%s\n' "$ALT_EXISTING_ROWS" | awk -F '\t' '!seen[$3]++ { print $3 }')
  ALT_VG_COUNT=$(printf '%s\n' "$ALT_VGS" | awk 'NF { count++ } END { print count+0 }')
  if [ "$ALT_VG_COUNT" -ne 1 ]; then
    ALT_ESCAPED="lspv reported more than one alternate-rootvg name; usability is ambiguous"
    alt_disk_append '"alt_disk_usability":{'
    alt_disk_append "$(printf '"status":"NOT_ASSESSED","usable":null,"volume_group":null,"disks":%s,' \
      "$(alt_disk_jlist "$ALT_EXISTING_DISKS")")"
    alt_disk_append '"boot_disk":null,"device_states":null,"platform_bootable":null,"in_normal_bootlist":null,"running_oslevel":null,"last_updated":null,"age_days":null,"freshness":null,"freshness_basis":null,"completion_target_disks":null,'
    alt_disk_append "$(printf '"reason":%s,' "$(alt_disk_jstring "$ALT_ESCAPED")")"
    alt_disk_emit_alt_sources
    alt_disk_append ',"basis":"partial",'
    alt_disk_append '"unreadable":["usable","volume_group","boot_disk","device_states","platform_bootable","in_normal_bootlist","running_oslevel","last_updated","age_days","freshness","freshness_basis","completion_target_disks"],"not_applicable":[]}'
    alt_disk_set_finding NOT_ASSESSED "" "" "$ALT_EXISTING_DISKS" "" "" "" "" \
      "" "" "" "" "$ALT_ESCAPED" true \
      'lspv; lsdev -Cc disk -F "name:status"'
    return 0
  fi
  ALT_VG=$(printf '%s\n' "$ALT_VGS" | awk 'NF { print; exit }')
  ALT_EXISTING_DISKS=$(printf '%s\n' "$ALT_EXISTING_ROWS" | awk -F '\t' -v vg="$ALT_VG" '$3 == vg { print $1 }')
  ALT_FIRST_DISK=$(printf '%s\n' "$ALT_EXISTING_DISKS" | awk 'NF { print; exit }')
  if [ "$ALT_VG" = old_rootvg ]; then
    ALT_LOG_TARGET_DISKS=$ALT_ROOTVG_DISKS
    ALT_FRESHNESS_BASIS=current_rootvg_phase3_completion
  else
    ALT_LOG_TARGET_DISKS=$ALT_EXISTING_DISKS
    ALT_FRESHNESS_BASIS=alternate_vg_phase3_completion
  fi

  ALT_DEVICE_ITEMS=""
  ALT_DEVICE_UNKNOWN=0
  ALT_DEVICE_BAD=0
  ALT_ALT_STATE_BAD=0
  ALT_ALT_STATE_REASON=""
  while IFS='	' read -r ALT_DISK ALT_PVID ALT_ROW_VG ALT_PV_STATE
  do
    [ "$ALT_ROW_VG" = "$ALT_VG" ] || continue
    ALT_ITEM_REASON=""
    case "$ALT_PV_STATE" in
      '') ALT_ITEM_PV_STATE=not_reported; ALT_ITEM_PV_SAFE=true;;
      'varied off') ALT_ITEM_PV_STATE=varied_off; ALT_ITEM_PV_SAFE=true;;
      *)
        ALT_ITEM_PV_STATE=$ALT_PV_STATE
        ALT_ITEM_PV_SAFE=false
        ALT_ALT_STATE_BAD=1
        ALT_ALT_STATE_REASON=$(alt_disk_add_reason "$ALT_ALT_STATE_REASON" \
          "$ALT_DISK lspv state is ${ALT_PV_STATE:-unknown}, not a sleeping alternate-rootvg state")
        ALT_ITEM_REASON="$ALT_DISK lspv state is ${ALT_PV_STATE:-unknown}, not a sleeping alternate-rootvg state"
        ;;
    esac

    ALT_ITEM_STATE=""
    ALT_ITEM_AVAILABLE=""
    ALT_ITEM_STATUS=NOT_ASSESSED
    if [ -n "$ALT_LSDEV_REASON" ]; then
      ALT_ITEM_REASON=$(alt_disk_add_reason "$ALT_ITEM_REASON" "$ALT_LSDEV_REASON")
      ALT_DEVICE_UNKNOWN=1
    else
      ALT_ITEM_STATE=$(printf '%s\n' "$ALT_LSDEV_ROWS" | awk -F '\t' \
        -v wanted="$ALT_DISK" '$1 == wanted { print $2; found=1; exit } END { if (!found) exit 1 }')
      ALT_LOOKUP_RC=$?
      if [ "$ALT_LOOKUP_RC" -eq 0 ] && [ -n "$ALT_ITEM_STATE" ]; then
        ALT_ITEM_STATUS=OBSERVED
        if [ "$ALT_ITEM_STATE" = Available ]; then
          ALT_ITEM_AVAILABLE=true
        else
          ALT_ITEM_AVAILABLE=false
          ALT_DEVICE_BAD=1
          ALT_ITEM_REASON=$(alt_disk_add_reason "$ALT_ITEM_REASON" \
            "$ALT_DISK device state is $ALT_ITEM_STATE, not Available")
        fi
      else
        ALT_ITEM_REASON=$(alt_disk_add_reason "$ALT_ITEM_REASON" \
          "lsdev disk-state capture reported no row for $ALT_DISK (rc=0)")
        ALT_DEVICE_UNKNOWN=1
      fi
    fi
    ALT_DEVICE_ITEM="{\"hdisk\":$(alt_disk_jstring "$ALT_DISK"),"
    ALT_DEVICE_ITEM="$ALT_DEVICE_ITEM\"lspv_state\":$(alt_disk_jstring "$ALT_ITEM_PV_STATE"),"
    ALT_DEVICE_ITEM="$ALT_DEVICE_ITEM\"pv_state_safe\":$(alt_disk_jbool "$ALT_ITEM_PV_SAFE"),"
    ALT_DEVICE_ITEM="$ALT_DEVICE_ITEM\"state\":$(alt_disk_jnullable_string "$ALT_ITEM_STATE"),"
    ALT_DEVICE_ITEM="$ALT_DEVICE_ITEM\"available\":$(alt_disk_jbool "$ALT_ITEM_AVAILABLE"),"
    ALT_DEVICE_ITEM="$ALT_DEVICE_ITEM\"status\":$(alt_disk_jstring "$ALT_ITEM_STATUS"),"
    ALT_DEVICE_ITEM="$ALT_DEVICE_ITEM\"reason\":$(alt_disk_jnullable_string "$ALT_ITEM_REASON")}"
    if [ -n "$ALT_DEVICE_ITEMS" ]; then
      ALT_DEVICE_ITEMS="$ALT_DEVICE_ITEMS,$ALT_DEVICE_ITEM"
    else
      ALT_DEVICE_ITEMS=$ALT_DEVICE_ITEM
    fi
  done <<EOF
$ALT_EXISTING_ROWS
EOF

  ALT_BOOT_DISK=""
  ALT_BOOT_REASON=""
  ALT_BOOT_RAW=$(aix "alt_rootvg_boot_$ALT_FIRST_DISK" alt_rootvg_op -q -d "$ALT_FIRST_DISK")
  ALT_BOOT_RC=$?
  if [ "$ALT_BOOT_RC" -ne 0 ]; then
    ALT_BOOT_REASON="alt_rootvg_op -q -d $ALT_FIRST_DISK capture failed (rc=$ALT_BOOT_RC)"
  elif ! alt_disk_has_nonblank "$ALT_BOOT_RAW"; then
    ALT_BOOT_REASON="alt_rootvg_op -q -d $ALT_FIRST_DISK capture empty (rc=0)"
  else
    ALT_BOOT_DISK=$(printf '%s\n' "$ALT_BOOT_RAW" |
      alt_disk_boot_disk_value "$ALT_EXISTING_DISKS")
    ALT_BOOT_PARSE_RC=$?
    if [ "$ALT_BOOT_PARSE_RC" -ne 0 ] || [ -z "$ALT_BOOT_DISK" ]; then
      ALT_BOOT_DISK=""
      ALT_BOOT_REASON="alt_rootvg_op -q -d $ALT_FIRST_DISK capture unparseable or outside the alternate VG (rc=0)"
    fi
  fi

  ALT_PLATFORM_BOOTABLE=""
  ALT_BOOTABLE_REASON=""
  ALT_IN_BOOTLIST=""
  ALT_BOOTLIST_REASON=""
  if [ -n "$ALT_BOOT_DISK" ]; then
    ALT_BOOTABLE_RAW=$(aix "bootinfo_bootable_$ALT_BOOT_DISK" bootinfo -B "$ALT_BOOT_DISK")
    ALT_BOOTABLE_RC=$?
    if [ "$ALT_BOOTABLE_RC" -ne 0 ]; then
      ALT_BOOTABLE_REASON="bootinfo -B $ALT_BOOT_DISK capture failed (rc=$ALT_BOOTABLE_RC)"
    elif ! alt_disk_has_nonblank "$ALT_BOOTABLE_RAW"; then
      ALT_BOOTABLE_REASON="bootinfo -B $ALT_BOOT_DISK capture empty (rc=0)"
    else
      ALT_BOOTABLE_TOKEN=$(printf '%s\n' "$ALT_BOOTABLE_RAW" | alt_disk_bootinfo_value)
      ALT_BOOTABLE_PARSE_RC=$?
      if [ "$ALT_BOOTABLE_PARSE_RC" -eq 0 ]; then
        if [ "$ALT_BOOTABLE_TOKEN" = 1 ]; then ALT_PLATFORM_BOOTABLE=true
        else ALT_PLATFORM_BOOTABLE=false; fi
      else
        ALT_BOOTABLE_REASON="bootinfo -B $ALT_BOOT_DISK capture unparseable (rc=0)"
      fi
    fi

    ALT_BOOTLIST=$(aix bootlist bootlist -m normal -o)
    ALT_BOOTLIST_RC=$?
    if [ "$ALT_BOOTLIST_RC" -ne 0 ]; then
      ALT_BOOTLIST_REASON="bootlist -m normal -o capture failed (rc=$ALT_BOOTLIST_RC)"
    elif ! alt_disk_has_nonblank "$ALT_BOOTLIST"; then
      ALT_BOOTLIST_REASON="bootlist -m normal -o capture empty (rc=0)"
    else
      ALT_IN_BOOTLIST=$(printf '%s\n' "$ALT_BOOTLIST" |
        alt_disk_bootlist_membership "$ALT_BOOT_DISK")
      ALT_BOOTLIST_PARSE_RC=$?
      if [ "$ALT_BOOTLIST_PARSE_RC" -ne 0 ] || [ -z "$ALT_IN_BOOTLIST" ]; then
        ALT_IN_BOOTLIST=""
        ALT_BOOTLIST_REASON="bootlist -m normal -o capture unparseable (rc=0)"
      fi
    fi
  fi

  ALT_RUNNING_OS=""
  ALT_OS_REASON=""
  ALT_OS_RAW=$(aix oslevel_s oslevel -s)
  ALT_OS_RC=$?
  if [ "$ALT_OS_RC" -ne 0 ]; then
    ALT_OS_REASON="oslevel -s capture failed (rc=$ALT_OS_RC)"
  elif ! alt_disk_has_nonblank "$ALT_OS_RAW"; then
    ALT_OS_REASON="oslevel -s capture empty (rc=0)"
  else
    ALT_RUNNING_OS=$(printf '%s\n' "$ALT_OS_RAW" | alt_disk_oslevel_value)
    ALT_OS_PARSE_RC=$?
    if [ "$ALT_OS_PARSE_RC" -ne 0 ] || [ -z "$ALT_RUNNING_OS" ]; then
      ALT_RUNNING_OS=""
      ALT_OS_REASON="oslevel -s capture unparseable (rc=0)"
    fi
  fi

  ALT_LAST_UPDATED=""
  ALT_AGE=""
  ALT_FRESHNESS=""
  ALT_LOG_REASON=""
  ALT_LOG=$(aix alt_disk_inst_log cat /var/adm/ras/alt_disk_inst.log)
  ALT_LOG_RC=$?
  if [ -z "$ALT_LOG_TARGET_DISKS" ]; then
    ALT_LOG_REASON="lspv reported no current rootvg disks for old_rootvg freshness correlation"
  elif [ "$ALT_LOG_RC" -ne 0 ]; then
    ALT_LOG_REASON="alt_disk_inst.log capture failed (rc=$ALT_LOG_RC)"
  elif ! alt_disk_has_nonblank "$ALT_LOG"; then
    ALT_LOG_REASON="alt_disk_inst.log capture empty (rc=0)"
  else
    ALT_COMPLETION=$(printf '%s\n' "$ALT_LOG" |
      alt_disk_log_completion "$ALT_LOG_TARGET_DISKS")
    ALT_COMPLETION_RC=$?
    if [ "$ALT_COMPLETION_RC" -eq 0 ] && [ -n "$ALT_COMPLETION" ]; then
      ALT_LAST_UPDATED=$(printf '%s\n' "$ALT_COMPLETION" | awk -F '\t' 'NF == 2 { print $1 }')
      ALT_LOG_BOOT=$(printf '%s\n' "$ALT_COMPLETION" | awk -F '\t' 'NF == 2 { print $2 }')
      ALT_TODAY=${AIXRAY_TODAY:-$(date +%Y-%m-%d)}
      if [ "$ALT_VG" = altinst_rootvg ] && [ -n "$ALT_BOOT_DISK" ] &&
         [ "$ALT_LOG_BOOT" != "$ALT_BOOT_DISK" ]; then
        ALT_LAST_UPDATED=""
        ALT_LOG_REASON="alt_disk_inst.log Phase-3 boot disk $ALT_LOG_BOOT does not match queried boot disk $ALT_BOOT_DISK"
      elif alt_disk_valid_ymd "$ALT_LAST_UPDATED" && alt_disk_valid_ymd "$ALT_TODAY"; then
        ALT_LAST_J=$(alt_disk_d2j "$ALT_LAST_UPDATED")
        ALT_TODAY_J=$(alt_disk_d2j "$ALT_TODAY")
        ALT_AGE=$((ALT_TODAY_J - ALT_LAST_J))
        if [ "$ALT_AGE" -lt 0 ]; then
          ALT_AGE=""
          ALT_FRESHNESS=""
          ALT_LOG_REASON="alt_disk_inst.log completion date $ALT_LAST_UPDATED is in the future"
        elif [ "$ALT_AGE" -le 30 ]; then
          ALT_FRESHNESS=FRESH
        elif [ "$ALT_AGE" -le 90 ]; then
          ALT_FRESHNESS=AGING
        else
          ALT_FRESHNESS=STALE
        fi
      else
        ALT_LAST_UPDATED=""
        ALT_LOG_REASON="alt_disk_inst.log completion date or assessment date is unparseable"
      fi
    else
      ALT_LOG_REASON="alt_disk_inst.log has no completed Phase-3 record for the exact $ALT_FRESHNESS_BASIS disk set"
    fi
  fi

  ALT_STATUS=""
  ALT_USABLE=""
  ALT_REASON=""
  if [ "$ALT_ALT_STATE_BAD" -eq 1 ]; then
    ALT_STATUS=NOT_USABLE
    ALT_USABLE=false
    ALT_REASON=$ALT_ALT_STATE_REASON
  elif [ "$ALT_DEVICE_BAD" -eq 1 ]; then
    ALT_STATUS=NOT_USABLE
    ALT_USABLE=false
    ALT_REASON="one or more alternate-rootvg disks are not Available"
  elif [ "$ALT_PLATFORM_BOOTABLE" = false ]; then
    ALT_STATUS=NOT_USABLE
    ALT_USABLE=false
    ALT_REASON="$ALT_BOOT_DISK is not platform-bootable according to bootinfo -B"
  elif [ "$ALT_FRESHNESS" = STALE ]; then
    ALT_STATUS=NOT_CURRENT
    ALT_USABLE=false
    ALT_REASON="matched alternate-rootvg Phase-3 completion is older than 90 days"
  elif [ "$ALT_DEVICE_UNKNOWN" -eq 1 ] || [ -z "$ALT_BOOT_DISK" ] ||
       [ -z "$ALT_PLATFORM_BOOTABLE" ] || [ -z "$ALT_FRESHNESS" ]; then
    ALT_STATUS=NOT_ASSESSED
    ALT_USABLE=""
  else
    ALT_STATUS=USABLE
    ALT_USABLE=true
    if [ "$ALT_IN_BOOTLIST" = false ]; then
      ALT_REASON="alternate boot disk is not in the current normal bootlist; rollback requires a bootlist change"
    fi
  fi

  [ "$ALT_DEVICE_UNKNOWN" -eq 1 ] &&
    ALT_REASON=$(alt_disk_add_reason "$ALT_REASON" \
      "one or more alternate-rootvg device states are unreadable")
  [ -n "$ALT_BOOT_REASON" ] &&
    ALT_REASON=$(alt_disk_add_reason "$ALT_REASON" "$ALT_BOOT_REASON")
  [ -n "$ALT_BOOTABLE_REASON" ] &&
    ALT_REASON=$(alt_disk_add_reason "$ALT_REASON" "$ALT_BOOTABLE_REASON")
  [ -n "$ALT_BOOTLIST_REASON" ] &&
    ALT_REASON=$(alt_disk_add_reason "$ALT_REASON" "$ALT_BOOTLIST_REASON")
  [ -n "$ALT_OS_REASON" ] &&
    ALT_REASON=$(alt_disk_add_reason "$ALT_REASON" "$ALT_OS_REASON")
  [ -n "$ALT_LOG_REASON" ] &&
    ALT_REASON=$(alt_disk_add_reason "$ALT_REASON" "$ALT_LOG_REASON")

  ALT_UNREAD=""
  [ -z "$ALT_USABLE" ] && ALT_UNREAD="$ALT_UNREAD usable"
  [ -z "$ALT_BOOT_DISK" ] && ALT_UNREAD="$ALT_UNREAD boot_disk"
  [ -z "$ALT_PLATFORM_BOOTABLE" ] && ALT_UNREAD="$ALT_UNREAD platform_bootable"
  [ -z "$ALT_IN_BOOTLIST" ] && ALT_UNREAD="$ALT_UNREAD in_normal_bootlist"
  [ -z "$ALT_RUNNING_OS" ] && ALT_UNREAD="$ALT_UNREAD running_oslevel"
  [ -z "$ALT_LAST_UPDATED" ] && ALT_UNREAD="$ALT_UNREAD last_updated"
  [ -z "$ALT_AGE" ] && ALT_UNREAD="$ALT_UNREAD age_days"
  [ -z "$ALT_FRESHNESS" ] && ALT_UNREAD="$ALT_UNREAD freshness"
  [ -z "$ALT_FRESHNESS_BASIS" ] && ALT_UNREAD="$ALT_UNREAD freshness_basis"
  [ -z "$ALT_LOG_TARGET_DISKS" ] && ALT_UNREAD="$ALT_UNREAD completion_target_disks"
  ALT_UNREAD=$(printf '%s\n' "$ALT_UNREAD" | awk '
    { for (field=1; field<=NF; field++) if (!seen[$field]++)
        output=output (output=="" ? "" : " ") $field }
    END { print output }')
  if [ -n "$ALT_UNREAD" ] || [ "$ALT_DEVICE_UNKNOWN" -eq 1 ]; then
    ALT_BASIS=partial
  else
    ALT_BASIS=observed
  fi
  ALT_NA=""

  alt_disk_append '"alt_disk_usability":{'
  alt_disk_append "$(printf '"status":"%s","usable":%s,"volume_group":%s,"disks":%s,' \
    "$ALT_STATUS" "$(alt_disk_jbool "$ALT_USABLE")" \
    "$(alt_disk_jstring "$ALT_VG")" "$(alt_disk_jlist "$ALT_EXISTING_DISKS")")"
  alt_disk_append "$(printf '"boot_disk":%s,"device_states":[%s],' \
    "$(alt_disk_jnullable_string "$ALT_BOOT_DISK")" "$ALT_DEVICE_ITEMS")"
  alt_disk_append "$(printf '"platform_bootable":%s,"in_normal_bootlist":%s,' \
    "$(alt_disk_jbool "$ALT_PLATFORM_BOOTABLE")" "$(alt_disk_jbool "$ALT_IN_BOOTLIST")")"
  alt_disk_append "$(printf '"running_oslevel":%s,"last_updated":%s,"age_days":%s,"freshness":%s,' \
    "$(alt_disk_jnullable_string "$ALT_RUNNING_OS")" \
    "$(alt_disk_jnullable_string "$ALT_LAST_UPDATED")" \
    "$(alt_disk_jnumber "$ALT_AGE")" "$(alt_disk_jnullable_string "$ALT_FRESHNESS")")"
  alt_disk_append "$(printf '"freshness_basis":%s,"completion_target_disks":%s,' \
    "$(alt_disk_jnullable_string "$ALT_FRESHNESS_BASIS")" \
    "$(alt_disk_jnullable_list "$ALT_LOG_TARGET_DISKS")")"
  alt_disk_append "$(printf '"reason":%s,' "$(alt_disk_jnullable_string "$ALT_REASON")")"
  alt_disk_emit_alt_sources
  alt_disk_append "$(printf ',"basis":"%s","unreadable":%s,"not_applicable":%s}' \
    "$ALT_BASIS" "$(alt_disk_jlist "$ALT_UNREAD")" "$(alt_disk_jlist "$ALT_NA")")"
  alt_disk_set_finding "$ALT_STATUS" "$ALT_USABLE" "$ALT_VG" "$ALT_EXISTING_DISKS" \
    "$ALT_BOOT_DISK" "$ALT_DEVICE_ITEMS" "$ALT_PLATFORM_BOOTABLE" "$ALT_IN_BOOTLIST" \
    "$ALT_RUNNING_OS" "$ALT_LAST_UPDATED" "$ALT_AGE" "$ALT_FRESHNESS" "$ALT_REASON"
}

function check_alt_disk_recoverability {
  if [ "$ALT_DISK_RECOVERY_ASSESSED" -ne 1 ]; then
    alt_disk_assess_recoverability
  fi
  if [ "$ALT_DISK_FINDING_ADDED" -ne 1 ]; then
    add resilience alt_disk "Alternate rootvg clone" \
      "$ALT_DISK_FINDING_STATUS" "$ALT_DISK_FINDING_SEVERITY" \
      "$ALT_DISK_FINDING_OBSERVED" "$ALT_DISK_FINDING_MEANING" \
      "$ALT_DISK_FINDING_FIX"
    ALT_DISK_FINDING_ADDED=1
  fi
}

function emit_fact_alt_disk_recoverability {
  if [ "$ALT_DISK_RECOVERY_ASSESSED" -ne 1 ]; then
    alt_disk_assess_recoverability
  fi
  printf '%s' "$ALT_DISK_RECOVERY_JSON"
}

# mon2num — three-letter English month name (who -b / ls -l form) -> 01..12; empty if unknown.
function mon2num {
  case "$1" in
    Jan) echo 01;; Feb) echo 02;; Mar) echo 03;; Apr) echo 04;; May) echo 05;; Jun) echo 06;;
    Jul) echo 07;; Aug) echo 08;; Sep) echo 09;; Oct) echo 10;; Nov) echo 11;; Dec) echo 12;;
    *) echo "";;
  esac
}

function checks_resilience {
  typeset R31 R91 R31RC R91RC RC MIRRLINE NPV MIRR BL ND HAF CL STATE NIMNOTE RVGO QUOR VGL VG VGD CV RVGMISS RVGSTALE
  typeset ROOTP ROOTL ROOTPRC ROOTLRC HAFRC CLRC
  typeset SD PRIM DUMPLV DEST ESTMB ESTGB LSDLV DPPS DPPMB DEVMB COPYDIR DFG CDFREE MARGIN
  typeset NIMI NIMMASTER NIMNAME NIMCONF NIMPROBERC WB BMON BDAY BMM BYEAR BJUL KINST KMM KDD KYY KJUL

  # NIM awareness — a NIM-managed box may hold mksysb resources on the master
  aix ls_niminfo ls /etc/niminfo >/dev/null 2>&1; NIMPROBERC=$?
  NIMNOTE=""
  # F1 retains rc=2 as the explicit absence result. Every other non-zero
  # outcome is unreadable: a probe that did not complete cannot prove absence.
  case "$NIMPROBERC" in
    0)
      NIMNOTE=" This box is NIM-managed — check the NIM master's mksysb resources too."
      FACT_RECOVERY_NIM=true
      ;;
    2) FACT_RECOVERY_NIM=false;;
    *) FACT_RECOVERY_NIM="";;
  esac

  # mksysb evidence: /image.data is rewritten by every mksysb/mkszfile — honest local proof
  R31=$(aix find_imagedata_31d find /image.data -mtime -31 -print); R31RC=$?
  if [ "$R31RC" -eq 0 ] && [ -n "$R31" ]; then
    FACT_RECOVERY_MKSYSB=fresh
    add resilience mksysb_age "OS backup (mksysb) evidence" PASS high "/image.data updated within 30 days" \
        "Local evidence of a recent mksysb — your OS restore point is fresh.$NIMNOTE" "n/a" "ffiec:II.C.21"
  else
    R91=$(aix find_imagedata_91d find /image.data -mtime -91 -print); R91RC=$?
    if [ "$R31RC" -eq 0 ] && [ -z "$R31" ] &&
       [ "$R91RC" -eq 0 ] && [ -n "$R91" ]; then
      FACT_RECOVERY_MKSYSB=aging
      add resilience mksysb_age "OS backup (mksysb) evidence" WARN high "/image.data is 31-90 days old" \
          "The restore point is aging — everything since is unrecoverable. (This is local evidence only; a NIM server may hold newer backups — confirm.)$NIMNOTE" \
          "run a mksysb now and put it on a schedule (NIM or cron to NFS)." "ffiec:II.C.21"
    else
      aix ls_imagedata ls /image.data >/dev/null; RC=$?
      if [ "$R31RC" -eq 0 ] && [ -z "$R31" ] &&
         [ "$R91RC" -eq 0 ] && [ -z "$R91" ] && [ "$RC" -eq 0 ]; then
        FACT_RECOVERY_MKSYSB=stale
        add resilience mksysb_age "OS backup (mksysb) evidence" FAIL high "/image.data older than 90 days" \
            "No recent OS backup evidence on this box — a rootvg loss means rebuild-from-scratch. (Local evidence only; confirm where mksysb lands and when it last ran.)$NIMNOTE" \
            "run a mksysb now; schedule it; verify the target is itself backed up." "ffiec:II.C.21"
      elif [ "$R31RC" -eq 0 ] && [ -z "$R31" ] &&
           [ "$R91RC" -eq 0 ] && [ -z "$R91" ] &&
           [ "$RC" -ne 126 ] && [ "$RC" -ne 127 ]; then
        FACT_RECOVERY_MKSYSB=absent
        add resilience mksysb_age "OS backup (mksysb) evidence" FAIL high "no /image.data found" \
            "No evidence this OS has ever been backed up — a rootvg loss means rebuild-from-scratch. (Local evidence only; confirm whether NIM backs this box up.)$NIMNOTE" \
            "run 'mksysb -i' to a file or NIM now; then schedule it." "ffiec:II.C.21"
      else
        FACT_RECOVERY_MKSYSB=unreadable
        add resilience mksysb_age "OS backup (mksysb) evidence" WARN high "mksysb freshness unreadable" \
            "One or more local /image.data freshness probes failed — no age band can be claimed safely.$NIMNOTE" \
            "check /image.data and run the find/ls probes manually; confirm the latest NIM or local mksysb." "ffiec:II.C.21"
      fi
    fi
  fi

  # rootvg mirroring
  ROOTP=$(aix lsvg_p_rootvg lsvg -p rootvg); ROOTPRC=$?
  ROOTL=$(aix lsvg_l_rootvg lsvg -l rootvg); ROOTLRC=$?
  NPV=$(printf '%s\n' "$ROOTP" | awk '$1 ~ /^hdisk/ {n++} END{print n+0}')
  MIRR=$(printf '%s\n' "$ROOTL" | awk '$2!="sysdump" && $3 ~ /^[0-9]+$/ {t++; if ($4+0 >= 2*$3) m++} END{if (t>0 && m==t) print "full"; else if (m>0) print "partial"; else print "none"}')
  if [ "$ROOTPRC" -eq 0 ] && [ "$NPV" -gt 0 ] && valid_json_number "$NPV"; then
    FACT_RECOVERY_MIRROR_DISKS="$NPV"
  fi
  if [ "$ROOTLRC" -eq 0 ]; then
    FACT_RECOVERY_MIRROR=$(printf '%s\n' "$ROOTL" | awk '$2!="sysdump" && $3 ~ /^[0-9]+$/ {t++; if ($4+0 >= 2*$3) m++} END{if(t>0){if(m==t)print "full"; else if(m>0)print "partial"; else print "none"}}')
  fi
  # A PP-count "full mirror" is a lie if a PV is already missing or LVs are stale:
  # the copy is gone/out of sync and the box is running on the survivor.
  RVGMISS=$(printf '%s\n' "$ROOTP" | awk '$2=="missing" || $2=="removed" {n++} END{print n+0}')
  RVGSTALE=$(printf '%s\n' "$ROOTL" | awk '/stale/{n++} END{print n+0}')
  if [ "$NPV" -le 1 ]; then
    add resilience rootvg_mirror "rootvg redundancy" WARN high "1 disk, unmirrored" \
        "The OS lives on one disk — a single point of failure unless the backing storage is RAID/SAN-protected. Verify which." \
        "mirror rootvg (mirrorvg + bosboot + bootlist) or document the storage-level protection."
  elif [ "${RVGMISS:-0}" -gt 0 ] || [ "${RVGSTALE:-0}" -gt 0 ]; then
    add resilience rootvg_mirror "rootvg redundancy" FAIL high "$NPV disks, mirror degraded" \
        "The PP counts say 'mirrored', but a rootvg disk is missing or LVs are stale — a copy is already lost/out of sync and you are running on the surviving copy. This is not redundancy." \
        "address the disk first (check errpt and 'lsvg -p rootvg'), then resync once it is back ('syncvg -v rootvg'); do not trust the mirror until every LV reads syncd."
  elif [ "$MIRR" = "full" ]; then
    add resilience rootvg_mirror "rootvg redundancy" PASS low "$NPV disks, fully mirrored" \
        "The OS survives a single disk loss." "n/a"
  elif [ "$MIRR" = "partial" ]; then
    add resilience rootvg_mirror "rootvg redundancy" FAIL med "$NPV disks, partially mirrored" \
        "Some LVs are mirrored and some are not — a disk loss still takes the box down, while costing mirror overhead." \
        "finish the mirror ('mirrorvg rootvg', bosboot, bootlist) or unmirror deliberately."
  else
    add resilience rootvg_mirror "rootvg redundancy" WARN high "$NPV disks, no LV copies" \
        "rootvg spans multiple disks with no mirroring — losing any one of them takes the OS down." \
        "mirror rootvg, or shrink it to one protected disk."
  fi
  # VIOS weighting: on a VIOS, rootvg loss takes down I/O for EVERY client LPAR — the most
  # critical disk on the box. Reframe the just-added rootvg_mirror finding, and where
  # redundancy is genuinely absent/degraded raise severity to high (this is the
  # VIOS-weighted 'vios_rootvg_mirror' signal, folded into the shared rootvg_mirror check).
  if [ "$IS_VIOS" -eq 1 ] && [ "${F_ID[$((NFIND-1))]}" = "rootvg_mirror" ]; then
    F_MEAN[$((NFIND-1))]="${F_MEAN[$((NFIND-1))]} On a VIOS this is the most critical disk on the box — its loss takes down I/O for every client LPAR that depends on this VIOS."
    case "${F_ST[$((NFIND-1))]}" in
      (WARN|FAIL) F_SEV[$((NFIND-1))]=high;;
    esac
  fi

  # rootvg_quorum — quorum on a mirrored rootvg (reported only when mirrored)
  if [ "$NPV" -ge 2 ] && [ "$MIRR" = "full" ]; then
    RVGO=$(aix lsvg_rootvg lsvg rootvg)
    QUOR=$(printf '%s\n' "$RVGO" | awk '{for(i=1;i<=NF;i++)if($i=="QUORUM:"){print $(i+1); exit}}')
    if [ "$QUOR" = "2" ]; then
      add resilience rootvg_quorum "rootvg quorum" WARN low "QUORUM enabled on a $NPV-disk mirror" \
          "Quorum on a 2-disk mirror can keep the survivor from varying on at boot — most shops disable it (chvg -Qn rootvg) deliberately." \
          "if intentional, leave it; otherwise disable quorum (chvg -Qn rootvg) so a single surviving disk still varies on and boots."
    else
      add resilience rootvg_quorum "rootvg quorum" PASS low "QUORUM disabled on a $NPV-disk mirror" \
          "Quorum is disabled on the rootvg mirror — a single surviving disk can still vary on and boot." "n/a"
    fi
  fi

  # bootlist — only meaningful when mirrored
  if [ "$NPV" -ge 2 ] && [ "$MIRR" = "full" ]; then
    BL=$(aix bootlist bootlist -m normal -o); RC=$?
    if [ "$RC" -ne 0 ] || [ -z "$BL" ]; then
      nr_warn resilience bootlist "Boot device list" "the boot device list" "bootlist -m normal -o"
    else
      ND=$(printf '%s\n' "$BL" | awk '{c[$1]++} END{n=0; for (d in c) n++; print n}')
      if valid_json_number "$ND"; then FACT_RECOVERY_BOOTLIST="$ND"; fi
      if [ "$ND" -ge 2 ]; then
        add resilience bootlist "Boot device list" PASS low "$ND boot devices" \
            "The box can boot from either mirror copy." "n/a"
      else
        add resilience bootlist "Boot device list" WARN high "1 boot device (mirrored rootvg)" \
            "The mirror survives a disk loss — but the box cannot boot from the surviving copy." \
            "add the second disk: 'bootlist -m normal hdiskA hdiskB' (after bosboot -ad on it)."
      fi
    fi
  fi

  # Alternate rootvg recoverability: one measured assessment owns both the
  # graded finding and the cached facts rendered under facts.recovery.
  check_alt_disk_recoverability

  # savevg_evidence — local savevg proof for each online non-rootvg VG
  VGL=$(aix lsvg_o lsvg -o)
  for VG in $VGL; do
    [ "$VG" = "rootvg" ] && continue
    VGD=$(aix "find_vgdata_${VG}_31d" find "/tmp/vgdata/$VG" -name '*.data' -mtime -31 -print)
    if [ -n "$VGD" ]; then
      add resilience "savevg_$VG" "savevg evidence ($VG)" PASS low "recent .data under /tmp/vgdata/$VG" \
          "Local evidence of a recent savevg for $VG — its application data has a restore point." "n/a" "ffiec:II.C.21"
    else
      add resilience "savevg_$VG" "savevg evidence ($VG)" WARN med "no recent savevg data for $VG" \
          "No local savevg evidence for $VG — a rootvg backup alone does not recover application data; confirm where this VG's backup lives." \
          "run 'savevg -if /path/to/image $VG' or confirm an external backup tool covers it, then put it on a schedule." "ffiec:II.C.21"
    fi
  done

  # PowerHA — reported only when the cluster filesets are installed
  HAF=$(aix lslpp_ha lslpp -L cluster.es.server.rte); HAFRC=$?
  if [ "$HAFRC" -eq 0 ] && printf '%s\n' "$HAF" | grep -q 'cluster.es.server.rte'; then
    FACT_RECOVERY_POWERHA_APPLICABLE=1
    CL=$(aix lssrc_clstrmgr lssrc -ls clstrmgrES); CLRC=$?
    if [ "$CLRC" -ne 0 ] || [ -z "$CL" ]; then
      nr_warn resilience powerha "PowerHA cluster state" "the cluster manager state" "lssrc -ls clstrmgrES"
    else
      STATE=$(printf '%s\n' "$CL" | awk -F': *' '/Current state/{print $2; exit}')
      FACT_RECOVERY_POWERHA="$STATE"
      if [ "$STATE" = "ST_STABLE" ]; then
        add resilience powerha "PowerHA cluster state" PASS high "ST_STABLE" \
            "The cluster is stable and able to fail over." "n/a"
      else
        add resilience powerha "PowerHA cluster state" FAIL high "${STATE:-unknown}" \
            "The cluster you are counting on is not able to fail over right now." \
            "investigate with 'clmgr view report status' / clstat before anything else fails."
      fi
    fi
    # powerha_verify — cluster verification recency
    CV=$(aix find_clverify_90d find /var/hacmp/clverify -name 'clverify.log*' -mtime -90 -print)
    if [ -n "$CV" ]; then
      add resilience powerha_verify "PowerHA cluster verification" PASS low "clverify.log within 90 days" \
          "The cluster was verified recently — a good sign it can fail over cleanly." "n/a"
    else
      add resilience powerha_verify "PowerHA cluster verification" WARN med "no clverify.log in 90 days" \
          "A cluster that has not been verified in 90+ days may not fail over cleanly." \
          "run 'clmgr verify cluster' and review /var/hacmp/clverify/clverify.log."
    fi
  else
    case "$HAFRC" in 126|127) FACT_RECOVERY_POWERHA_APPLICABLE="";; *) FACT_RECOVERY_POWERHA_APPLICABLE=0;; esac
  fi

  # ==================== LEVEL 2/3 RESILIENCE DEPTH (grouped findings) ===================
  # Each check states its veteran signal in the comment. Level-3 findings default to WARN/
  # informational unless genuinely broken; an undersized dump on a box that matters = WARN
  # high. See docs/DEPTH-STANDARD.md.

  # The dump estimate + primary device drive both dump_sizing and dump_copy_dir; read once.
  SD=$(aix sysdumpdev_l sysdumpdev -l)
  PRIM=$(printf '%s\n' "$SD" | awk '$1=="primary"{print $2; exit}')
  DUMPLV=$(printf '%s\n' "$PRIM" | sed 's|^/dev/||')
  # sysdumpdev -e -> "Estimated dump size in bytes: N"; take the trailing integer.
  DEST=$(aix sysdumpdev_e sysdumpdev -e | awk '{for(i=NF;i>=1;i--) if($i ~ /^[0-9]+$/){print $i; exit}}')
  : ${DEST:=0}
  ESTMB=$(( DEST / 1048576 ))
  ESTGB=$(( (DEST + 536870912) / 1073741824 ))   # rounded GB, for plain-English text

  # dump_sizing (LEVEL 3) — is the primary dump DEVICE big enough for THIS box's memory?
  # Veteran signal: an undersized dump device is a silent landmine — everything looks fine
  # until the box panics, then the dump truncates at the end of the LV and the forensics you
  # needed to root-cause the crash are gone. Read-only: 'sysdumpdev -e' estimate vs the dump
  # LV size (lslv PPs x PP SIZE). Only meaningful when a real device is configured — a
  # sysdumpnull/absent primary is already flagged under Errors -> System dump device.
  if [ -n "$PRIM" ] && [ "$PRIM" != "/dev/sysdumpnull" ] && [ -n "$DUMPLV" ] && [ "$DEST" -gt 0 ]; then
    LSDLV=$(aix dump_lslv lslv "$DUMPLV")
    DPPS=$(printf '%s\n' "$LSDLV" | awk '{for(i=1;i<=NF;i++) if($i=="PPs:"){print $(i+1); exit}}')
    DPPMB=$(printf '%s\n' "$LSDLV" | awk '{for(i=1;i<=NF;i++) if($i=="SIZE:"){print $(i+1); exit}}')
    : ${DPPS:=0}; : ${DPPMB:=0}
    DEVMB=$(( DPPS * DPPMB ))
    if [ "$DEVMB" -gt 0 ]; then
      if [ "$DEVMB" -lt "$ESTMB" ]; then
        add resilience dump_sizing "Dump device sizing" WARN high "device ${DEVMB} MB < estimated dump ${ESTMB} MB" \
            "The primary dump device ($DUMPLV, ${DEVMB} MB) is smaller than the estimated dump for this LPAR's memory (${ESTMB} MB). If the box panics the dump truncates when the device fills, and the forensics you need to root-cause the crash are lost with it. This is the landmine you only find AFTER the crash." \
            "grow the dump LV to at least the current estimate ('sysdumpdev -e', then 'extendlv $DUMPLV <n>' or recreate larger); re-check with 'sysdumpdev -e' after any memory increase." "ffiec:II.C.21"
      elif [ $(( DEVMB * RES_DUMP_MARGIN_DEN )) -lt $(( ESTMB * RES_DUMP_MARGIN_NUM )) ]; then
        add resilience dump_sizing "Dump device sizing" WARN med "device ${DEVMB} MB vs estimate ${ESTMB} MB (under 1.25x headroom)" \
            "The dump device ($DUMPLV) covers the current estimate but with little headroom (${DEVMB} MB vs ${ESTMB} MB). The estimate rises as memory use grows, so a device this close can slip under the line after the next workload bump or memory add and start truncating dumps." \
            "add headroom now: grow the dump LV so it is comfortably above 'sysdumpdev -e' (target ~1.25x or more)." "ffiec:II.C.21"
      else
        add resilience dump_sizing "Dump device sizing" PASS low "device ${DEVMB} MB covers estimated dump ${ESTMB} MB" \
            "The primary dump device ($DUMPLV, ${DEVMB} MB) is comfortably larger than the estimated dump for this LPAR (${ESTMB} MB), so a panic can capture a complete image. Re-check 'sysdumpdev -e' after any memory increase — the estimate tracks RAM." "n/a"
      fi
    fi

    # dump_copy_dir — the copy directory must have room for a dump of the estimated size.
    # Veteran signal: a dump device big enough to CAPTURE the dump is only half the path —
    # on reboot AIX copies the image off the device into the copy directory before the device
    # is reused. If that filesystem cannot hold the dump, the forensics are lost the same way,
    # one step later. Copy dir + free space from 'sysdumpdev -l' and 'df -g' (no extra command).
    COPYDIR=$(printf '%s\n' "$SD" | awk '$1=="copy" && $2=="directory"{print $3; exit}')
    if [ -n "$COPYDIR" ]; then
      DFG=$(aix df_g df -g)
      # free MB of the filesystem holding COPYDIR = the longest mount point that prefixes it.
      CDFREE=$(printf '%s\n' "$DFG" | awk -v cd="$COPYDIR" '
        $4 ~ /%$/ && $NF ~ /^\// {
          mp=$NF; sep=mp
          if (mp != "/") sep=mp "/"
          if (cd==mp || index(cd, sep)==1) {
            t=mp; ln=gsub(/./,"",t)          # portable strlen via gsub count (no awk length call)
            if (ln >= bl) { bl=ln; free=$3 }
          }
        }
        END{ printf "%d", (free*1024)+0 }')
      : ${CDFREE:=0}
      if [ "$CDFREE" -gt 0 ] && [ "$CDFREE" -lt "$ESTMB" ]; then
        add resilience dump_copy_dir "Dump copy directory" WARN med "copy dir $COPYDIR has ${CDFREE} MB free, estimated dump ${ESTMB} MB" \
            "The dump device can capture the dump, but the copy directory ($COPYDIR, ${CDFREE} MB free) is too small to hold a dump of the estimated size (${ESTMB} MB). On reboot the copy off the device fails, so the image is lost before anyone can analyze it — the same forensic loss as an undersized device, one step later." \
            "free space in $COPYDIR or point the copy directory at a filesystem with room for the dump ('sysdumpdev -D <dir>'), sized to 'sysdumpdev -e'." "ffiec:II.C.21"
      elif [ "$CDFREE" -gt 0 ]; then
        add resilience dump_copy_dir "Dump copy directory" PASS low "copy dir $COPYDIR has ${CDFREE} MB free (>= estimate ${ESTMB} MB)" \
            "The copy directory ($COPYDIR) has room for a dump of the estimated size, so after a panic the image can be copied off the device and preserved for analysis." "n/a"
      fi
    fi
  fi

  # nim_client_state (LEVEL 2) — if /etc/niminfo exists this box is a NIM client; decode the
  # master. Veteran signal: on a NIM-managed box the mksysb/lpp_source resources usually live
  # on the NIM master, so a thin local-backup story is not the whole picture — the real restore
  # image is centralized there. AIXray cannot reach the master, but niminfo names it. Reuses the
  # ls /etc/niminfo probe that already feeds the mksysb note above.
  if [ "$NIMPROBERC" -eq 0 ]; then
    NIMI=$(aix cat_niminfo cat /etc/niminfo)
    NIMMASTER=$(printf '%s\n' "$NIMI" | awk -F= '/NIM_MASTER_HOSTNAME=/{gsub(/[" ]/,"",$2); print $2; exit}')
    NIMNAME=$(printf '%s\n' "$NIMI" | awk -F= '/NIM_NAME=/{gsub(/[" ]/,"",$2); print $2; exit}')
    NIMCONF=$(printf '%s\n' "$NIMI" | awk -F= '/NIM_CONFIGURATION=/{gsub(/[" ]/,"",$2); print $2; exit}')
    if [ -n "$NIMMASTER" ]; then
      add resilience nim_client_state "NIM client state" PASS low "NIM client${NIMNAME:+ '$NIMNAME'}${NIMCONF:+ ($NIMCONF)}, master $NIMMASTER" \
          "This box is a NIM client of master $NIMMASTER. On a NIM-managed LPAR the mksysb and lpp_source images normally live on that master, so its OS restore point and patch source are centralized there — confirm the master holds a CURRENT mksysb for this client, since a thin local backup story here is expected and not the whole picture." \
          "on the NIM master, verify a recent mksysb resource for this client ('lsnim -t mksysb', check its timestamp) and that the master itself is backed up." "ffiec:II.C.21"
    else
      add resilience nim_client_state "NIM client state" WARN low "/etc/niminfo present, master hostname not parsed" \
          "This box has /etc/niminfo, so it is a NIM client, but the NIM master hostname could not be read from it. NIM clients usually keep their mksysb/lpp_source on the master — you need to know which master." \
          "read /etc/niminfo (NIM_MASTER_HOSTNAME) and confirm the master holds a current mksysb for this client." "ffiec:II.C.21"
    fi
  elif [ "$NIMPROBERC" -ne 2 ]; then
    add resilience nim_client_state "NIM client state" WARN low \
        "not assessed — ls /etc/niminfo probe failed (rc=$NIMPROBERC)" \
        "AIXray could not determine whether this box is a NIM client because the /etc/niminfo probe did not execute successfully; absence cannot be inferred from probe rc=$NIMPROBERC." \
        "run 'ls /etc/niminfo' manually, then read NIM_MASTER_HOSTNAME from the file if it exists." "ffiec:II.C.21"
  fi

  # bosboot_currency (LEVEL 2) — after a kernel/TL update the boot image on hd5 must be rebuilt
  # (bosboot) or the box may boot the pre-update kernel or fail to boot. AIXray is READ-ONLY: it
  # cannot run or inspect bosboot, and the /dev/hd5 node timestamp reflects device access, not
  # the image build — so this compares the kernel fileset (bos.mp64) install date to the last
  # boot as a proxy and says so. Veteran signal: if the kernel fileset is NEWER than the last
  # boot, the running kernel is the pre-update one and a reboot is pending — confirm a bosboot
  # was run so the boot image carries the patched kernel before that reboot.
  KINST=$(aix lslpp_h_kernel lslpp -h bos.mp64 | awk '{for(i=1;i<=NF;i++) if($i ~ /^[0-1][0-9]\/[0-3][0-9]\/[0-9][0-9]$/){print $i; exit}}')
  WB=$(aix who_b who -b)
  BMON=$(printf '%s\n' "$WB" | awk '{for(i=1;i<=NF;i++) if($i=="boot"){print $(i+1); exit}}')
  BDAY=$(printf '%s\n' "$WB" | awk '{for(i=1;i<=NF;i++) if($i=="boot"){print $(i+2); exit}}')
  BMM=$(mon2num "${BMON:-}")
  if [ -n "$KINST" ] && [ -n "$BMM" ] && [ -n "$BDAY" ]; then
    KMM=$(printf '%s' "$KINST" | cut -d/ -f1)
    KDD=$(printf '%s' "$KINST" | cut -d/ -f2)
    KYY=$(printf '%s' "$KINST" | cut -d/ -f3)
    KJUL=$(d2j "20$KYY-$KMM-$KDD")
    BYEAR=${TODAY%%-*}
    BJUL=$(d2j "$BYEAR-$BMM-$BDAY")
    # who -b has no year; if the inferred date lands in the future it must be last year.
    [ "$BJUL" -gt $(( TODAY_J + 2 )) ] && BJUL=$(d2j "$(( BYEAR - 1 ))-$BMM-$BDAY")
    if [ "$KJUL" -gt "$BJUL" ]; then
      add resilience bosboot_currency "Boot image currency" WARN med "kernel bos.mp64 installed $KINST, after last boot $BMON $BDAY" \
          "The kernel fileset (bos.mp64) was installed AFTER the system last booted ($BMON $BDAY), so the box is still running the pre-update kernel and a reboot is pending. If a bosboot was not run as part of that update the boot image on hd5 is stale — the box could boot the old kernel or, worse, fail to boot the patched one. (AIXray is read-only and cannot inspect the boot image itself; this compares install date to last boot as a proxy — see below.)" \
          "confirm a bosboot was applied for the new kernel ('bosboot -av' if unsure — it rebuilds the hd5 boot image) and schedule the pending reboot; verify the boot device with 'bootlist -m normal -o'." "ffiec:II.C.21"
    else
      add resilience bosboot_currency "Boot image currency" PASS low "booted $BMON $BDAY, after kernel bos.mp64 install $KINST" \
          "The system last booted AFTER the running kernel (bos.mp64) was installed, so the running kernel matches what is on disk and no kernel-update reboot is outstanding. (AIXray is read-only: it cannot inspect the hd5 boot image directly, so this compares the kernel install date to the last boot as a proxy for boot-image currency.)" "n/a"
    fi
  fi
}

# ---- D. Performance & sizing (point-in-time snapshots) ---------------------------------
# ---- performance data / tunable references --------------------------------------------
# Sources: IBM AIX 7.3 Performance Tools/Commands references (vmo, ioo, lvmo, lparstat,
# svmon, vmstat, entstat) + live verification on an AIX 7.3 LPAR.
#   VMM cache defaults (vmo, AIX 6.1+): minperm%=3, maxperm%=90, maxclient%=90.
#   I/O pacing (sys0) AIX 7.x default: maxpout=8193, minpout=4096 (0 = disabled/unpaced).
#   vmstat -v "...blocked with no fsbuf/pbuf/psbuf" counters are CUMULATIVE since boot:
#   any non-zero value means that buffer pool was exhausted at least once under load.
#   Tunables to relieve them: numfsbufs & j2_dynamicBufferPreallocation (ioo, JFS2 fsbuf),
#   pv_pbuf_count (lvmo, LVM pbuf). Static non-zero after a busy period is usually benign;
#   still-climbing is the real problem.
PERF_MINPERM_DEF=3; PERF_MAXPERM_DEF=90; PERF_MAXCLIENT_DEF=90

# vmv <ere> — leading numeric value of the first vmstat -v line matching <ere> (0 if none).
function vmv { printf '%s\n' "$VMV" | awk -v re="$1" '$0 ~ re {print $1+0; exit}'; }
# vmvraw <ere> — uncoerced first token for evidence validation before vmv/ipart.
function vmvraw { printf '%s\n' "$VMV" | awk -v re="$1" '$0 ~ re {print $1; exit}'; }
# ipart <str> — integer part of a possibly-decimal value (portable; no ${v:0:n}).
function ipart { typeset v; v=${1%.*}; case "$v" in ''|*[!0-9-]*) v=0;; esac; echo "$v"; }
# lpif <label> — right-hand value of a "Label : value" line from lparstat -i.
function lpif { printf '%s\n' "$LPI" | awk -v k="$1" 'index($0,k)==1 && index($0,":")>0 {sub(/^[^:]*:[ \t]*/,""); sub(/[ \t]+$/,""); print; exit}'; }


function checks_performance {
  typeset TYPE MODE ENT OVP WEIGHT SMT IDLE PHYSC ENTC ENTI ENTCI IDLEI
  typeset SIZE INUSE FREE PIN VIRT AVAIL NUMPERM AVAILPCT SIZEI AVAILI PINI INUSEI NUMPI
  typeset LPS LPSRC SVMON SVMONRC COMPRAW NUMRAW COMPFACT NUMFACT VMVRC LPIRC
  typeset MINP MAXP MAXC NUMP MINRAW MAXRAW MAXCRAW NUMPRAW MINPI MAXPI MAXCI
  typeset FSB CFSB EPFSB FSTOT PBUF PSBUF BUFTOT
  typeset MAXPOUT MINPOUT MAXPI2
  typeset R PI PO US SY ID PC LCPU IDI RQ
  typeset IFL IF ESTAT AERR TOTERR SPEED MS DR NETSUM ADOWN NADAP
  typeset MAXU PSU TOPUSER TOPN RATIO

  # single reads, reused across checks below
  VMV=$(aix vmstat_v vmstat -v); VMVRC=$?
  LPI=$(aix lparstat_i lparstat -i); LPIRC=$?
  if [ "$LPIRC" -eq 0 ] && [ -n "$LPI" ]; then FACT_CPU_LPI_READ=1; fi
  SYS0=$(aix lsattr_sys0 lsattr -El sys0)

  # entitlement — shared-vs-dedicated efficiency, not just "CPU busy".
  # Veteran signal: shared consuming <25% of a >=1-core entitlement = paying for idle
  # cores; pinned near 100% entc with no idle = throttled/under-entitled; dedicated idle = fine.
  TYPE=$(lpif "Type"); MODE=$(lpif "Mode"); ENT=$(lpif "Entitled Capacity")
  OVP=$(lpif "Online Virtual CPUs"); WEIGHT=$(lpif "Variable Capacity Weight")
  LPS=$(aix lparstat_2_1 lparstat 2 1); LPSRC=$?
  set -- $(printf '%s\n' "$LPS" | awk '
    $1 ~ /^[0-9]+\.[0-9]+$/ && $4 ~ /^[0-9]+\.[0-9]+$/ &&
      $5 ~ /^[0-9]+\.[0-9]+$/ && $6 ~ /^[0-9]+\.[0-9]+$/ && NF>=6 {
        i=$4; p=$5; e=$6; found=1
      }
    END{if(found)print i+0, p+0, e+0}')
  IDLE=${1:-}; PHYSC=${2:-}; ENTC=${3:-}
  if [ "$LPSRC" -eq 0 ] && [ -n "$LPS" ]; then FACT_CPU_SAMPLE_READ=1; fi
  SMT=$(printf '%s\n' "$TYPE" | awk -F- '{print $NF}'); case "$SMT" in ''|*[!0-9]*) SMT="?";; esac
  if [ "$LPIRC" -eq 0 ]; then
    case "$TYPE" in *Shared*) FACT_CPU_MODE=shared;; *Dedicated*) FACT_CPU_MODE=dedicated;; esac
    case "$MODE" in Capped) FACT_CPU_CAPPED=true;; Uncapped) FACT_CPU_CAPPED=false;; esac
    if valid_json_number "$ENT"; then FACT_CPU_ENT="$ENT"; fi
    if valid_json_number "$OVP"; then FACT_CPU_OVP="$OVP"; fi
    if valid_json_number "$WEIGHT"; then FACT_CPU_WEIGHT="$WEIGHT"; fi
    if valid_json_number "$SMT"; then FACT_CPU_SMT="$SMT"; fi
  fi
  if [ "$LPSRC" -eq 0 ]; then
    if valid_json_number "$PHYSC"; then FACT_CPU_PHYSC="$PHYSC"; fi
    if valid_json_number "$ENTC"; then FACT_CPU_ENTC="$ENTC"; fi
    if valid_json_number "$IDLE"; then FACT_CPU_IDLE="$IDLE"; fi
  fi
  ENTI=$(ipart "$ENT"); ENTCI=$(ipart "$ENTC"); IDLEI=$(ipart "$IDLE")
  case "$TYPE" in
    *Dedicated*)
      add performance entitlement "LPAR CPU entitlement" PASS low \
          "dedicated, $OVP VP(s), SMT-$SMT, idle ${IDLE}% (snapshot)" \
          "This is a dedicated-processor LPAR — it owns its cores. Idle here is fine; there is no shared-pool entitlement to right-size." "n/a";;
    *Shared*)
      if [ "$ENTCI" -ge 90 ] && [ "$IDLEI" -lt 10 ]; then
        add performance entitlement "LPAR CPU entitlement" WARN med \
            "shared $MODE, ent $ENT, physc $PHYSC (${ENTC}% entc), idle ${IDLE}%" \
            "The LPAR is pinned near 100% of its entitled capacity with almost no idle — it is under-entitled and being throttled to its guarantee (uncapped can borrow only when the pool has spare cycles)." \
            "raise Entitled Capacity for this LPAR on the HMC (or add pool capacity); confirm the pressure is sustained, not a single busy sample." "" ;
      elif [ "$ENTI" -ge 1 ] && [ "$ENTCI" -lt 25 ]; then
        add performance entitlement "LPAR CPU entitlement" WARN low \
            "shared $MODE, ent $ENT, physc $PHYSC (${ENTC}% entc), weight ${WEIGHT:-n/a}" \
            "The LPAR is consuming under 25% of a whole-core-plus entitlement in this sample — likely over-provisioned, paying for guaranteed cores it is not using; uncapped means it can still burst above entitlement when needed." \
            "if sustained-low across a representative period, lower Entitled Capacity (keep it uncapped so it bursts) to free pool capacity; do not size off one idle sample." "" ;
      else
        add performance entitlement "LPAR CPU entitlement" PASS low \
            "shared $MODE, ent $ENT, physc $PHYSC (${ENTC}% entc), ${OVP:-?} VP SMT-$SMT, idle ${IDLE}%" \
            "Shared-pool CPU entitlement looks reasonable for this sample: consuming ${ENTC}% of the ${ENT}-core guarantee, uncapped so it can burst. A small entitlement plus uncapped is efficient design. Snapshot, not a trend." "n/a" ;
      fi;;
    *)
      add performance entitlement "LPAR CPU entitlement" WARN low "type ${TYPE:-unknown}" \
          "Could not classify the LPAR as shared or dedicated from lparstat -i." \
          "check 'lparstat -i' (Type/Mode/Entitled Capacity) manually.";;
  esac

  # memory_decomposition — decompose "used" into computational vs file vs pinned.
  # Veteran signal: high computational% + low numperm (file cache at its floor) = genuine
  # working memory that CANNOT be reclaimed; high inuse with high numperm = reclaimable cache
  # (scary-looking but fine). Replaces the naive virtual/real ratio.
  SVMON=$(aix svmon_g_mb svmon -G -O unit=MB); SVMONRC=$?
  if [ "$SVMONRC" -eq 0 ] && [ -n "$SVMON" ]; then FACT_MEM_PRIMARY_READ=1; fi
  set -- $(printf '%s\n' "$SVMON" | awk '$1=="memory"{print $2, $3, $4, $5, $6, $7; exit}')
  SIZE=${1:-}; INUSE=${2:-}; FREE=${3:-}; PIN=${4:-}; VIRT=${5:-}; AVAIL=${6:-}
  NUMPERM=$(vmv 'numperm percentage'); NUMPI=$(ipart "$NUMPERM")
  SIZEI=$(ipart "$SIZE"); AVAILI=$(ipart "$AVAIL"); PINI=$(ipart "$PIN"); INUSEI=$(ipart "$INUSE")
  if [ "$SVMONRC" -eq 0 ]; then
    if valid_plain_decimal "$SIZE" && valid_json_number "$SIZEI" && [ "$SIZEI" -gt 0 ]; then
      FACT_MEM_TOTAL="$SIZEI"
    fi
    if valid_plain_decimal "$INUSE" && [ "${INUSE#-}" = "$INUSE" ] &&
       valid_json_number "$INUSEI" && [ "$INUSEI" -ge 0 ]; then FACT_MEM_INUSE="$INUSEI"; fi
    if valid_plain_decimal "$AVAIL" && [ "${AVAIL#-}" = "$AVAIL" ] &&
       valid_json_number "$AVAILI" && [ "$AVAILI" -ge 0 ]; then FACT_MEM_AVAILABLE="$AVAILI"; fi
    if valid_plain_decimal "$PIN" && [ "${PIN#-}" = "$PIN" ] &&
       valid_json_number "$PINI" && [ "$PINI" -ge 0 ]; then FACT_MEM_PINNED="$PINI"; fi
  fi
  COMPRAW=$(printf '%s\n' "$VMV" | awk '$0 ~ /percentage of memory used for computational pages/ && $1 ~ /^-?[0-9]+([.][0-9]+)?$/ {print $1; exit}')
  NUMRAW=$(printf '%s\n' "$VMV" | awk '$0 ~ /numperm percentage/ && $1 ~ /^-?[0-9]+([.][0-9]+)?$/ {print $1; exit}')
  if [ "$VMVRC" -eq 0 ] &&
     valid_pct_decimal "$COMPRAW" "$STOR_FACT_MAX_USED_PCT"; then
    COMPFACT=$(ipart "$COMPRAW")
    if valid_json_number "$COMPFACT" && [ "$COMPFACT" -ge 0 ] &&
       [ "$COMPFACT" -le "$STOR_FACT_MAX_USED_PCT" ]; then FACT_MEM_COMP="$COMPFACT"; fi
  fi
  if [ "$VMVRC" -eq 0 ] &&
     valid_pct_decimal "$NUMRAW" "$STOR_FACT_MAX_USED_PCT"; then
    NUMFACT=$(ipart "$NUMRAW")
    if valid_json_number "$NUMFACT" && [ "$NUMFACT" -ge 0 ] &&
       [ "$NUMFACT" -le "$STOR_FACT_MAX_USED_PCT" ]; then FACT_MEM_NUMPERM="$NUMFACT"; fi
  fi
  if [ -z "$FACT_MEM_TOTAL" ] || [ -z "$FACT_MEM_INUSE" ] ||
     [ -z "$FACT_MEM_AVAILABLE" ] || [ -z "$FACT_MEM_PINNED" ] ||
     [ -z "$FACT_MEM_COMP" ] || [ -z "$FACT_MEM_NUMPERM" ]; then
    add performance memory_decomposition "Memory composition" WARN low "unreadable" \
        "Memory decomposition not assessed — unreadable svmon or vmstat token (a point-in-time snapshot)." "check 'svmon -G -O unit=MB' and 'vmstat -v' manually."
  else
    AVAILPCT=$(( AVAILI * 100 / SIZEI ))
    if [ "$FACT_MEM_COMP" -ge 90 ]; then
      add performance memory_decomposition "Memory composition" WARN med \
          "computational ${FACT_MEM_COMP}%, file/numperm ${FACT_MEM_NUMPERM}%, ${AVAILI}MB avail (${AVAILPCT}%), ${PINI}MB pinned of ${SIZEI}MB" \
          "Nearly all memory is computational (working) pages, not file cache (numperm ${FACT_MEM_NUMPERM}%) — this is genuine in-use memory the VMM cannot reclaim, so the tight look is real, not just cache. Only ${AVAILI}MB is available. Whether it is actually hurting depends on the paging-activity check; composition alone says there is little slack." \
          "if the working set grows, add RAM or trim the top consumers ('svmon -P -O unit=MB | head'); reclaimable file cache is already at its floor, so there is nothing to give back." ""
    elif [ "$FACT_MEM_NUMPERM" -ge 40 ]; then
      add performance memory_decomposition "Memory composition" PASS low \
          "inuse ${INUSEI}MB but file/numperm ${FACT_MEM_NUMPERM}% (reclaimable), computational ${FACT_MEM_COMP}%, ${AVAILI}MB avail" \
          "Memory looks heavily used but a large share is reclaimable file cache (numperm ${FACT_MEM_NUMPERM}%) — this is the classic scary-looking-but-fine case; computational demand is only ${FACT_MEM_COMP}%." "n/a"
    else
      add performance memory_decomposition "Memory composition" PASS low \
          "computational ${FACT_MEM_COMP}%, file/numperm ${FACT_MEM_NUMPERM}%, ${AVAILI}MB avail (${AVAILPCT}%)" \
          "Memory has headroom: ${FACT_MEM_COMP}% computational, ${AVAILI}MB available; no composition red flags in this snapshot." "n/a"
    fi
  fi

  # vmm_tuning — the minperm/maxperm/maxclient/numperm triad.
  # Veteran signal: maxperm very low starves file cache (disk re-reads); numperm pinned at
  # maxperm evicts computational pages; off-default values should be intentional.
  MINRAW=$(vmvraw 'minperm percentage'); MAXRAW=$(vmvraw 'maxperm percentage')
  MAXCRAW=$(vmvraw 'maxclient percentage'); NUMPRAW=$(vmvraw 'numperm percentage')
  if [ "$VMVRC" -ne 0 ] ||
     ! valid_pct_decimal "$MINRAW" "$STOR_FACT_MAX_USED_PCT" ||
     ! valid_pct_decimal "$MAXRAW" "$STOR_FACT_MAX_USED_PCT" ||
     ! valid_pct_decimal "$MAXCRAW" "$STOR_FACT_MAX_USED_PCT" ||
     ! valid_pct_decimal "$NUMPRAW" "$STOR_FACT_MAX_USED_PCT"; then
    add performance vmm_tuning "VMM cache tuning" WARN low "unreadable" \
        "VMM cache tuning not assessed — vmstat -v returned a failed capture or an unreadable/implausible minperm, maxperm, maxclient, or numperm percentage." \
        "check 'vmstat -v' and 'vmo -a' manually before relying on the cache-tuning result."
  else
    # Preserve the existing normalized prose after the raw tokens pass the
    # percentage evidence gate; vmv's numeric rendering drops cosmetic .0.
    MINP=$(vmv 'minperm percentage'); MAXP=$(vmv 'maxperm percentage')
    MAXC=$(vmv 'maxclient percentage'); NUMP=$(vmv 'numperm percentage')
    MINPI=$(ipart "$MINP"); MAXPI=$(ipart "$MAXP"); MAXCI=$(ipart "$MAXC"); NUMPI=$(ipart "$NUMP")
    if [ "${MAXPI:-0}" -le 0 ]; then
      add performance vmm_tuning "VMM cache tuning" WARN low "unreadable" \
          "VMM cache tuning not assessed — maxperm from vmstat -v is not a usable positive ceiling." \
          "check 'vmstat -v' and 'vmo -a' manually before relying on the cache-tuning result."
    elif [ "$MAXPI" -lt 20 ]; then
      add performance vmm_tuning "VMM cache tuning" WARN low \
          "minperm ${MINP}% / maxperm ${MAXP}% / maxclient ${MAXC}% / numperm ${NUMP}%" \
          "maxperm ${MAXP}% is unusually low (AIX default 90%) — it caps the file cache small, forcing repeated disk re-reads of data that would otherwise stay cached." \
          "unless this was a deliberate DB/raw-I/O choice, restore defaults: 'vmo -p -o maxperm%=90 -o maxclient%=90'." ""
    elif [ "$NUMPI" -ge "$(( MAXPI - 2 ))" ] && [ "$MAXPI" -gt 50 ]; then
      add performance vmm_tuning "VMM cache tuning" WARN low \
          "numperm ${NUMP}% at maxperm ${MAXP}% ceiling / minperm ${MINP}%" \
          "The file cache (numperm ${NUMP}%) is sitting at the maxperm ceiling — file pages may be evicting computational pages under memory pressure." \
          "confirm lru_file_repage=0 and strict_maxclient=1 ('vmo -a'); if computational pressure is real, lower maxclient%/maxperm% so file cache yields first." ""
    elif [ "$MINPI" -ne "$PERF_MINPERM_DEF" ] || [ "$MAXPI" -ne "$PERF_MAXPERM_DEF" ] || [ "$MAXCI" -ne "$PERF_MAXCLIENT_DEF" ]; then
      add performance vmm_tuning "VMM cache tuning" WARN low \
          "minperm ${MINP}% / maxperm ${MAXP}% / maxclient ${MAXC}% (defaults ${PERF_MINPERM_DEF}/${PERF_MAXPERM_DEF}/${PERF_MAXCLIENT_DEF})" \
          "VMM cache thresholds differ from AIX defaults — fine if a DBA/vendor set them deliberately, worth confirming otherwise." \
          "verify the values were set intentionally ('vmo -a'); restore with 'vmo -p -o minperm%=3 -o maxperm%=90 -o maxclient%=90' if not." ""
    else
      add performance vmm_tuning "VMM cache tuning" PASS low \
          "minperm ${MINP}% / maxperm ${MAXP}% / maxclient ${MAXC}% (AIX defaults); numperm ${NUMP}%" \
          "VMM cache tuning is at AIX defaults and the file cache is not pinned at its ceiling." "n/a"
    fi
  fi

  # fsbuf_blocking (LEVEL 3) — JFS2 filesystem-buffer starvation from vmstat -v.
  # Veteran signal: non-zero "...I/Os blocked with no fsbuf" = the fsbuf pool ran dry under
  # I/O load, adding latency a CPU/mem dashboard never shows; still-climbing => tune numfsbufs.
  FSB=$(vmv '[0-9] filesystem I/Os blocked with no fsbuf$')
  CFSB=$(vmv 'client filesystem I/Os blocked with no fsbuf$')
  EPFSB=$(vmv 'external pager filesystem I/Os blocked with no fsbuf$')
  FSTOT=$(( FSB + CFSB + EPFSB ))
  if [ "$FSTOT" -gt 0 ]; then
    add performance fsbuf_blocking "JFS2 filesystem-buffer blocking" WARN med \
        "blocked since boot: jfs2 fsbuf $FSB, external-pager $EPFSB, client $CFSB" \
        "Filesystem I/O has been blocked waiting for JFS2 filesystem buffers (fsbuf) $FSTOT time(s) since boot — the buffer pool ran dry under I/O load and requests had to wait, adding latency that CPU/memory graphs never reveal. The count is cumulative since boot." \
        "re-read 'vmstat -v' after a busy period: if the number is still climbing, raise JFS2 buffers with 'ioo -p -o j2_dynamicBufferPreallocation=<n>' (default 16, in 16KB units) and/or 'ioo -p -o numfsbufs=<n>'; a static non-zero count from a past burst is usually benign." ""
  else
    add performance fsbuf_blocking "JFS2 filesystem-buffer blocking" PASS low \
        "0 filesystem I/Os blocked with no fsbuf" \
        "No JFS2 filesystem-buffer (fsbuf) starvation since boot — the buffer pool has kept up with I/O demand." "n/a"
  fi

  # pbuf_psbuf_blocking (LEVEL 3) — LVM pbuf / paging psbuf starvation from vmstat -v.
  # Veteran signal: non-zero pbuf = LVM ran out of physical-buffer headers (disk I/O delayed);
  # non-zero psbuf = the pager itself was starved (worse — stalls under paging).
  PBUF=$(vmv 'pending disk I/Os blocked with no pbuf$')
  PSBUF=$(vmv 'paging space I/Os blocked with no psbuf$')
  BUFTOT=$(( PBUF + PSBUF ))
  if [ "$PSBUF" -gt 0 ]; then
    add performance pbuf_psbuf_blocking "LVM/paging buffer blocking" WARN med \
        "pbuf $PBUF, psbuf $PSBUF (blocked since boot)" \
        "Paging-space I/O has been blocked with no psbuf $PSBUF time(s) since boot — the pager ran out of buffers while paging, which stalls processes system-wide. That it happened at all means the box was under real memory pressure. (LVM pbuf blocks: $PBUF.)" \
        "relieve the memory pressure driving paging (see the memory and paging-activity checks); psbuf blocking is a symptom of paging, not a value you tune away." ""
  elif [ "$PBUF" -gt 0 ]; then
    add performance pbuf_psbuf_blocking "LVM/paging buffer blocking" WARN med \
        "pbuf $PBUF, psbuf 0 (blocked since boot)" \
        "LVM disk I/O has been blocked with no pbuf $PBUF time(s) since boot — the per-volume-group LVM physical-buffer pool was exhausted under load, delaying disk I/O. Cumulative since boot." \
        "check the current count with 'lvmo -v <vg> -a'; if still climbing, raise it per VG with 'lvmo -v <vg> -o pv_pbuf_count=<n>'. A static non-zero count from a past burst is usually benign." ""
  else
    add performance pbuf_psbuf_blocking "LVM/paging buffer blocking" PASS low \
        "0 pbuf and 0 psbuf blocks" \
        "No LVM pbuf or paging psbuf starvation since boot — buffer pools have kept up with disk and paging I/O." "n/a"
  fi

  # io_pacing — sys0 maxpout/minpout high/low water marks.
  # Veteran signal: 0/0 = unpaced, a single large sequential writer can fill the queue and
  # starve interactive I/O; set (e.g. 8193/4096) caps any one file's pending writes.
  MAXPOUT=$(printf '%s\n' "$SYS0" | awk '$1=="maxpout"{print $2; exit}')
  MINPOUT=$(printf '%s\n' "$SYS0" | awk '$1=="minpout"{print $2; exit}')
  MAXPI2=$(ipart "$MAXPOUT")
  if [ -z "$MAXPOUT" ]; then
    add performance io_pacing "I/O pacing (maxpout/minpout)" WARN low "unreadable" \
        "Could not read maxpout/minpout from lsattr -El sys0." "check 'lsattr -El sys0 -a maxpout -a minpout' manually."
  elif [ "$MAXPI2" -eq 0 ]; then
    add performance io_pacing "I/O pacing (maxpout/minpout)" WARN med \
        "maxpout=$MAXPOUT, minpout=$MINPOUT (unpaced)" \
        "I/O pacing is disabled (maxpout=0) — a single process doing a large sequential write can fill the disk write queue and starve interactive processes' I/O, so the box feels frozen under a backup or big copy." \
        "enable pacing: 'chdev -l sys0 -a maxpout=8193 -a minpout=4096' (the AIX 7.x default; takes effect immediately)." ""
  else
    add performance io_pacing "I/O pacing (maxpout/minpout)" PASS low \
        "maxpout=$MAXPOUT, minpout=$MINPOUT (paced)" \
        "System-wide I/O pacing is configured, so a runaway writer cannot monopolize a disk and starve interactive I/O." "n/a"
  fi

  # cpu_snapshot — idle + physc + run queue vs logical CPUs (one vmstat sample).
  # Veteran signal: idle high with low run queue = headroom; run queue > 2x logical CPUs =
  # threads waiting on CPU even if %busy looks OK. Point-in-time, not a trend.
  set -- $(printf '%s\n' "$(aix vmstat_1_2 vmstat 1 2)" | \
           awk '$1 ~ /^[0-9]+$/ && NF>=18 {r=$1; pi=$6; po=$7; id=$16; pc=$18} END{print r+0, pi+0, po+0, id+0, pc}')
  R=${1:-0}; PI=${2:-0}; PO=${3:-0}; ID=${4:-0}; PC=${5:-}
  LCPU=$(printf '%s\n' "$(aix lparstat_2_1 lparstat 2 1)" | \
         awk '{for(i=1;i<=NF;i++)if(index($i,"lcpu=")==1)print substr($i,6)}' | awk 'NR==1{print}')
  case "$LCPU" in ''|*[!0-9]*) LCPU=$(printf '%s\n' "$PRTCONF" | awk -F': *' '/Number Of Processors/{print $2; exit}');; esac
  case "$LCPU" in ''|*[!0-9]*) LCPU=1;; esac
  IDI=$(ipart "$ID"); RQ=$(( 2 * LCPU ))
  if [ "$IDI" -lt 10 ]; then
    add performance cpu_snapshot "CPU headroom (snapshot)" WARN med \
        "idle ${ID}%, physc ${PC:-n/a}, run queue r=$R vs $LCPU logical CPUs" \
        "CPU is near saturation in this one sample — low idle with the run queue backing up. This is a point-in-time snapshot, not a trend." \
        "confirm with 'nmon'/'topas' over time; if sustained, chase the top consumers or review CPU sizing/entitlement." ""
  elif [ "$R" -gt "$RQ" ]; then
    add performance cpu_snapshot "CPU headroom (snapshot)" WARN low \
        "run queue r=$R vs $LCPU logical CPUs, idle ${ID}%" \
        "The run queue is more than twice the logical-CPU count while idle is ${ID}% — threads are waiting to dispatch even though average CPU looks OK. Point-in-time snapshot." \
        "confirm with 'vmstat 2'/'nmon' over time; if sustained, look at SMT settings, thread affinity, or CPU sizing." ""
  else
    add performance cpu_snapshot "CPU headroom (snapshot)" PASS low \
        "idle ${ID}%, physc ${PC:-n/a}, run queue r=$R vs $LCPU logical CPUs" \
        "CPU has headroom in this sample: idle ${ID}% with a short run queue for $LCPU logical CPUs (point-in-time snapshot, not a trend)." "n/a"
  fi

  # paging_activity — vmstat pi/po: actual page-in/out RATE, distinct from paging-space %used.
  # Veteran signal: sustained pi/po > 0 = real memory pressure paging to disk NOW; the
  # storage paging-space check is capacity, this is activity. Zero here = not paging.
  if [ "$(( PI + PO ))" -gt 0 ]; then
    add performance paging_activity "Paging activity (snapshot)" WARN med \
        "page-ins ${PI}/s, page-outs ${PO}/s" \
        "The system is actively paging to disk in this sample (pi/po > 0) — real memory pressure is forcing pages out to and in from paging space, which adds disk latency to memory access. This is paging ACTIVITY, distinct from the paging-space %-used capacity check." \
        "confirm it is sustained ('vmstat 2' for a minute); if so, reduce the memory load or add RAM — a busy paging path slows everything." ""
  else
    add performance paging_activity "Paging activity (snapshot)" PASS low \
        "pi=0, po=0 in this sample" \
        "No active paging in this sample — memory demand is being met from RAM (this is the activity read; paging-space capacity is checked separately under storage)." "n/a"
  fi

  # net_adapter_health — per-interface entstat: link state + cumulative error/buffer counters.
  # Veteran signal: any Transmit/Receive/CRC error or "No Resource Errors" (adapter buffers
  # exhausted) is worth a look; counters are cumulative since boot, so climbing matters, not
  # the absolute. Down/non-operational link is the loud one.
  IFL=$(aix ifconfig_l ifconfig -l)
  TOTERR=0; NETSUM=""; ADOWN=""; NADAP=0
  for IF in $IFL; do
    case "$IF" in en[0-9]*) : ;; *) continue;; esac
    ESTAT=$(aix "entstat_$IF" entstat -d "$IF")
    [ -z "$ESTAT" ] && continue
    NADAP=$(( NADAP + 1 ))
    AERR=$(printf '%s\n' "$ESTAT" | awk '
      /Transmit Errors:/     {for(i=1;i<=NF;i++)if($i=="Errors:"&&$(i-1)=="Transmit")e+=$(i+1)}
      /Receive Errors:/      {for(i=1;i<=NF;i++)if($i=="Errors:"&&$(i-1)=="Receive")e+=$(i+1)}
      /CRC Errors:/          {for(i=1;i<=NF;i++)if($i=="Errors:"&&$(i-1)=="CRC")e+=$(i+1)}
      /No Resource Errors:/  {for(i=1;i<=NF;i++)if($i=="Errors:"&&$(i-1)=="Resource")e+=$(i+1)}
      END{print e+0}')
    MS=$(printf '%s\n' "$ESTAT" | awk -F: '/Media Speed/ && $0 !~ /Selected/ {sub(/^[ \t]+/,"",$2); sub(/[ \t]+$/,"",$2); print $2; exit}')
    DR=$(printf '%s\n' "$ESTAT" | awk -F: '/Adapter Data Rate/{gsub(/[ \t]/,"",$2); print $2; exit}')
    SPEED=${MS:-}; [ -z "$SPEED" ] && [ -n "$DR" ] && SPEED="${DR}Mb(virt)"; [ -z "$SPEED" ] && SPEED="?"
    if printf '%s\n' "$ESTAT" | grep -Eiq 'Link Status.*Down|LAN state.*(DOWN|RESET|CLOSED)'; then
      ADOWN="$ADOWN $IF"
    fi
    TOTERR=$(( TOTERR + AERR ))
    NETSUM="${NETSUM}${NETSUM:+; }$IF ${SPEED} ${AERR}err"
  done
  if [ "$NADAP" -eq 0 ]; then
    add performance net_adapter_health "Adapter health" WARN low "no ethernet interfaces read" \
        "Could not read adapter statistics (ifconfig -l / entstat)." "check 'ifconfig -l' and 'entstat -d <if>' manually."
  elif [ -n "$ADOWN" ]; then
    add performance net_adapter_health "Adapter health" WARN high "down/non-operational:${ADOWN}; $NETSUM" \
        "One or more ethernet interfaces are down or not operational — traffic on them is failing or has failed over. On a virtual adapter this can mean the SEA or VIOS path is down." \
        "check the link and the VIOS/SEA path ('entstat -d <if>', physical-adapter/SEA state on the VIOS); fix cabling/trunk/VLAN as needed." ""
  elif [ "$TOTERR" -gt 0 ]; then
    add performance net_adapter_health "Adapter health" WARN med "errors (since boot): $NETSUM" \
        "Ethernet adapters report transmit/receive/CRC or 'No Resource' (buffer-exhaustion) errors. These counters are cumulative since boot, so they may be old — what matters is whether they are still climbing." \
        "re-read 'entstat -d <if>' after some traffic: if errors climb, chase cabling/SEA/VLAN/switch-port for CRC/transmit-receive, or raise adapter receive buffers for 'No Resource' errors; static counts from an old event are usually benign." ""
  else
    add performance net_adapter_health "Adapter health" PASS low "$NETSUM" \
        "All ethernet interfaces are up with zero transmit/receive/CRC/buffer errors (counters cumulative since boot)." "n/a"
  fi

  # proc_limits — busiest user's process count vs maxuproc (per-user fork ceiling).
  # Veteran signal: approaching maxuproc = imminent 'fork: resource temporarily unavailable';
  # a runaway or under-set limit shows here before it takes the app down.
  MAXU=$(printf '%s\n' "$SYS0" | awk '$1=="maxuproc"{print $2; exit}')
  PSU=$(aix ps_user ps -eo user)
  set -- $(printf '%s\n' "$PSU" | awk 'NR>1{c[$1]++} END{m=0;u="";for(k in c)if(c[k]>m){m=c[k];u=k} print u, m+0}')
  TOPUSER=${1:-}; TOPN=${2:-0}
  case "$MAXU" in ''|*[!0-9]*)
      add performance proc_limits "Process limits (maxuproc)" WARN low "maxuproc unreadable" \
          "Could not read maxuproc from lsattr -El sys0." "check 'lsattr -El sys0 -a maxuproc' manually.";;
    *)
      RATIO=$(( TOPN * 100 / MAXU ))
      if [ "$RATIO" -ge 80 ]; then
        add performance proc_limits "Process limits (maxuproc)" WARN med \
            "user '$TOPUSER' $TOPN procs vs maxuproc $MAXU (${RATIO}%)" \
            "The busiest user is within ${RATIO}% of maxuproc, the per-user process ceiling — near the limit new forks fail with 'resource temporarily unavailable' and the app or shell simply stops spawning work." \
            "raise it if the load is legitimate: 'chdev -l sys0 -a maxuproc=<n>' (effective immediately, no reboot); if it is a runaway, find the process leak first." ""
      else
        add performance proc_limits "Process limits (maxuproc)" PASS low \
            "busiest user '$TOPUSER' $TOPN procs vs maxuproc $MAXU (${RATIO}%)" \
            "Per-user process headroom is fine — the busiest user is well under the maxuproc fork ceiling." "n/a"
      fi;;
  esac
}

# ---- G. Security & hardening -----------------------------------------------------------
function checks_security {
  typeset SSHT RC CIPH WEAK PRL LSU MA MI LR HS DEV UID0 XTRA N INE SVCS RH RHRC RHPRESENT RHCOMP RHBAD RHCOUNT RHUNIQ WW WWN SNMP AUD TE HERALD HV
  typeset LSUA NEVERLIST NNEVER NEVER5 LOCKED SUID SUID3 NSL NL
  typeset PRIV PRLI PSUG PADM BAD LSP STALE NNEV NST NEVL STL NPRIV
  typeset SUDOPKG SUDORC SUDOPKGOK SUDOLS SUDOLSRC SUDOFILES SUDOFILESRC SUDOFILECOUNT SUR SURRC SUDOPARSE SUDOPARSERC SUDOWHY NOPW ALLALL RBAC ASSIGNED IPSEC FILTON EXT NEXT PORTS PSHOW

  # sshd effective config drives two checks (root-gated on AIX)
  SSHT=$(aix sshd_T sshd -T); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security ssh_ciphers "SSH ciphers" "the sshd effective config" "sshd -T | grep ciphers" "stig:V-215402 cis-l1"
    nr_warn security ssh_rootlogin "SSH root login" "the sshd effective config" "sshd -T | grep permitrootlogin" "stig:V-215287 cis-l1 ffiec:II.C.7"
  else
    CIPH=$(printf '%s\n' "$SSHT" | awk '$1=="ciphers"{print $2; exit}')
    WEAK=$(printf '%s' "$CIPH" | awk -F, '{for(i=1;i<=NF;i++)if($i ~ /cbc|arcfour|3des|blowfish/)printf "%s%s",(n++?", ":""),$i}')
    if [ -n "$WEAK" ]; then
      add security ssh_ciphers "SSH ciphers" FAIL high "weak: $WEAK" \
          "sshd offers broken or deprecated ciphers — traffic that looks encrypted can be downgraded and read." \
          "remove cbc/arcfour/3des/blowfish from the Ciphers line in sshd_config and restart sshd." "stig:V-215402 cis-l1"
    else
      add security ssh_ciphers "SSH ciphers" PASS high "${CIPH:-strong set}" \
          "sshd offers only strong ciphers." "n/a" "stig:V-215402 cis-l1"
    fi
    PRL=$(printf '%s\n' "$SSHT" | awk '$1=="permitrootlogin"{print $2; exit}')
    case "$PRL" in
      yes) add security ssh_rootlogin "SSH root login" FAIL high "permitrootlogin yes" \
             "Direct SSH root login is open — a single brute-forceable credential with no accountability." \
             "set 'PermitRootLogin no' (or prohibit-password) in sshd_config and restart sshd." "stig:V-215287 cis-l1 ffiec:II.C.7";;
      no|prohibit-password|without-password) add security ssh_rootlogin "SSH root login" PASS med "permitrootlogin $PRL" \
             "Direct SSH root login is disabled — admins log in as themselves and escalate." "n/a" "stig:V-215287 cis-l1 ffiec:II.C.7";;
      *) add security ssh_rootlogin "SSH root login" WARN med "permitrootlogin ${PRL:-unknown}" \
             "Could not confirm the SSH root-login policy from sshd -T." \
             "verify 'PermitRootLogin' in sshd_config is no or prohibit-password." "stig:V-215287 cis-l1 ffiec:II.C.7";;
    esac
  fi

  # pw_policy — default password rules (root-gated)
  LSU=$(aix lssec_user_default lssec -f /etc/security/user -s default -a maxage -a minlen -a loginretries -a histsize); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security pw_policy "Default password policy" "the default password rules" "lssec -f /etc/security/user -s default" "cis-l1 ffiec:II.C.15"
  else
    MA=$(printf '%s\n' "$LSU" | awk '{for(i=1;i<=NF;i++)if(index($i,"maxage=")==1)print substr($i,8)}')
    MI=$(printf '%s\n' "$LSU" | awk '{for(i=1;i<=NF;i++)if(index($i,"minlen=")==1)print substr($i,8)}')
    LR=$(printf '%s\n' "$LSU" | awk '{for(i=1;i<=NF;i++)if(index($i,"loginretries=")==1)print substr($i,14)}')
    HS=$(printf '%s\n' "$LSU" | awk '{for(i=1;i<=NF;i++)if(index($i,"histsize=")==1)print substr($i,10)}')
    DEV=""
    case "$MA" in ''|*[!0-9]*) ;; *) { [ "$MA" -eq 0 ] || [ "$MA" -gt 13 ]; } && DEV="$DEV maxage=$MA";; esac
    case "$MI" in ''|*[!0-9]*) ;; *) [ "$MI" -lt 8 ] && DEV="$DEV minlen=$MI";; esac
    case "$LR" in ''|*[!0-9]*) ;; *) [ "$LR" -eq 0 ] && DEV="$DEV loginretries=$LR";; esac
    case "$HS" in ''|*[!0-9]*) ;; *) [ "$HS" -eq 0 ] && DEV="$DEV histsize=$HS";; esac
    if [ -n "$DEV" ]; then
      add security pw_policy "Default password policy" WARN high "weak:$DEV" \
          "The default password rules are weaker than any standard requires — every new account inherits them." \
          "tighten the /etc/security/user default stanza (maxage 1-13wk, minlen>=8, loginretries>0, histsize>0)." "cis-l1 ffiec:II.C.15"
    else
      add security pw_policy "Default password policy" PASS med "maxage=$MA minlen=$MI loginretries=$LR histsize=$HS" \
          "The default password rules meet a baseline." "n/a" "cis-l1 ffiec:II.C.15"
    fi
  fi


  # pw_hashing — the usw password-hash algorithm. An unset pwd_algorithm
  # falls back to legacy DES crypt, which considers only the first 8 password
  # characters. This check is diagnostic only: chsec appears in fix prose but
  # is never invoked.
  typeset PWH_RAW PWH_RC PWH_PARSED PWH_STATE PWH_VALUE
  if [ "${MYUID:-0}" != "0" ]; then
    PWH_RAW=""
    PWH_RC=126
  else
    PWH_RAW=$(aix pwd_algorithm lssec -f /etc/security/login.cfg -s usw -a pwd_algorithm); PWH_RC=$?
  fi
  if [ "$PWH_RC" -ne 0 ]; then
    nr_warn security pw_hashing "Password hashing algorithm" \
        "the password hashing policy" \
        "lssec -f /etc/security/login.cfg -s usw -a pwd_algorithm" \
        "cis-l1" NOT_ASSESSED high
  else
    PWH_PARSED=$(printf '%s\n' "$PWH_RAW" | awk '
      NF {
        rows++
        if ($1 != "usw") bad=1
        for (i=2; i<=NF; i++) {
          if (index($i,"pwd_algorithm=")==1) {
            attrs++
            value=substr($i,length("pwd_algorithm=")+1)
          } else {
            bad=1
          }
        }
      }
      END {
        if (rows==0) print "unset"
        else if (bad || rows!=1 || attrs>1) print "bad"
        else if (attrs==0 || value=="") print "unset"
        else if (value ~ /^[A-Za-z0-9_.-]+$/) print "value " value
        else print "bad"
      }')
    PWH_STATE=${PWH_PARSED%% *}
    case "$PWH_PARSED" in
      value\ *) PWH_VALUE=${PWH_PARSED#value } ;;
      *) PWH_VALUE="" ;;
    esac

    case "$PWH_STATE" in
      bad)
        add security pw_hashing "Password hashing algorithm" NOT_ASSESSED high \
            "not assessed — lssec pwd_algorithm output was unparseable" \
            "The password hashing policy could not be parsed, so AIXray cannot claim that password hashes use an approved algorithm." \
            "run 'lssec -f /etc/security/login.cfg -s usw -a pwd_algorithm' manually, then rerun AIXray." "cis-l1"
        ;;
      unset)
        add security pw_hashing "Password hashing algorithm" FAIL high \
            "(unset — defaults to legacy crypt)" \
            "An unset pwd_algorithm defaults to legacy DES crypt, which truncates passwords to 8 characters; characters after the eighth do not strengthen the stored hash." \
            "set pwd_algorithm to ssha256 at minimum (for example, 'chsec -f /etc/security/login.cfg -s usw -a pwd_algorithm=ssha256'); AIXray only recommends this command and never executes it." "cis-l1"
        ;;
      value)
        case "$PWH_VALUE" in
          ssha256|ssha512|bcrypt)
            add security pw_hashing "Password hashing algorithm" PASS high \
                "$PWH_VALUE" \
                "The configured password hashing algorithm avoids the legacy DES crypt default and its 8-character password limit." \
                "n/a" "cis-l1"
            ;;
          crypt)
            add security pw_hashing "Password hashing algorithm" FAIL high \
                "$PWH_VALUE" \
                "pwd_algorithm=crypt selects legacy DES crypt, which truncates passwords to 8 characters; characters after the eighth do not strengthen the stored hash." \
                "set pwd_algorithm to ssha256 at minimum (for example, 'chsec -f /etc/security/login.cfg -s usw -a pwd_algorithm=ssha256'); AIXray only recommends this command and never executes it." "cis-l1"
            ;;
          *)
            add security pw_hashing "Password hashing algorithm" FAIL high \
                "$PWH_VALUE" \
                "The configured password hashing algorithm is not one of the accepted choices (ssha256, ssha512, or bcrypt); ssha256 is the minimum recommendation." \
                "set pwd_algorithm to ssha256 at minimum (for example, 'chsec -f /etc/security/login.cfg -s usw -a pwd_algorithm=ssha256'); AIXray only recommends this command and never executes it." "cis-l1"
            ;;
        esac
        ;;
    esac
  fi

  # uid0_accounts
  UID0=$(aix passwd_uid0 awk -F: '$3==0 {print $1}' /etc/passwd)
  XTRA=$(printf '%s\n' "$UID0" | awk 'NF && $1!="root"{printf "%s%s",(n++?", ":""),$1}')
  if [ -n "$XTRA" ]; then
    add security uid0_accounts "UID 0 accounts" FAIL high "extra: $XTRA" \
        "More than one account has UID 0 — each one is effectively root, multiplying the attack surface." \
        "give each admin a unique non-zero UID and use su/sudo; remove or re-UID the extra accounts." "cis-l1 ffiec:II.C.7"
  else
    add security uid0_accounts "UID 0 accounts" PASS med "root only" \
        "root is the only UID 0 account." "n/a" "cis-l1 ffiec:II.C.7"
  fi

  # failed_logins (root-gated). The log is created on the FIRST failed login —
  # on a clean install it does not exist, and that absence is itself the answer.
  if [ "${MYUID:-0}" != "0" ]; then
    nr_warn security failed_logins "Failed login attempts" "the failed-login log" "who /etc/security/failedlogin"
  elif ! aix ls_failedlogin ls /etc/security/failedlogin >/dev/null; then
    add security failed_logins "Failed login attempts" PASS low "no log — 0 recorded" \
        "/etc/security/failedlogin does not exist, which means no failed login has ever been recorded here." "n/a"
  else
    N=$(aix failedlogin count_nonempty_lines who /etc/security/failedlogin); RC=$?
    if [ "$RC" -ne 0 ]; then
      add security failed_logins "Failed login attempts" NOT_ASSESSED med \
          "not assessed — failed-login count capture failed (rc=$RC)" \
          "The failed-login log exists, but its streamed count did not complete successfully; zero cannot be inferred from failed evidence." \
          "run 'who /etc/security/failedlogin | wc -l' manually, check that the log is readable, and rerun AIXray."
    else
      case "$N" in
        ''|0*|*[!0-9]*)
          add security failed_logins "Failed login attempts" NOT_ASSESSED med \
              "not assessed — failed-login count capture was empty or invalid" \
              "The failed-login log exists, but its streamed count was not a valid positive integer; zero cannot be inferred from empty or invalid evidence." \
              "run 'who /etc/security/failedlogin | wc -l' manually, check that the log is readable, and rerun AIXray."
          ;;
        *)
          # /etc/security/failedlogin is never auto-trimmed, so a large lifetime total is
          # near-universal and says little on its own — only a very high count is worth a WARN.
          if [ "$N" -gt 500 ]; then
            add security failed_logins "Failed login attempts" WARN med "$N recorded (lifetime total)" \
                "A high lifetime total of failed logins — someone has been knocking, whether a misconfigured app or a brute-force attempt. This log is never auto-trimmed, so review recency, not just the count." \
                "review recency ('who /etc/security/failedlogin | tail') and rotate the log; lock or investigate the source accounts/hosts."
          else
            add security failed_logins "Failed login attempts" PASS low "$N recorded" \
                "Failed-login volume is low." "n/a"
          fi
          ;;
      esac
    fi
  fi

  # inetd_cleartext
  INE=$(aix inetd_conf grep -E '^(telnet|ftp|shell|login|exec|rsh|rlogin)' /etc/inetd.conf) # network-lint: allow -- reads the LOCAL /etc/inetd.conf capture text (via the aix wrapper), never a network call
  SVCS=$(printf '%s\n' "$INE" | awk 'NF{printf "%s%s",(n++?", ":""),$1}')
  if [ -n "$SVCS" ]; then
    add security inetd_cleartext "Cleartext inetd services" FAIL high "enabled: $SVCS" \
        "Cleartext remote-access services are enabled — credentials cross the wire readable." \
        "disable telnet/ftp/rsh/rlogin in /etc/inetd.conf and 'refresh -s inetd'; use ssh/sftp." "stig:V-215258 stig:V-215259 cis-l1" # network-lint: allow -- remediation-advice prose, not a network call
  else
    add security inetd_cleartext "Cleartext inetd services" PASS med "none enabled" \
        "No cleartext remote-access services are enabled in inetd." "n/a" "stig:V-215258 stig:V-215259 cis-l1"
  fi

  # rhosts
  # The probe always emits a completion marker after checking both paths. That
  # makes a clean result positive evidence instead of inferring absence from an
  # empty/nonzero compound ls. Legacy real captures with one exact present path
  # and rc 1/2 remain strong adverse evidence for the #76 partial-presence case.
  RH=$(aix ls_rhosts sh -c '
    for path in /.rhosts /etc/hosts.equiv; do
      if [ -f "$path" ] || [ -L "$path" ]; then
        printf "%s\n" "$path"
      fi
    done
    printf "%s\n" __AIXRAY_RHOSTS_PROBE_COMPLETE__
  '); RHRC=$?
  RHPRESENT=$(printf '%s\n' "$RH" | awk '$0=="/.rhosts" || $0=="/etc/hosts.equiv" {printf "%s%s",(n++?", ":""),$0}')
  RHCOMP=$(printf '%s\n' "$RH" | awk '$0=="__AIXRAY_RHOSTS_PROBE_COMPLETE__"{n++} END{print n+0}')
  RHBAD=$(printf '%s\n' "$RH" | awk 'NF && $0!="/.rhosts" && $0!="/etc/hosts.equiv" && $0!="__AIXRAY_RHOSTS_PROBE_COMPLETE__"{n++} END{print n+0}')
  RHCOUNT=$(printf '%s\n' "$RH" | awk '$0=="/.rhosts" || $0=="/etc/hosts.equiv"{n++} END{print n+0}')
  RHUNIQ=$(printf '%s\n' "$RH" | awk '$0=="/.rhosts" || $0=="/etc/hosts.equiv"{seen[$0]=1} END{for(k in seen)n++; print n+0}')
  if [ -n "$RHPRESENT" ] && [ "$RHBAD" -eq 0 ] && [ "$RHCOMP" -eq 0 ] &&
     [ "$RHCOUNT" -eq "$RHUNIQ" ] &&
     { [ "$RHRC" -eq 0 ] || [ "$RHRC" -eq 1 ] || [ "$RHRC" -eq 2 ]; }; then
    add security rhosts "Trust files (.rhosts)" FAIL high "present: $RHPRESENT" \
        "Host-trust files allow passwordless login from named hosts — a classic lateral-movement path." \
        "remove /.rhosts and /etc/hosts.equiv; rely on key-based ssh instead." "stig:V-215432" # network-lint: allow -- remediation-advice prose, not a network call
  elif [ "$RHRC" -ne 0 ]; then
    add security rhosts "Trust files (.rhosts)" NOT_ASSESSED high "not assessed — rhosts probe failed (rc=$RHRC)" \
        "The trust-file probe did not complete, so absence of .rhosts/hosts.equiv cannot be asserted." \
        "check /.rhosts and /etc/hosts.equiv manually, then rerun AIXray." "stig:V-215432"
  elif [ -z "$RH" ]; then
    add security rhosts "Trust files (.rhosts)" NOT_ASSESSED high "not assessed — rhosts probe empty (rc=0)" \
        "The trust-file probe returned no evidence, so absence of .rhosts/hosts.equiv cannot be asserted." \
        "check /.rhosts and /etc/hosts.equiv manually, then rerun AIXray." "stig:V-215432"
  elif [ "$RHCOMP" -ne 1 ] || [ "$RHBAD" -ne 0 ] || [ "$RHCOUNT" -ne "$RHUNIQ" ]; then
    add security rhosts "Trust files (.rhosts)" NOT_ASSESSED high "not assessed — rhosts probe unparseable (rc=0)" \
        "The trust-file probe output was incomplete, contradictory, duplicated, or did not match its completion protocol." \
        "check /.rhosts and /etc/hosts.equiv manually, then rerun AIXray." "stig:V-215432"
  elif [ -n "$RHPRESENT" ]; then
    add security rhosts "Trust files (.rhosts)" FAIL high "present: $RHPRESENT" \
        "Host-trust files allow passwordless login from named hosts — a classic lateral-movement path." \
        "remove /.rhosts and /etc/hosts.equiv; rely on key-based ssh instead." "stig:V-215432" # network-lint: allow -- remediation-advice prose, not a network call
  else
    add security rhosts "Trust files (.rhosts)" PASS low "none present" \
        "No .rhosts or hosts.equiv trust files present." "n/a" "stig:V-215432"
  fi

  # world_writable (scope bounded to /etc and /usr/local/bin on purpose)
  WW=$(aix find_ww find /etc /usr/local/bin -xdev -type f -perm -002)
  if [ -n "$WW" ]; then
    WWN=$(printf '%s\n' "$WW" | awk 'NR<=3{printf "%s%s",(NR>1?", ":""),$0} END{if(NR>3)printf " +%d more",NR-3}')
    add security world_writable "World-writable files" WARN high "$WWN" \
        "World-writable files in /etc and /usr/local/bin (scope bounded to those on purpose) let any user alter system content." \
        "remove world write with 'chmod o-w <file>'; find the process that created them." "cis-l1"
  else
    add security world_writable "World-writable files" PASS low "none in /etc, /usr/local/bin" \
        "No world-writable files in the scanned directories (scope bounded to /etc and /usr/local/bin)." "n/a" "cis-l1"
  fi

  # snmp_community — grep rc>=2 means the config was UNREADABLE (permissions),
  # which must never masquerade as a clean PASS on an unprivileged run.
  SNMP=$(aix snmp_conf grep -E '^community[ 	]+(public|private)' /etc/snmpd.conf /etc/snmpdv3.conf); RC=$?
  if [ -n "$SNMP" ]; then
    add security snmp_community "SNMP community strings" FAIL med "default community in use" \
        "SNMP uses a default community string (public/private) — anyone on the network can read, or write, system data." \
        "replace public/private with a strong community in /etc/snmpd.conf and refresh snmpd." "stig:V-215231 cis-l1"
  elif [ "$RC" -ge 2 ] && [ "${MYUID:-0}" != "0" ]; then
    nr_warn security snmp_community "SNMP community strings" "the SNMP configuration" "grep community /etc/snmpd.conf" "stig:V-215231 cis-l1"
  elif [ "$RC" -ge 2 ]; then
    add security snmp_community "SNMP community strings" PASS low "no snmpd configuration" \
        "No SNMP daemon configuration present on this box." "n/a" "stig:V-215231 cis-l1"
  else
    add security snmp_community "SNMP community strings" PASS low "no default community" \
        "No default public/private SNMP community strings configured." "n/a" "stig:V-215231 cis-l1"
  fi

  # audit_active (root-gated)
  AUD=$(aix audit_query audit query); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security audit_active "Audit subsystem" "the audit state" "audit query" "cis-l1 ffiec:II.C.22"
  elif printf '%s\n' "$AUD" | grep -qi 'auditing on'; then
    add security audit_active "Audit subsystem" PASS med "auditing on" \
        "The audit subsystem is running — you can answer 'who did what'." "n/a" "cis-l1 ffiec:II.C.22"
  else
    add security audit_active "Audit subsystem" WARN high "auditing off" \
        "No audit trail — you cannot answer 'who did what' after an incident." \
        "configure and start audit ('audit start'; set it to start at boot)." "cis-l1 ffiec:II.C.22"
  fi

  # trusted_exec (root-gated; skip on older AIX without TE — but rc 127 proves
  # absence only as root: trustchk is mode 500, invisible to non-root PATH search)
  TE=$(aix trustchk_p trustchk -p TE); RC=$?
  if [ "$RC" -eq 127 ] && [ "${MYUID:-0}" = "0" ]; then
    :  # Trusted Execution not present on this AIX — nothing to report
  elif [ "$RC" -ne 0 ]; then
    nr_warn security trusted_exec "Trusted Execution" "the Trusted Execution policy" "trustchk -p TE"
  elif printf '%s\n' "$TE" | grep -q 'TE=ON'; then
    add security trusted_exec "Trusted Execution" PASS low "TE=ON" \
        "Trusted Execution is enabled — the kernel checks binary integrity at load." "n/a"
  else
    add security trusted_exec "Trusted Execution" WARN low "TE=OFF" \
        "Trusted Execution is off (informational) — no runtime binary-integrity enforcement." \
        "consider enabling TE ('trustchk -p TE=ON') if your change control supports it."
  fi

  # login_banner (root-gated)
  HERALD=$(aix login_herald lssec -f /etc/security/login.cfg -s default -a herald); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security login_banner "Login banner" "the login herald" "lssec -f /etc/security/login.cfg -s default -a herald"
  else
    HV=$(printf '%s\n' "$HERALD" | sed -n 's/.*herald=//p')
    case "$HV" in
      ''|'""') add security login_banner "Login banner" WARN low "no herald set" \
                 "No legal login banner is set — auditors ask for one and it deters casual access." \
                 "set a herald in the /etc/security/login.cfg default stanza (chsec -a herald=...)." "stig:V-215200";;
      *) add security login_banner "Login banner" PASS low "herald set" \
                 "A login banner is configured." "n/a" "stig:V-215200";;
    esac
  fi

  # account_hygiene — non-system accounts whose password never expires (root-gated)
  LSUA=$(aix lsuser_all lsuser -a account_locked maxage ALL); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security account_hygiene "Account password aging" "the per-user password aging" "lsuser -a account_locked maxage ALL" "cis-l1 ffiec:II.C.7"
  else
    NEVERLIST=$(printf '%s\n' "$LSUA" | awk '
      BEGIN{split("root daemon bin sys adm uucp guest nobody lpd lp invscout snapp ipsec nuucp pconsole sshd esaadmin",s," "); for(i in s)sysu[s[i]]=1}
      {u=$1; ma="x"; for(i=2;i<=NF;i++)if(index($i,"maxage=")==1)ma=substr($i,8)
       if(u!="" && !(u in sysu) && ma=="0") print u}')
    NNEVER=$(printf '%s\n' "$NEVERLIST" | awk 'NF{n++} END{print n+0}')
    NEVER5=$(printf '%s\n' "$NEVERLIST" | awk 'NF{if(n<5){printf "%s%s",(n?", ":""),$0; n++}} END{if(NR>5)printf " +%d more",NR-5}')
    LOCKED=$(printf '%s\n' "$LSUA" | awk '{for(i=1;i<=NF;i++)if($i=="account_locked=true")n++} END{print n+0}')
    if [ "${NNEVER:-0}" -gt 0 ]; then
      add security account_hygiene "Account password aging" WARN med "$NNEVER never-expire: $NEVER5 ($LOCKED locked)" \
          "Non-system accounts have maxage=0 — passwords that never expire outlive the people who set them." \
          "set aging on these accounts (chuser maxage=13 <user>), or lock/remove ones no longer in use." "cis-l1 ffiec:II.C.7"
    else
      add security account_hygiene "Account password aging" PASS low "no non-system account with maxage=0 ($LOCKED locked)" \
          "Every non-system account has password aging set." "n/a" "cis-l1 ffiec:II.C.7"
    fi
  fi

  # suid_unexpected — setuid/setgid files outside the system paths
  SUID=$(aix find_suid find /home /tmp /var/tmp /usr/local -xdev -type f \( -perm -4000 -o -perm -2000 \))
  if [ -n "$SUID" ]; then
    SUID3=$(printf '%s\n' "$SUID" | awk 'NF{if(n<3){printf "%s%s",(n?", ":""),$0; n++}} END{if(NR>3)printf " +%d more",NR-3}')
    add security suid_unexpected "Unexpected setuid/setgid files" WARN high "$SUID3" \
        "setuid outside system paths is either a mistake or a foothold for privilege escalation." \
        "review each file; strip the bit (chmod u-s / g-s) or remove it if it should not be there." "cis-l1"
  else
    add security suid_unexpected "Unexpected setuid/setgid files" PASS low "none in /home /tmp /var/tmp /usr/local" \
        "No setuid/setgid files outside the system paths." "n/a" "cis-l1"
  fi

  # listeners — count of listening sockets (attack surface)
  NSL=$(aix netstat_Aan netstat -Aan); RC=$?
  if [ "$RC" -ne 0 ] || [ -z "$NSL" ]; then
    add security listeners "Listening network sockets" WARN low "unreadable" \
        "Could not read the listening-socket list from netstat." "check 'netstat -Aan' manually."
  else
    NL=$(printf '%s\n' "$NSL" | awk '/LISTEN/{n++} END{print n+0}')
    add security listeners "Listening network sockets" PASS low "$NL listening socket(s)" \
        "Each listening socket is attack surface — review anything you do not recognize." "n/a"
  fi

  # ---- G depth: correlated privileged-access hardening (WP-K area 5) ----------------
  # Beyond the sshd-level and per-rule STIG checks: the OS account gates and delegation
  # posture a veteran hunts for — the correlated "root wide open" signals.

  # privileged_access — root's AIX account controls from /etc/security/user (root-gated).
  # Veteran signal: rlogin=true (root may log in directly over the network) + sugroups=ALL
  # (any user may attempt su to root) is the classic "root wide open" pair — distinct from
  # sshd PermitRootLogin, which only gates the ssh daemon. rlogin should be false; sugroups # network-lint: allow -- comment prose, not a network call
  # a named sysadmin group. Confirmed FAIL on lab-host-01 (rlogin=true, sugroups=ALL).
  PRIV=$(aix lssec_user_root lssec -f /etc/security/user -s root -a rlogin -a sugroups -a admin -a expires); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security privileged_access "root account controls" "root's account gates" "lssec -f /etc/security/user -s root" "cis-l1 ffiec:II.C.7"
  else
    PRLI=$(printf '%s\n' "$PRIV" | awk '{for(i=1;i<=NF;i++)if(index($i,"rlogin=")==1)print substr($i,8)}')
    PSUG=$(printf '%s\n' "$PRIV" | awk '{for(i=1;i<=NF;i++)if(index($i,"sugroups=")==1)print substr($i,10)}')
    BAD=""
    [ "$PRLI" = "true" ] && BAD="$BAD rlogin=true"
    [ "$PSUG" = "ALL" ] && BAD="$BAD sugroups=ALL"
    if [ "$PRLI" = "true" ] && [ "$PSUG" = "ALL" ]; then
      add security privileged_access "root account controls" FAIL high \
          "rlogin=true + sugroups=ALL (root wide open)" \
          "root can log in directly over the network (rlogin=true) AND any user may attempt su to root (sugroups=ALL) — the classic 'root wide open' pair. Either alone is a gap; together, root is one guessed password away from a network login with no accountability. This is the OS account gate in /etc/security/user, separate from sshd's PermitRootLogin." \
          "restrict both: 'chsec -f /etc/security/user -s root -a rlogin=false' (admins log in as themselves and su/sudo to root) and '-a sugroups=<sysadmin-group>' so only a named group may su to root." "cis-l1 ffiec:II.C.7"
    elif [ -n "$BAD" ]; then
      add security privileged_access "root account controls" WARN high \
          "weak:$BAD" \
          "A root account gate in /etc/security/user is left open: rlogin=true lets root log in directly over the network; sugroups=ALL lets any user attempt su to root. Tighten whichever is set — this is the OS gate, independent of sshd." \
          "set 'chsec -f /etc/security/user -s root -a rlogin=false' and/or '-a sugroups=<sysadmin-group>' as needed." "cis-l1 ffiec:II.C.7"
    else
      add security privileged_access "root account controls" PASS med \
          "rlogin=${PRLI:-unset}, sugroups=${PSUG:-unset}" \
          "root's OS account gates are restricted: direct network root login is off and su to root is limited (not sugroups=ALL)." "n/a" "cis-l1 ffiec:II.C.7"
    fi
  fi

  # stale_privileged_accounts (LEVEL 3) — privileged accounts nobody watches (root-gated).
  # Veteran signal: an admin account not logged into in 90+ days — worse, one that has
  # NEVER logged in and whose password never expires (maxage=0) — is the forgotten door a
  # breach persists through. Privileged = root (uid 0) plus any non-system account with
  # admin=true. Last-login age from time_last_login (unix epoch) vs the frozen "today".
  LSP=$(aix lsuser_priv lsuser -a admin maxage account_locked time_last_login ALL); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security stale_privileged_accounts "Stale privileged accounts" "per-user privilege and last-login data" "lsuser -a admin maxage account_locked time_last_login ALL" "cis-l1 ffiec:II.C.7"
  else
    STALE=$(printf '%s\n' "$LSP" | awk -v tj="$TODAY_J" -v ej=2440588 '
      BEGIN{split("daemon bin sys adm uucp guest nobody lpd lp invscout snapp ipsec nuucp pconsole sshd esaadmin slotd ragent smmsp",s," "); for(i in s)sysu[s[i]]=1}
      {u=$1; if(u=="")next
       adm="false"; ma="x"; lk="false"; tl=""
       for(i=2;i<=NF;i++){
         if(index($i,"admin=")==1)adm=substr($i,7)
         else if(index($i,"maxage=")==1)ma=substr($i,8)
         else if(index($i,"account_locked=")==1)lk=substr($i,16)
         else if(index($i,"time_last_login=")==1)tl=substr($i,17)
       }
       priv = (u=="root") || (!(u in sysu) && adm=="true")
       if(!priv || lk=="true") next
       npriv++
       if(tl=="" || tl+0==0){ if(ma=="0"){ never++; if(never<=5) nl=nl (nl?", ":"") u } next }
       age = tj - (ej + int(tl/86400)); if(age<0)age=0
       if(age>90){ stale++; npe=(ma=="0")?" maxage=0":""; if(stale<=5) sl=sl (sl?", ":"") u" ("age"d"npe")" }
      }
      END{printf "%d\t%d\t%s\t%s\t%d", never+0, stale+0, nl, sl, npriv+0}')
    NNEV=$(printf '%s' "$STALE" | awk -F'\t' '{print $1+0}')
    NST=$(printf '%s' "$STALE" | awk -F'\t' '{print $2+0}')
    NEVL=$(printf '%s' "$STALE" | awk -F'\t' '{print $3}')
    STL=$(printf '%s' "$STALE" | awk -F'\t' '{print $4}')
    NPRIV=$(printf '%s' "$STALE" | awk -F'\t' '{print $5+0}')
    if [ "$NST" -gt 0 ] || [ "$NNEV" -gt 0 ]; then
      add security stale_privileged_accounts "Stale privileged accounts" WARN med \
          "$([ "$NST" -gt 0 ] && echo "stale(>90d): $STL")$([ "$NST" -gt 0 ] && [ "$NNEV" -gt 0 ] && echo "; ")$([ "$NNEV" -gt 0 ] && echo "never-used non-expiring: $NEVL")" \
          "One or more privileged accounts (root or an admin account) have not been used in over 90 days, or have never logged in and never expire (maxage=0). A dormant account with standing privilege is a prime target — nobody would notice it being used, and a non-expiring password outlives the person who set it." \
          "confirm each is still needed; lock or remove the unused ones ('chuser account_locked=true <user>' or 'rmuser'), and set aging on any that stay ('chuser maxage=13 <user>')." "cis-l1 ffiec:II.C.7"
    else
      add security stale_privileged_accounts "Stale privileged accounts" PASS low \
          "$NPRIV privileged account(s), none stale" \
          "Every privileged account has been used within 90 days (or is locked); no dormant standing-privilege accounts with non-expiring passwords." "n/a" "cis-l1 ffiec:II.C.7"
    fi
  fi

  # sudo_rbac — is privilege delegation done safely? (root-gated reads)
  # Veteran signal: a NOPASSWD ALL sudoers grant is a root-equivalent backdoor — full
  # command set with no re-auth. On AIX with no sudo, delegation is native su/RBAC and
  # there is no sudoers backdoor to worry about (informational).
  SUDOWHY=""
  SUDOPKG=$(aix lslpp_sudo lslpp -L sudo); SUDORC=$?
  if [ "$SUDORC" -ne 0 ]; then
    SUDOWHY="not assessed — lslpp sudo capture failed (rc=$SUDORC)"
  elif [ -z "$SUDOPKG" ]; then
    SUDOWHY="not assessed — lslpp sudo capture empty (rc=0)"
  else
    SUDOPKGOK=$(printf '%s\n' "$SUDOPKG" | awk '
      NF && $0 ~ /^sudo:[^:]*:[^:]*:sudo:[^:]+:/ {found=1}
      NF >= 2 && ($1 == "sudo" || $1 ~ /^sudo[.][A-Za-z0-9_.-]+$/) {found=1}
      END {print found ? 1 : 0}')
    [ "$SUDOPKGOK" -eq 1 ] || SUDOWHY="not assessed — lslpp sudo capture unparseable (rc=0)"
  fi

  if [ -z "$SUDOWHY" ]; then
    SUDOLS=$(aix ls_sudoers sh -c '
      for path in /opt/freeware/etc/sudoers /etc/sudoers; do
        if [ -f "$path" ] || [ -L "$path" ]; then
          ls -ld "$path" || exit $?
        fi
      done
    '); SUDOLSRC=$?
    if [ "$SUDOLSRC" -ne 0 ]; then
      SUDOWHY="not assessed — sudoers file-list capture failed (rc=$SUDOLSRC)"
    elif [ -z "$SUDOLS" ]; then
      SUDOWHY="not assessed — sudoers file-list capture empty (rc=0)"
    else
      SUDOFILES=$(printf '%s\n' "$SUDOLS" | awk '
        NF {
          n++
          mode=$1; path=$NF
          if (substr(mode,1,1) == "l" && NF >= 11 && $(NF-1) == "->")
            path=$(NF-2)
          if (NF < 9 || mode !~ /^[-bcdlps][rwxStTs-][rwxStTs-][rwxStTs-][rwxStTs-][rwxStTs-][rwxStTs-][rwxStTs-][rwxStTs-][rwxStTs-][+.]?$/) bad=1
          else if (path == "/opt/freeware/etc/sudoers" || path == "/etc/sudoers") {
            if (!seen[path]++) print path
          } else bad=1
        }
        END {if (n == 0 || bad) exit 1}')
      SUDOFILESRC=$?
      SUDOFILECOUNT=$(printf '%s\n' "$SUDOFILES" | awk 'NF{n++} END{print n+0}')
      if [ "$SUDOFILESRC" -ne 0 ] || [ "$SUDOFILECOUNT" -eq 0 ]; then
        SUDOWHY="not assessed — sudoers file-list capture unparseable (rc=0)"
      fi
    fi
  fi

  if [ -z "$SUDOWHY" ]; then
    SUR=$(aix sudoers_active sh -c '
      set --
      for path in /opt/freeware/etc/sudoers /etc/sudoers; do
        if [ -f "$path" ] || [ -L "$path" ]; then
          set -- "$@" "$path"
        fi
      done
      [ "$#" -gt 0 ] || exit 1
      grep -h -Ev "^[ 	]*#|^[ 	]*$" "$@"
    '); SURRC=$?
    if [ "$SURRC" -ne 0 ]; then
      SUDOWHY="not assessed — sudoers rule capture failed (rc=$SURRC)"
    elif [ -z "$SUR" ]; then
      SUDOWHY="not assessed — sudoers rule capture empty (rc=0)"
    else
      SUDOPARSE=$(printf '%s\n' "$SUR" | awk '
        {
          line=$0
          sub(/^\/opt\/freeware\/etc\/sudoers:/,"",line)
          sub(/^\/etc\/sudoers:/,"",line)
          sub(/^[ \t]*/,"",line); sub(/[ \t]*$/,"",line)
          valid=0
          if (line ~ /^Defaults([^ \t]*)?[ \t]+[^ \t]/) valid=1
          else if (line ~ /^(Host_Alias|User_Alias|Runas_Alias|Cmnd_Alias)[ \t]+[^=]+=[ \t]*[^ \t]/) valid=1
          else if (line ~ /^@include(dir)?[ \t]+[^ \t]+/) valid=1
          else if (line ~ /^[^ \t]+[ \t]+[^ \t=]+([ \t]*,[ \t]*[^ \t=]+)*[ \t]*=[ \t]*[^ \t]/) valid=1
          if (!valid) {bad=1; next}
          seen++
          principal=line; sub(/[ \t].*$/,"",principal)
          if (line ~ /NOPASSWD/) nopw++
          if (principal != "root" && line ~ /ALL[ \t]*=[ \t]*\(ALL(:ALL)?\)[ \t]+ALL/) allall++
        }
        END {
          if (seen == 0 || bad) exit 1
          printf "%d\t%d", nopw+0, allall+0
        }')
      SUDOPARSERC=$?
      if [ "$SUDOPARSERC" -ne 0 ] || [ -z "$SUDOPARSE" ]; then
        SUDOWHY="not assessed — sudoers rule capture unparseable (rc=0)"
      else
        NOPW=$(printf '%s' "$SUDOPARSE" | awk -F'\t' '{print $1+0}')
        ALLALL=$(printf '%s' "$SUDOPARSE" | awk -F'\t' '{print $2+0}')
      fi
    fi
  fi

  if [ -n "$SUDOWHY" ]; then
    add security sudo_rbac "Privilege delegation (sudo/RBAC)" NOT_ASSESSED med "$SUDOWHY" \
        "Privilege delegation could not be assessed because the sudo package, sudoers file list, or active-rule capture failed, was empty, or was unparseable." \
        "verify sudo installation and inspect every active sudoers file with visudo before treating delegation as scoped." "cis-l1 ffiec:II.C.7"
  elif [ "${NOPW:-0}" -gt 0 ]; then
      add security sudo_rbac "Privilege delegation (sudo/RBAC)" FAIL high \
          "$NOPW NOPASSWD grant(s) in sudoers" \
          "sudoers contains $NOPW NOPASSWD grant(s) — a user (or a compromised process running as that user) can run privileged commands with no password re-auth. A NOPASSWD ALL rule is a root-equivalent backdoor that bypasses accountability." \
          "remove NOPASSWD from /etc/sudoers unless it is a tightly-scoped single command for an automation account; visudo the file and require a password for interactive escalation." "cis-l1 ffiec:II.C.7"
  elif [ "${ALLALL:-0}" -gt 0 ]; then
      add security sudo_rbac "Privilege delegation (sudo/RBAC)" WARN med \
          "$ALLALL unrestricted ALL=(ALL) ALL grant(s)" \
          "sudoers grants full 'ALL=(ALL) ALL' (any command as any user) to $ALLALL principal(s). A password is still required, but the grant is unrestricted — every holder is effectively root, with no command scoping." \
          "scope sudo grants to the specific commands each role needs (Cmnd_Alias) rather than blanket ALL; reserve full ALL for a small, named admin group." "cis-l1 ffiec:II.C.7"
  else
      add security sudo_rbac "Privilege delegation (sudo/RBAC)" PASS low \
          "sudo installed; no NOPASSWD or blanket ALL grants" \
          "sudo is installed and its grants require a password and are not blanket ALL=(ALL) ALL — delegation is scoped and accountable." "n/a" "cis-l1 ffiec:II.C.7"
  fi

  # network_exposure (LEVEL 3) — externally-reachable listeners vs host packet filtering.
  # Veteran signal: N listeners on non-loopback addresses AND no host firewall (AIX IP
  # Security filter inactive) = the box leans entirely on the network perimeter; one VLAN
  # change or misrouted subnet exposes every one. The listeners check just counts; this
  # correlates exposure against the control. Confirmed on lab-host-01: 9 external, filter inactive.
  IPSEC=$(aix lsdev_ipsec lsdev -l ipsec_v4)
  FILTON=0; printf '%s\n' "$IPSEC" | grep -q 'Available' && FILTON=1
  if [ -n "$NSL" ]; then
    EXT=$(printf '%s\n' "$NSL" | awk '
      /LISTEN/{a=$5
        if(a=="" || a ~ /^127\./ || a ~ /^::1\./) next
        p=a; sub(/.*\./,"",p)
        if(p!="" && !(p in seen)){seen[p]=1; ports=ports (ports?",":"") p}
        n++
      } END{printf "%d\t%s", n+0, ports}')
    NEXT=$(printf '%s' "$EXT" | awk -F'\t' '{print $1+0}')
    PORTS=$(printf '%s' "$EXT" | awk -F'\t' '{print $2}')
    PSHOW=$(printf '%s\n' "$PORTS" | awk -F, '{if(NF>8){s="";for(i=1;i<=8;i++)s=s (i>1?",":"") $i; print s" +"(NF-8)" more"} else print $0}')
    if [ "$NEXT" -eq 0 ]; then
      add security network_exposure "Network exposure vs filtering" PASS low \
          "no externally-reachable listeners" \
          "No listening socket is bound to a non-loopback address — nothing is reachable from the network, regardless of host filtering." "n/a"
    elif [ "$FILTON" -eq 1 ]; then
      add security network_exposure "Network exposure vs filtering" PASS med \
          "$NEXT external listener(s); host IP filtering active" \
          "There are $NEXT externally-reachable listeners, but AIX IP Security packet filtering is active — the host enforces its own access control, not just the upstream perimeter." "n/a"
    else
      add security network_exposure "Network exposure vs filtering" WARN med \
          "$NEXT external listener(s) on ports $PSHOW; host IP filtering INACTIVE" \
          "$NEXT services listen on non-loopback addresses (reachable from the network) and AIX host packet filtering (IP Security) is not active — the box relies entirely on the upstream network/firewall. One perimeter mistake, VLAN change, or misrouted subnet exposes every one of these ports directly." \
          "reduce the surface first (stop services you do not need — see the listeners and cleartext-inetd checks), then, if the box must self-defend, define rules with 'genfilt'/'mkfilt' and activate host filtering with 'mkfilt -v4 -u'." ""
    fi
  fi

  # stig_fileperms — data-driven STIG file permission/ownership rule engine (R_FILEPERM)
  eval_fileperms
  # stig_secattr — data-driven STIG account/attribute policy rule engine (R_SECATTR)
  eval_secattr
  # stig_nettune — data-driven STIG network-tunable rule engine (R_NETTUNE)
  eval_nettune
  # stig_svcoff — data-driven STIG disabled-service rule engine (R_SVCOFF)
  eval_svcoff
}

# eval_fileperms — evaluate every R_FILEPERM row against ONE evidence capture and emit
# one grouped finding plus the per-rule detail (F_RULES). A single wrapped command
# (aix stig_fileperm_ls ls -ldn <all paths>) preserves the per-path association: a
# missing path simply produces no line (NA), and ls's nonzero rc for missing paths is
# expected. Owner/group are compared by numeric id (ls -n); mode by mask, not equality.
function eval_fileperms {
  typeset PATHS LS RAW SUM DETAIL CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX

  PATHS=$(printf '%s\n' "$R_FILEPERM" | awk -F'|' 'NF>=5 && $1 !~ /^#/ && $2!="" && !seen[$2]++{printf "%s ", $2}')
  [ -z "$PATHS" ] && return 0
  # ls -ldn on every distinct rule path in one shot. rc is ignored: missing paths are
  # expected and simply yield no line (parsed as NA below).
  LS=$(aix stig_fileperm_ls ls -ldn $PATHS)

  # One awk pass: build path -> (mode,uid,gid) from the ls lines, then evaluate each rule.
  RAW=$({ printf '%s\n' "$R_FILEPERM"; echo "AIXRAY_LS"; printf '%s\n' "$LS"; } | awk '
    # rwx string (10 chars, incl. suid/sgid/sticky) -> mode as decimal-octal digits (e.g. 0644->644)
    function permoct(s,  o,g,ot,sp,c){
      sp=0;o=0;g=0;ot=0
      if(substr(s,2,1)=="r")o+=4; if(substr(s,3,1)=="w")o+=2
      c=substr(s,4,1); if(c=="x")o+=1; else if(c=="s"){o+=1;sp+=4} else if(c=="S")sp+=4
      if(substr(s,5,1)=="r")g+=4; if(substr(s,6,1)=="w")g+=2
      c=substr(s,7,1); if(c=="x")g+=1; else if(c=="s"){g+=1;sp+=2} else if(c=="S")sp+=2
      if(substr(s,8,1)=="r")ot+=4; if(substr(s,9,1)=="w")ot+=2
      c=substr(s,10,1); if(c=="x")ot+=1; else if(c=="t"){ot+=1;sp+=1} else if(c=="T")sp+=1
      return sp*1000 + o*100 + g*10 + ot
    }
    # is 3-bit octal digit a a subset of b (no bit set in a that is unset in b)
    function bitle(a,b){ return (int(a/4)%2<=int(b/4)%2) && (int(a/2)%2<=int(b/2)%2) && (a%2<=b%2) }
    # does file mode fm (decimal-octal) satisfy the maxmode ceiling mm (decimal-octal)?
    function modeok(fm,mm){
      return bitle(int(fm/1000)%10,int(mm/1000)%10) && bitle(int(fm/100)%10,int(mm/100)%10) \
          && bitle(int(fm/10)%10,int(mm/10)%10) && bitle(fm%10,mm%10)
    }
    function oct4(m){ return sprintf("%04d", m) }
    BEGIN{ phase=0; nr=0 }
    $0=="AIXRAY_LS"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="") next
      n=split($0,r,"|"); if(n<5) next
      nr++; R_id[nr]=r[1]; R_path[nr]=r[2]; R_own[nr]=r[3]; R_grp[nr]=r[4]; R_max[nr]=r[5]
      next
    }
    phase==1{
      if(NF<9) next
      p=$NF; seen[p]=1; M_mode[p]=permoct($1); M_uid[p]=$3+0; M_gid[p]=$4+0
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        p=R_path[i]
        if(!(p in seen)){ st="NA"; obs=p" absent"; nna++ }
        else{
          fm=M_mode[p]; ok=1
          if(R_max[i]!="" && !modeok(fm,R_max[i]+0)) ok=0
          if(R_own[i]!="" && M_uid[p]!=R_own[i]+0) ok=0
          if(R_grp[i]!="" && M_gid[p]!=R_grp[i]+0) ok=0
          obs=p" "oct4(fm)" u="M_uid[p]" g="M_gid[p]
          if(ok){ st="PASS"; npass++ } else { st="FAIL"; nfail++; nf++; fl[nf]=R_id[i]" "p" ("oct4(fm)")" }
        }
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  # controls = every rule id evaluated (stig: tag grammar), space-separated
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA not applicable; failing: $FLIST"
    MEAN="One or more files mandated by the DISA STIG for IBM AIX 7.x are more permissive, or wrong-owned, than the rule allows — each is a documented hardening gap an auditor will flag."
    FIX="chmod/chown the failing files to the required mode/owner per the rule list (chmod <maxmode> <path>; chown <owner>:<group> <path>); the compliance report lists every rule and its evidence."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA not applicable"
    MEAN="Every applicable STIG file-permission/ownership rule (DISA STIG for IBM AIX 7.x) passes on this box — the mandated files are no more permissive than required."
    FIX="n/a"
  fi
  add security stig_fileperms "STIG file permissions" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"
}

# eval_secattr — evaluate every R_SECATTR row and emit one grouped finding (stig_secattr)
# plus per-rule detail (F_RULES). Attributes are grouped by (file,stanza): ONE lssec call
# captures a whole stanza's attribute list (fewest commands, and lssec aborts the entire
# call if any one attribute is invalid for the stanza — so only real attributes are grouped).
# A stanza that cannot be read (non-root: rc!=0/empty) makes its rules NA; a missing/empty
# attribute value is NA. Numeric compare only; op le treats an observed 0 as a FAIL (0 =
# disabled/unlimited on AIX). If nothing was readable at all (NAPPLIC=0) the finding is a
# root-gated WARN rather than a hollow PASS.
function eval_secattr {
  typeset PAIRS CAP RAW DETAIL SUM CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX

  # distinct file|stanza pairs in first-seen (deterministic) order
  PAIRS=$(printf '%s\n' "$R_SECATTR" | awk -F'|' 'NF>=6 && $1 !~ /^#/ && $2!="" && !seen[$2 FS $3]++{print $2"|"$3}')
  [ -z "$PAIRS" ] && return 0

  # one lssec per stanza; parse "stanza attr=val attr=val" into "file|stanza|attr|value"
  # lines. An unreadable stanza (rc!=0 or empty) emits nothing -> its rules fall to NA.
  # KEEP the per-stanza attribute lists in tools/capture-fixtures.sh in sync with R_SECATTR.
  CAP=$(printf '%s\n' "$PAIRS" | while IFS='|' read SA_F SA_S; do
    [ -z "$SA_F" ] && continue
    SA_ATTRS=$(printf '%s\n' "$R_SECATTR" | awk -F'|' -v f="$SA_F" -v s="$SA_S" '$2==f && $3==s{printf " -a %s", $4}')
    SA_SLUG=$(printf '%s' "$SA_F" | sed 's|.*/||; s|\.cfg$||')_$SA_S
    SA_RAW=$(aix "stig_secattr_$SA_SLUG" lssec -f "$SA_F" -s "$SA_S" $SA_ATTRS)
    if [ $? -eq 0 ] && [ -n "$SA_RAW" ]; then
      printf '%s\n' "$SA_RAW" | awk -v f="$SA_F" -v s="$SA_S" \
        '{for(i=1;i<=NF;i++){e=index($i,"="); if(e>1) print f "|" s "|" substr($i,1,e-1) "|" substr($i,e+1)}}'
    fi
  done)

  # one awk pass: rules then captured values -> per-rule verdict + summary
  RAW=$({ printf '%s\n' "$R_SECATTR"; echo "AIXRAY_CAP"; printf '%s\n' "$CAP"; } | awk -F'|' '
    function isnum(x){ return (x ~ /^-?[0-9]+$/) }
    BEGIN{ phase=0; nr=0 }
    $0=="AIXRAY_CAP"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="" || NF<6) next
      nr++; R_id[nr]=$1; R_file[nr]=$2; R_st[nr]=$3; R_attr[nr]=$4; R_op[nr]=$5; R_val[nr]=$6
      next
    }
    phase==1{
      if(NF<4) next
      key=$1 SUBSEP $2 SUBSEP $3; M[key]=$4; P[key]=1
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        key=R_file[i] SUBSEP R_st[i] SUBSEP R_attr[i]
        if(!(key in P) || M[key]==""){ st="NA"; obs=R_attr[i]" unset"; nna++ }
        else if(!isnum(M[key])){ st="NA"; obs=R_attr[i]"="M[key]" non-numeric"; nna++ }
        else{
          v=M[key]+0; req=R_val[i]+0; op=R_op[i]; ok=0
          if(op=="ge") ok=(v>=req)
          else if(op=="le") ok=(v!=0 && v<=req)
          else if(op=="eq") ok=(v==req)
          obs=R_attr[i]"="M[key]" (need "op" "req")"
          if(ok){ st="PASS"; npass++ } else { st="FAIL"; nfail++; nf++; fl[nf]=R_id[i]" "R_attr[i]"="M[key]" (needs "op" "req")" }
        }
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NAPPLIC" -eq 0 ]; then
    ST=WARN; SEV=med
    OBS="n/a"
    MEAN="Could not read the /etc/security account-policy stanzas (needs root); no STIG account/attribute rule could be assessed on this run."
    FIX="re-run aixray as root to evaluate the account-policy controls; or inspect 'lssec -f /etc/security/user -s default' manually."
  elif [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a; failing: $FLIST"
    MEAN="One or more account/password-policy attributes in /etc/security are weaker than the DISA STIG for IBM AIX 7.x mandates — each is a documented hardening gap an auditor will flag, and it applies to every account inheriting the default stanza."
    FIX="tighten the failing attributes with chsec (chsec -f <file> -s default -a <attr>=<value>); the compliance report lists every rule, the required value, and the observed value."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a"
    MEAN="Every applicable STIG account/password-policy attribute meets the DISA STIG for IBM AIX 7.x required value."
    FIX="n/a"
  fi
  add security stig_secattr "STIG account policy" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"
}

# eval_nettune — evaluate every R_NETTUNE row and emit one grouped finding (stig_nettune)
# plus per-rule detail (F_RULES). One capture per distinct command: 'no -a' and/or 'nfso -a'
# (both are NON-root reads — listing a tunable never needs privilege, only setting one does,
# so there is no root gate here). Each captured "tunable = value" line becomes a
# command|tunable|value record; a tunable absent from the capture is NA. Numeric compare only;
# unlike R_SECATTR, op le does NOT special-case 0 — for a network tunable 0 is normally the
# SECURE value, so it is compared literally.
function eval_nettune {
  typeset CMDS CAP RAW DETAIL SUM CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX NT_CMD NT_RAW

  # distinct commands (no, nfso) in first-seen order
  CMDS=$(printf '%s\n' "$R_NETTUNE" | awk -F'|' 'NF>=5 && $1 !~ /^#/ && $2!="" && !seen[$2]++{print $2}')
  [ -z "$CMDS" ] && return 0

  # one 'no -a' / 'nfso -a' per command; parse "tunable = value" -> "command|tunable|value".
  # An unreadable command (rc!=0 or empty) emits nothing -> its rules fall to NA.
  CAP=$(printf '%s\n' "$CMDS" | while read NT_CMD; do
    [ -z "$NT_CMD" ] && continue
    NT_RAW=$(aix "stig_${NT_CMD}_a" "$NT_CMD" -a)
    if [ $? -eq 0 ] && [ -n "$NT_RAW" ]; then
      printf '%s\n' "$NT_RAW" | awk -v cmd="$NT_CMD" 'NF>=3 && $2=="="{print cmd "|" $1 "|" $3}'
    fi
  done)

  # one awk pass: rules then captured values -> per-rule verdict + summary
  RAW=$({ printf '%s\n' "$R_NETTUNE"; echo "AIXRAY_CAP"; printf '%s\n' "$CAP"; } | awk -F'|' '
    function isnum(x){ return (x ~ /^-?[0-9]+$/) }
    BEGIN{ phase=0; nr=0 }
    $0=="AIXRAY_CAP"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="" || NF<5) next
      nr++; R_id[nr]=$1; R_cmd[nr]=$2; R_tun[nr]=$3; R_op[nr]=$4; R_val[nr]=$5
      next
    }
    phase==1{
      if(NF<3) next
      key=$1 SUBSEP $2; M[key]=$3; P[key]=1
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        key=R_cmd[i] SUBSEP R_tun[i]
        if(!(key in P) || M[key]==""){ st="NA"; obs=R_tun[i]" absent"; nna++ }
        else if(!isnum(M[key])){ st="NA"; obs=R_tun[i]"="M[key]" non-numeric"; nna++ }
        else{
          v=M[key]+0; req=R_val[i]+0; op=R_op[i]; ok=0
          if(op=="ge") ok=(v>=req)
          else if(op=="le") ok=(v<=req)
          else if(op=="eq") ok=(v==req)
          obs=R_tun[i]"="M[key]" (need "op" "req")"
          if(ok){ st="PASS"; npass++ } else { st="FAIL"; nfail++; nf++; fl[nf]=R_id[i]" "R_tun[i]"="M[key]" (needs "op" "req")" }
        }
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NAPPLIC" -eq 0 ]; then
    ST=WARN; SEV=med
    OBS="n/a"
    MEAN="Could not read the network tunables (no -a / nfso -a); no STIG network-option rule could be assessed on this run."
    FIX="verify the 'no' subsystem is available and re-run; or inspect 'no -a' manually."
  elif [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a; failing: $FLIST"
    MEAN="One or more kernel network options are set to a value the DISA STIG for IBM AIX 7.x flags — e.g. IP forwarding on a non-router, or TCP half-open connection cleanup disabled. Each is a documented hardening gap an auditor will flag."
    FIX="set the failing tunables with 'no -p -o <tunable>=<value>' (nfso for NFS options) so the change persists across reboot; the compliance report lists every rule, the required value, and the observed value."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a"
    MEAN="Every applicable STIG network-option tunable (DISA STIG for IBM AIX 7.x) is at its required value."
    FIX="n/a"
  fi
  add security stig_nettune "STIG network tunables" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"
}

# eval_svcoff — evaluate every R_SVCOFF row and emit one grouped finding (stig_svcoff) plus
# per-rule detail (F_RULES). Two captures: the uncommented /etc/inetd.conf service lines
# (type inetd: the service token must NOT appear enabled) and 'lssrc -a' (type lssrc: the SRC
# subsystem must be inoperative, not active). Both are non-root reads. For a disable-service
# rule the STIG treats "service enabled/running" as the finding, so a token that is
# absent/commented (inetd) or a subsystem that is inoperative/undefined (lssrc) is compliant =
# PASS, not NA. Guard: if lssrc -a yields no subsystem rows at all, lssrc-type rules are NA
# (can't assess) rather than a hollow PASS. This is the broad per-V-ID STIG service list; it
# does NOT duplicate the inetd_cleartext check (which flags cleartext-LOGIN daemons enabled).
function eval_svcoff {
  typeset TYPES CAP INE LSS RAW DETAIL SUM CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX

  [ -z "$R_SVCOFF" ] && return 0
  # space-separated (not newline): the `case " $TYPES "` tests below match on
  # spaces, so with >1 type a newline-joined list would match none of them.
  TYPES=$(printf '%s\n' "$R_SVCOFF" | awk -F'|' 'NF>=3 && $1 !~ /^#/{print $2}' | sort -u | tr '\n' ' ')
  [ -z "$TYPES" ] && return 0

  # Build the evidence: enabled inetd tokens and SRC subsystem states.
  CAP=$(
    case " $TYPES " in
      (*" inetd "*)
        INE=$(aix stig_inetd_active grep -v '^#' /etc/inetd.conf)
        printf '%s\n' "$INE" | awk 'NF>=1 && $1 !~ /^#/{print "inetd|" $1 "|on"}'
        ;;
    esac
    case " $TYPES " in
      (*" lssrc "*)
        LSS=$(aix stig_lssrc_a lssrc -a)
        printf '%s\n' "$LSS" | awk 'NR>1 && NF>=2 && $1!="Subsystem"{print "lssrc|" $1 "|" $NF}'
        ;;
    esac
    case " $TYPES " in
      (*" rctcp "*)
        # uncommented "start /path/daemon ..." lines in /etc/rc.tcpip = the daemon boots.
        # A commented rule (#start ...) does not match the anchored grep.
        RCT=$(aix stig_rctcp grep -E '^[	 ]*start ' /etc/rc.tcpip)
        printf '%s\n' "$RCT" | awk '$1=="start" && $2!=""{n=split($2,a,"/"); print "rctcp|" a[n] "|on"}'
        ;;
    esac
  )

  RAW=$({ printf '%s\n' "$R_SVCOFF"; echo "AIXRAY_CAP"; printf '%s\n' "$CAP"; } | awk -F'|' '
    BEGIN{ phase=0; nr=0; nlssrc=0 }
    $0=="AIXRAY_CAP"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="" || NF<3) next
      nr++; R_id[nr]=$1; R_type[nr]=$2; R_name[nr]=$3
      next
    }
    phase==1{
      if(NF<3) next
      if($1=="inetd"){ enabled[$2]=1 }
      else if($1=="lssrc"){ state[$2]=$3; nlssrc++ }
      else if($1=="rctcp"){ rctcp_on[$2]=1; nrctcp++ }
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        t=R_type[i]; n=R_name[i]
        if(t=="inetd"){
          if(n in enabled){ st="FAIL"; obs=n" enabled in inetd.conf"; nfail++; nf++; fl[nf]=R_id[i]" "n }
          else { st="PASS"; obs=n" not enabled in inetd.conf"; npass++ }
        }
        else if(t=="lssrc"){
          if(nlssrc==0){ st="NA"; obs=n" (lssrc unreadable)"; nna++ }
          else if(n in state){
            if(state[n]=="active"){ st="FAIL"; obs=n" active"; nfail++; nf++; fl[nf]=R_id[i]" "n }
            else { st="PASS"; obs=n" "state[n]; npass++ }
          }
          else { st="PASS"; obs=n" not defined"; npass++ }
        }
        else if(t=="rctcp"){
          if(n in rctcp_on){ st="FAIL"; obs=n" starts at boot in /etc/rc.tcpip"; nfail++; nf++; fl[nf]=R_id[i]" "n }
          else { st="PASS"; obs=n" not started in /etc/rc.tcpip"; npass++ }
        }
        else { st="NA"; obs=n" unknown type"; nna++ }
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NAPPLIC" -eq 0 ]; then
    ST=WARN; SEV=med
    OBS="n/a"
    MEAN="Could not read the service inventory (/etc/inetd.conf and lssrc -a); no STIG disabled-service rule could be assessed on this run."
    FIX="verify /etc/inetd.conf is readable and the SRC is running; or inspect 'lssrc -a' manually."
  elif [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a; failing: $FLIST"
    MEAN="One or more legacy network services the DISA STIG for IBM AIX 7.x requires disabled are still enabled or running — each is an unneeded, often unauthenticated, network-facing daemon an auditor will flag."
    FIX="comment the service out of /etc/inetd.conf and 'refresh -s inetd' (inetd services), or 'stopsrc -s <subsystem>' and disable it at boot (SRC subsystems); the compliance report lists every rule and its evidence."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a"
    MEAN="Every legacy network service the DISA STIG for IBM AIX 7.x requires disabled is off on this box."
    FIX="n/a"
  fi
  add security stig_svcoff "STIG disabled services" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"

  # nfs_exports — unsafe root/anonymous mappings and unrestricted writable exports.
  # Both reads are fixture-routed and side-effect free. In particular, exportfs is
  # deliberately invoked without arguments: that form only lists /etc/xtab.
  typeset NFS_CONFIG NFS_CONFIG_RC NFS_LIVE NFS_LIVE_RC
  typeset NFS_CONFIG_LINES NFS_LIVE_LINES NFS_CONFIG_COUNT NFS_LIVE_COUNT
  typeset NFS_LINES NFS_ASSESS NFS_HIGH_COUNT NFS_MED_COUNT NFS_RO_COUNT
  typeset NFS_TOTAL_COUNT NFS_EVIDENCE
  typeset NFS_CONFIGURED_ONLY NFS_OBS NFS_PARTIAL_NOTE

  NFS_CONFIG=$(aix etc_exports cat /etc/exports); NFS_CONFIG_RC=$?
  NFS_LIVE=$(aix exportfs exportfs); NFS_LIVE_RC=$?

  NFS_CONFIG_LINES=""
  if [ "$NFS_CONFIG_RC" -eq 0 ]; then
    NFS_CONFIG_LINES=$(printf '%s\n' "$NFS_CONFIG" | awk '
      {
        raw=$0
        parsed=$0
        sub(/[ \t]*#.*/, "", parsed)
        if (parsed !~ /^[ \t]*$/) print raw
      }
    ')
  fi
  NFS_LIVE_LINES=""
  if [ "$NFS_LIVE_RC" -eq 0 ]; then
    NFS_LIVE_LINES=$(printf '%s\n' "$NFS_LIVE" | awk '
      {
        raw=$0
        parsed=$0
        sub(/[ \t]*#.*/, "", parsed)
        if (parsed !~ /^[ \t]*$/) print raw
      }
    ')
  fi

  NFS_CONFIG_COUNT=$(printf '%s\n' "$NFS_CONFIG_LINES" \
    | awk 'NF {n++} END {print n+0}')
  NFS_LIVE_COUNT=$(printf '%s\n' "$NFS_LIVE_LINES" \
    | awk 'NF {n++} END {print n+0}')
  NFS_LINES=$(printf '%s\n%s\n' "$NFS_CONFIG_LINES" "$NFS_LIVE_LINES" \
    | awk 'NF && !seen[$0]++ {print}')

  NFS_ASSESS=$(printf '%s\n' "$NFS_LINES" | awk '
    function valid_ipv4(value, octet, count, i) {
      count=split(value, octet, ".")
      if (count != 4) return 0
      for (i=1; i<=4; i++) {
        if (octet[i] !~ /^[0-9][0-9]*$/) return 0
        if ((octet[i] + 0) < 0 || (octet[i] + 0) > 255) return 0
      }
      return 1
    }
    function unsafe_root_list(value, client, count, i) {
      if (value == "") return 1
      count=split(value, client, ":")
      for (i=1; i<=count; i++) {
        if (client[i] == "") return 1
        # AIX subnet designators begin with @ and include a mask. Prefix-@
        # netgroup forms are likewise not a specific, locally-proven host.
        if (client[i] ~ /^@/ || client[i] ~ /\//) return 1
        if (client[i] ~ /[*?]/) return 1
        if (client[i] ~ /^[0-9.]+$/) {
          if (!valid_ipv4(client[i])) return 1
        } else if (client[i] !~ /^[a-z0-9][a-z0-9_.-]*$/) {
          return 1
        }
      }
      return 0
    }
    {
      raw=$0
      text=$0
      sub(/[ \t]*#.*/, "", text)
      if (text ~ /^[ \t]*$/) next
      gsub(/[ \t]*=[ \t]*/, "=", text)
      text=tolower(text)
      count=split(text, option, /[[:space:],]+/)
      has_ro=0
      has_rw=0
      has_access=0
      unsafe_root=0
      unsafe_anon=0
      for (i=1; i<=count; i++) {
        item=option[i]
        sub(/^-+/, "", item)
        if (item == "ro" || item ~ /^ro=/) has_ro=1
        if (item == "rw" || item ~ /^rw=/) has_rw=1
        if (item ~ /^access=/ && substr(item, 8) != "") has_access=1
        if (item == "anon=0") unsafe_anon=1
        if (item ~ /^root=/ && unsafe_root_list(substr(item, 6))) {
          unsafe_root=1
        }
      }
      if (unsafe_root || unsafe_anon) grade="H"
      else if ((has_rw || !has_ro) && !has_access) grade="M"
      else if (has_ro && !has_rw && has_access) grade="R"
      else grade="S"
      print grade "\t" raw
    }
  ')

  NFS_HIGH_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="H" {n++} END {print n+0}')
  NFS_MED_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="M" {n++} END {print n+0}')
  NFS_RO_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="R" {n++} END {print n+0}')
  NFS_TOTAL_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1!="" {n++} END {print n+0}')
  NFS_EVIDENCE=$(printf '%s\n' "$NFS_ASSESS" | awk -F '\t' '
    $1=="H" || $1=="M" {
      total++
      if (shown < 20) {
        print substr($0, 3)
        shown++
      }
    }
    END {
      if (total > 20) {
        printf "%d additional offending line(s) omitted (cap 20)", total-20
      }
    }
  ')

  NFS_CONFIGURED_ONLY=0
  if [ "$NFS_CONFIG_RC" -eq 0 ] && [ "$NFS_LIVE_RC" -eq 0 ] \
      && [ "$NFS_CONFIG_COUNT" -gt 0 ] && [ "$NFS_LIVE_COUNT" -eq 0 ]; then
    NFS_CONFIGURED_ONLY=1
  fi

  NFS_PARTIAL_NOTE=""
  if [ "$NFS_CONFIG_RC" -ne 0 ] && [ "$NFS_LIVE_RC" -eq 0 ]; then
    NFS_PARTIAL_NOTE="partially assessed — /etc/exports read failed; live exportfs evidence follows"
  elif [ "$NFS_CONFIG_RC" -eq 0 ] && [ "$NFS_LIVE_RC" -ne 0 ]; then
    NFS_PARTIAL_NOTE="partially assessed — current exportfs listing failed; configured /etc/exports evidence follows"
  fi

  if [ "$NFS_HIGH_COUNT" -gt 0 ]; then
    NFS_OBS=$NFS_EVIDENCE
    if [ -n "$NFS_PARTIAL_NOTE" ]; then
      NFS_OBS="${NFS_PARTIAL_NOTE}
${NFS_OBS}"
    fi
    if [ "$NFS_CONFIGURED_ONLY" -eq 1 ]; then
      NFS_OBS="${NFS_OBS}
configured-but-not-live: $NFS_CONFIG_COUNT uncommented /etc/exports line(s); exportfs listed no current exports"
    fi
    add security nfs_exports "NFS exports" FAIL high "$NFS_OBS" \
        "One or more NFS export definitions map anonymous requests to UID 0 or grant root privileges beyond a specific host or IP address." \
        "remove anon=0 and restrict every root= list to explicit trusted hostnames or IP addresses; then re-export the corrected definitions during an approved change." "cis-l1"
  elif [ "$NFS_MED_COUNT" -gt 0 ]; then
    NFS_OBS=$NFS_EVIDENCE
    if [ -n "$NFS_PARTIAL_NOTE" ]; then
      NFS_OBS="${NFS_PARTIAL_NOTE}
${NFS_OBS}"
    fi
    if [ "$NFS_CONFIGURED_ONLY" -eq 1 ]; then
      NFS_OBS="${NFS_OBS}
configured-but-not-live: $NFS_CONFIG_COUNT uncommented /etc/exports line(s); exportfs listed no current exports"
    fi
    add security nfs_exports "NFS exports" WARN med "$NFS_OBS" \
        "One or more exports are writable by default and have no access= client restriction, so any client that can reach the NFS service can attempt to mount them." \
        "add an explicit access= host list and use ro unless the clients genuinely require writes; re-export only through the normal approved change process." "cis-l1"
  elif [ "$NFS_CONFIG_RC" -ne 0 ] && [ "$NFS_LIVE_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — both NFS evidence reads failed (/etc/exports exit=$NFS_CONFIG_RC; exportfs exit=$NFS_LIVE_RC)" \
        "Neither configured nor current NFS export evidence was readable, so absence of exports and safe export options cannot be established." \
        "restore read access to /etc/exports and the no-argument exportfs listing, then re-run AIXray." "cis-l1"
  elif [ "$NFS_CONFIG_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports read failed (exit=$NFS_CONFIG_RC); no unsafe option was established from the current exportfs listing" \
        "The live listing alone did not establish an unsafe export, but unreadable configuration can contain dormant definitions that later become active." \
        "restore read access to /etc/exports and re-run AIXray." "cis-l1"
  elif [ "$NFS_LIVE_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — current exportfs listing failed (exit=$NFS_LIVE_RC); no unsafe option was established from /etc/exports" \
        "The configuration alone did not establish an unsafe export, but the unreadable live listing can contain currently exported state not represented by that file." \
        "restore access to the no-argument exportfs listing and re-run AIXray." "cis-l1"
  elif [ "$NFS_CONFIGURED_ONLY" -eq 1 ]; then
    add security nfs_exports "NFS exports" WARN low \
        "configured-but-not-live: $NFS_CONFIG_COUNT uncommented /etc/exports line(s); exportfs listed no current exports" \
        "NFS exports are configured but were not present in the current exportfs listing; the configuration can become live when NFS is started or exports are refreshed." \
        "confirm whether these exports are intentionally dormant; remove stale definitions or activate only the intended host-restricted exports during an approved change." "cis-l1"
  elif [ "$NFS_TOTAL_COUNT" -eq 0 ]; then
    add security nfs_exports "NFS exports" PASS high \
        "NFS server not exporting" \
        "No uncommented configured export and no current exportfs entry was observed." \
        "n/a" "cis-l1"
  elif [ "$NFS_RO_COUNT" -eq "$NFS_TOTAL_COUNT" ]; then
    add security nfs_exports "NFS exports" PASS high \
        "$NFS_TOTAL_COUNT export line(s) assessed; read-only and host-restricted" \
        "Every observed export is read-only, client-restricted, and has no unsafe root or anonymous UID 0 mapping." \
        "n/a" "cis-l1"
  else
    add security nfs_exports "NFS exports" PASS high \
        "$NFS_TOTAL_COUNT export line(s) assessed; host-restricted with no unsafe root or anonymous mapping" \
        "Every observed writable export is client-restricted, and no export grants root broadly or maps anonymous requests to UID 0." \
        "n/a" "cis-l1"
  fi
}

# ---- H. Config hygiene -----------------------------------------------------------------
function checks_config {
  typeset XN STAT NTPS RESOLV RT TN TZ HOSTS HOSTSRC HOSTSTATE NETSVC NETSVCRC RESORDER ORDERNOTE

  # ntp — daemon running and at least one server configured
  XN=$(aix lssrc_xntpd lssrc -s xntpd)
  STAT=$(printf '%s\n' "$XN" | awk '$1=="xntpd"{print $NF; exit}')
  NTPS=$(aix ntp_conf grep '^server' /etc/ntp.conf | awk 'NF{n++} END{print n+0}')
  if [ "$STAT" = "active" ] && [ "${NTPS:-0}" -ge 1 ]; then
    add config ntp "Time synchronization (NTP)" PASS med "xntpd active, $NTPS server(s)" \
        "The clock is disciplined by NTP — log correlation, Kerberos and TLS all depend on it." "n/a" "stig:V-215208 cis-l1"
  else
    add config ntp "Time synchronization (NTP)" FAIL med "xntpd ${STAT:-inactive}, ${NTPS:-0} server(s)" \
        "No working time sync — clock drift breaks log correlation, Kerberos and TLS." \
        "configure /etc/ntp.conf with a server and start xntpd ('startsrc -s xntpd'; enable at boot)." "stig:V-215208 cis-l1"
  fi

  # dns
  RESOLV=$(aix resolv_conf grep nameserver /etc/resolv.conf | awk 'NF{n++} END{print n+0}')
  if [ "${RESOLV:-0}" -ge 1 ]; then
    add config dns "DNS resolver" PASS low "$RESOLV nameserver(s)" \
        "At least one DNS resolver is configured." "n/a"
  else
    add config dns "DNS resolver" WARN low "no nameserver" \
        "No DNS resolver configured — this may be intentional on an isolated LPAR, or a gap." \
        "add a nameserver to /etc/resolv.conf if this box should resolve names."
  fi

  # default_route
  RT=$(aix netstat_rn netstat -rn)
  if printf '%s\n' "$RT" | grep -q '^default'; then
    add config default_route "Default route" PASS low "default route present" \
        "A default route is configured." "n/a"
  else
    add config default_route "Default route" WARN low "no default route" \
        "No default route — this may be intentional on an isolated LPAR, or a gap." \
        "add a default gateway if off-subnet traffic should route."
  fi

  # tunables — non-default kernel tunables staged for next boot
  # tunables — an unreadable nextboot (permissions, non-root) must not read as
  # "no non-default tunables"; that would be a silent false PASS.
  TNOUT=$(aix tunables_nextboot cat /etc/tunables/nextboot); TNRC=$?
  TN=$(printf '%s\n' "$TNOUT" | awk '!/^#/ && NF>0 {n++} END{print n+0}')
  if [ "$TNRC" -ne 0 ] && [ "${MYUID:-0}" != "0" ]; then
    nr_warn config tunables "Kernel tunables (nextboot)" "the nextboot tunables file" "cat /etc/tunables/nextboot"
  elif [ "${TN:-0}" -gt 0 ]; then
    add config tunables "Kernel tunables (nextboot)" WARN low "$TN changed tunable line(s)" \
        "Kernel tunables are changed from default for next boot — deliberate tuning or archaeology? document each." \
        "review /etc/tunables/nextboot; record why each change exists, or revert to default." ""
  else
    add config tunables "Kernel tunables (nextboot)" PASS low "no non-default tunables" \
        "No non-default kernel tunables set for next boot." "n/a"
  fi

  # tz_set
  TZ=$(aix etc_environment grep '^TZ=' /etc/environment | awk 'NR==1{print}')
  if [ -n "$TZ" ]; then
    add config tz_set "Timezone (TZ)" PASS low "$TZ" \
        "The system timezone is set explicitly." "n/a"
  else
    add config tz_set "Timezone (TZ)" WARN low "TZ not set" \
        "TZ is not set in /etc/environment — timestamps can be ambiguous." \
        "set TZ in /etc/environment to this system's timezone."
  fi

  # host_resolves — static evidence ONLY. The 2026-07-14 lab-host-01 D52 drill
  # proved that invoking a resolver client here emits a real UDP DNS query
  # whenever the hostname is absent from /etc/hosts. Read and parse the local
  # file instead; an absent entry is the finding, never a reason to query DNS.
  RESORDER=$(printf '%s\n' "${NSORDER:-}" | awk 'NR==1{gsub(/^[ \t]+|[ \t]+$/, ""); print; exit}')
  if [ -n "$RESORDER" ]; then
    ORDERNOTE="NSORDER=$RESORDER"
  else
    NETSVC=$(aix netsvc_conf cat /etc/netsvc.conf); NETSVCRC=$?
    if [ "$NETSVCRC" -eq 0 ]; then
      RESORDER=$(printf '%s\n' "$NETSVC" | awk '
        {
          line=$0
          sub(/[ \t]*#.*/, "", line)
          if (line ~ /^[ \t]*hosts[ \t]*=/) {
            sub(/^[ \t]*hosts[ \t]*=[ \t]*/, "", line)
            gsub(/[ \t]+/, "", line)
            if (line != "") print line
            exit
          }
        }
      ')
    else
      RESORDER=""
    fi
    if [ -n "$RESORDER" ]; then
      ORDERNOTE="/etc/netsvc.conf hosts=$RESORDER"
    else
      ORDERNOTE="resolution order not declared/readable"
    fi
  fi

  HOSTS=$(aix etc_hosts cat /etc/hosts); HOSTSRC=$?
  if [ -z "$HOST" ]; then
    HOSTSTATE=NO_HOSTNAME
  elif [ "$HOSTSRC" -ne 0 ]; then
    HOSTSTATE=UNREADABLE
  else
    HOSTSTATE=$(printf '%s\n' "$HOSTS" | awk -v wanted="$HOST" '
      function valid_ipv4(address, count, octet, i) {
        count=split(address, octet, "[.]")
        if (count != 4) return 0
        for (i=1; i<=4; i++) {
          if (octet[i] !~ /^[0-9][0-9]*$/ || octet[i] + 0 > 255) return 0
        }
        return 1
      }
      function valid_ipv6(address, zone_count, zone, core, rest, first,
                          ipv4, has_ipv4, count, part, piece, i, compressed, effective) {
        zone_count=split(address, zone, "%")
        if (zone_count < 1 || zone_count > 2) return 0
        if (zone_count == 2 && zone[2] !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        core=zone[1]
        if (core !~ /:/ || core ~ /:::/ || core !~ /^[0-9A-Fa-f:.][0-9A-Fa-f:.]*$/) return 0
        if (core ~ /^:[^:]/ || core ~ /[^:]:$/) return 0
        first=index(core, "::")
        if (first > 0) {
          compressed=1
          rest=substr(core, first + 2)
          if (index(rest, "::") > 0) return 0
        }
        if (core ~ /[.]/) {
          ipv4=core
          sub(/^.*:/, "", ipv4)
          if (!valid_ipv4(ipv4)) return 0
          sub(/[^:]*$/, "", core)
          has_ipv4=1
        }
        count=split(core, part, "[:]")
        for (i=1; i<=count; i++) {
          piece=part[i]
          if (piece == "") continue
          if (piece !~ /^[0-9A-Fa-f][0-9A-Fa-f]?[0-9A-Fa-f]?[0-9A-Fa-f]?$/) return 0
          effective++
        }
        effective += 2 * has_ipv4
        if (compressed) return effective < 8
        return effective == 8
      }
      {
        line=$0
        sub(/[ \t]*#.*/, "", line)
        if (line ~ /^[ \t]*$/) next
        $0=line
        if (NF < 2 || (!valid_ipv4($1) && !valid_ipv6($1))) {
          bad=1
          next
        }
        for (i=2; i<=NF; i++) {
          if ($i !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) bad=1
          if (tolower($i) == tolower(wanted)) found=1
        }
        valid++
      }
      END {
        if (bad || valid == 0) print "UNUSABLE"
        else if (found) print "FOUND"
        else print "ABSENT"
      }
    ')
  fi

  case "$HOSTSTATE" in
    FOUND)
      add config host_resolves "Host self-resolution" PASS low \
          "$HOST found in /etc/hosts; $ORDERNOTE" \
          "The hostname has a matching entry in the static local hosts file; this does not claim that live DNS works." "n/a"
      ;;
    ABSENT)
      add config host_resolves "Host self-resolution" WARN low \
          "$HOST does not self-resolve locally — no matching /etc/hosts entry; $ORDERNOTE" \
          "Tools and certs can misbehave when the box has no local entry for its own hostname; AIXray deliberately did not query DNS." \
          "add $HOST to /etc/hosts with the system's intended local address."
      ;;
    UNREADABLE)
      add config host_resolves "Host self-resolution" WARN low \
          "not assessed — /etc/hosts capture failed (rc=$HOSTSRC); $ORDERNOTE" \
          "AIXray could not inspect the local hosts file and deliberately did not fall back to a live DNS lookup." \
          "make /etc/hosts readable, then re-run AIXray."
      ;;
    NO_HOSTNAME)
      add config host_resolves "Host self-resolution" WARN low \
          "not assessed — hostname capture was empty; $ORDERNOTE" \
          "AIXray cannot test a local hosts-file entry without a captured hostname and deliberately did not query DNS." \
          "verify that hostname(1) returns this system's hostname, then re-run AIXray."
      ;;
    *)
      add config host_resolves "Host self-resolution" WARN low \
          "not assessed — /etc/hosts capture is empty or malformed; $ORDERNOTE" \
          "AIXray could not safely interpret the local hosts file and deliberately did not fall back to a live DNS lookup." \
          "repair /etc/hosts syntax, then re-run AIXray."
      ;;
  esac
}

# ---- I. Monitoring & operational readiness ---------------------------------------------
function checks_monitoring {
  typeset PSE PSERC AG KNOWN_AGENT_ALLOWLIST KNOWN_AGENT_ALLOWLIST_RE EN SYS PH CR RC ENDEC2 ENCUST2

  KNOWN_AGENT_ALLOWLIST_RE='zabbix_agent|nrpe|node_export|kuxagent|collectd|njmon|nimon|datadog'
  KNOWN_AGENT_ALLOWLIST='Zabbix agent, Nagios NRPE, Prometheus node_exporter, IBM Tivoli/ITM kuxagent, collectd, njmon/nimon, Datadog agent'
  PSE=$(aix ps_e ps -e -o comm); PSERC=$?

  # monitoring_agent — the managed-service hook
  if [ "$PSERC" -ne 0 ]; then
    add monitoring monitoring_agent "Monitoring agent" NOT_ASSESSED high \
        "not assessed — ps -e -o comm capture failed (rc=$PSERC)" \
        "AIXray could not inspect running processes, so it cannot determine whether a known monitoring agent is running." \
        "make 'ps -e -o comm' available, then re-run AIXray." "ffiec:III.B"
  elif [ -z "$PSE" ]; then
    add monitoring monitoring_agent "Monitoring agent" NOT_ASSESSED high \
        "not assessed — ps -e -o comm capture empty (rc=0)" \
        "AIXray received no process evidence, so it cannot determine whether a known monitoring agent is running." \
        "verify that 'ps -e -o comm' returns the process list, then re-run AIXray." "ffiec:III.B"
  else
    AG=$(printf '%s\n' "$PSE" | grep -E "$KNOWN_AGENT_ALLOWLIST_RE" | awk 'NR==1{print $NF}')
    if [ -n "$AG" ]; then
      add monitoring monitoring_agent "Monitoring agent" PASS med "$AG running" \
          "A known monitoring agent is running — findings on this box can reach someone automatically." "n/a" "ffiec:III.B"
    else
      add monitoring monitoring_agent "Monitoring agent" WARN high \
          "no KNOWN monitoring agent detected (checked: $KNOWN_AGENT_ALLOWLIST)" \
          "AIXray checked only the listed known agents and found none; other monitoring may still be present." \
          "confirm monitoring coverage; if none exists, install and point a monitoring agent at this LPAR." "ffiec:III.B"
    fi
  fi

  # errpt_notify — AIX ships ~5 default errnotify stanzas. Believability review 2026-07-13
  # (review-queue #62, finding #7): this used to PASS on a raw stanza-COUNT threshold
  # (>6 stanzas = "custom methods exist, can page a human"), which could — and did —
  # contradict the errors category's errnotify_methods finding, which decodes what the
  # methods actually DO. A box can carry more than 6 stanzas that are ALL still default/
  # diagela (no real site paging) or, in the other direction, carry a genuine custom
  # method among fewer than 7 total stanzas; either way the two checks were reading the
  # same on-box fact through two different, disagreeing lenses. Now shares the SAME
  # decode (errnotify_decode) errnotify_methods uses, so the two findings can never again
  # diverge on the same underlying signal.
  EN=$(printf '%s\n' "$(aix odmget_errnotify odmget errnotify)" | awk '/en_name/{n++} END{print n+0}')
  ENDEC2=$(errnotify_decode)
  ENCUST2=$(printf '%s' "$ENDEC2" | awk -F'\t' '{print $1+0}')
  if [ "${ENCUST2:-0}" -gt 0 ]; then
    add monitoring errpt_notify "Error notification" PASS low "$EN errnotify stanzas ($ENCUST2 custom alert method(s))" \
        "Custom error-notification methods exist beyond the defaults — errors can page a human." "n/a"
  else
    add monitoring errpt_notify "Error notification" WARN med "$EN errnotify stanzas (defaults only)" \
        "Errors log locally and tell no one — the error log only helps if someone happens to read it." \
        "add an errnotify ODM stanza that emails or pages on PERM hardware and disk errors."
  fi

  # remote_syslog
  SYS=$(printf '%s\n' "$(aix syslog_conf grep '@' /etc/syslog.conf)" | awk '!/^#/ && /@/ {n++} END{print n+0}')
  if [ "${SYS:-0}" -ge 1 ]; then
    add monitoring remote_syslog "Remote syslog" PASS low "$SYS forwarding rule(s)" \
        "syslog forwards to a remote collector — logs survive the box." "n/a" "ffiec:II.C.22"
  else
    add monitoring remote_syslog "Remote syslog" WARN low "no remote target" \
        "No remote syslog target — logs die with the box, exactly when you need them." \
        "add an '@loghost' line to /etc/syslog.conf and 'refresh -s syslogd'." "ffiec:II.C.22"
  fi

  # perf_history — reuse ps_e
  PH=$(printf '%s\n' "$PSE" | grep -E 'topasrec|xmwlm|nmon' | awk 'NR==1{print}')
  if [ -n "$PH" ]; then
    add monitoring perf_history "Performance history" PASS low "collector running" \
        "A performance-history collector is running — sizing and incident forensics have data to work from." "n/a"
  else
    add monitoring perf_history "Performance history" WARN low "none running" \
        "No performance-history collection — sizing and incident forensics become guesswork." \
        "enable topas recording ('topasrec'/xmwlm) so history exists when you need it."
  fi

  # backup_job (root-gated; silent skip unprivileged — F already covers backup evidence)
  CR=$(aix crontab_root crontab -l); RC=$?
  if [ "$RC" -ne 0 ]; then
    if [ "${MYUID:-0}" != "0" ]; then
      :  # cannot read root's crontab unprivileged — skip silently
    else
      add monitoring backup_job "Scheduled backup job" WARN med "no root crontab" \
          "No scheduled backup in root's crontab — where does the mksysb come from?" \
          "schedule mksysb/savevg in root's crontab, or confirm NIM/central backup owns it."
    fi
  elif printf '%s\n' "$CR" | grep -Eq 'mksysb|savevg|backup'; then
    add monitoring backup_job "Scheduled backup job" PASS med "backup job scheduled" \
        "root's crontab schedules a backup — the mksysb has an owner and a cadence." "n/a"
  else
    add monitoring backup_job "Scheduled backup job" WARN med "no backup in crontab" \
        "No scheduled backup in root's crontab — where does the mksysb come from?" \
        "schedule mksysb/savevg in root's crontab, or confirm NIM/central backup owns it."
  fi
}

# ---- VIOS role depth (fires ONLY when IS_VIOS=1) -------------------------------------
# LAYER 2. Every finding here is built from IBM DOCUMENTED command output formats — NOT
# from a live VIOS (PowerVS gives no padmin access; a real test VIOS arrives with IBM
# Partner Silver tier). They are therefore documentation-grounded and PENDING live-VIOS
# validation; see docs/COVERAGE.md ("VIOS role checks — documentation-grounded, pending
# live-VIOS validation"). Discipline: conservative — WARN/informational, never a confident
# FAIL on a parse we could not verify live; a parse we cannot read degrades to WARN, not a
# hollow PASS. Each finding also carries the single-VIOS limit: the PARTNER VIOS's health
# lives on the other LPAR and a single-box scan cannot see it (dual-VIOS fleet view deferred).
function checks_vios {
  typeset SEAS SEA ESTAT SST LSA HAM CTL PRIO
  typeset SEACNT BADHA NOCTL NOPRIO SEADET
  typeset CLST RC CLBAD CLNODES CLPRESENT
  typeset NPIVRAW NPTOT NPBAD NPLIST NPSPAN NPFCS
  typeset LSNP NPFAB
  typeset VSRAW VSTOT VSBAD VSLIST BACKHD HD RP RPV RSVTOT RSVBAD RSVUNK RSVDET

  # ---- shared signals: CAA cluster presence + per-SEA HA config --------------------
  # Read cluster -status ONCE (used by ssp_cluster below AND by the SEA no-control-channel
  # logic: a CAA/SSP cluster enables the newer control-channel-less SEA failover, so a
  # missing ctl_chan is NOT a hard FAIL when a cluster is present).
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  CLST=$(aix cluster_status ioscli cluster -status); RC=$?
  CLPRESENT=0
  if [ "$RC" -eq 0 ] && [ -n "$CLST" ] && printf '%s\n' "$CLST" | grep -qi 'Cluster'; then CLPRESENT=1; fi

  # sea_failover — Shared Ethernet Adapter HA posture (DEEPENED).
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # Prefer the CONFIG attributes over parsing entstat sections: 'lsdev -dev <sea> -attr'
  # (== 'lsattr -El <sea>') exposes ha_mode {auto|standby|sharing|disabled}, ctl_chan (the
  # control-channel ent adapter, empty when unset), and priority (1-15). entstat -d <sea>
  # is read only to enrich the observed line with the RUNTIME State (PRIMARY/BACKUP/STANDBY,
  # or LIMBO/RECOVERY = cannot settle a role). Veteran signal: ha_mode=disabled OR an empty
  # ctl_chan (without a CAA cluster) means a second VIOS cannot take over the network cleanly
  # — a network SPOF / split-brain risk for every client LPAR bridged through this SEA. We
  # see only THIS VIOS's side; a clean local config still needs the partner VIOS confirmed.
  # FIELD PARSING UNVERIFIED — PJ to confirm the lsdev/lsattr attr rows and entstat State
  # label spelling on a live VIOS. ctl_chan is validated to look like 'entN' precisely so an
  # empty value (where awk would otherwise read the description column) degrades to "unset",
  # not a misparse.
  SEAS=$(aix lsdev_sea ioscli lsdev -type sea | awk 'NR>1 && $1 ~ /^ent[0-9]+$/{print $1}')
  if [ -n "$SEAS" ]; then
    SEACNT=0; BADHA=0; NOCTL=0; NOPRIO=0; SEADET=""
    for SEA in $SEAS; do
      SEACNT=$((SEACNT+1))
      LSA=$(aix "lsattr_sea_$SEA" ioscli lsdev -dev "$SEA" -attr)
      HAM=$(printf '%s\n' "$LSA" | awk '$1=="ha_mode"{print $2; exit}')
      CTL=$(printf '%s\n' "$LSA" | awk '$1=="ctl_chan"{print $2; exit}')
      PRIO=$(printf '%s\n' "$LSA" | awk '$1=="priority"{print $2; exit}')
      [ -z "$HAM" ] && HAM="unknown"
      # ctl_chan is a control-channel adapter (entN) when set; anything else = unset (an
      # empty attr value makes awk read the description word, so anchor on the entN shape).
      case "$CTL" in (ent[0-9]*) : ;; (*) CTL="";; esac
      case "$PRIO" in (''|*[!0-9]*) PRIO="";; esac
      case "$HAM" in (auto|standby) : ;; (*) BADHA=$((BADHA+1));; esac
      [ -z "$CTL" ] && NOCTL=$((NOCTL+1))
      [ -z "$PRIO" ] && NOPRIO=$((NOPRIO+1))
      ESTAT=$(aix "entstat_sea_$SEA" entstat -d "$SEA")
      SST=$(printf '%s\n' "$ESTAT" | awk -F: '/^[ \t]*State:/{v=$2; gsub(/^[ \t]+|[ \t]+$/,"",v); print v; exit}')
      [ -z "$SST" ] && SST="?"
      SEADET="$SEADET${SEADET:+; }$SEA ha_mode=$HAM ctl_chan=${CTL:-none} priority=${PRIO:-unset} state=$SST"
    done
    if [ "$BADHA" -gt 0 ]; then
      add resilience sea_failover "SEA failover posture" FAIL high "$SEADET" \
          "A Shared Ethernet Adapter on this VIOS is not configured for failover (ha_mode not auto/standby) — a second VIOS cannot take over the bridge, so every client LPAR bridged through this SEA loses its network the moment this VIOS goes down. This is not a redundant network." \
          "set the SEA for failover ('chdev -dev <sea> -attr ha_mode=auto ctl_chan=<ent> priority=<n>'), give the pair distinct priorities, and confirm the partner VIOS's SEA ('entstat -d <sea>' on both)."
    elif [ "$NOCTL" -gt 0 ] && [ "$CLPRESENT" -eq 0 ]; then
      add resilience sea_failover "SEA failover posture" FAIL high "$SEADET" \
          "A Shared Ethernet Adapter is set to fail over but has no control channel (ctl_chan) and no CAA cluster to replace it — the two VIOS cannot arbitrate primary/backup, so a failover can leave both bridging at once (split-brain: duplicated frames, a broadcast storm) or neither." \
          "add a control-channel adapter/VLAN ('mkvdev -sea ...'/'chdev -dev <sea> -attr ctl_chan=<ent>'), or adopt the CAA control-channel-less method on a supported VIOS level; verify on both VIOS."
    elif [ "$NOCTL" -gt 0 ]; then
      add resilience sea_failover "SEA failover posture" WARN med "$SEADET" \
          "A Shared Ethernet Adapter has no ctl_chan, but a CAA cluster is present — the newer control-channel-less SEA failover uses the cluster instead. Likely intentional; confirm it is actually the CAA method and not a half-removed control channel." \
          "confirm the SEA uses CAA-based failover (supported VIOS level + cluster) rather than a lost control channel; check the partner VIOS's SEA config too."
    elif [ "$NOPRIO" -gt 0 ]; then
      add resilience sea_failover "SEA failover posture" WARN med "$SEADET" \
          "The SEA is set for failover with a control channel, but a priority is unset/unreadable — without distinct priorities across the pair the primary/backup roles are undefined and can flap." \
          "set a priority on each side ('chdev -dev <sea> -attr priority=<n>'), distinct between the two VIOS (e.g. 1 and 2)."
    else
      add resilience sea_failover "SEA failover posture" PASS low "$SEADET" \
          "This VIOS's Shared Ethernet Adapter(s) are configured for failover (ha_mode auto/standby, a control channel set, a priority set) — the network bridge is set up to survive this VIOS. Single-box scan: confirm the partner VIOS's SEA (priority + state on the other LPAR) to prove the pair actually fails over." \
          "n/a"
    fi
  fi

  # vios_topology — single-vs-dual VIOS & the box-level SPOF verdict (NEW).
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # A single VIOS is a single point of failure for EVERY client LPAR it serves — both disk
  # AND network. Inherited shops are full of "dual VIOS" that is really one working side (the
  # second was never wired, or was wired and left broken). We infer HA topology from what one
  # box can see: a SEA configured for failover (ha_mode auto/standby + a control channel) OR
  # a CAA/SSP cluster implies a partner VIOS exists. A lone SEA with no HA config, and no
  # cluster, means either a genuinely standalone VIOS or a broken pair — both a SPOF worth
  # flagging. Conservative: WARN when we simply cannot see a partner (an inference, not a
  # confident FAIL); FAIL only when a SEA is present but demonstrably unable to fail over.
  # FIELD PARSING UNVERIFIED — PJ to confirm; this reuses the sea_failover attr reads above.
  if [ -n "$SEAS" ] || [ "$CLPRESENT" -eq 1 ]; then
    if [ -n "$SEAS" ] && { [ "$BADHA" -gt 0 ] || [ "$NOCTL" -gt 0 ]; } && [ "$CLPRESENT" -eq 0 ]; then
      add resilience vios_topology "VIOS redundancy topology" FAIL high "SEA present, not failover-ready; no CAA cluster" \
          "This VIOS bridges the network but its SEA is not able to fail over to a partner (no control channel / ha_mode not set) and there is no CAA cluster — so a second VIOS cannot cleanly take over the network. Either this is a standalone VIOS (a single point of failure for every client's disk and network) or a broken pair where the second side was never fully wired." \
          "decide the intent: if it is meant to be an HA pair, wire the SEA control channel + ha_mode on BOTH VIOS and confirm the partner is serving; if it is genuinely standalone, treat this VIOS as a known SPOF (single client outage domain) in the runbook."
    elif { [ -n "$SEAS" ] && [ "$BADHA" -eq 0 ] && [ "$NOCTL" -eq 0 ]; } || [ "$CLPRESENT" -eq 1 ]; then
      add resilience vios_topology "VIOS redundancy topology" PASS low "HA config present (SEA failover / CAA cluster) — partner VIOS implied" \
          "This VIOS carries HA configuration (a failover-ready SEA and/or a CAA cluster), which implies a partner VIOS exists to take over. A single-box scan cannot PROVE the partner is healthy and actually serving — that lives on the other LPAR." \
          "confirm the second VIOS exists, is on a different physical path, and is genuinely serving clients (its own aixray/entstat/lsmap) — do not assume 'configured for failover' means the partner is up."
    else
      add resilience vios_topology "VIOS redundancy topology" WARN high "no SEA HA config and no CAA cluster visible from this box" \
          "Nothing on this box indicates a partner VIOS — no failover-ready SEA, no CAA cluster. This may be a genuinely single VIOS, in which case every client LPAR's disk AND network depends on this one server: a single point of failure whose loss takes down all its clients." \
          "confirm whether a second VIOS exists and is actually serving; if not, this is a real SPOF — plan a partner VIOS, or document the single-VIOS risk and its blast radius explicitly."
    fi
  fi

  # npiv_maps — virtual FC (NPIV) mappings.
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # 'lsmap -all -npiv': each vfchost has a "Status:" line (LOGGED_IN vs NOT_LOGGED_IN). A
  # vfchost NOT_LOGGED_IN (or with no backing FC name) has no live path to the fabric —
  # the client LPAR it serves has a dead or half virtual-FC path.
  NPIVRAW=$(aix lsmap_npiv ioscli lsmap -all -npiv)
  if [ -n "$NPIVRAW" ] && printf '%s\n' "$NPIVRAW" | grep -q '^Status:'; then
    # Separate awk passes (never a pipe-delimited $()+${%%|*} split — ksh treats a bare
    # '|' in a ${%%} pattern as alternation and strips the whole value to empty).
    NPTOT=$(printf '%s\n' "$NPIVRAW" | awk -F: '/^Status:/{n++} END{print n+0}')
    NPBAD=$(printf '%s\n' "$NPIVRAW" | awk -F: '/^Status:/{s=$2; gsub(/[ \t]/,"",s); if(s!="LOGGED_IN") n++} END{print n+0}')
    NPLIST=$(printf '%s\n' "$NPIVRAW" | awk -F: '
      $1 ~ /^vfchost[0-9]/ { split($0,a," "); name=a[1] }
      /^Status:/ { s=$2; gsub(/[ \t]/,"",s); if (s!="LOGGED_IN") printf "%s%s (%s)", (n++?", ":""), name, s }')
    if [ "${NPBAD:-0}" -gt 0 ]; then
      add storage npiv_maps "Virtual FC (NPIV) mappings" WARN high "$NPBAD of $NPTOT vfchost not logged in: $NPLIST" \
          "One or more virtual-FC host adapters are NOT_LOGGED_IN — the physical FC login to the fabric is down, so the client LPAR mapped to it has a dead or degraded virtual-FC path (if its second path via the partner VIOS is also down, that client loses disk)." \
          "check the physical fibre (fcstat/errpt on this VIOS, the SAN zoning and the switch port); on a dual-VIOS pair confirm the client still has a live path through the other VIOS."
    else
      add storage npiv_maps "Virtual FC (NPIV) mappings" PASS low "$NPTOT vfchost mapping(s), all LOGGED_IN" \
          "Every virtual-FC host adapter on this VIOS is logged in to the fabric — the client LPARs' NPIV paths through this VIOS are live." "n/a"
    fi

    # npiv_redundancy — is the NPIV path ACTUALLY redundant, from this VIOS's view (NEW).
    # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
    # Complements npiv_maps (login status) with the redundancy question a veteran asks:
    #  (1) any vfchost NOT_LOGGED_IN is a DEAD FC path for that client through this VIOS — FAIL
    #      (npiv_maps flags the same at WARN as a mapping issue; here it is the redundancy
    #      verdict: the client is relying on its OTHER VIOS right now).
    #  (2) do the physical FC ports feeding the vfchosts span more than one PHYSICAL ADAPTER?
    #      Two vfc on two ports of the SAME card is not adapter/fabric redundancy — one card
    #      or one fabric event kills them all. We derive the physical adapter from the FC loc
    #      code by stripping the -Tn port suffix (the -Cn card slot is the adapter); lsnports
    #      corroborates how many ports actually see a fabric (fabric column = 1).
    # FIELD PARSING UNVERIFIED — PJ to confirm: the 'FC name:'/'FC loc code:' line layout in
    # lsmap -all -npiv, and the lsnports column order (name physloc fabric tports aports ...).
    # Conservative: if the physical span cannot be derived, PASS with an informational note
    # rather than a WARN/FAIL on a guess.
    LSNP=$(aix lsnports ioscli lsnports)
    NPFAB=$(printf '%s\n' "$LSNP" | awk 'NR>1 && $3+0>=1{n++} END{print n+0}')
    # distinct physical FC adapter slots feeding NPIV (loc code minus the -Tn port suffix)
    NPSPAN=$(printf '%s\n' "$NPIVRAW" | awk -F'FC loc code:' '
      /FC loc code:/ { v=$2; gsub(/^[ \t]+/,"",v); sub(/[ \t].*/,"",v); sub(/-T[0-9]+.*/,"",v);
                       if (v!="" && !s[v]++) n++ } END{print n+0}')
    # fallback span = distinct physical FC port names (FC name:) if loc codes did not parse
    NPFCS=$(printf '%s\n' "$NPIVRAW" | awk -F'FC name:' '
      /FC name:/ { v=$2; gsub(/^[ \t]+/,"",v); sub(/[ \t].*/,"",v);
                   if (v!="" && !s[v]++) n++ } END{print n+0}')
    [ "${NPSPAN:-0}" -eq 0 ] && NPSPAN=$NPFCS
    if [ "${NPBAD:-0}" -gt 0 ]; then
      add storage npiv_redundancy "NPIV path redundancy" FAIL high "$NPBAD of $NPTOT vfchost NOT_LOGGED_IN: $NPLIST" \
          "One or more virtual-FC host adapters on this VIOS are NOT_LOGGED_IN — that client's FC path THROUGH THIS VIOS is dead. Right now the client is surviving only on its other VIOS's path (if it has one); this side is not providing the redundancy it is supposed to." \
          "restore the physical FC login (fcstat/errpt on this VIOS, SAN zoning, switch port), then confirm the vfchost logs in; verify the client's second path via the partner VIOS is actually up so it is not a single path masquerading as two."
    elif [ "${NPSPAN:-0}" -ge 2 ]; then
      add storage npiv_redundancy "NPIV path redundancy" PASS low "$NPTOT vfchost across $NPSPAN physical FC adapter(s); $NPFAB fabric-connected port(s)" \
          "Every NPIV vfchost is logged in, and they ride more than one physical FC adapter on this VIOS — a single FC card/port loss does not take out all NPIV clients on this side." "n/a"
    else
      add storage npiv_redundancy "NPIV path redundancy" WARN high "all $NPTOT vfchost on a single physical FC adapter" \
          "Every NPIV vfchost is logged in, but they all ride ONE physical FC adapter on this VIOS — no fabric/adapter redundancy from this side. One FC card, port, or fabric event takes out every NPIV client served by this VIOS at once (they then depend entirely on the partner VIOS)." \
          "spread the NPIV maps across a second physical FC adapter/fabric on this VIOS ('vfcmap' to a vfchost backed by a different fcs), and confirm the partner VIOS uses a different adapter/fabric too."
    fi
  fi

  # vscsi_maps — virtual SCSI mappings with a missing backing device.
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # 'lsmap -all': a vhost's VTD names its "Backing device"; VIOS prints "NO VIRTUAL TARGET
  # DEVICE FOUND" for an empty vhost, and a VTD "Status Defined" (not Available) is a
  # broken/offline mapping — either way the client LPAR's vSCSI disk is not being served.
  VSRAW=$(aix lsmap_vscsi ioscli lsmap -all)
  if [ -n "$VSRAW" ] && printf '%s\n' "$VSRAW" | awk '$1 ~ /^vhost[0-9]/{f=1} END{exit f?0:1}'; then
    # Separate awk passes for the same ksh ${%%|*} reason noted in npiv_maps above.
    VSTOT=$(printf '%s\n' "$VSRAW" | awk '$1 ~ /^vhost[0-9]/{n++} END{print n+0}')
    VSBAD=$(printf '%s\n' "$VSRAW" | awk '/NO VIRTUAL TARGET DEVICE FOUND/{n++} $1=="Status" && $2=="Defined"{n++} END{print n+0}')
    VSLIST=$(printf '%s\n' "$VSRAW" | awk '
      $1 ~ /^vhost[0-9]/ { vh=$1 }
      /NO VIRTUAL TARGET DEVICE FOUND/ { printf "%s%s (no VTD)", (n++?", ":""), vh }
      $1=="Status" && $2=="Defined" { printf "%s%s (Defined)", (n++?", ":""), vh }')
    if [ "${VSBAD:-0}" -gt 0 ]; then
      add storage vscsi_maps "Virtual SCSI mappings" WARN high "$VSBAD issue(s) across $VSTOT vhost: $VSLIST" \
          "A virtual-SCSI host adapter has no backing device, or a target device is Defined (offline) — the client LPAR mapped to it is not being served that vSCSI disk (a rebuild or a failed backing hdisk usually left it behind)." \
          "map the missing backing device ('mkvdev -vdev <hdisk> -vadapter <vhost>') or clear the stale one; on a dual-VIOS pair confirm the client still reaches the disk via the other VIOS."
    else
      add storage vscsi_maps "Virtual SCSI mappings" PASS low "$VSTOT vhost mapping(s), all backed" \
          "Every virtual-SCSI host adapter on this VIOS has a live backing device — the client LPARs' vSCSI disks served by this VIOS are mapped." "n/a"
    fi

    # vscsi_reserve — the silent killer of dual-VIOS vSCSI (NEW).
    # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
    # For a LUN to be served by BOTH VIOS (vSCSI failover), the backing hdisk must NOT hold a
    # SCSI reservation: reserve_policy=no_reserve (older attr reserve_lock=no). If a backing
    # LUN is single_path / PR_exclusive / reserve_lock=yes, the OTHER VIOS physically cannot
    # open it — so failover fails SILENTLY: everything looks mapped, the config looks dual,
    # but the moment this VIOS drops, the client's disk does not come back on the partner.
    # This is the highest-value fake-redundancy catch. For each backing hdisk from lsmap -all
    # we read its reserve_policy ('lsdev -dev <hdisk> -attr reserve_policy' == 'lsattr -El
    # <hdisk> -a reserve_policy'). Any backing LUN not no_reserve ⇒ FAIL; a value we cannot
    # read degrades to WARN (older disks expose reserve_lock instead, not reserve_policy).
    # FIELD PARSING UNVERIFIED — PJ to confirm: the ioscli 'lsdev -dev <hdisk> -attr
    # reserve_policy' output layout ("value" header + blank + value) vs the lsattr row form;
    # the parser accepts both (a lone known reserve token on its own line, or a reserve_policy
    # lsattr row) and treats anything else as unknown -> WARN.
    BACKHD=$(printf '%s\n' "$VSRAW" | awk '$1=="Backing" && $2=="device" && $3!="" && !s[$3]++{print $3}')
    if [ -n "$BACKHD" ]; then
      RSVTOT=0; RSVBAD=0; RSVUNK=0; RSVDET=""
      for HD in $BACKHD; do
        RSVTOT=$((RSVTOT+1))
        RP=$(aix "reserve_$HD" ioscli lsdev -dev "$HD" -attr reserve_policy)
        # Accept both output shapes: ioscli 'value\n\n<val>' (a known reserve token alone on
        # a line) and lsattr 'reserve_policy <val> <desc> True' (the reserve_policy row).
        RPV=$(printf '%s\n' "$RP" | awk '
          $1=="reserve_policy" && NF>=2 { v=$2 }
          $1=="no_reserve" || $1=="single_path" || $1=="PR_exclusive" || $1=="PR_shared" { v=$1 }
          END { print v }')
        if [ -z "$RPV" ]; then
          RSVUNK=$((RSVUNK+1)); RSVDET="$RSVDET${RSVDET:+, }$HD=?"
        elif [ "$RPV" = "no_reserve" ]; then
          RSVDET="$RSVDET${RSVDET:+, }$HD=no_reserve"
        else
          RSVBAD=$((RSVBAD+1)); RSVDET="$RSVDET${RSVDET:+, }$HD=$RPV"
        fi
      done
      if [ "$RSVBAD" -gt 0 ]; then
        add storage vscsi_reserve "vSCSI backing-LUN reservation" FAIL high "$RSVBAD of $RSVTOT backing LUN(s) reserved: $RSVDET" \
            "A backing LUN behind a vSCSI map is holding a SCSI reservation (reserve_policy not no_reserve) — the OTHER VIOS physically cannot open this LUN, so vSCSI failover for that client fails SILENTLY. Everything looks mapped and 'dual', but if this VIOS drops, the client's disk does not come back on the partner. This vSCSI path is not actually redundant." \
            "set the backing disk to no_reserve on this VIOS ('chdev -dev <hdisk> -attr reserve_policy=no_reserve'; older disks: reserve_lock=no) and confirm the SAME on the partner VIOS for the same LUN before relying on failover."
      elif [ "$RSVUNK" -eq "$RSVTOT" ]; then
        add storage vscsi_reserve "vSCSI backing-LUN reservation" WARN med "reserve_policy unreadable on all $RSVTOT backing LUN(s): $RSVDET" \
            "Could not read reserve_policy on the vSCSI backing LUNs — cannot confirm they are no_reserve, which dual-VIOS vSCSI failover requires (older disks expose reserve_lock instead). Not confirming this leaves a common silent-failover trap unchecked." \
            "check each backing hdisk ('lsdev -dev <hdisk> -attr reserve_policy' or 'lsattr -El <hdisk> -a reserve_lock') on BOTH VIOS; they must be no_reserve / reserve_lock=no to fail over."
      else
        add storage vscsi_reserve "vSCSI backing-LUN reservation" PASS low "$RSVTOT backing LUN(s), all no_reserve: $RSVDET" \
            "Every vSCSI backing LUN on this VIOS is no_reserve — the partner VIOS can physically open the same LUNs, so vSCSI failover is viable from this side. Single-box scan: confirm the partner VIOS holds no_reserve on the same LUNs too." "n/a"
      fi
    fi
  fi

  # ssp_cluster — Shared Storage Pool / CAA cluster state (reported ONLY when a cluster
  # exists on this VIOS). Reuses the cluster -status read at the top of this function.
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # 'cluster -status': the pool and each node report a State (OK vs DOWN/DEGRADED). A node
  # DOWN or a degraded pool means the SSP's shared storage is not fully redundant. When no
  # cluster is defined the command errors / prints nothing — skip cleanly (no finding).
  if [ "$CLPRESENT" -eq 1 ]; then
    CLBAD=$(printf '%s\n' "$CLST" | awk '{u=toupper($0)} u ~ /DOWN|DEGRADED|FAILED|INCOMPLETE/{n++} END{print n+0}')
    CLNODES=$(printf '%s\n' "$CLST" | awk '/^[ \t]+[A-Za-z]/ && NR>2 {n++} END{print n+0}')
    if [ "${CLBAD:-0}" -gt 0 ]; then
      add resilience ssp_cluster "Shared Storage Pool cluster" WARN high "cluster reports a node/pool not OK" \
          "The Shared Storage Pool / CAA cluster reports a node down or a degraded pool — SSP-backed client disks may have lost a redundant path or a node's storage access." \
          "check 'cluster -status' and 'lssp -clustername <c>' on both VIOS; investigate the down node's repository-disk and SAN access before it becomes a client outage."
    else
      add resilience ssp_cluster "Shared Storage Pool cluster" PASS low "cluster + ${CLNODES} node(s) report OK" \
          "The Shared Storage Pool / CAA cluster and its nodes report OK — the shared pool backing client disks is healthy on this VIOS's view." "n/a"
    fi
  fi
}

# ---- --flrt-export: PJ-style FLRT Vulnerability Checker upload files -------------------
# Mirrors PJ's FLRT.report: emit the two inputs IBM's FLRT VC consumes — the full colon
# fileset inventory ('lslpp -Lcq' == our 'lslpp -qcL') and the ifix inventory
# ('emgr -lv3') — to timestamped files the admin uploads at esupport.ibm.com/.../flrt/vc.
# Read-only: writes ONLY into <dir> on this box, reads nothing it does not already read.
# Filenames follow FLRT.report: <epoch>_<host>_<oslevel>_<date>.{lslpp,emgr}.txt
if [ -n "$FLRT_EXPORT" ]; then
  if ! mkdir -p "$FLRT_EXPORT" 2>/dev/null; then
    echo "aixray: --flrt-export: cannot create directory '$FLRT_EXPORT'" >&2; exit 2
  fi
  FLRT_EPOCH=$(date +%s 2>/dev/null); [ -n "$FLRT_EPOCH" ] || FLRT_EPOCH=0
  FLRT_DATE=$(echo "$TODAY" | tr -d ' ')
  FLRT_HOST=$(printf '%s' "${HOST%%.*}" | tr -cd 'A-Za-z0-9_.-'); [ -n "$FLRT_HOST" ] || FLRT_HOST=unknown
  FLRT_OS=${OSLEVEL:-unknown}
  FLRT_BASE="${FLRT_EPOCH}_${FLRT_HOST}_${FLRT_OS}_${FLRT_DATE}"
  FLRT_LSLPP="$FLRT_EXPORT/$FLRT_BASE.lslpp.txt"
  FLRT_EMGR="$FLRT_EXPORT/$FLRT_BASE.emgr.txt"
  umask 077
  aix lslpp_qcL lslpp -qcL > "$FLRT_LSLPP" 2>/dev/null
  aix emgr_lv3 emgr -lv3   > "$FLRT_EMGR"  2>/dev/null
  FLRT_NL=$(awk 'END{print NR+0}' "$FLRT_LSLPP" 2>/dev/null)
  FLRT_NE=$(awk 'END{print NR+0}' "$FLRT_EMGR" 2>/dev/null)
  echo "aixray: FLRT export written to $FLRT_EXPORT/"
  echo "  $FLRT_BASE.lslpp.txt   ($FLRT_NL lines)  <- upload to IBM FLRT Vulnerability Checker"
  echo "  $FLRT_BASE.emgr.txt    ($FLRT_NE lines)  <- upload to IBM FLRT Vulnerability Checker"
  echo "  then: h""ttps://esupport.ibm.com/customercare/flrt/vc"
  exit 0
fi

progress 1 "lifecycle and support"
checks_lifecycle
progress 2 "patch and vulnerability currency"
checks_patch
progress 3 "storage and capacity"
checks_storage
progress 4 "performance and sizing"
checks_performance
progress 5 "errors and diagnostics"
checks_errors
progress 6 "availability and recovery"
checks_resilience
progress 7 "security and hardening"
checks_security
progress 8 "configuration hygiene"
checks_config
progress 9 "monitoring and operations"
checks_monitoring
if [ "$IS_VIOS" -eq 1 ]; then
  printf '[+] VIOS depth checks…\n' >&2
  checks_vios
fi

function cat_status { # <index> -> RED/AMBER/INCOMPLETE/GREEN
  # Believability review follow-up (2026-07-14): a category carrying NOT_ASSESSED
  # findings alongside an otherwise-clean PASS set previously fell straight through to
  # GREEN — CN (the not-assessed count) was never consulted here at all, even though
  # §62 finding #9 already established NOT_ASSESSED as its own status specifically so a
  # measurement gap could never silently read as "clean." INCOMPLETE is the SAME term
  # and the SAME RED > AMBER > INCOMPLETE > GREEN precedence docs/aixray-spec-v2.md's
  # §10.1.3 DISTILL pipeline already uses for this identical situation ("no new grade
  # names exist beyond John's model") — ported here so the v1 engine's own category
  # chip stops re-hiding exactly what that spec exists to keep visible. (INCOMPLETE's
  # exact visual/color treatment is flagged §10.1.4 "REQ: PENDING JOHN" in that same
  # spec; the chip styling here reuses the existing MUTE/not-assessed color as the
  # safest placeholder, not a final design call.)
  if   [ "${CF[$1]}" -gt 0 ]; then echo RED
  elif [ "${CW[$1]}" -gt 0 ]; then echo AMBER
  elif [ "${CN[$1]}" -gt 0 ]; then echo INCOMPLETE
  else echo GREEN; fi
}

# risk_of <status> <sev> -> Critical/High/Medium/Low (status x severity)
function risk_of {
  case "$1 $2" in
    "FAIL high") echo Critical;;
    "FAIL med"|"WARN high") echo High;;
    "FAIL low"|"WARN med") echo Medium;;
    *) echo Low;;
  esac
}

# ---- scoring --------------------------------------------------------------------------
TOTAL=$((PASS+WARN+FAIL))
if [ "$TOTAL" -gt 0 ]; then SCORE=$((PASS*100/TOTAL)); else SCORE=0; fi
# The executive message must reconcile field-for-field with findings[].severity.
# risk_of() above is a separate status-plus-severity RISK label used by the compliance
# renderer; applying it here would silently rename high -> critical and med -> high.
# Count the native finding vocabulary directly, including low if a low-severity FAIL is
# ever emitted, so this summary never invents or inflates a customer-facing tier.
NHIGH=0; NMED=0; NLOW=0
i=0
while [ "$i" -lt "$NFIND" ]; do
  if [ "${F_ST[$i]}" = "FAIL" ]; then
    case "${F_SEV[$i]}" in
      high) NHIGH=$((NHIGH+1));;
      med) NMED=$((NMED+1));;
      low) NLOW=$((NLOW+1));;
      *) ;; # add() emits only the contract vocabulary: high, med, low
    esac
  fi
  i=$((i+1))
done
# Believability review follow-up (2026-07-14): NASSESSED (the scan-wide NOT_ASSESSED
# count) was never consulted anywhere in this block -- a scan that was otherwise PASS
# but carried unassessed findings (missing/unreadable source data, §62 finding #9's own
# class) still rendered the bare GREEN "No issues detected in this snapshot." banner,
# an unqualified clean claim over content that was never actually looked at. Ported the
# SAME RED > AMBER > INCOMPLETE > GREEN precedence docs/aixray-spec-v2.md's DISTILL
# pipeline (§10.1.3) already uses for this identical situation, and every tier's own
# message now separately discloses the unassessed count whenever NASSESSED>0 -- a scan
# is never allowed to claim completeness (via its FAIL/WARN wording) while silently
# carrying gaps in what was actually measured, regardless of which tier it lands in.
NABIT=""
[ "$NASSESSED" -gt 0 ] && NABIT=" $NASSESSED area(s) not assessed."
if [ "$FAIL" -gt 0 ]; then
  BANNER="RED"
  FBITS=""
  [ "$NHIGH" -gt 0 ] && FBITS="$FBITS$NHIGH high, "
  [ "$NMED" -gt 0 ] && FBITS="$FBITS$NMED med, "
  [ "$NLOW" -gt 0 ] && FBITS="$FBITS$NLOW low, "
  FBITS=${FBITS%, }
  if [ -n "$FBITS" ]; then BMSG="$FAIL finding(s) need attention now ($FBITS).$NABIT"
  else BMSG="$FAIL finding(s) need attention now.$NABIT"; fi
elif [ "$WARN" -gt 0 ]; then
  BANNER="AMBER"; BMSG="$WARN item(s) to address.$NABIT"
elif [ "$NASSESSED" -gt 0 ]; then
  # No FAIL, no WARN -- but this is NOT "no issues detected": it's "nothing FOUND wrong
  # in what was assessed, and $NASSESSED area(s) were never assessed at all." Never the
  # unqualified GREEN claim over unassessed content.
  BANNER="INCOMPLETE"
  BMSG="No issues found in what was assessed, but $NASSESSED area(s) were not assessed -- review those before treating this as a clean scan."
else
  BANNER="GREEN"; BMSG="No issues detected in this snapshot."
fi

FLRTVC_HTML_META=""
if [ "${FV_PROVENANCE_REAL:-0}" = 1 ]; then
  FV_META_SOURCE_H=$(printf '%s' "$FLRTVC_DATA_SOURCE" | hesc)
  FV_META_VERSION_H=$(printf '%s' "${FLRTVC_DATA_VERSION:-unknown}" | hesc)
  FV_META_VINTAGE_H=$(printf '%s' "${FLRTVC_DATA_VINTAGE:-unknown}" | hesc)
  if [ -n "$FLRTVC_DATA_AGE" ]; then
    FV_META_AGE_H="$FLRTVC_DATA_AGE day(s) old"
  else
    FV_META_AGE_H="age unknown"
  fi
  FLRTVC_HTML_META=" &nbsp;·&nbsp; <b>FLRTVC data:</b> $FV_META_SOURCE_H · v$FV_META_VERSION_H · apar.csv $FV_META_VINTAGE_H ($FV_META_AGE_H)"
fi

HOST_H=$(printf '%s' "$HOST" | hesc)
PRINT_HOST=$(printf '%s\n' "$HOST" | awk 'NR==1{gsub(/[^A-Za-z0-9_.-]/,"_"); print; exit}')
[ -n "$PRINT_HOST" ] || PRINT_HOST=unknown
REPORT_HOST=$(printf '%s\n' "${HOST%%.*}" | awk 'NR==1{gsub(/[^A-Za-z0-9_.-]/,"_"); print; exit}')
[ -n "$REPORT_HOST" ] || REPORT_HOST=unknown
REPORT_DATE=$(printf '%s' "$TODAY" | tr -cd '0-9-')
[ -n "$REPORT_DATE" ] || REPORT_DATE=unknown-date

# ============================ RENDER ====================================================
# Resolve the curated numeric crosswalk against this run's actual evidence. A
# grouped STIG finding is evaluated per rule, then folded by control number:
# any failed source fails the control; otherwise an assessed source passes it.
# Unassessed/not-applicable sources emit no verdict, so missing evidence can
# never become an invented PASS. A fully assessed nfs_exports WARN concerns a
# writable/access restriction outside its mapped root-access check; a partial
# WARN emits no numeric verdict, and only confirmed unsafe evidence fails it.
function cis_l1_verdicts { # <finding-index> -> control|PASS-or-FAIL, one per line
  typeset CIS_INDEX CIS_DIRECT_STATUS
  CIS_INDEX=$1
  CIS_DIRECT_STATUS=${F_ST[$CIS_INDEX]}
  # A partial NFS WARN is actionable evidence, but it cannot prove the whole
  # mapped control passed while one of the two required evidence sources was
  # unreadable. Keep the action and omit the numeric verdict.
  if [ "${F_ID[$CIS_INDEX]}" = "nfs_exports" ] \
      && [ "$CIS_DIRECT_STATUS" = "WARN" ]; then
    case "${F_OBS[$CIS_INDEX]}" in
      "partially assessed —"*) CIS_DIRECT_STATUS=NOT_ASSESSED;;
    esac
  fi
  {
    printf '%s\n' "$cis_l1_map" | awk 'NF{print "M|" $0}'
    printf 'R|finding:%s|%s\n' "${F_ID[$CIS_INDEX]}" "$CIS_DIRECT_STATUS"
    if [ -n "${F_RULES[$CIS_INDEX]}" ]; then
      printf '%s\n' "${F_RULES[$CIS_INDEX]}" | awk 'NF{print "R|" $0}'
    fi
  } | awk -F'|' '
    $1=="M" {
      source=$2; control=$3; mapped[source]=control
      if(!(control in ordered)){ordered[control]=++n; controls[n]=control}
      next
    }
    $1=="R" {
      source=$2; status=$3
      if(!(source in mapped)) next
      control=mapped[source]
      if(status=="NA" || status=="NOT_ASSESSED" || status=="NOT_APPLICABLE") next
      if(source=="finding:nfs_exports" && status=="WARN") status="PASS"
      else if(status=="WARN") status="FAIL"
      if(status=="FAIL") verdict[control]="FAIL"
      else if(status=="PASS" && verdict[control]!="FAIL") verdict[control]="PASS"
    }
    END {
      for(i=1;i<=n;i++) if(controls[i] in verdict)
        print controls[i] "|" verdict[controls[i]]
    }
  '
}

function cis_l1_html { # <finding-index> -> escaped numeric verdicts separated by <br>
  typeset CIS_ROWS
  CIS_ROWS=$(cis_l1_verdicts "$1")
  if [ -z "$CIS_ROWS" ]; then
    printf '%s' '—'
  else
    printf '%s\n' "$CIS_ROWS" | awk -F'|' '
      NF>=2 {printf "%s%s %s", (n++?"<br>":""), $1, $2}
    '
  fi
}

function attr_hesc { # HTML attribute escaping for authored finding identifiers
  sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' \
      -e 's/"/\&quot;/g' -e "s/'/\&#39;/g"
}

if [ "$FORMAT" = "compliance" ]; then
  case "$COMPLIANCE" in
    stig)   STDLABEL="DISA STIG (IBM AIX 7.x)"; STDFULL="DISA STIG for IBM AIX 7.x"
            ATTRIB="Control mappings reference the DISA STIG for IBM AIX 7.x (public domain). This report indicates AIXray's read-only observations and is not a certified audit.";;
    cis-l1) STDLABEL="PowerTrue CIS L1 cross-check"; STDFULL="PowerTrue-authored CIS L1 numeric cross-check"
            ATTRIB="PowerTrue's cross-check uses control-number references and PowerTrue verdicts only; it is not a certified assessment.";;
    ffiec)  STDLABEL="FFIEC IT Handbook"; STDFULL="FFIEC IT Handbook alignment"
            ATTRIB="FFIEC alignment tags reference the public FFIEC IT Examination Handbook (public domain); they indicate coverage territory, not a certified examination. This report indicates AIXray's read-only observations and is not a certified audit.";;
  esac

  function ctl_match { # <index> -> space-separated control tags of $COMPLIANCE carried by finding
    typeset tok out; out=""
    for tok in ${F_CTL[$1]}; do
      case "$COMPLIANCE" in
        stig)   case "$tok" in stig:*)  out="$out $tok";; esac;;
        cis-l1) ;;
        ffiec)  case "$tok" in ffiec:*) out="$out $tok";; esac;;
      esac
    done
    if [ "$COMPLIANCE" = "cis-l1" ]; then
      cis_l1_verdicts "$1" | awk -F'|' 'NF>=2{printf "%s%s",(n++?" ":""),$1}'
    else
      echo $out
    fi
  }
  function chip_of { case "$1" in FAIL) echo RED;; WARN) echo AMBER;; NOT_ASSESSED|NOT_APPLICABLE) echo MUTE;; *) echo GREEN;; esac; }
  # rule-engine detail: concatenate every finding's F_RULES so a control tag that is a
  # rule id can be rendered as its OWN per-rule row (status + observed) instead of the
  # grouped worst-status finding row.
  ALLRULES=""
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    if [ -n "${F_RULES[$i]}" ]; then ALLRULES="$ALLRULES
${F_RULES[$i]}"; fi
    i=$((i+1))
  done
  function rule_lookup { # <tag> -> "status|observed" if the tag is a rule id, else empty
    printf '%s\n' "$ALLRULES" | awk -F'|' -v t="$1" '$1==t{print $2"|"$3; exit}'
  }
  function rulechip { case "$1" in FAIL) echo RED;; PASS) echo GREEN;; NA) echo MUTE;; *) echo AMBER;; esac; }
  function riskcls { case "$1" in Critical) echo crit;; High) echo high;; Medium) echo med;; *) echo low;; esac; }
  function catlbl_of { # <catid> -> display label
    typeset k; k=0
    while [ "$k" -lt 9 ]; do
      [ "${CAT_ID[$k]}" = "$1" ] && { echo "${CAT_LBL[$k]}"; return; }
      k=$((k+1))
    done
  }

  # coverage count + distinct control tags of the chosen standard
  NMAP=0; CTAGS=""
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    M=$(ctl_match $i)
    if [ -n "$M" ]; then
      NMAP=$((NMAP+1))
      for tok in $M; do
        case " $CTAGS " in *" $tok "*) ;; *) CTAGS="$CTAGS $tok";; esac
      done
    fi
    i=$((i+1))
  done

  # (c) auditor summary — one row per distinct control tag; non-PASS first
  AR_NP=""; AR_P=""
  for t in $CTAGS; do
    # rule-engine control tag: render ONE row per rule with its own status + observed,
    # sourced from the finding's per-rule detail rather than the grouped worst status.
    rl=""
    [ "$COMPLIANCE" != "cis-l1" ] && rl=$(rule_lookup "$t")
    if [ -n "$rl" ]; then
      rst=${rl%%"|"*}; robs=${rl#*"|"}; rlbl=""
      i=0
      while [ "$i" -lt "$NFIND" ]; do
        case " ${F_CTL[$i]} " in *" $t "*) rlbl=$(printf '%s' "${F_LBL[$i]}"|hesc); break;; esac
        i=$((i+1))
      done
      row="<tr><td class=\"obs\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\">$rlbl</td><td><span class=\"chip $(rulechip "$rst")\">$rst</span></td><td class=\"obs\">$(printf '%s' "$robs"|hesc)</td></tr>"
      if [ "$rst" = "FAIL" ]; then AR_NP="$AR_NP$row"; else AR_P="$AR_P$row"; fi
      continue
    fi
    worst=PASS; labels=""; obs=""; nmapped=0; nneedroot=0; nnotassessed=0; nnotapplicable=0
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      for tok in $(ctl_match $i); do
        if [ "$tok" = "$t" ]; then
          if [ "$COMPLIANCE" = "cis-l1" ]; then
            mapped_status=$(cis_l1_verdicts "$i" | awk -F'|' -v c="$t" '$1==c{print $2; exit}')
            [ -n "$mapped_status" ] || continue
          else
            mapped_status=${F_ST[$i]}
          fi
          labels="$labels${labels:+<br>}$(printf '%s' "${F_LBL[$i]}"|hesc)"
          obs="$obs${obs:+<br>}$(printf '%s' "${F_OBS[$i]}"|hesc)"
          nmapped=$((nmapped+1))
          # need-root WARN: observed "n/a" and meaning explicitly says it needs root
          if [ "$mapped_status" = "WARN" ] && [ "${F_OBS[$i]}" = "n/a" ]; then
            case "${F_MEAN[$i]}" in *"needs root"*) nneedroot=$((nneedroot+1));; esac
          fi
          # a literal NOT_ASSESSED finding must count the same way (§62 finding #9's
          # class): it must never silently leave `worst` at its PASS default just
          # because NOT_ASSESSED matches neither the FAIL nor WARN case below.
          [ "$mapped_status" = "NOT_ASSESSED" ] && nnotassessed=$((nnotassessed+1))
          [ "$mapped_status" = "NOT_APPLICABLE" ] && nnotapplicable=$((nnotapplicable+1))
          case "$mapped_status" in
            FAIL) worst=FAIL;;
            WARN) [ "$worst" != "FAIL" ] && worst=WARN;;
            NOT_ASSESSED)
              # Believability review follow-up (2026-07-14, Codex confirming review,
              # HIGH): a control mapped to a MIX of PASS and NOT_ASSESSED findings
              # (not ALL not-assessed, which the dedicated row below already catches)
              # previously left `worst` at its PASS default -- NOT_ASSESSED matched
              # neither the FAIL nor WARN case, so a control with, say, one PASS and
              # one NOT_ASSESSED finding rendered a plain PASS row, the exact
              # re-hidden-NOT_ASSESSED class this whole review exists to close, just
              # in this THIRD rendering path (compliance auditor rows) instead of
              # cat_status/BANNER. Never downgrades a real FAIL/WARN already recorded.
              case "$worst" in FAIL|WARN) ;; *) worst=NOT_ASSESSED;; esac
              ;;
            NOT_APPLICABLE)
              # An NA lifecycle check is assessed evidence, but it is not a PASS.
              # Preserve a real adverse/unreadable result from another mapped check.
              case "$worst" in FAIL|WARN|NOT_ASSESSED) ;; *) worst=NOT_APPLICABLE;; esac
              ;;
          esac
        fi
      done
      i=$((i+1))
    done
    if [ "$nmapped" -gt 0 ] && [ $((nneedroot+nnotassessed)) -eq "$nmapped" ]; then
      # every mapped finding is either an unassessed need-root WARN or a literal
      # NOT_ASSESSED — an examiner must see NOT ASSESSED (never a WARN that reads as a
      # finding, and never a silently-defaulted PASS).
      row="<tr><td class=\"obs\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\">$labels</td><td><span class=\"chip MUTE\">NOT ASSESSED</span></td><td class=\"obs\">$obs</td></tr>"
      AR_NP="$AR_NP$row"
    elif [ "$nmapped" -gt 0 ] && [ "$nnotapplicable" -eq "$nmapped" ]; then
      row="<tr><td class=\"obs\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\">$labels</td><td><span class=\"chip MUTE\">NOT APPLICABLE</span></td><td class=\"obs\">$obs</td></tr>"
      AR_NP="$AR_NP$row"
    else
      ch=$(chip_of "$worst")
      # display text: "NOT ASSESSED" (with space) for the mixed-NOT_ASSESSED case,
      # matching the dedicated all-unassessed row's own wording above -- never the
      # raw internal "NOT_ASSESSED" token.
      wlbl=$worst; [ "$worst" = "NOT_ASSESSED" ] && wlbl="NOT ASSESSED"
      [ "$worst" = "NOT_APPLICABLE" ] && wlbl="NOT APPLICABLE"
      row="<tr><td class=\"obs\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\">$labels</td><td><span class=\"chip $ch\">$wlbl</span></td><td class=\"obs\">$obs</td></tr>"
      if [ "$worst" = "PASS" ]; then AR_P="$AR_P$row"; else AR_NP="$AR_NP$row"; fi
    fi
  done
  AUDITROWS="$AR_NP$AR_P"
  [ -z "$AUDITROWS" ] && AUDITROWS="<tr><td colspan=\"4\">No findings carry a $STDLABEL control tag in this scan.</td></tr>"

  # (d) critical-first queue — Critical then High across every category
  CQ=""
  for want in Critical High; do
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      rk=$(risk_of "${F_ST[$i]}" "${F_SEV[$i]}")
      if [ "$rk" = "$want" ]; then
        CQ="$CQ<tr><td><span class=\"risk $(riskcls "$rk")\">$rk</span></td><td>$(catlbl_of "${F_CAT[$i]}"|hesc)</td><td class=\"ctl\">$(printf '%s' "${F_LBL[$i]}"|hesc)</td><td class=\"obs\">$(printf '%s' "${F_OBS[$i]}"|hesc)</td></tr>"
      fi
      i=$((i+1))
    done
  done
  [ -z "$CQ" ] && CQ="<tr><td colspan=\"4\">No Critical or High risk items in this scan.</td></tr>"

  # (d) remediation worklist — every non-PASS finding grouped by category in display order
  WL=""
  ci=0
  while [ "$ci" -lt 9 ]; do
    seg=""
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      if [ "${F_CAT[$i]}" = "${CAT_ID[$ci]}" ] &&
         [ "${F_ST[$i]}" != "PASS" ] && [ "${F_ST[$i]}" != "NOT_APPLICABLE" ]; then
        rk=$(risk_of "${F_ST[$i]}" "${F_SEV[$i]}")
        tg=""
        if [ "$COMPLIANCE" = "cis-l1" ]; then
          tg=$(cis_l1_verdicts "$i" | awk -F'|' 'NF>=2{printf "%s%s %s",(n++?", ":""),$1,$2}')
        else
          for tok in ${F_CTL[$i]}; do tg="$tg${tg:+, }$tok"; done
        fi
        [ -z "$tg" ] && tg="—"
        seg="$seg<tr class=\"${F_ST[$i]}\"><td><span class=\"risk $(riskcls "$rk")\">$rk</span></td>"
        seg="$seg<td class=\"ctl\">$(printf '%s' "${F_LBL[$i]}"|hesc)</td><td class=\"obs\">$(printf '%s' "${F_OBS[$i]}"|hesc)</td>"
        seg="$seg<td>$(printf '%s' "${F_MEAN[$i]}"|hesc)<div class=\"fix\">Fix: $(printf '%s' "${F_FIX[$i]}"|hesc)</div></td>"
        seg="$seg<td class=\"obs\">$(printf '%s' "$tg"|hesc)</td></tr>"
      fi
      i=$((i+1))
    done
    if [ -n "$seg" ]; then
      WL="$WL<div class=\"cathead\"><span class=\"cl\">$(catlbl_of "${CAT_ID[$ci]}"|hesc)</span></div>"
      WL="$WL<table><thead><tr><th>Risk</th><th>Finding</th><th>Observed</th><th>What it means &amp; how to fix</th><th>Control tags</th></tr></thead><tbody>$seg</tbody></table>"
    fi
    ci=$((ci+1))
  done
  [ -z "$WL" ] && WL="<p class=\"none\">No open findings — every check passed in this scan.</p>"

  cat <<HTML
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>AIXray compliance — ${STDLABEL} — ${HOST_H}</title>
<style>
@font-face{font-family:'Plex Sans';src:url(data:font/woff2;base64,${report_font_plex_sans_variable_b64}) format('woff2');font-weight:300 700;font-display:swap}
@font-face{font-family:'Plex Serif';src:url(data:font/woff2;base64,${report_font_plex_serif_semibold_b64}) format('woff2');font-weight:600;font-display:swap}
@font-face{font-family:'Plex Serif';src:url(data:font/woff2;base64,${report_font_plex_serif_medium_b64}) format('woff2');font-weight:500;font-display:swap}
@font-face{font-family:'Plex Mono';src:url(data:font/woff2;base64,${report_font_plex_mono_regular_b64}) format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'Plex Mono';src:url(data:font/woff2;base64,${report_font_plex_mono_medium_b64}) format('woff2');font-weight:500;font-display:swap}
:root{
  --slate:#1B1F24; --slate2:#23272E; --slate3:#2B3038;
  --ink:#23272E; --body:#5C5F63; --mute:#8A929B;
  --cream:#F4F2EE; --line:#E2DDD5; --bg:#ffffff;
  --copper:#C2703D; --copper-d:#A85A2C; --copper-l:#D98A5A;
  --red:#B23A2C; --amber:#A9781A; --green:#2E7D52; --na:#8A929B;
  --red-t:#f7ece9; --amber-t:#f7f1e6; --green-t:#eef4ef; --na-t:#f1f1ef;
  --sans:'Plex Sans',-apple-system,system-ui,sans-serif;
  --serif:'Plex Serif',Georgia,serif;
  --mono:'Plex Mono',ui-monospace,Menlo,monospace;
}
@media (prefers-color-scheme:dark){:root{
  --slate:#0e1114; --slate2:#161a1f; --slate3:#1e242b; --ink:#eef0f2; --body:#b7bcc2; --mute:#8A929B;
  --cream:#191d22; --line:#2a3037; --bg:#111418;
  --red:#d6584a; --amber:#c99436; --green:#46a578; --na:#8a929b;
  --red-t:#20140f; --amber-t:#1f1810; --green-t:#0f1e16; --na-t:#181b1f;
}}
:root[data-theme="dark"]{--slate:#0e1114;--slate2:#161a1f;--slate3:#1e242b;--ink:#eef0f2;--body:#b7bcc2;--mute:#8A929B;--cream:#191d22;--line:#2a3037;--bg:#111418;--red:#d6584a;--amber:#c99436;--green:#46a578;--na:#8a929b;--red-t:#20140f;--amber-t:#1f1810;--green-t:#0f1e16;--na-t:#181b1f}
:root[data-theme="light"]{--slate:#1B1F24;--slate2:#23272E;--slate3:#2B3038;--ink:#23272E;--body:#5C5F63;--mute:#8A929B;--cream:#F4F2EE;--line:#E2DDD5;--bg:#ffffff;--red:#B23A2C;--amber:#A9781A;--green:#2E7D52;--na:#8A929B;--red-t:#f7ece9;--amber-t:#f7f1e6;--green-t:#eef4ef;--na-t:#f1f1ef}

*{box-sizing:border-box;border-radius:0}
html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{margin:0;background:var(--bg);color:var(--body);font-family:var(--sans);font-size:13.5px;line-height:1.55;-webkit-font-smoothing:antialiased;max-width:940px;margin-inline:auto}
b{color:var(--ink);font-weight:600}

.band{position:relative;background:var(--slate);color:#fff;padding:32px 40px 26px;overflow:hidden}
.band::before{content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;background-image:linear-gradient(color-mix(in srgb,var(--copper) 12%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--copper) 12%,transparent) 1px,transparent 1px);background-size:26px 26px;mask-image:linear-gradient(120deg,#000,transparent 78%)}
.band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--copper)}
.band>*{position:relative}
.wm{font-family:var(--serif);font-size:27px;font-weight:600;color:#fff;line-height:1;letter-spacing:-.2px}
.tag{display:block;font-family:var(--mono);font-size:10px;letter-spacing:2.4px;color:#9aa2ab;text-transform:uppercase;margin-top:10px}
.ey{font-family:var(--mono);font-size:10.5px;letter-spacing:3px;text-transform:uppercase;color:var(--copper-l);margin-top:20px;font-weight:500}
h1{font-family:var(--serif);color:#fff;font-size:23px;font-weight:600;margin:7px 0 0;letter-spacing:-.2px;text-wrap:balance}
h2{font-family:var(--serif);color:var(--ink);font-size:15.5px;font-weight:600;margin:30px 40px 0;padding:0 0 8px;border-bottom:2px solid var(--ink)}
h2 .sub{font-family:var(--mono);font-size:9.5px;letter-spacing:1px;color:var(--mute);text-transform:uppercase;font-weight:500}

.meta{padding:13px 40px;background:var(--cream);border-bottom:1px solid var(--line);font-family:var(--mono);font-size:11px;color:var(--mute);display:flex;flex-wrap:wrap;gap:5px 4px;align-items:center}
.meta b{color:var(--ink)}
.ro{display:inline-block;background:var(--bg);color:var(--green);font-family:var(--mono);font-size:10px;font-weight:600;padding:2px 9px;letter-spacing:.5px;border:1px solid color-mix(in srgb,var(--green) 40%,var(--line))}
.cov{margin:18px 40px;padding:14px 16px;background:var(--cream);border-left:3px solid var(--copper);font-size:12px;color:var(--ink)}
.cov b{color:var(--ink)}

.cathead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin:30px 40px 0;padding:0 0 8px;border-bottom:2px solid var(--ink)}
.cathead .cl{font-family:var(--serif);font-size:15.5px;color:var(--ink);font-weight:600}
.cathead .cr{display:flex;align-items:center;gap:10px}
.cathead .cnt{font-family:var(--mono);font-size:10.5px;color:var(--mute);font-variant-numeric:tabular-nums}
.chip{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.8px;padding:3px 9px;color:#fff;text-transform:uppercase}
.chip.RED{background:var(--red)}.chip.AMBER{background:var(--amber)}.chip.GREEN{background:var(--green)}.chip.INCOMPLETE,.chip.MUTE{background:var(--na)}
.risk{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.5px;padding:3px 8px;color:#fff;display:inline-block;white-space:nowrap;text-transform:uppercase}
.risk.crit,.risk.high{background:var(--red)}.risk.med{background:var(--amber)}.risk.low{background:var(--na)}

table{width:calc(100% - 80px);margin:2px 40px 6px;border-collapse:separate;border-spacing:0;font-size:12.5px}
thead th{color:var(--mute);font-family:var(--mono);font-size:9.5px;letter-spacing:1.1px;text-transform:uppercase;text-align:left;font-weight:600;padding:10px 12px 7px;border-bottom:1px solid var(--line)}
td{padding:11px 12px;border-bottom:1px solid var(--line);vertical-align:top}
td.ctl{font-weight:600;color:var(--ink);width:19%}
td.st{font-family:var(--mono);font-weight:600;width:7%;font-size:10px}
td.st.PASS{color:var(--green)}td.st.WARN{color:var(--amber)}td.st.FAIL{color:var(--red)}td.st.NOT_ASSESSED,td.st.NOT_APPLICABLE{color:var(--na)}
td.sev{font-family:var(--mono);color:var(--mute);text-transform:uppercase;font-size:9.5px;width:6%;letter-spacing:.4px}
td.obs{font-family:var(--mono);font-size:11px;color:var(--ink);width:20%;word-break:break-word}
tr.FAIL td:first-child{box-shadow:inset 4px 0 var(--red)}
tr.WARN td:first-child{box-shadow:inset 4px 0 var(--amber)}
tr.PASS td:first-child{box-shadow:inset 4px 0 color-mix(in srgb,var(--green) 55%,transparent)}
tr.NOT_ASSESSED td:first-child{box-shadow:inset 4px 0 var(--na)}
tr.NOT_APPLICABLE td:first-child{box-shadow:inset 4px 0 var(--na)}
tr.FAIL{background:var(--red-t)}tr.WARN{background:var(--amber-t)}tr.NOT_ASSESSED,tr.NOT_APPLICABLE{background:var(--na-t)}
.fix{margin-top:5px;color:var(--body);font-size:11px;line-height:1.5;padding-left:11px;border-left:2px solid var(--copper)}
.fix::before{content:"→ ";color:var(--copper-d);font-weight:700}

.manual{margin:6px 40px 10px;font-size:12px;color:var(--body)}.manual li{margin:6px 0}.manual b{color:var(--ink)}
.none{margin:10px 40px;color:var(--green);font-size:12px}
.attrib{margin:22px 40px 0;padding:12px 16px;background:var(--cream);border-left:3px solid var(--na);font-size:11px;color:var(--body)}
footer{margin:26px 40px 34px;padding:15px 0 0;border-top:2px solid var(--copper);font-family:var(--mono);font-size:10px;letter-spacing:.4px;color:var(--mute);display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
footer b,footer a{color:var(--copper-d)}

@media print{
  @page{
    margin:18mm 12mm 18mm;
    @top-left{content:"AIXray · ${PRINT_HOST}";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @top-right{content:"${REPORT_DATE}";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @bottom-left{content:"PowerTrue Systems";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @bottom-right{content:"Page " counter(page) " of " counter(pages);font-family:var(--mono);font-size:8pt;color:#5C5F63}
  }
  :root,:root[data-theme="dark"],:root[data-theme="light"]{
    --slate:#1B1F24;--slate2:#23272E;--slate3:#2B3038;
    --ink:#23272E;--body:#5C5F63;--mute:#6B7280;
    --cream:#F4F2EE;--line:#D8D3CB;--bg:#ffffff;
    --red:#9F2F23;--amber:#805B12;--green:#236641;--na:#666E78;
    --red-t:#F7ECE9;--amber-t:#F7F1E6;--green-t:#EEF4EF;--na-t:#F1F1EF;
  }
  html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
  body{max-width:none;background:#fff;color:var(--body);font-size:10pt;line-height:1.4}
  .band::before{display:none}
  .band,.meta,.score,.banner,.scorebox,.cov,.attrib,footer,li{break-inside:avoid;page-break-inside:avoid}
  h2,.cathead{break-after:avoid-page;page-break-after:avoid}
