</style></head><body>
<div class="band"><div class="wm">AIXray<div class="tag">by PowerTrue Systems · AIX · IBM Power · VIOS</div></div><div class="ey">Compliance report</div><h1>Compliance report — ${STDLABEL} — ${HOST_H}</h1></div>
<div class="meta"><b>Host:</b> ${HOST_H} &nbsp;·&nbsp; <b>Generated:</b> ${NOW} &nbsp;·&nbsp; <b>Reference data:</b> ${DATA_VINTAGE}${FLRTVC_HTML_META} &nbsp;·&nbsp; <b>Standard:</b> ${STDFULL} &nbsp;·&nbsp; <span class="ro">READ-ONLY — nothing was changed</span></div>
<div class="cov"><b>Automation coverage.</b> AIXray automates ${NMAP} finding(s) mapped to this standard. A compliance program also requires manual/organizational review — see the manual-review section below. N is the count of findings carrying a ${STDLABEL} control tag in this scan; no full control-set total is claimed.</div>
<h2>Auditor control summary <span class="sub">one row per mapped control · non-pass first</span></h2>
<table><thead><tr><th>Control</th><th>Mapped finding(s)</th><th>Status</th><th>Observed evidence</th></tr></thead><tbody>${AUDITROWS}</tbody></table>
<h2>Critical-first queue <span class="sub">Critical then High risk · work top-down</span></h2>
<table><thead><tr><th>Risk</th><th>Category</th><th>Finding</th><th>Observed</th></tr></thead><tbody>${CQ}</tbody></table>
<h2>Remediation worklist <span class="sub">every open finding, grouped by category</span></h2>
${WL}
<h2>Manual review <span class="sub">outside the tool's read-only view</span></h2>
<ul class="manual">
<li><b>HMC currency &amp; config</b> — HMC firmware level and managed-system settings need HMC access; this tool runs inside the LPAR and cannot see the HMC.</li>
<li><b>SWMA / hardware maintenance entitlement</b> — software-maintenance and warranty coverage live in IBM's entitlement systems, not on the box.</li>
<li><b>DR / replication evidence</b> — an offsite/recovery story (failover site, replicated storage, tested runbook) is an organizational fact the tool cannot observe locally.</li>
<li><b>Documented runbook &amp; alerting ownership</b> — who gets paged, and the written procedure they follow, are process artifacts, not system state.</li>
<li><b>Physical &amp; organizational controls</b> — data-center access, change control, separation of duties and staff training are program-level controls no host scan can measure.</li>
</ul>
<div class="attrib">${ATTRIB}</div>
<footer><span>AIXray · by PowerTrue Systems · read-only · this report is yours to keep</span><a href="mailto:review@powertruesystems.com">${REVIEW_CTA}</a></footer>
</body></html>
HTML
  REPORT_RC=$?
  if [ "$REPORT_RC" -eq 0 ]; then
    finish_report
    exit 0
  fi
  exit "$REPORT_RC"
fi

function prepare_facts {
  # identity
  FACT_ID_UNREAD=""; FACT_ID_NA=""
  [ -z "$FACT_FRAME_SERIAL" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD frame_serial"
  [ -z "$FACT_PARTITION_ID" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD partition_id"
  [ -z "$FACT_PARTITION_NAME" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD partition_name"
  [ -z "$UC_MODEL" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD machine_type"
  if [ -n "$FACT_ID_UNREAD" ]; then FACT_ID_BASIS=partial; else FACT_ID_BASIS=observed; fi

  # os
  FACT_OS_UNREAD=""; FACT_OS_NA=""
  [ -z "$OSLEVEL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD oslevel_s"
  [ -z "$REL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD release"
  [ -z "$FACT_OS_TL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD tl"
  [ -z "$FACT_OS_SP" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD sp"
  [ -z "$BWEEK" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD build_week"
  [ -z "$FACT_OS_EOS" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD eos_date"
  [ -z "$FACT_OS_EOSPS" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD eosps_date"
  [ -z "$UC_LATEST" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD tl_latest"
  case "$ROLE" in
    vios) [ -z "$UC_IOSL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD vios_level";;
    aix) FACT_OS_NA="$FACT_OS_NA vios_level";;
    *) FACT_OS_UNREAD="$FACT_OS_UNREAD vios_level";;
  esac
  FACT_OS_BASIS=observed
  if [ -n "$FACT_OS_UNREAD" ]; then
    FACT_OS_BASIS=partial
    if [ "$FACT_OS_SOURCE_READ" -eq 0 ]; then
      if [ "$ROLE" != vios ] || [ -z "$UC_IOSL" ]; then FACT_OS_BASIS=not_assessed; fi
    fi
  fi

  # firmware / hardware lifecycle
  FACT_FW_UNREAD=""; FACT_FW_NA=""
  [ -z "$UC_FW" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD level"
  [ -z "$UC_FWFAM" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD family"
  [ -z "$FACT_HW_GEN" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD hw_generation"
  [ -z "$FACT_HW_EOS" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD hw_eos_date"
  case "$FACT_FW_UAK_EXPIRY" in
    '') FACT_FW_UNREAD="$FACT_FW_UNREAD firmware_uak_expiry";;
    NOT_APPLICABLE) FACT_FW_NA="$FACT_FW_NA firmware_uak_expiry";;
  esac
  case "$FACT_AIX_UAK_EXPIRY" in
    '') FACT_FW_UNREAD="$FACT_FW_UNREAD aix_uak_expiry";;
    NOT_APPLICABLE) FACT_FW_NA="$FACT_FW_NA aix_uak_expiry";;
  esac
  FACT_FW_BASIS=observed
  if [ -n "$FACT_FW_UNREAD" ]; then
    FACT_FW_BASIS=partial
    if [ -z "$UC_FW" ] && [ -z "$UC_FWFAM" ] && [ -z "$UC_MODEL" ]; then FACT_FW_BASIS=not_assessed; fi
  fi

  # capacity.cpu. Applicability is decided only after mode/capping is known.
  FACT_CPU_UNREAD=""; FACT_CPU_NA=""
  FACT_CPU_ENT_OUT="$FACT_CPU_ENT"; FACT_CPU_WEIGHT_OUT="$FACT_CPU_WEIGHT"; FACT_CPU_ENTC_OUT="$FACT_CPU_ENTC"
  [ -z "$FACT_CPU_MODE" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD mode"
  [ -z "$FACT_CPU_CAPPED" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD capped"
  if [ "$FACT_CPU_MODE" = dedicated ]; then
    FACT_CPU_ENT_OUT=""; FACT_CPU_WEIGHT_OUT=""; FACT_CPU_ENTC_OUT=""
    FACT_CPU_NA="$FACT_CPU_NA entitled_capacity variable_weight entc_pct"
  else
    [ -z "$FACT_CPU_ENT_OUT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD entitled_capacity"
    if [ "$FACT_CPU_CAPPED" = true ]; then
      FACT_CPU_WEIGHT_OUT=""; FACT_CPU_NA="$FACT_CPU_NA variable_weight"
    else
      [ -z "$FACT_CPU_WEIGHT_OUT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD variable_weight"
    fi
    [ -z "$FACT_CPU_ENTC_OUT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD entc_pct"
  fi
  [ -z "$FACT_CPU_OVP" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD online_vcpus"
  [ -z "$FACT_CPU_SMT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD smt"
  [ -z "$FACT_CPU_PHYSC" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD physc"
  [ -z "$FACT_CPU_IDLE" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD idle_pct"
  FACT_CPU_BASIS=observed
  if [ "$FACT_CPU_LPI_READ" -eq 0 ] && [ "$FACT_CPU_SAMPLE_READ" -eq 0 ]; then
    FACT_CPU_BASIS=not_assessed
  elif [ -n "$FACT_CPU_UNREAD" ]; then
    FACT_CPU_BASIS=partial
  fi

  # capacity.memory. svmon is the primary block read; when it is unavailable the
  # block is not assessed even if the independent vmstat percentages survived.
  FACT_MEM_UNREAD=""; FACT_MEM_NA=""
  [ -z "$FACT_MEM_TOTAL" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD total_mb"
  [ -z "$FACT_MEM_INUSE" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD inuse_mb"
  [ -z "$FACT_MEM_AVAILABLE" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD available_mb"
  [ -z "$FACT_MEM_PINNED" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD pinned_mb"
  [ -z "$FACT_MEM_COMP" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD computational_pct"
  [ -z "$FACT_MEM_NUMPERM" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD numperm_pct"
  if [ "$FACT_MEM_PRIMARY_READ" -eq 0 ]; then
    FACT_MEM_BASIS=not_assessed
  elif [ -n "$FACT_MEM_UNREAD" ]; then
    FACT_MEM_BASIS=partial
  else
    FACT_MEM_BASIS=observed
  fi

  # capacity.paging
  FACT_PAGING_UNREAD=""; FACT_PAGING_NA=""
  [ -z "$FACT_PAGING_SPACES" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD spaces"
  [ -z "$FACT_PAGING_MAX" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD max_used_pct"
  [ -z "$FACT_PAGING_ROOT" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD all_in_rootvg"
  [ -z "$FACT_PAGING_DUP" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD shares_pv"
  if [ "$FACT_PAGING_READ" -eq 0 ]; then
    FACT_PAGING_BASIS=not_assessed
  elif [ -n "$FACT_PAGING_UNREAD" ]; then
    FACT_PAGING_BASIS=partial
  else
    FACT_PAGING_BASIS=observed
  fi

  # capacity.storage
  FACT_STORAGE_UNREAD=""; FACT_STORAGE_NA=""
  if [ -z "$FACT_STORAGE_FS_ROWS" ]; then
    FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD filesystems worst_fs_used_pct worst_fs_mount max_inode_pct"
  else
    if [ -z "$FACT_STORAGE_WORST_FS_PCT" ] || [ -z "$FACT_STORAGE_WORST_FS_MOUNT" ]; then
      FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD worst_fs_used_pct worst_fs_mount"
    fi
    [ -z "$FACT_STORAGE_MAX_INODE" ] && FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD max_inode_pct"
  fi
  [ -z "$FACT_STORAGE_WORST_VG_PCT" ] && FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD worst_vg_free_pct"
  [ -z "$FACT_STORAGE_WORST_VG" ] && FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD worst_vg"
  if [ "$FACT_STORAGE_DF_READ" -eq 0 ] && [ "$FACT_STORAGE_VG_READ" -eq 0 ]; then
    FACT_STORAGE_BASIS=not_assessed
  elif [ -n "$FACT_STORAGE_UNREAD" ]; then
    FACT_STORAGE_BASIS=partial
  else
    FACT_STORAGE_BASIS=observed
  fi

  # The capacity-level envelope is an aggregate only. Nulls are disclosed once,
  # in their owning nested block, never duplicated here.
  FACT_CAP_UNREAD=""; FACT_CAP_NA=""
  if [ "$FACT_CPU_BASIS" = not_assessed ] && [ "$FACT_MEM_BASIS" = not_assessed ] &&
     [ "$FACT_PAGING_BASIS" = not_assessed ] && [ "$FACT_STORAGE_BASIS" = not_assessed ]; then
    FACT_CAP_BASIS=not_assessed
  elif [ "$FACT_CPU_BASIS" != observed ] || [ "$FACT_MEM_BASIS" != observed ] ||
       [ "$FACT_PAGING_BASIS" != observed ] || [ "$FACT_STORAGE_BASIS" != observed ]; then
    FACT_CAP_BASIS=partial
  else
    FACT_CAP_BASIS=observed
  fi

  # recovery
  FACT_REC_UNREAD=""; FACT_REC_NA=""; FACT_REC_POWERHA_OUT="$FACT_RECOVERY_POWERHA"
  [ -z "$FACT_RECOVERY_ALT" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD alt_disk_present"
  [ -z "$FACT_RECOVERY_MIRROR" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD rootvg_mirror"
  [ -z "$FACT_RECOVERY_MIRROR_DISKS" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD rootvg_mirror_disks"
  [ -z "$FACT_RECOVERY_BOOTLIST" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD bootlist_devices"
  [ -z "$FACT_RECOVERY_NIM" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD nim_client"
  if [ "$FACT_RECOVERY_POWERHA_APPLICABLE" = 0 ]; then
    FACT_REC_POWERHA_OUT=""; FACT_REC_NA="$FACT_REC_NA powerha_state"
  elif [ -z "$FACT_REC_POWERHA_OUT" ]; then
    FACT_REC_UNREAD="$FACT_REC_UNREAD powerha_state"
  fi
  if [ "$FACT_RECOVERY_MKSYSB" = unreadable ] || [ -n "$FACT_REC_UNREAD" ]; then
    FACT_REC_BASIS=partial
  else
    FACT_REC_BASIS=observed
  fi
}

# Emit one JSON member named "software" from the lslpp -qcL capture already
# held by the patch checks. This module defines the emitter only; the separate
# integration build owns the spine include and facts-emitter call.
function emit_fact_software {
  typeset SI_FILESET_LIMIT SI_WORKLOAD_LIMIT SI_EVIDENCE_LIMIT
  typeset SI_RC SI_CONFIRMED SI_AWK_RC

  SI_FILESET_LIMIT=${1:-1000}
  case "$SI_FILESET_LIMIT" in
    [1-9]|[1-9][0-9]|[1-9][0-9][0-9]|1000) ;;
    *) SI_FILESET_LIMIT=1000 ;;
  esac

  SI_WORKLOAD_LIMIT=${2:-100}
  case "$SI_WORKLOAD_LIMIT" in
    [1-9]|[1-9][0-9]|100) ;;
    *) SI_WORKLOAD_LIMIT=100 ;;
  esac

  SI_EVIDENCE_LIMIT=${3:-25}
  case "$SI_EVIDENCE_LIMIT" in
    [1-9]|1[0-9]|2[0-5]) ;;
    *) SI_EVIDENCE_LIMIT=25 ;;
  esac

  SI_RC=${LSLPPQ_RC:-}
  case "$SI_RC" in
    [0-9]|[0-9][0-9]|[0-9][0-9][0-9])
      SI_CONFIRMED=1
      SI_AWK_RC=$SI_RC
      ;;
    *)
      SI_CONFIRMED=0
      SI_AWK_RC=0
      ;;
  esac

  printf '%s\n' "${LSLPPQ:-}" | awk -F: \
    -v confirmed="$SI_CONFIRMED" -v capture_rc="$SI_AWK_RC" \
    -v max_rows="$SI_FILESET_LIMIT" \
    -v max_workloads="$SI_WORKLOAD_LIMIT" \
    -v max_evidence="$SI_EVIDENCE_LIMIT" '
    BEGIN {
      state_name["A"] = "APPLIED"
      state_name["B"] = "BROKEN"
      state_name["C"] = "COMMITTED"
      state_name["E"] = "EFIX_LOCKED"
      state_name["O"] = "OBSOLETE"
      state_name["?"] = "INCONSISTENT"

      classification_gap = "ISV/workload classification uses explicit IBM Java, Python, and Perl lpp_source/name-pair heuristics; every other fileset remains UNCLASSIFIED."
      unmanaged_gap = "Software not registered with lslpp -Lc is not assessed."
      business_gap = "Business criticality, active use, and workload coupling are not established by lslpp -Lc and remain NOT_ASSESSED."
      workload_gap = "Only package-managed IBM Java, Python, and Perl runtimes matched by explicit lpp_source/name-pair heuristics are normalized; package publisher/provenance remains NOT_ASSESSED, and absence does not prove that no other ISV or workload software exists."
    }

    function usable_field(value) {
      return value != "" && value !~ /[[:cntrl:]]/
    }

    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") {
          result = result "\\\\"
        } else if (character == "\"") {
          result = result "\\\""
        } else {
          result = result character
        }
      }
      return result
    }

    function remember_workload(product_id, product_name, category,
                               version, fileset, key, evidence_key, number) {
      key = product_id SUBSEP version
      if (!(key in workload_seen)) {
        workload_seen[key] = 1
        workload_order[++workload_count] = key
        workload_id[key] = product_id
        workload_name[key] = product_name
        workload_category[key] = category
        workload_version[key] = version
      }

      evidence_key = key SUBSEP fileset
      if (!(evidence_key in evidence_seen)) {
        evidence_seen[evidence_key] = 1
        number = ++workload_evidence_count[key]
        workload_evidence[key SUBSEP number] = fileset
      }
    }

    function classify(row, lpp_source, fileset, version, product_id) {
      product_id = ""
      if (lpp_source ~ /^Java[0-9_]+\.(jre|sdk)$/ &&
          fileset == lpp_source) {
        product_id = "ibm-java"
        remember_workload(product_id, "IBM Java", "runtime", version, fileset)
      } else if ((lpp_source ~ /^python[0-9]+$/ ||
                  lpp_source ~ /^python[0-9]+\.[0-9]+$/ ||
                  lpp_source ~ /^python[0-9]+\.[0-9]+\.base$/) &&
                 (fileset == lpp_source ||
                  index(fileset, lpp_source "-") == 1)) {
        product_id = "python"
        remember_workload(product_id, "Python", "runtime", version, fileset)
      } else if (lpp_source == "perl.rte" && fileset == lpp_source) {
        product_id = "perl"
        remember_workload(product_id, "Perl", "runtime", version, fileset)
      }

      if (product_id == "") {
        row_class[row] = "UNCLASSIFIED"
        row_product[row] = ""
      } else {
        row_class[row] = "WORKLOAD_RUNTIME"
        row_product[row] = product_id
      }
    }

    function emit_gaps() {
      printf "\"gaps\":[\"%s\",\"%s\",\"%s\"]", classification_gap, unmanaged_gap, business_gap
    }

    function emit_not_assessed(reason, rc_json) {
      printf "\"software\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"platform\":\"AIX\","
      printf "\"reason\":\"%s\",", reason
      printf "\"source\":{\"capture\":\"lslpp_qcL\",\"command\":\"lslpp -qcL\","
      printf "\"format\":\"lslpp -Lc colon-delimited (headings suppressed)\",\"rc\":%s},", rc_json

      printf "\"filesets\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"reason\":\"%s\",", reason
      printf "\"captured_count\":null,\"emitted_count\":null,"
      printf "\"invalid_row_count\":null,\"invalid_row_marker\":null,"
      printf "\"omitted_count\":null,\"truncated\":null,"
      printf "\"truncation_marker\":null,\"items\":null},"

      printf "\"isv_workloads\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"reason\":\"%s\",", reason
      printf "\"basis\":null,\"detected_count\":null,"
      printf "\"emitted_count\":null,\"omitted_count\":null,"
      printf "\"truncated\":null,\"truncation_marker\":null,\"items\":null,"
      printf "\"gap\":\"%s\"},", workload_gap
      emit_gaps()
      printf "}"
    }

    /^[ \t\r]*$/ { next }

    {
      saw_nonblank++
      if ($0 !~ /^[ \t]*#/ && NF >= 6 && usable_field($1) && usable_field($2) &&
          usable_field($3) && ($6 in state_name)) {
        row = ++valid_count
        row_lpp[row] = $1
        row_name[row] = $2
        row_version[row] = $3
        row_state_code[row] = $6
        row_state[row] = state_name[$6]
        if ($2 ~ /^bos\.rte(\.|$)/ && !($2 in bos_family_seen)) {
          bos_family_seen[$2] = 1
          bos_family_count++
        }
        classify(row, $1, $2, $3)
      } else {
        invalid_count++
      }
    }

    END {
      if (!confirmed) {
        emit_not_assessed("lslpp -qcL capture return code was not confirmed",
                          "null")
        exit
      }
      if ((capture_rc + 0) != 0) {
        reason = "lslpp -qcL capture failed (rc=" (capture_rc + 0) ")"
        emit_not_assessed(reason, capture_rc + 0)
        exit
      }
      if (valid_count == 0) {
        if (saw_nonblank == 0) {
          reason = "lslpp -qcL capture was empty"
        } else {
          reason = "lslpp -qcL capture had no structurally valid rows (" invalid_count " malformed)"
        }
        emit_not_assessed(reason, "0")
        exit
      }
      if (valid_count < 50 || bos_family_count < 3) {
        reason = "lslpp -qcL capture was implausibly small (" valid_count " structurally valid rows; minimum 50, " (bos_family_count + 0) " distinct bos.rte filesets)"
        emit_not_assessed(reason, "0")
        exit
      }

      emitted_count = valid_count
      if (emitted_count > max_rows) emitted_count = max_rows
      omitted_count = valid_count - emitted_count
      fileset_status = "COMPLETE"
      if (invalid_count > 0 || omitted_count > 0) fileset_status = "PARTIAL"

      fileset_reason = "null"
      if (invalid_count > 0 && omitted_count > 0) {
        fileset_reason = "\"capture contained " invalid_count " malformed rows and output omitted " omitted_count " valid rows\""
      } else if (invalid_count > 0) {
        fileset_reason = "\"capture contained " invalid_count " malformed rows\""
      } else if (omitted_count > 0) {
        fileset_reason = "\"output bounded at " emitted_count " of " valid_count " valid rows\""
      }

      printf "\"software\":{"
      printf "\"status\":\"PARTIAL\",\"platform\":\"AIX\",\"reason\":null,"
      printf "\"source\":{\"capture\":\"lslpp_qcL\",\"command\":\"lslpp -qcL\","
      printf "\"format\":\"lslpp -Lc colon-delimited (headings suppressed)\",\"rc\":0},"

      printf "\"filesets\":{"
      printf "\"status\":\"%s\",\"reason\":%s,", fileset_status, fileset_reason
      printf "\"captured_count\":%d,\"emitted_count\":%d,", valid_count, emitted_count
      printf "\"invalid_row_count\":%d,", invalid_count
      if (invalid_count > 0) {
        if (invalid_count == 1) {
          printf "\"invalid_row_marker\":\"1 malformed row not emitted\","
        } else {
          printf "\"invalid_row_marker\":\"%d malformed rows not emitted\",", invalid_count
        }
      } else {
        printf "\"invalid_row_marker\":null,"
      }
      printf "\"omitted_count\":%d,", omitted_count
      if (omitted_count > 0) {
        printf "\"truncated\":true,"
        if (omitted_count == 1) {
          printf "\"truncation_marker\":\"1 more fileset not emitted (limit %d)\",", max_rows
        } else {
          printf "\"truncation_marker\":\"%d more filesets not emitted (limit %d)\",", omitted_count, max_rows
        }
      } else {
        printf "\"truncated\":false,\"truncation_marker\":null,"
      }

      printf "\"items\":["
      for (row = 1; row <= emitted_count; row++) {
        if (row > 1) printf ","
        printf "{\"lpp_source\":\"%s\",\"name\":\"%s\",", json_escape(row_lpp[row]), json_escape(row_name[row])
        printf "\"version\":\"%s\",\"state_code\":\"%s\",", json_escape(row_version[row]), row_state_code[row]
        printf "\"state\":\"%s\",\"classification\":\"%s\",", row_state[row], row_class[row]
        if (row_product[row] == "") {
          printf "\"normalized_product_id\":null}"
        } else {
          printf "\"normalized_product_id\":\"%s\"}", row_product[row]
        }
      }
      printf "]},"

      printf "\"isv_workloads\":{"
      printf "\"status\":\"PARTIAL\",\"reason\":null,"
      printf "\"basis\":\"package_name_pair_heuristics\","
      workload_emitted = workload_count
      if (workload_emitted > max_workloads) workload_emitted = max_workloads
      workload_omitted = workload_count - workload_emitted
      printf "\"detected_count\":%d,\"emitted_count\":%d,", workload_count, workload_emitted
      printf "\"omitted_count\":%d,", workload_omitted
      if (workload_omitted > 0) {
        printf "\"truncated\":true,"
        if (workload_omitted == 1) {
          printf "\"truncation_marker\":\"1 more workload product not emitted (limit %d)\",", max_workloads
        } else {
          printf "\"truncation_marker\":\"%d more workload products not emitted (limit %d)\",", workload_omitted, max_workloads
        }
      } else {
        printf "\"truncated\":false,\"truncation_marker\":null,"
      }
      printf "\"items\":["
      for (workload = 1; workload <= workload_emitted; workload++) {
        key = workload_order[workload]
        if (workload > 1) printf ","
        printf "{\"product_id\":\"%s\",\"name\":\"%s\",", workload_id[key], workload_name[key]
        printf "\"vendor\":null,\"category\":\"%s\",", workload_category[key]
        evidence_count = workload_evidence_count[key]
        evidence_emitted = evidence_count
        if (evidence_emitted > max_evidence) evidence_emitted = max_evidence
        evidence_omitted = evidence_count - evidence_emitted
        printf "\"version\":\"%s\",", json_escape(workload_version[key])
        printf "\"evidence_count\":%d,\"evidence_emitted_count\":%d,", evidence_count, evidence_emitted
        printf "\"evidence_omitted_count\":%d,", evidence_omitted
        if (evidence_omitted > 0) {
          printf "\"evidence_truncated\":true,"
          if (evidence_omitted == 1) {
            printf "\"evidence_truncation_marker\":\"1 more evidence fileset not emitted (limit %d)\",", max_evidence
          } else {
            printf "\"evidence_truncation_marker\":\"%d more evidence filesets not emitted (limit %d)\",", evidence_omitted, max_evidence
          }
        } else {
          printf "\"evidence_truncated\":false,\"evidence_truncation_marker\":null,"
        }
        printf "\"evidence_filesets\":["
        for (evidence = 1; evidence <= evidence_emitted; evidence++) {
          if (evidence > 1) printf ","
          printf "\"%s\"", json_escape(workload_evidence[key SUBSEP evidence])
        }
        printf "]}"
      }
      printf "],\"gap\":\"%s\"},", workload_gap
      emit_gaps()
      printf "}"
    }
  '
}
# Standalone facts emitter for AIX adapter firmware and microcode inventory.
# Include-safe: integration calls emit_fact_adapter_microcode from the facts renderer.

function adapter_microcode_json_escape {
  awk '
    {
      s=$0
      gsub(/\\/, "\\\\", s)
      gsub(/"/, "\\\"", s)
      gsub(/\t/, "\\t", s)
      gsub(/\r/, "\\r", s)
      gsub(/[\001-\010\013\014\016-\037]/, "", s)
      if (seen++) printf "\\n"
      printf "%s", s
    }
  '
}

function adapter_microcode_lsdev_shape {
  awk '
    function is_location(value) {
      return value ~ /^[0-9][0-9]-[0-9][0-9](-[0-9][0-9])*$/ ||
        value ~ /^[A-Z][0-9][A-Za-z0-9.]*-[A-Za-z0-9][A-Za-z0-9.\/-]*$/
    }
    NF {
      rows++
      if (NF < 3 || $1 !~ /^[A-Za-z][A-Za-z0-9_.-]*$/ ||
          $2 !~ /^[A-Za-z][A-Za-z0-9_-]*$/ || seen[$1]++) {
        bad=1
        next
      }
      first=3
      if (is_location($3)) first=4
      description=""
      for (i=first; i<=NF; i++)
        description=description (description=="" ? "" : " ") $i
      if (description=="") bad=1
    }
    END { if (rows==0 || bad) exit 1 }
  '
}

function adapter_microcode_parse_lsdev {
  awk '
    function is_location(value) {
      return value ~ /^[0-9][0-9]-[0-9][0-9](-[0-9][0-9])*$/ ||
        value ~ /^[A-Z][0-9][A-Za-z0-9.]*-[A-Za-z0-9][A-Za-z0-9.\/-]*$/
    }
    NF {
      first=3
      if (is_location($3)) first=4
      description=""
      for (i=first; i<=NF; i++)
        description=description (description=="" ? "" : " ") $i
      category=$1
      sub(/[0-9][0-9]*$/, "", category)
      if (category=="") category="adapter"
      printf "%s\t%s\t%s\n", $1, category, description
    }
  '
}

# Validate the whole lsmcode capture and print its recognized layout. Bang
# records may have typed continuation rows (for example raid-dasd); columnar
# records require only a device token plus a nonempty remainder, never a fixed
# number of fields.
function adapter_microcode_lsmcode_shape {
  awk '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function valid_name(value) {
      return value ~ /^[A-Za-z][A-Za-z0-9_.-]*$/
    }
    {
      line=$0
      sub(/\r$/, "", line)
      line=trim(line)
      if (line=="") next

      if (mode=="") {
        bang=index(line, "!")
        if (bang>1) {
          mode="bang"
        } else {
          count=split(line, header, /[ \t]+/)
          has_level=0
          for (i=2; i<=count; i++)
            if (tolower(header[i]) ~ /level/) has_level=1
          if (tolower(header[1])=="device" && has_level) {
            mode="column"
            next
          }
          bad=1
          next
        }
      }

      if (mode=="bang") {
        bang=index(line, "!")
        if (bang>1) {
          name=substr(line, 1, bang-1)
          level=trim(substr(line, bang+1))
          if (!valid_name(name) || level=="" || seen[name]++) bad=1
          else records++
          have_record=1
        } else if (!(have_record && line ~ /^[A-Za-z][A-Za-z0-9-]*:[^ \t]/)) {
          bad=1
        }
      } else {
        if (line ~ /^-+[ \t]+-+/) next
        name=line
        sub(/[ \t].*$/, "", name)
        level=line
        sub(/^[^ \t][^ \t]*[ \t][ \t]*/, "", level)
        level=trim(level)
        if (!valid_name(name) || tolower(name)=="device" ||
            level==line || level=="" || seen[name]++) bad=1
        else records++
      }
    }
    END {
      if (bad || records==0) exit 1
      print mode
    }
  '
}

function adapter_microcode_lsmcode_level {
  typeset wanted layout
  wanted=$1
  layout=$2
  awk -v wanted="$wanted" -v layout="$layout" '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function unavailable(value, normalized) {
      value=trim(value)
      normalized=tolower(value)
      gsub(/[ _-]/, "", normalized)
      if (normalized=="unknown" || normalized=="notavailable" ||
          normalized=="notapplicable" || normalized=="none" ||
          normalized=="n/a") return 1
      return 0
    }
    function usable(value) {
      value=trim(value)
      if (unavailable(value)) return 0
      if (value !~ /[0-9]/ || value ~ /[^A-Za-z0-9_.:+#|() \/-]/) return 0
      return 1
    }
    {
      line=$0
      sub(/\r$/, "", line)
      line=trim(line)
      if (line=="") next

      if (layout=="bang") {
        bang=index(line, "!")
        if (bang>1) {
          current=substr(line, 1, bang-1)
          if (current==wanted) {
            if (found) bad=1
            value=trim(substr(line, bang+1))
            found=1
          }
        } else if (current==wanted && line ~ /^[A-Za-z][A-Za-z0-9-]*:/) {
          value=value "|" line
        }
      } else {
        if (!header_seen) {
          header_seen=1
          next
        }
        if (line ~ /^-+[ \t]+-+/) next
        name=line
        sub(/[ \t].*$/, "", name)
        rest=line
        sub(/^[^ \t][^ \t]*[ \t][ \t]*/, "", rest)
        rest=trim(rest)
        if (name==wanted) {
          if (found) bad=1
          value=rest
          found=1
        }
      }
    }
    END {
      if (!found) exit 1
      gsub(/[ \t]+/, " ", value)
      value=trim(value)
      if (bad) exit 3
      if (unavailable(value)) {
        print value
        exit 2
      }
      if (!usable(value)) exit 3
      print value
    }
  '
}

function adapter_microcode_lscfg_shape {
  typeset wanted
  wanted=$1
  awk -v wanted="$wanted" '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    {
      line=$0
      sub(/\r$/, "", line)
      if (line ~ /^[ \t]*$/) next

      nonblank++
      if (nonblank==1) {
        header=line
        sub(/^[ \t]+/, "", header)
        name=header
        sub(/[ \t].*$/, "", name)
        remainder=header
        sub(/^[^ \t][^ \t]*[ \t][ \t]*/, "", remainder)
        if (name!=wanted || remainder==header || trim(remainder)=="") bad=1
        next
      }

      if (line ~ /^[ \t]+[^ \t].*[.][.][.]/) {
        label=line
        sub(/^[ \t]+/, "", label)
        sub(/[.][.][.].*$/, "", label)
        if (trim(label)=="") bad=1
        else vpd++
      }
    }
    END { if (bad || nonblank==0 || vpd==0) exit 1 }
  '
}

function adapter_microcode_lscfg_level {
  awk '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function label_type(value) {
      value=tolower(value)
      if (value ~ /rom level[.][(]alterable[)]/) return 1
      if (value ~ /microcode([ \t]*level)?/) return 2
      if (value ~ /firmware[ \t]*level/) return 3
      if (value ~ /device specific[.][(]z9[)]/) return 4
      return 0
    }
    function field_value(value) {
      if (value ~ /[.][.][.]/)
        sub(/^.*[.][.][.][.]*[ \t]*/, "", value)
      else if (value ~ /:/)
        sub(/^[^:]*:[ \t]*/, "", value)
      else
        return ""
      return trim(value)
    }
    function usable(value, normalized) {
      value=trim(value)
      normalized=tolower(value)
      gsub(/[ _-]/, "", normalized)
      if (normalized=="unknown" || normalized=="notavailable" ||
          normalized=="notapplicable" || normalized=="none" ||
          normalized=="n/a") return 0
      if (value !~ /[0-9]/ || value ~ /[^A-Za-z0-9_.:+#|() \/-]/) return 0
      return 1
    }
    {
      kind=label_type($0)
      candidate=field_value($0)
      if (kind && usable(candidate) && (!found || kind<best)) {
        best=kind
        value=candidate
        found=1
      }
    }
    END {
      if (!found) exit 1
      gsub(/[ \t]+/, " ", value)
      print trim(value)
    }
  '
}

function adapter_microcode_emit_unavailable {
  typeset reason escaped
  reason=$1
  escaped=$(printf '%s' "$reason" | adapter_microcode_json_escape)
  printf '%s' '"adapter_microcode": { "status": "NOT_ASSESSED", "platform": "AIX", '
  printf '%s' '"inventory_source_cmd": "lsdev -Cc adapter", "primary_source_cmd": "lsmcode -A", '
  printf '"capture_gaps": ["%s"], "reason": "%s", "adapters": null }' \
    "$escaped" "$escaped"
}

function emit_fact_adapter_microcode {
  typeset LSDEV_OUT LSDEV_RC LSDEV_ROWS LSDEV_WHY
  typeset LSMCODE_OUT LSMCODE_RC LSMCODE_LAYOUT LSMCODE_SHAPE_RC LSMCODE_WHY
  typeset DEV CATEGORY DESCRIPTION LEVEL SOURCE STATUS REASON
  typeset LSM_LEVEL LSM_LEVEL_RC LSM_REASON LSCFG_OUT LSCFG_RC LSCFG_WHY
  typeset ITEMS ITEM KNOWN UNKNOWN TOP_STATUS TOP_REASON
  typeset EDEV ECATEGORY EDESCRIPTION ELEVEL ESOURCE EREASON ETOP_REASON EGAP

  LSDEV_OUT=$(aix lsdev_adapter lsdev -Cc adapter)
  LSDEV_RC=$?
  if [ "$LSDEV_RC" -ne 0 ]; then
    LSDEV_WHY="lsdev -Cc adapter capture failed (rc=$LSDEV_RC)"
    adapter_microcode_emit_unavailable "$LSDEV_WHY"
    return
  fi
  if [ -z "$LSDEV_OUT" ]; then
    adapter_microcode_emit_unavailable "lsdev -Cc adapter capture empty (rc=0)"
    return
  fi
  if ! printf '%s\n' "$LSDEV_OUT" | adapter_microcode_lsdev_shape; then
    adapter_microcode_emit_unavailable "lsdev -Cc adapter capture unparseable (rc=0)"
    return
  fi
  LSDEV_ROWS=$(printf '%s\n' "$LSDEV_OUT" | adapter_microcode_parse_lsdev)

  LSMCODE_OUT=$(aix lsmcode_A lsmcode -A)
  LSMCODE_RC=$?
  LSMCODE_LAYOUT=""
  LSMCODE_WHY=""
  if [ "$LSMCODE_RC" -ne 0 ]; then
    LSMCODE_WHY="lsmcode -A capture failed (rc=$LSMCODE_RC)"
  elif [ -z "$LSMCODE_OUT" ]; then
    LSMCODE_WHY="lsmcode -A capture empty (rc=0)"
  else
    LSMCODE_LAYOUT=$(printf '%s\n' "$LSMCODE_OUT" | adapter_microcode_lsmcode_shape)
    LSMCODE_SHAPE_RC=$?
    if [ "$LSMCODE_SHAPE_RC" -ne 0 ] || [ -z "$LSMCODE_LAYOUT" ]; then
      LSMCODE_LAYOUT=""
      LSMCODE_WHY="lsmcode -A capture unparseable (rc=0)"
    fi
  fi

  ITEMS=""
  KNOWN=0
  UNKNOWN=0
  while IFS='	' read -r DEV CATEGORY DESCRIPTION
  do
    [ -n "$DEV" ] || continue
    LEVEL=""
    SOURCE=""
    STATUS="NOT_ASSESSED"
    REASON=""
    LSM_REASON="$LSMCODE_WHY"

    if [ -n "$LSMCODE_LAYOUT" ]; then
      LSM_LEVEL=$(printf '%s\n' "$LSMCODE_OUT" |
        adapter_microcode_lsmcode_level "$DEV" "$LSMCODE_LAYOUT")
      LSM_LEVEL_RC=$?
      case "$LSM_LEVEL_RC" in
        0)
          LEVEL=$LSM_LEVEL
          SOURCE="lsmcode -A"
          STATUS="OBSERVED"
          ;;
        1)
          LSM_REASON="lsmcode -A did not report $DEV"
          ;;
        2)
          LSM_REASON="lsmcode -A device reported microcode level $LSM_LEVEL for $DEV"
          ;;
        *)
          LSM_REASON="lsmcode -A record for $DEV unparseable (rc=0)"
          ;;
      esac
    fi

    if [ "$STATUS" != "OBSERVED" ]; then
      LSCFG_OUT=$(aix "lscfg_vpl_$DEV" lscfg -vpl "$DEV")
      LSCFG_RC=$?
      LSCFG_WHY=""
      if [ "$LSCFG_RC" -ne 0 ]; then
        LSCFG_WHY="lscfg -vpl $DEV capture failed (rc=$LSCFG_RC)"
      elif [ -z "$LSCFG_OUT" ]; then
        LSCFG_WHY="lscfg -vpl $DEV capture empty (rc=0)"
      elif ! printf '%s\n' "$LSCFG_OUT" |
          adapter_microcode_lscfg_shape "$DEV"; then
        LSCFG_WHY="lscfg -vpl $DEV capture unparseable (rc=0)"
      else
        LEVEL=$(printf '%s\n' "$LSCFG_OUT" | adapter_microcode_lscfg_level)
        if [ -n "$LEVEL" ]; then
          SOURCE="lscfg -vpl $DEV"
          STATUS="OBSERVED"
        else
          LSCFG_WHY="lscfg -vpl $DEV: no microcode/firmware level reported by device (no usable ROM/MicroCode/Firmware/Z9 VPD value)"
        fi
      fi
      if [ "$STATUS" != "OBSERVED" ]; then
        REASON="$LSM_REASON${LSM_REASON:+; }$LSCFG_WHY"
        SOURCE="lsmcode -A; lscfg -vpl $DEV"
      fi
    fi

    EDEV=$(printf '%s' "$DEV" | adapter_microcode_json_escape)
    ECATEGORY=$(printf '%s' "$CATEGORY" | adapter_microcode_json_escape)
    EDESCRIPTION=$(printf '%s' "$DESCRIPTION" | adapter_microcode_json_escape)
    ESOURCE=$(printf '%s' "$SOURCE" | adapter_microcode_json_escape)
    if [ "$STATUS" = "OBSERVED" ]; then
      ELEVEL=$(printf '%s' "$LEVEL" | adapter_microcode_json_escape)
      ITEM=$(printf '%s' "{ \"name\": \"$EDEV\", \"category\": \"$ECATEGORY\", \"description\": \"$EDESCRIPTION\", \"microcode_level\": \"$ELEVEL\", \"source_cmd\": \"$ESOURCE\", \"status\": \"OBSERVED\", \"reason\": null }")
      KNOWN=$((KNOWN + 1))
    else
      EREASON=$(printf '%s' "$REASON" | adapter_microcode_json_escape)
      ITEM=$(printf '%s' "{ \"name\": \"$EDEV\", \"category\": \"$ECATEGORY\", \"description\": \"$EDESCRIPTION\", \"microcode_level\": null, \"source_cmd\": \"$ESOURCE\", \"status\": \"NOT_ASSESSED\", \"reason\": \"$EREASON\" }")
      UNKNOWN=$((UNKNOWN + 1))
    fi
    if [ -n "$ITEMS" ]; then ITEMS="$ITEMS, $ITEM"; else ITEMS=$ITEM; fi
  done <<EOF
$LSDEV_ROWS
EOF

  TOP_REASON=""
  if [ "$KNOWN" -eq 0 ]; then
    TOP_STATUS="NOT_ASSESSED"
    TOP_REASON="no enumerated adapter had a trustworthy microcode level; see per-adapter reasons"
  elif [ "$UNKNOWN" -eq 0 ]; then
    TOP_STATUS="COMPLETE"
  else
    TOP_STATUS="PARTIAL"
  fi

  printf '"adapter_microcode": { "status": "%s", "platform": "AIX", ' "$TOP_STATUS"
  printf '%s' '"inventory_source_cmd": "lsdev -Cc adapter", "primary_source_cmd": "lsmcode -A", '
  if [ -n "$LSMCODE_WHY" ]; then
    EGAP=$(printf '%s' "$LSMCODE_WHY" | adapter_microcode_json_escape)
    printf '"capture_gaps": ["%s"], ' "$EGAP"
  else
    printf '%s' '"capture_gaps": [], '
  fi
  if [ -n "$TOP_REASON" ]; then
    ETOP_REASON=$(printf '%s' "$TOP_REASON" | adapter_microcode_json_escape)
    printf '"reason": "%s", ' "$ETOP_REASON"
  else
    printf '%s' '"reason": null, '
  fi
  printf '"adapters": [%s] }' "$ITEMS"
}
# Emit one JSON member named "storage_layout" from fresh, replayable AIX
# captures. This facts-only module deliberately does not add a finding; a
# separate integration build owns the spine include and facts-emitter call.

function storage_layout_has_nonblank {
  printf '%s\n' "$1" | awk 'NF { found=1 } END { exit(found ? 0 : 1) }'
}

function storage_layout_emit_inventory_gap {
  typeset SL_FATAL_REASON
  SL_FATAL_REASON=$1

  printf '%s\n' "$SL_FATAL_REASON" | awk '
    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") result = result "\\\\"
        else if (character == "\"") result = result "\\\""
        else if (character == "\t") result = result "\\t"
        else if (character == "\r") result = result "\\r"
        else result = result character
      }
      return result
    }
    {
      if (NR > 1) reason = reason "\\n"
      reason = reason $0
    }
    END {
      printf "\"storage_layout\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"platform\":\"AIX\","
      printf "\"reason\":\"%s\",", json_escape(reason)
      printf "\"inventory_source_cmd\":\"lspv\","
      printf "\"size_source_cmd\":\"getconf DISK_SIZE /dev/<hdisk>\","
      printf "\"type_source_cmd\":\"%s\",", \
        json_escape("lsdev -Cc disk -F \"name:status:description\"")
      printf "\"path_source_cmd\":\"%s\",", \
        json_escape("lspath -F \"name parent path_id status\"")
      printf "\"capture_gaps\":[\"%s\"],\"disks\":null}", \
        json_escape(reason)
    }
  '
}

function emit_fact_storage_layout {
  typeset SL_LSPV SL_LSPV_RC SL_LSPV_ROWS SL_SHAPE_RC
  typeset SL_LSDEV SL_LSDEV_RC SL_LSDEV_ROWS SL_LSDEV_REASON
  typeset SL_LSPATH SL_LSPATH_RC SL_LSPATH_ROWS SL_LSPATH_REASON
  typeset SL_DISK SL_PVID SL_VG SL_KEY
  typeset SL_SIZE_RAW SL_SIZE_RC SL_SIZE SL_SIZE_REASON SL_SIZE_KNOWN
  typeset SL_DESC SL_DESC_REASON SL_DESC_KNOWN SL_LOOKUP_RC
  typeset SL_PATH_DATA SL_PATH_REST SL_PATH_COUNT SL_PATH_SUMMARY
  typeset SL_PATH_FAILED SL_PATH_MISSING SL_PATH_NOTE SL_PATH_REASON
  typeset SL_PATH_KNOWN

  # lspv is the inventory authority. A failed, empty, or malformed inventory
  # cannot safely supply device names for any later dynamic capture key.
  SL_LSPV=$(aix lspv lspv); SL_LSPV_RC=$?
  if [ "$SL_LSPV_RC" -ne 0 ]; then
    storage_layout_emit_inventory_gap \
      "lspv capture failed (rc=$SL_LSPV_RC)"
    return 0
  fi
  if ! storage_layout_has_nonblank "$SL_LSPV"; then
    storage_layout_emit_inventory_gap "lspv capture empty (rc=0)"
    return 0
  fi
  SL_LSPV_ROWS=$(printf '%s\n' "$SL_LSPV" | awk '
    function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
    function pvid(value) {
      return value == "none" ||
        (value ~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/ &&
         substr(value,16,1) != "" && substr(value,17,1) == "")
    }
    function vg(value) {
      return value ~ /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/
    }
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF < 3 || !hdisk($1) || !pvid($2) || !vg($3) || seen[$1]++) {
        bad=1
        next
      }
      disk[rows]=$1
      disk_pvid[rows]=$2
      disk_vg[rows]=$3
    }
    END {
      if (bad || rows == 0) exit 1
      for (row=1; row<=rows; row++)
        printf "%s\t%s\t%s\n", disk[row], disk_pvid[row], disk_vg[row]
    }
  '); SL_SHAPE_RC=$?
  if [ "$SL_SHAPE_RC" -ne 0 ] || [ -z "$SL_LSPV_ROWS" ]; then
    storage_layout_emit_inventory_gap "lspv capture unparseable (rc=0)"
    return 0
  fi

  # Device descriptions are supplemental. Their capture gap must not erase
  # the lspv inventory or prevent independent size/path facts from surfacing.
  SL_LSDEV_REASON=""
  SL_LSDEV_ROWS=""
  SL_LSDEV=$(aix lsdev_disk_fields lsdev -Cc disk -F \
    "name:status:description"); SL_LSDEV_RC=$?
  if [ "$SL_LSDEV_RC" -ne 0 ]; then
    SL_LSDEV_REASON="lsdev -Cc disk -F \"name:status:description\" capture failed (rc=$SL_LSDEV_RC)"
  elif ! storage_layout_has_nonblank "$SL_LSDEV"; then
    SL_LSDEV_REASON="lsdev -Cc disk -F \"name:status:description\" capture empty (rc=0)"
  else
    SL_LSDEV_ROWS=$(printf '%s\n' "$SL_LSDEV" | awk -F ':' '
      function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
      /^[ \t]*$/ { next }
      {
        rows++
        if (NF != 3 || !hdisk($1) ||
            ($2 != "Available" && $2 != "Defined" && $2 != "Stopped") ||
            seen[$1]++) {
          bad=1
          next
        }
        description=$3
        if (description !~ /[^ \t]/) {
          bad=1
          next
        }
        disk[rows]=$1
        disk_description[rows]=description
      }
      END {
        if (bad || rows == 0) exit 1
        for (row=1; row<=rows; row++)
          printf "%s\t%s\n", disk[row], disk_description[row]
      }
    '); SL_SHAPE_RC=$?
    if [ "$SL_SHAPE_RC" -ne 0 ] || [ -z "$SL_LSDEV_ROWS" ]; then
      SL_LSDEV_ROWS=""
      SL_LSDEV_REASON="lsdev -Cc disk -F \"name:status:description\" capture unparseable (rc=0)"
    fi
  fi

  # Empty lspath is a normal non-MPIO observation, but it does not prove a
  # numeric zero for every disk. Preserve it as an explicit assessment gap.
  SL_LSPATH_REASON=""
  SL_LSPATH_ROWS=""
  SL_LSPATH=$(aix lspath_disk lspath -F "name parent path_id status")
  SL_LSPATH_RC=$?
  if [ "$SL_LSPATH_RC" -ne 0 ]; then
    SL_LSPATH_REASON="lspath -F \"name parent path_id status\" capture failed (rc=$SL_LSPATH_RC)"
  elif ! storage_layout_has_nonblank "$SL_LSPATH"; then
    SL_LSPATH_REASON="lspath -F \"name parent path_id status\" capture empty (rc=0); no MPIO paths reported"
  else
    SL_LSPATH_ROWS=$(printf '%s\n' "$SL_LSPATH" | awk '
      function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
      function token(value) {
        return value ~ /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/
      }
      /^[ \t]*$/ { next }
      {
        rows++
        key=$1 SUBSEP $2 SUBSEP $3
        if (NF < 4 || !hdisk($1) || !token($2) ||
            $3 !~ /^[0-9][0-9]*$/ || !token($4) || seen[key]++) {
          bad=1
          next
        }
        disk[rows]=$1
        parent[rows]=$2
        path_id[rows]=$3
        path_status[rows]=$4
      }
      END {
        if (bad || rows == 0) exit 1
        for (row=1; row<=rows; row++)
          printf "%s\t%s\t%s\t%s\n", disk[row], parent[row],
            path_id[row], path_status[row]
      }
    '); SL_SHAPE_RC=$?
    if [ "$SL_SHAPE_RC" -ne 0 ] || [ -z "$SL_LSPATH_ROWS" ]; then
      SL_LSPATH_ROWS=""
      SL_LSPATH_REASON="lspath -F \"name parent path_id status\" capture unparseable (rc=0)"
    fi
  fi

  {
    printf '%s\n' "$SL_LSPV_ROWS" | awk -F '\t' \
      '{ printf "I\t%s\t%s\t%s\n", $1, $2, $3 }'
    [ -n "$SL_LSDEV_REASON" ] && printf 'G\t%s\n' "$SL_LSDEV_REASON"
    [ -n "$SL_LSPATH_REASON" ] && printf 'G\t%s\n' "$SL_LSPATH_REASON"

    printf '%s\n' "$SL_LSPV_ROWS" |
      while read SL_DISK SL_PVID SL_VG; do
        # Each size is independently captured and gated. A plausible-looking
        # payload from a failed command is never used.
        SL_KEY="getconf_disk_size_$SL_DISK"
        SL_SIZE_RAW=$(aix "$SL_KEY" getconf DISK_SIZE "/dev/$SL_DISK")
        SL_SIZE_RC=$?
        SL_SIZE=""
        SL_SIZE_REASON=""
        SL_SIZE_KNOWN=0
        if [ "$SL_SIZE_RC" -ne 0 ]; then
          SL_SIZE_REASON="getconf DISK_SIZE /dev/$SL_DISK capture failed (rc=$SL_SIZE_RC)"
        elif ! storage_layout_has_nonblank "$SL_SIZE_RAW"; then
          SL_SIZE_REASON="getconf DISK_SIZE /dev/$SL_DISK capture empty (rc=0)"
        else
          SL_SIZE=$(printf '%s\n' "$SL_SIZE_RAW" | awk '
            /^[ \t]*$/ { next }
            {
              rows++
              if (NF != 1 || $1 !~ /^[1-9][0-9]*$/) bad=1
              value=$1
            }
            END {
              if (bad || rows != 1) exit 1
              print value
            }
          '); SL_SHAPE_RC=$?
          if [ "$SL_SHAPE_RC" -eq 0 ] && [ -n "$SL_SIZE" ]; then
            SL_SIZE_KNOWN=1
          else
            SL_SIZE=""
            SL_SIZE_REASON="getconf DISK_SIZE /dev/$SL_DISK capture unparseable (rc=0)"
          fi
        fi

        SL_DESC=""
        SL_DESC_REASON=""
        SL_DESC_KNOWN=0
        if [ -n "$SL_LSDEV_REASON" ]; then
          SL_DESC_REASON=$SL_LSDEV_REASON
        else
          SL_DESC=$(printf '%s\n' "$SL_LSDEV_ROWS" | awk -F '\t' \
            -v wanted="$SL_DISK" '
              $1 == wanted { print $2; found=1; exit }
              END { if (!found) exit 1 }
            ')
          SL_LOOKUP_RC=$?
          if [ "$SL_LOOKUP_RC" -eq 0 ] && [ -n "$SL_DESC" ]; then
            SL_DESC_KNOWN=1
          else
            SL_DESC=""
            SL_DESC_REASON="lsdev -Cc disk -F \"name:status:description\" reported no description for $SL_DISK (rc=0)"
          fi
        fi

        SL_PATH_COUNT=""
        SL_PATH_SUMMARY=""
        SL_PATH_NOTE=""
        SL_PATH_REASON=""
        SL_PATH_KNOWN=0
        if [ -n "$SL_LSPATH_REASON" ]; then
          SL_PATH_REASON=$SL_LSPATH_REASON
        else
          SL_PATH_DATA=$(printf '%s\n' "$SL_LSPATH_ROWS" | awk -F '\t' \
            -v wanted="$SL_DISK" '
              $1 == wanted {
                count++
                status=$4
                if (!seen[status]++) order[++states]=status
                if (status == "Failed") failed++
                if (status == "Missing") missing++
              }
              END {
                if (count == 0) exit 1
                printf "%d:", count
                for (state=1; state<=states; state++) {
                  if (state > 1) printf ", "
                  printf "%s=%d", order[state], seen[order[state]]
                }
                printf ":%d:%d", failed+0, missing+0
              }
            ')
          SL_LOOKUP_RC=$?
          if [ "$SL_LOOKUP_RC" -eq 0 ] && [ -n "$SL_PATH_DATA" ]; then
            SL_PATH_COUNT=${SL_PATH_DATA%%:*}
            SL_PATH_REST=${SL_PATH_DATA#*:}
            SL_PATH_SUMMARY=${SL_PATH_REST%%:*}
            SL_PATH_REST=${SL_PATH_REST#*:}
            SL_PATH_FAILED=${SL_PATH_REST%%:*}
            SL_PATH_MISSING=${SL_PATH_REST#*:}
            if [ "$SL_PATH_FAILED" -gt 0 ] || [ "$SL_PATH_MISSING" -gt 0 ]; then
              SL_PATH_NOTE="Failed/Missing path state observed (Failed=$SL_PATH_FAILED, Missing=$SL_PATH_MISSING)"
            fi
            SL_PATH_KNOWN=1
          else
            SL_PATH_REASON="lspath -F \"name parent path_id status\" reported no paths for $SL_DISK (rc=0)"
          fi
        fi

        [ -n "$SL_SIZE_REASON" ] && printf 'G\t%s\n' "$SL_SIZE_REASON"
        [ -n "$SL_DESC_REASON" ] && printf 'G\t%s\n' "$SL_DESC_REASON"
        [ -n "$SL_PATH_REASON" ] && printf 'G\t%s\n' "$SL_PATH_REASON"
        printf 'D\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\tX\n' \
          "$SL_DISK" "$SL_SIZE_KNOWN" "$SL_SIZE" "$SL_SIZE_REASON" \
          "$SL_DESC_KNOWN" "$SL_DESC" "$SL_DESC_REASON" \
          "$SL_PATH_KNOWN" "$SL_PATH_COUNT" "$SL_PATH_SUMMARY" \
          "$SL_PATH_NOTE" "$SL_PATH_REASON"
      done
  } | awk -F '\t' '
    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") result = result "\\\\"
        else if (character == "\"") result = result "\\\""
        else if (character == "\t") result = result "\\t"
        else if (character == "\r") result = result "\\r"
        else result = result character
      }
      return result
    }
    function add_gap(reason) {
      if (reason != "" && !gap_seen[reason]++) gap[++gap_count]=reason
    }
    function add_reason(current, reason) {
      if (reason == "") return current
      if (current == "") return reason
      if (index("; " current "; ", "; " reason "; ") > 0) return current
      return current "; " reason
    }
    $1 == "G" {
      add_gap($2)
      next
    }
    $1 == "I" {
      inventory_pvid[$2]=$3
      inventory_vg[$2]=$4
      next
    }
    $1 == "D" {
      row=++disk_count
      disk[row]=$2
      size_known[row]=$3+0
      size[row]=$4
      size_reason[row]=$5
      description_known[row]=$6+0
      description[row]=$7
      description_reason[row]=$8
      path_known[row]=$9+0
      path_count[row]=$10
      path_summary[row]=$11
      path_note[row]=$12
      path_reason[row]=$13
      next
    }
    END {
      printf "\"storage_layout\":{"
      printf "\"status\":\"%s\",", (gap_count ? "PARTIAL" : "COMPLETE")
      printf "\"platform\":\"AIX\","
      if (gap_count) printf "\"reason\":\"one or more storage-layout facts were not assessed\","
      else printf "\"reason\":null,"
      printf "\"inventory_source_cmd\":\"lspv\","
      printf "\"size_source_cmd\":\"getconf DISK_SIZE /dev/<hdisk>\","
      printf "\"type_source_cmd\":\"%s\",", \
        json_escape("lsdev -Cc disk -F \"name:status:description\"")
      printf "\"path_source_cmd\":\"%s\",", \
        json_escape("lspath -F \"name parent path_id status\"")
      printf "\"capture_gaps\":["
      for (item=1; item<=gap_count; item++) {
        if (item > 1) printf ","
        printf "\"%s\"", json_escape(gap[item])
      }
      printf "],\"disks\":["
      for (row=1; row<=disk_count; row++) {
        if (row > 1) printf ","
        assessed=size_known[row] && description_known[row] && path_known[row]
        reason=""
        if (!size_known[row]) reason=add_reason(reason, size_reason[row])
        if (!description_known[row]) reason=add_reason(reason, description_reason[row])
        if (!path_known[row]) reason=add_reason(reason, path_reason[row])

        printf "{\"hdisk\":\"%s\",", json_escape(disk[row])
        if (size_known[row]) printf "\"size_mb\":%s,", size[row]
        else printf "\"size_mb\":null,"
        printf "\"vg\":\"%s\",", json_escape(inventory_vg[disk[row]])
        printf "\"pvid\":\"%s\",", json_escape(inventory_pvid[disk[row]])
        if (description_known[row])
          printf "\"type_desc\":\"%s\",", json_escape(description[row])
        else printf "\"type_desc\":null,"
        if (path_known[row]) {
          printf "\"path_count\":%s,", path_count[row]
          printf "\"path_status_summary\":\"%s\",", \
            json_escape(path_summary[row])
          if (path_note[row] != "")
            printf "\"path_note\":\"%s\",", json_escape(path_note[row])
          else printf "\"path_note\":null,"
        } else {
          printf "\"path_count\":null,\"path_status_summary\":null,"
          printf "\"path_note\":null,"
        }
        printf "\"status\":\"%s\",", (assessed ? "OBSERVED" : "NOT_ASSESSED")
        if (assessed) printf "\"reason\":null,"
        else printf "\"reason\":\"%s\",", json_escape(reason)
        printf "\"not_assessed\":{"
        separator=""
        if (!size_known[row]) {
          printf "\"size_mb\":\"%s\"", json_escape(size_reason[row])
          separator=","
        }
        if (!description_known[row]) {
          printf "%s\"type_desc\":\"%s\"", separator, \
            json_escape(description_reason[row])
          separator=","
        }
        if (!path_known[row]) {
          printf "%s\"path_count\":\"%s\"", separator, \
            json_escape(path_reason[row])
          printf ",\"path_status_summary\":\"%s\"", \
            json_escape(path_reason[row])
        }
        printf "}}"
      }
      printf "]}"
    }
  '
}
# Standalone facts emitter for AIX interface, route, and resolver inventory.
# Include-safe: integration calls emit_fact_network_inventory from the facts renderer.

function network_inventory_json_escape {
  awk '
    {
      s=$0
      gsub(/\\/, "\\\\", s)
      gsub(/"/, "\\\"", s)
      gsub(/\t/, "\\t", s)
      gsub(/\r/, "\\r", s)
      gsub(/[\001-\010\013\014\016-\037]/, "", s)
      if (seen++) printf "\\n"
      printf "%s", s
    }
  '
}

function network_inventory_ifconfig_shape {
  awk '
    function ipv4(value, part, count, i) {
      count=split(value, part, ".")
      if (count!=4) return 0
      for (i=1; i<=4; i++)
        if (part[i] !~ /^[0-9][0-9]*$/ || part[i]+0>255) return 0
      return 1
    }
    function netmask(value, raw) {
      if (ipv4(value)) return 1
      raw=value
      sub(/^0[xX]/, "", raw)
      return substr(raw,8,1)!="" && substr(raw,9,1)=="" &&
        raw ~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/
    }
    function ipv6_component(value, allow_ipv4) {
      if (index(value, ".")>0) {
        if (!allow_ipv4 || !ipv4(value)) return 0
        return 2
      }
      if (substr(value,1,1)=="" || substr(value,5,1)!="" ||
          value !~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/) return 0
      return 1
    }
    function ipv6_side(value, allow_ipv4, part, count, i, units, size) {
      count=split(value, part, ":")
      units=0
      for (i=1; i<=count; i++) {
        size=ipv6_component(part[i], allow_ipv4 && i==count)
        if (size==0) return -1
        units+=size
      }
      return units
    }
    function ipv6(value, percent, zone, compression, remainder, left,
                  right, left_units, right_units, total) {
      percent=index(value, "%")
      if (percent>0) {
        zone=substr(value, percent+1)
        if (zone=="" || index(zone, "%")>0 ||
            zone !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        value=substr(value, 1, percent-1)
      }
      if (value=="" || index(value, ":")==0) return 0
      compression=index(value, "::")
      if (compression>0) {
        remainder=substr(value, compression+2)
        if (index(remainder, "::")>0) return 0
        left=substr(value, 1, compression-1)
        right=remainder
        left_units=0
        right_units=0
        if (left!="") left_units=ipv6_side(left, 0)
        if (right!="") right_units=ipv6_side(right, 1)
        if (left_units<0 || right_units<0) return 0
        total=left_units+right_units
        return total<8
      }
      if (value ~ /^:/ || value ~ /:$/) return 0
      total=ipv6_side(value, 1)
      return total==8
    }
    function ipv6_prefix(value, slash, address, prefix) {
      slash=index(value, "/")
      if (slash==0) return ipv6(value)
      address=substr(value, 1, slash-1)
      prefix=substr(value, slash+1)
      if (address=="" || prefix !~ /^[0-9][0-9]*$/ ||
          prefix+0>128 || index(prefix, "/")>0) return 0
      return ipv6(address)
    }
    /^[ \t\r]*$/ { next }
    /^[^ \t]/ {
      if ($0 !~ /^[A-Za-z][A-Za-z0-9_.-]*:[ \t]*flags=[^<]*<[^>]*>/) {
        bad=1
        next
      }
      name=$1
      sub(/:.*/, "", name)
      if (name !~ /^[A-Za-z][A-Za-z0-9_.-]*$/ || seen[name]++) bad=1
      current=name
      headers++
      for (i=1; i<=NF; i++) {
        if ($i=="mtu") {
          mtu++
          if (i==NF || $(i+1) !~ /^[1-9][0-9]*$/) bad=1
        }
      }
      next
    }
    {
      if (current=="") { bad=1; next }
      if ($1=="inet") {
        if (!ipv4($2)) { bad=1; next }
        masks=0
        for (i=3; i<=NF; i++) {
          if ($i=="netmask") {
            masks++
            if (i==NF || !netmask($(i+1))) bad=1
          }
        }
        if (masks!=1) bad=1
      } else if ($1=="inet6") {
        if (!ipv6_prefix($2)) bad=1
      } else if ($1=="tcp_sendspace" || $1=="tcp_recvspace" ||
                 $1=="rfc1323") {
        if (NF<2 || NF%2!=0) { bad=1; next }
        for (i=1; i<=NF; i+=2) {
          if (($i!="tcp_sendspace" && $i!="tcp_recvspace" &&
               $i!="rfc1323") ||
              $(i+1) !~ /^[0-9][0-9]*$/) bad=1
        }
      } else {
        bad=1
      }
    }
    END { if (bad || headers==0) exit 1 }
  '
}

function network_inventory_parse_ifconfig {
  awk '
    /^[ \t\r]*$/ { next }
    /^[^ \t]/ {
      name=$1
      sub(/:.*/, "", name)
      flags=$0
      sub(/^[^<]*</, "", flags)
      sub(/>.*/, "", flags)
      count=split(flags, flag, ",")
      state="down"
      for (i=1; i<=count; i++) if (flag[i]=="UP") state="up"
      mtu=""
      for (i=1; i<=NF; i++) if ($i=="mtu") mtu=$(i+1)
      current=name
      printf "I\t%s\t%s\t%s\n", name, state, mtu
      next
    }
    $1=="inet" {
      mask=""
      for (i=3; i<=NF; i++) if ($i=="netmask") mask=$(i+1)
      printf "A\t%s\t%s\t%s\n", current, $2, mask
    }
  '
}

function network_inventory_lsattr_shape {
  awk '
    /^[ \t\r]*$/ { next }
    $1=="mtu" {
      seen++
      if (NF<2 || $2 !~ /^[1-9][0-9]*$/) bad=1
    }
    END { if (bad || seen!=1) exit 1 }
  '
}

function network_inventory_entstat_shape {
  typeset NI_ES_WANTED
  NI_ES_WANTED=$1
  awk -v wanted="$NI_ES_WANTED" '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    /^ETHERNET STATISTICS \(/ {
      value=$0
      sub(/^[^(]*\(/, "", value)
      sub(/\).*/, "", value)
      headers++
      if (value!=wanted) bad=1
    }
    /^Device Type:/ {
      value=$0
      sub(/^[^:]*:[ \t]*/, "", value)
      types++
      if (trim(value)=="") bad=1
    }
    END { if (bad || headers!=1 || types!=1) exit 1 }
  '
}

function network_inventory_entstat_type {
  awk '
    /^Device Type:/ {
      sub(/^[^:]*:[ \t]*/, "")
      sub(/[ \t]+$/, "")
      print
      exit
    }
  '
}

function network_inventory_entstat_speed {
  awk '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    /^Media Speed Running:/ {
      value=$0
      sub(/^[^:]*:[ \t]*/, "", value)
      value=trim(value)
      split(value, part, /[ \t]+/)
      if (part[1] ~ /^[1-9][0-9]*$/) media=part[1]
    }
    /^Adapter Data Rate:/ {
      value=$0
      sub(/^[^:]*:[ \t]*/, "", value)
      value=trim(value)
      split(value, part, /[ \t]+/)
      if (part[1] ~ /^[1-9][0-9]*$/) rate=part[1]
    }
    END {
      if (media!="") print media
      else if (rate!="") print rate
    }
  '
}

function network_inventory_netstat_shape {
  awk '
    function ipv4(value, part, count, i) {
      count=split(value, part, ".")
      if (count!=4) return 0
      for (i=1; i<=4; i++)
        if (part[i] !~ /^[0-9][0-9]*$/ || part[i]+0>255) return 0
      return 1
    }
    function ipv6_component(value, allow_ipv4) {
      if (index(value, ".")>0) {
        if (!allow_ipv4 || !ipv4(value)) return 0
        return 2
      }
      if (substr(value,1,1)=="" || substr(value,5,1)!="" ||
          value !~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/) return 0
      return 1
    }
    function ipv6_side(value, allow_ipv4, part, count, i, units, size) {
      count=split(value, part, ":")
      units=0
      for (i=1; i<=count; i++) {
        size=ipv6_component(part[i], allow_ipv4 && i==count)
        if (size==0) return -1
        units+=size
      }
      return units
    }
    function ipv6(value, percent, zone, compression, remainder, left,
                  right, left_units, right_units, total) {
      percent=index(value, "%")
      if (percent>0) {
        zone=substr(value, percent+1)
        if (zone=="" || index(zone, "%")>0 ||
            zone !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        value=substr(value, 1, percent-1)
      }
      if (value=="" || index(value, ":")==0) return 0
      compression=index(value, "::")
      if (compression>0) {
        remainder=substr(value, compression+2)
        if (index(remainder, "::")>0) return 0
        left=substr(value, 1, compression-1)
        right=remainder
        left_units=0
        right_units=0
        if (left!="") left_units=ipv6_side(left, 0)
        if (right!="") right_units=ipv6_side(right, 1)
        if (left_units<0 || right_units<0) return 0
        total=left_units+right_units
        return total<8
      }
      if (value ~ /^:/ || value ~ /:$/) return 0
      total=ipv6_side(value, 1)
      return total==8
    }
    {
      lower=tolower($0)
      if ($1=="Routing" && $2=="tables") headers++
      if (lower ~ /protocol family[ \t]+24([ \t(:]|$)/ ||
          lower ~ /internet v6/) {
        family="ipv6"
        families++
        next
      }
      if (lower ~ /protocol family[ \t]+2([ \t(:]|$)/) {
        family="ipv4"
        families++
        next
      }
      if ($1=="default" || $1=="0.0.0.0" ||
          $1=="::/0" || $1=="::0/0") {
        route_family=family
        if ($1=="0.0.0.0") route_family="ipv4"
        if ($1=="::/0" || $1=="::0/0") route_family="ipv6"
        defaults++
        if (NF<3 || $3 !~ /^[A-Za-z][A-Za-z]*$/ || route_family=="" ||
            (route_family=="ipv4" && !ipv4($2)) ||
            (route_family=="ipv6" && !ipv6($2))) bad=1
      }
    }
    END { if (bad || headers!=1 || families==0) exit 1 }
  '
}

function network_inventory_parse_netstat {
  awk '
    {
      lower=tolower($0)
      if (lower ~ /protocol family[ \t]+24([ \t(:]|$)/ ||
          lower ~ /internet v6/) {
        family="ipv6"
        next
      }
      if (lower ~ /protocol family[ \t]+2([ \t(:]|$)/) {
        family="ipv4"
        next
      }
      if ($1=="default" || $1=="0.0.0.0" ||
          $1=="::/0" || $1=="::0/0") {
        route_family=family
        if ($1=="0.0.0.0") route_family="ipv4"
        if ($1=="::/0" || $1=="::0/0") route_family="ipv6"
        iface=""
        for (i=3; i<=NF; i++)
          if ($i ~ /^[A-Za-z][A-Za-z_.-]*[0-9][0-9]*$/) iface=$i
        if (iface=="")
          printf "%s\t%s\t\tPARTIAL\tnetstat -rn default route did not expose an interface\n", route_family, $2
        else
          printf "%s\t%s\t%s\tOBSERVED\t\n", route_family, $2, iface
      }
    }
  '
}

function network_inventory_resolv_shape {
  awk '
    function ipv4(value, part, count, i) {
      count=split(value, part, ".")
      if (count!=4) return 0
      for (i=1; i<=4; i++)
        if (part[i] !~ /^[0-9][0-9]*$/ || part[i]+0>255) return 0
      return 1
    }
    function ipv6_component(value, allow_ipv4) {
      if (index(value, ".")>0) {
        if (!allow_ipv4 || !ipv4(value)) return 0
        return 2
      }
      if (substr(value,1,1)=="" || substr(value,5,1)!="" ||
          value !~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/) return 0
      return 1
    }
    function ipv6_side(value, allow_ipv4, part, count, i, units, size) {
      count=split(value, part, ":")
      units=0
      for (i=1; i<=count; i++) {
        size=ipv6_component(part[i], allow_ipv4 && i==count)
        if (size==0) return -1
        units+=size
      }
      return units
    }
    function ipv6(value, percent, zone, compression, remainder, left,
                  right, left_units, right_units, total) {
      percent=index(value, "%")
      if (percent>0) {
        zone=substr(value, percent+1)
        if (zone=="" || index(zone, "%")>0 ||
            zone !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        value=substr(value, 1, percent-1)
      }
      if (value=="" || index(value, ":")==0) return 0
      compression=index(value, "::")
      if (compression>0) {
        remainder=substr(value, compression+2)
        if (index(remainder, "::")>0) return 0
        left=substr(value, 1, compression-1)
        right=remainder
        left_units=0
        right_units=0
        if (left!="") left_units=ipv6_side(left, 0)
        if (right!="") right_units=ipv6_side(right, 1)
        if (left_units<0 || right_units<0) return 0
        total=left_units+right_units
        return total<8
      }
      if (value ~ /^:/ || value ~ /:$/) return 0
      total=ipv6_side(value, 1)
      return total==8
    }
    /^[ \t\r]*$/ { next }
    /^[ \t]*[#;]/ { next }
    {
      if ($1=="nameserver") {
        if (NF<2 || (!ipv4($2) && !ipv6($2))) { bad=1; next }
        for (i=3; i<=NF; i++) {
          if (substr($i,1,1)=="#" || substr($i,1,1)==";") break
          bad=1
        }
      } else if ($1=="domain" || $1=="search" || $1=="sortlist" ||
                 $1=="options" || $1=="lookup") {
        if (NF<2) bad=1
      } else {
        bad=1
      }
    }
    END { if (bad) exit 1 }
  '
}

function network_inventory_parse_resolv {
  awk '
    /^[ \t]*nameserver[ \t]+/ { print $2 }
  '
}

function network_inventory_append_gap {
  typeset NI_AG_CURRENT NI_AG_REASON NI_AG_ESCAPED
  NI_AG_CURRENT=$1
  NI_AG_REASON=$2
  NI_AG_ESCAPED=$(printf '%s' "$NI_AG_REASON" |
    network_inventory_json_escape)
  if [ -n "$NI_AG_CURRENT" ]; then
    printf '%s, "%s"' "$NI_AG_CURRENT" "$NI_AG_ESCAPED"
  else
    printf '"%s"' "$NI_AG_ESCAPED"
  fi
}

function emit_fact_network_inventory {
  typeset NI_IFCONFIG NI_IFCONFIG_RC NI_IF_WHY NI_IF_SOURCE NI_PARSED
  typeset NI_NAMES NI_IF_ITEMS NI_IF_PARTIAL NI_IF NI_STATE NI_HEADER_MTU
  typeset NI_IPV4 NI_MTU NI_MTU_STATUS NI_MTU_REASON NI_MTU_REASON_JSON
  typeset NI_LSATTR NI_LSATTR_RC NI_ADAPTER NI_ADAPTER_TYPE
  typeset NI_ADAPTER_STATUS NI_ADAPTER_REASON NI_ADAPTER_REASON_JSON
  typeset NI_SPEED NI_SPEED_STATUS NI_SPEED_REASON NI_SPEED_REASON_JSON
  typeset NI_ENTSTAT NI_ENTSTAT_RC NI_SUFFIX NI_ADAPTER_CANDIDATE
  typeset NI_ITEM_STATUS NI_ITEM_REASON
  typeset NI_ITEM_REASON_ESC NI_ITEM_REASON_JSON NI_ADAPTER_JSON NI_TYPE_ESC
  typeset NI_TYPE_JSON NI_SPEED_JSON NI_MTU_JSON NI_ITEM
  typeset NI_INTERFACES_STATUS NI_INTERFACES_REASON NI_INTERFACES_REASON_JSON
  typeset NI_NETSTAT NI_NETSTAT_RC NI_ROUTE_WHY NI_ROUTE_SOURCE NI_ROUTE_ROWS
  typeset NI_ROUTE_ITEMS NI_ROUTE_STATUS NI_ROUTE_REASON NI_ROUTE_REASON_JSON
  typeset NI_DNS_RAW NI_DNS_RC NI_DNS_WHY NI_DNS_SOURCE NI_DNS_ITEMS
  typeset NI_DNS_STATUS NI_DNS_REASON_JSON NI_GAPS NI_OBSERVED NI_COMPLETE
  typeset NI_TOP_STATUS NI_TOP_REASON NI_TOP_REASON_JSON

  NI_GAPS=""
  NI_IF_ITEMS=""
  NI_IF_PARTIAL=0

  NI_IFCONFIG=$(aix network_ifconfig_a ifconfig -a)
  NI_IFCONFIG_RC=$?
  NI_IF_SOURCE="{ \"capture\": \"network_ifconfig_a\", \"command\": \"ifconfig -a\", \"rc\": $NI_IFCONFIG_RC }"
  NI_IF_WHY=""
  if [ "$NI_IFCONFIG_RC" -ne 0 ]; then
    NI_IF_WHY="ifconfig -a capture failed (rc=$NI_IFCONFIG_RC)"
  elif [ -z "$NI_IFCONFIG" ]; then
    NI_IF_WHY="ifconfig -a capture empty (rc=0)"
  elif ! printf '%s\n' "$NI_IFCONFIG" | network_inventory_ifconfig_shape; then
    NI_IF_WHY="ifconfig -a capture unparseable (rc=0)"
  fi

  if [ -n "$NI_IF_WHY" ]; then
    NI_INTERFACES_STATUS="NOT_ASSESSED"
    NI_INTERFACES_REASON=$NI_IF_WHY
    NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_IF_WHY")
  else
    NI_PARSED=$(printf '%s\n' "$NI_IFCONFIG" |
      network_inventory_parse_ifconfig)
    NI_NAMES=$(printf '%s\n' "$NI_PARSED" |
      awk -F '\t' '$1=="I" { print $2 }')

    while IFS= read -r NI_IF
    do
      [ -n "$NI_IF" ] || continue
      NI_STATE=$(printf '%s\n' "$NI_PARSED" |
        awk -F '\t' -v wanted="$NI_IF" \
          '$1=="I" && $2==wanted { print $3; exit }')
      NI_HEADER_MTU=$(printf '%s\n' "$NI_PARSED" |
        awk -F '\t' -v wanted="$NI_IF" \
          '$1=="I" && $2==wanted { print $4; exit }')
      NI_IPV4=$(printf '%s\n' "$NI_PARSED" |
        awk -F '\t' -v wanted="$NI_IF" '
          $1=="A" && $2==wanted {
            if (seen++) printf ", "
            printf "{ \"address\": \"%s\", \"netmask\": \"%s\" }", $3, $4
          }')

      NI_MTU=""
      NI_MTU_STATUS="OBSERVED"
      NI_MTU_REASON=""
      if [ -n "$NI_HEADER_MTU" ]; then
        NI_MTU=$NI_HEADER_MTU
      else
        NI_LSATTR=$(aix "network_lsattr_$NI_IF" lsattr -El "$NI_IF")
        NI_LSATTR_RC=$?
        if [ "$NI_LSATTR_RC" -ne 0 ]; then
          NI_MTU_REASON="lsattr -El $NI_IF capture failed (rc=$NI_LSATTR_RC)"
        elif [ -z "$NI_LSATTR" ]; then
          NI_MTU_REASON="lsattr -El $NI_IF capture empty (rc=0)"
        elif ! printf '%s\n' "$NI_LSATTR" |
            network_inventory_lsattr_shape; then
          NI_MTU_REASON="lsattr -El $NI_IF capture unparseable (rc=0)"
        else
          NI_MTU=$(printf '%s\n' "$NI_LSATTR" |
            awk '$1=="mtu" { print $2; exit }')
        fi
        if [ -n "$NI_MTU_REASON" ]; then
          NI_MTU_STATUS="NOT_ASSESSED"
          NI_IF_PARTIAL=1
          NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_MTU_REASON")
        fi
      fi

      NI_ADAPTER=""
      NI_ADAPTER_TYPE=""
      NI_ADAPTER_STATUS="NOT_APPLICABLE"
      NI_ADAPTER_REASON="$NI_IF is not an Ethernet interface"
      NI_SPEED=""
      NI_SPEED_STATUS="NOT_APPLICABLE"
      NI_SPEED_REASON="$NI_IF is not an Ethernet interface"
      NI_SUFFIX=""
      NI_ADAPTER_CANDIDATE=""
      case "$NI_IF" in
        ent*) NI_SUFFIX=${NI_IF#ent} ;;
        en*) NI_SUFFIX=${NI_IF#en} ;;
        et*) NI_SUFFIX=${NI_IF#et} ;;
      esac
      case "$NI_SUFFIX" in
        ''|*[!0-9]*) ;;
        *)
          NI_ADAPTER_CANDIDATE="ent$NI_SUFFIX"
          NI_ENTSTAT=$(aix "network_entstat_$NI_ADAPTER_CANDIDATE" \
            entstat -d "$NI_ADAPTER_CANDIDATE")
          NI_ENTSTAT_RC=$?
          NI_ADAPTER_STATUS="NOT_ASSESSED"
          if [ "$NI_ENTSTAT_RC" -ne 0 ]; then
            NI_ADAPTER_REASON="entstat -d $NI_ADAPTER_CANDIDATE capture failed (rc=$NI_ENTSTAT_RC)"
          elif [ -z "$NI_ENTSTAT" ]; then
            NI_ADAPTER_REASON="entstat -d $NI_ADAPTER_CANDIDATE capture empty (rc=0)"
          elif ! printf '%s\n' "$NI_ENTSTAT" |
              network_inventory_entstat_shape "$NI_ADAPTER_CANDIDATE"; then
            NI_ADAPTER_REASON="entstat -d $NI_ADAPTER_CANDIDATE capture unparseable (rc=0)"
          else
            NI_ADAPTER=$NI_ADAPTER_CANDIDATE
            NI_ADAPTER_TYPE=$(printf '%s\n' "$NI_ENTSTAT" |
              network_inventory_entstat_type)
            NI_ADAPTER_STATUS="OBSERVED"
            NI_ADAPTER_REASON=""
            NI_SPEED=$(printf '%s\n' "$NI_ENTSTAT" |
              network_inventory_entstat_speed)
          fi

          if [ "$NI_ADAPTER_STATUS" = "OBSERVED" ]; then
            if [ -n "$NI_SPEED" ]; then
              NI_SPEED_STATUS="OBSERVED"
              NI_SPEED_REASON=""
            else
              NI_SPEED_STATUS="NOT_ASSESSED"
              NI_SPEED_REASON="entstat -d $NI_ADAPTER_CANDIDATE did not report media speed or adapter data rate"
            fi
          else
            NI_SPEED_STATUS="NOT_ASSESSED"
            NI_SPEED_REASON=$NI_ADAPTER_REASON
            NI_IF_PARTIAL=1
            NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_ADAPTER_REASON")
          fi
          ;;
      esac

      NI_ITEM_STATUS="OBSERVED"
      NI_ITEM_REASON=""
      if [ "$NI_MTU_STATUS" = "NOT_ASSESSED" ]; then
        NI_ITEM_STATUS="PARTIAL"
        NI_ITEM_REASON="MTU: $NI_MTU_REASON"
      fi
      if [ "$NI_ADAPTER_STATUS" = "NOT_ASSESSED" ]; then
        NI_ITEM_STATUS="PARTIAL"
        if [ -n "$NI_ITEM_REASON" ]; then
          NI_ITEM_REASON="$NI_ITEM_REASON; adapter: $NI_ADAPTER_REASON"
        else
          NI_ITEM_REASON="adapter: $NI_ADAPTER_REASON"
        fi
      fi

      if [ -n "$NI_MTU" ]; then NI_MTU_JSON=$NI_MTU; else NI_MTU_JSON=null; fi
      if [ -n "$NI_ADAPTER" ]; then
        NI_ADAPTER_JSON="\"$NI_ADAPTER\""
      else
        NI_ADAPTER_JSON=null
      fi
      if [ -n "$NI_ADAPTER_TYPE" ]; then
        NI_TYPE_ESC=$(printf '%s' "$NI_ADAPTER_TYPE" |
          network_inventory_json_escape)
        NI_TYPE_JSON="\"$NI_TYPE_ESC\""
      else
        NI_TYPE_JSON=null
      fi
      if [ -n "$NI_SPEED" ]; then NI_SPEED_JSON=$NI_SPEED; else NI_SPEED_JSON=null; fi

      if [ -n "$NI_MTU_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_MTU_REASON" |
          network_inventory_json_escape)
        NI_MTU_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_MTU_REASON_JSON=null
      fi
      if [ -n "$NI_ADAPTER_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_ADAPTER_REASON" |
          network_inventory_json_escape)
        NI_ADAPTER_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_ADAPTER_REASON_JSON=null
      fi
      if [ -n "$NI_SPEED_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_SPEED_REASON" |
          network_inventory_json_escape)
        NI_SPEED_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_SPEED_REASON_JSON=null
      fi
      if [ -n "$NI_ITEM_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_ITEM_REASON" |
          network_inventory_json_escape)
        NI_ITEM_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_ITEM_REASON_JSON=null
      fi

      NI_ITEM="{ \"name\": \"$NI_IF\", \"ipv4\": [$NI_IPV4], \"ipv4_status\": \"OBSERVED\", \"ipv4_reason\": null, \"state\": \"$NI_STATE\", \"state_status\": \"OBSERVED\", \"state_reason\": null, \"mtu\": $NI_MTU_JSON, \"mtu_status\": \"$NI_MTU_STATUS\", \"mtu_reason\": $NI_MTU_REASON_JSON, \"adapter\": $NI_ADAPTER_JSON, \"adapter_type\": $NI_TYPE_JSON, \"adapter_status\": \"$NI_ADAPTER_STATUS\", \"adapter_reason\": $NI_ADAPTER_REASON_JSON, \"media_speed_mbps\": $NI_SPEED_JSON, \"media_speed_status\": \"$NI_SPEED_STATUS\", \"media_speed_reason\": $NI_SPEED_REASON_JSON, \"status\": \"$NI_ITEM_STATUS\", \"reason\": $NI_ITEM_REASON_JSON }"
      if [ -n "$NI_IF_ITEMS" ]; then
        NI_IF_ITEMS="$NI_IF_ITEMS, $NI_ITEM"
      else
        NI_IF_ITEMS=$NI_ITEM
      fi
    done <<EOF
$NI_NAMES
EOF

    if [ "$NI_IF_PARTIAL" -eq 1 ]; then
      NI_INTERFACES_STATUS="PARTIAL"
      NI_INTERFACES_REASON="one or more interface attributes were not assessed; see per-interface reasons"
    else
      NI_INTERFACES_STATUS="COMPLETE"
      NI_INTERFACES_REASON=""
    fi
  fi

  if [ -n "$NI_INTERFACES_REASON" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_INTERFACES_REASON" |
      network_inventory_json_escape)
    NI_INTERFACES_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_INTERFACES_REASON_JSON=null
  fi

  NI_NETSTAT=$(aix network_netstat_rn netstat -rn)
  NI_NETSTAT_RC=$?
  NI_ROUTE_SOURCE="{ \"capture\": \"network_netstat_rn\", \"command\": \"netstat -rn\", \"rc\": $NI_NETSTAT_RC }"
  NI_ROUTE_WHY=""
  NI_ROUTE_ITEMS=""
  if [ "$NI_NETSTAT_RC" -ne 0 ]; then
    NI_ROUTE_WHY="netstat -rn capture failed (rc=$NI_NETSTAT_RC)"
  elif [ -z "$NI_NETSTAT" ]; then
    NI_ROUTE_WHY="netstat -rn capture empty (rc=0)"
  elif ! printf '%s\n' "$NI_NETSTAT" | network_inventory_netstat_shape; then
    NI_ROUTE_WHY="netstat -rn capture unparseable (rc=0)"
  fi

  if [ -n "$NI_ROUTE_WHY" ]; then
    NI_ROUTE_STATUS="NOT_ASSESSED"
    NI_ROUTE_REASON=$NI_ROUTE_WHY
    NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_ROUTE_WHY")
  else
    NI_ROUTE_ROWS=$(printf '%s\n' "$NI_NETSTAT" |
      network_inventory_parse_netstat)
    NI_ROUTE_ITEMS=$(printf '%s\n' "$NI_ROUTE_ROWS" | awk -F '\t' '
      NF {
        if (seen++) printf ", "
        if ($3=="") iface="null"; else iface="\"" $3 "\""
        if ($5=="") reason="null"; else reason="\"" $5 "\""
        printf "{ \"family\": \"%s\", \"gateway\": \"%s\", \"interface\": %s, \"status\": \"%s\", \"reason\": %s }", $1, $2, iface, $4, reason
      }')
    if printf '%s\n' "$NI_ROUTE_ROWS" |
        awk -F '\t' '$4=="PARTIAL" { found=1 } END { exit !found }'; then
      NI_ROUTE_STATUS="PARTIAL"
      NI_ROUTE_REASON="one or more default routes did not expose an interface"
      NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" \
        "netstat -rn default route did not expose an interface")
    else
      NI_ROUTE_STATUS="COMPLETE"
      NI_ROUTE_REASON=""
    fi
  fi
  if [ -n "$NI_ROUTE_REASON" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_ROUTE_REASON" |
      network_inventory_json_escape)
    NI_ROUTE_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_ROUTE_REASON_JSON=null
  fi

  NI_DNS_RAW=$(aix network_resolv_conf cat /etc/resolv.conf)
  NI_DNS_RC=$?
  NI_DNS_SOURCE="{ \"capture\": \"network_resolv_conf\", \"command\": \"cat /etc/resolv.conf\", \"rc\": $NI_DNS_RC }"
  NI_DNS_WHY=""
  NI_DNS_ITEMS=""
  if [ "$NI_DNS_RC" -ne 0 ]; then
    NI_DNS_WHY="cat /etc/resolv.conf capture failed (rc=$NI_DNS_RC)"
  elif [ -z "$NI_DNS_RAW" ]; then
    NI_DNS_WHY="cat /etc/resolv.conf capture empty (rc=0)"
  elif ! printf '%s\n' "$NI_DNS_RAW" | network_inventory_resolv_shape; then
    NI_DNS_WHY="cat /etc/resolv.conf capture unparseable (rc=0)"
  fi

  if [ -n "$NI_DNS_WHY" ]; then
    NI_DNS_STATUS="NOT_ASSESSED"
    NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_DNS_WHY")
  else
    NI_DNS_STATUS="COMPLETE"
    NI_DNS_ITEMS=$(printf '%s\n' "$NI_DNS_RAW" |
      network_inventory_parse_resolv |
      awk '{ if (seen++) printf ", "; printf "\"%s\"", $0 }')
  fi
  if [ -n "$NI_DNS_WHY" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_DNS_WHY" |
      network_inventory_json_escape)
    NI_DNS_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_DNS_REASON_JSON=null
  fi

  NI_OBSERVED=0
  NI_COMPLETE=0
  for NI_ITEM_STATUS in \
    "$NI_INTERFACES_STATUS" "$NI_ROUTE_STATUS" "$NI_DNS_STATUS"
  do
    [ "$NI_ITEM_STATUS" != "NOT_ASSESSED" ] && NI_OBSERVED=$((NI_OBSERVED + 1))
    [ "$NI_ITEM_STATUS" = "COMPLETE" ] && NI_COMPLETE=$((NI_COMPLETE + 1))
  done
  if [ "$NI_OBSERVED" -eq 0 ]; then
    NI_TOP_STATUS="NOT_ASSESSED"
    NI_TOP_REASON="no network fact source produced trustworthy output; see capture_gaps"
  elif [ "$NI_COMPLETE" -eq 3 ]; then
    NI_TOP_STATUS="COMPLETE"
    NI_TOP_REASON=""
  else
    NI_TOP_STATUS="PARTIAL"
    NI_TOP_REASON="one or more network fact sources or fields were not assessed; see sub-block reasons and capture_gaps"
  fi
  if [ -n "$NI_TOP_REASON" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_TOP_REASON" |
      network_inventory_json_escape)
    NI_TOP_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_TOP_REASON_JSON=null
  fi

  printf '"network": { "status": "%s", "platform": "AIX", ' "$NI_TOP_STATUS"
  printf '"reason": %s, "capture_gaps": [%s], ' "$NI_TOP_REASON_JSON" "$NI_GAPS"
  if [ "$NI_INTERFACES_STATUS" = "NOT_ASSESSED" ]; then
    printf '"interfaces": { "status": "%s", "reason": %s, "source": %s, "interfaces": null }, ' \
      "$NI_INTERFACES_STATUS" "$NI_INTERFACES_REASON_JSON" "$NI_IF_SOURCE"
  else
    printf '"interfaces": { "status": "%s", "reason": %s, "source": %s, "interfaces": [%s] }, ' \
      "$NI_INTERFACES_STATUS" "$NI_INTERFACES_REASON_JSON" "$NI_IF_SOURCE" "$NI_IF_ITEMS"
  fi
  if [ "$NI_ROUTE_STATUS" = "NOT_ASSESSED" ]; then
    printf '"routing": { "status": "%s", "reason": %s, "source": %s, "default_gateways": null }, ' \
      "$NI_ROUTE_STATUS" "$NI_ROUTE_REASON_JSON" "$NI_ROUTE_SOURCE"
  else
    printf '"routing": { "status": "%s", "reason": %s, "source": %s, "default_gateways": [%s] }, ' \
      "$NI_ROUTE_STATUS" "$NI_ROUTE_REASON_JSON" "$NI_ROUTE_SOURCE" "$NI_ROUTE_ITEMS"
  fi
  if [ "$NI_DNS_STATUS" = "NOT_ASSESSED" ]; then
    printf '"dns": { "status": "%s", "reason": %s, "source": %s, "resolvers": null } }' \
      "$NI_DNS_STATUS" "$NI_DNS_REASON_JSON" "$NI_DNS_SOURCE"
  else
    printf '"dns": { "status": "%s", "reason": %s, "source": %s, "resolvers": [%s] } }' \
      "$NI_DNS_STATUS" "$NI_DNS_REASON_JSON" "$NI_DNS_SOURCE" "$NI_DNS_ITEMS"
  fi
}

function emit_fact_filesystems {
  if [ -z "$FACT_STORAGE_FS_ROWS" ]; then printf 'null'; return; fi
  printf '%s\n' "$FACT_STORAGE_FS_ROWS" | awk -F'\t' '
    function jescape(s){
      gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\t/,"\\t",s); gsub(/\r/,"\\r",s)
      gsub(/[\001-\010\013\014\016-\037]/,"",s); return s
    }
    function jnum(v){return v=="?" ? "null" : v}
    BEGIN{printf "["}
    NF>=4{printf "%s{ \"mount\": \"%s\", \"size_mb\": %s, \"used_pct\": %s, \"iused_pct\": %s }",(n++?", ":""),jescape($1),$2,jnum($3),jnum($4)}
    END{printf "]"}'
}

if [ "$FORMAT" = "json" ]; then
  prepare_facts
  printf '{\n'
  printf '  "tool": "aixray",\n  "contract": "1.1",\n  "version": "%s",\n  "platform": "aix",\n  "role": "%s",\n' "$VERSION" "$ROLE"
  printf '  "host": "%s",\n  "generated": "%s",\n  "read_only": true,\n  "data_vintage": "%s",\n' \
         "$(printf '%s' "$HOST"|jesc)" "$(printf '%s' "$NOW"|jesc)" "$DATA_VINTAGE"
  if [ "${FV_PROVENANCE_REAL:-0}" = 1 ]; then
    FV_META_AGE_JSON=null
    [ -n "$FLRTVC_DATA_AGE" ] && FV_META_AGE_JSON=$FLRTVC_DATA_AGE
    printf '  "flrtvc_data": { "source": "%s", "version": %s, "apar_csv_vintage": %s, "apar_csv_age_days": %s },\n' \
      "$(printf '%s' "$FLRTVC_DATA_SOURCE" | jesc)" \
      "$(jn "$FLRTVC_DATA_VERSION")" "$(jn "$FLRTVC_DATA_VINTAGE")" "$FV_META_AGE_JSON"
  fi
  printf '  "summary": { "pass": %d, "warn": %d, "fail": %d, "not_assessed": %d, "score_pct": %d, "banner": "%s", "message": "%s" },\n' \
         "$PASS" "$WARN" "$FAIL" "$NASSESSED" "$SCORE" "$BANNER" "$(printf '%s' "$BMSG"|jesc)"
  printf '  "categories": [\n'
  ci=0
  while [ "$ci" -lt 9 ]; do
    CT=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} ))
    if [ "$CT" -gt 0 ]; then CSC=$(( ${CP[$ci]} * 100 / CT )); else CSC=0; fi
    sep=','; [ "$ci" -eq 8 ] && sep=''
    printf '    { "id": "%s", "label": "%s", "pass": %d, "warn": %d, "fail": %d, "not_assessed": %d, "score_pct": %d, "status": "%s" }%s\n' \
           "${CAT_ID[$ci]}" "$(printf '%s' "${CAT_LBL[$ci]}"|jesc)" "${CP[$ci]}" "${CW[$ci]}" "${CF[$ci]}" "${CN[$ci]}" "$CSC" "$(cat_status $ci)" "$sep"
    ci=$((ci+1))
  done
  printf '  ],\n'
  printf '  "findings": [\n'
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    sep=','; [ "$i" -eq $((NFIND-1)) ] && sep=''
    if [ -z "${F_CTL[$i]}" ]; then
      CJ='[]'
    else
      CJ='['; cfirst=1
      for ctl in ${F_CTL[$i]}; do
        [ "$cfirst" -eq 1 ] && cfirst=0 || CJ="$CJ, "
        CJ="$CJ\"$ctl\""
      done
      CJ="$CJ]"
    fi
    # optional rules array — grouped rule-engine findings only (F_RULES non-empty)
    if [ -z "${F_RULES[$i]}" ]; then
      RSUF=""
    else
      RJ=$(printf '%s\n' "${F_RULES[$i]}" | awk -F'|' '
        BEGIN{printf "["}
        NF>=3 && $1!=""{ printf "%s{ \"id\": \"%s\", \"status\": \"%s\", \"observed\": \"%s\" }", (n++?", ":""), $1, $2, $3 }
        END{printf "]"}')
      RSUF=", \"rules\": $RJ"
    fi
    # optional exposures array — apar_scan only (F_EXPOSURES non-empty). Report-derived
    # fields (fileset names, bulletin URLs, apar/ifix labels) are external IBM text and
    # MUST be JSON-escaped like any ordinary finding — "these are tightly-structured
    # identifiers" is not itself a safety boundary (Codex review round 3, item 5): a
    # stray quote/backslash/control byte here would previously have produced invalid or
    # injectable JSON. jescape() mirrors the shell jesc() helper exactly.
    if [ -z "${F_EXPOSURES[$i]}" ]; then
      EXPSUF=""
    else
      EJ=$(printf '%s\n' "${F_EXPOSURES[$i]}" | awk -F'\t' '
        function jescape(s){
          gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\t/,"\\t",s); gsub(/\r/,"\\r",s)
          gsub(/\n/,"\\n",s); gsub(/[\001-\010\013\014\016-\037]/,"",s)
          return s
        }
        # apars (field 7): semicolon-joined list of ALL non-CVE identifiers from the row
        # (never just the first — Codex review round 3, item 4) — a JSON array, never
        # mislabeled a singular "apar" since many of these are ifix labels, not APAR
        # numbers, and IBM own compact report does not distinguish the two.
        function apars_json(s,  cnt,a,i,out){
          if(s=="")return "[]"
          cnt=split(s,a,";")
          out="["
          for(i=1;i<=cnt;i++) out=out (i>1?", ":"") "\"" jescape(a[i]) "\""
          return out "]"
        }
        BEGIN{printf "["}
        NF>=11{ printf "%s{ \"cve\": \"%s\", \"hiper\": %s, \"fileset\": \"%s\", \"installed\": \"%s\", \"vulnerable_range\": \"%s\", \"fixed_at_or_above\": %s, \"apars\": %s, \"ifix\": \"%s\", \"bulletin\": \"%s\", \"cvss\": %s, \"reboot\": \"%s\" }", (n++?", ":""), jescape($1), ($2=="1"?"true":"false"), jescape($3), jescape($4), jescape($5), ($6==""?"null":"\"" jescape($6) "\""), apars_json($7), jescape($8), jescape($9), ($10==""?"null":$10), jescape($11) }
        END{printf "]"}')
      EXPSUF=", \"exposures\": $EJ"
    fi
    if [ -z "${F_EVIDENCE_COMMANDS[$i]}" ]; then
      EVSUF=""
    else
      EVSUF=", \"evidence\": { \"source_commands\": $(jcmds "${F_EVIDENCE_COMMANDS[$i]}") }"
    fi
    CIS_ROWS=$(cis_l1_verdicts "$i")
    if [ -z "$CIS_ROWS" ]; then
      CISSUF=""
    else
      CISJ=$(printf '%s\n' "$CIS_ROWS" | awk -F'|' '
        BEGIN{printf "["}
        NF>=2{printf "%s{ \"control\": \"%s\", \"verdict\": \"%s\" }",(n++?", ":""),$1,$2}
        END{printf "]"}')
      CISSUF=", \"cis_l1\": $CISJ"
    fi
    printf '    { "id": "%s", "category": "%s", "label": "%s", "status": "%s", "severity": "%s", "observed": "%s", "meaning": "%s", "fix": "%s", "controls": %s%s%s%s%s }%s\n' \
      "$(printf '%s' "${F_ID[$i]}"|jesc)" "${F_CAT[$i]}" "$(printf '%s' "${F_LBL[$i]}"|jesc)" "${F_ST[$i]}" "${F_SEV[$i]}" \
      "$(printf '%s' "${F_OBS[$i]}"|jesc)" "$(printf '%s' "${F_MEAN[$i]}"|jesc)" "$(printf '%s' "${F_FIX[$i]}"|jesc)" "$CJ" "$RSUF" "$EXPSUF" "$EVSUF" "$CISSUF" "$sep"
    i=$((i+1))
  done
  printf '  ],\n'
  printf '  "facts": {\n'
  printf '    "identity": { "hostname": "%s", "frame_serial": %s, "partition_id": %s, "partition_name": %s, "machine_type": %s, "role": "%s", "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(printf '%s' "$HOST" | jesc)" "$(jn "$FACT_FRAME_SERIAL")" "$(jnum "$FACT_PARTITION_ID")" \
    "$(jn "$FACT_PARTITION_NAME")" "$(jn "$UC_MODEL")" "$ROLE" "$FACT_ID_BASIS" \
    "$(jlist "$FACT_ID_UNREAD")" "$(jlist "$FACT_ID_NA")"
  printf '    "os": { "oslevel_s": %s, "release": %s, "tl": %s, "sp": %s, "build_week": %s, "eos_date": %s, "eosps_date": %s, "tl_latest": %s, "vios_level": %s, "source_commands": { "oslevel_s": %s, "vios_role": %s, "vios_level": %s }, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$OSLEVEL")" "$(jn "$REL")" "$(jn "$FACT_OS_TL")" "$(jn "$FACT_OS_SP")" "$(jn "$BWEEK")" \
    "$(jn "$FACT_OS_EOS")" "$(jn "$FACT_OS_EOSPS")" "$(jn "$UC_LATEST")" "$(jn "$UC_IOSL")" \
    "$(jcmds "oslevel -s")" "$(jcmds "ls /usr/ios/cli/ioscli")" "$(jcmds "$FACT_OS_VIOS_COMMANDS")" \
    "$FACT_OS_BASIS" "$(jlist "$FACT_OS_UNREAD")" "$(jlist "$FACT_OS_NA")"
  printf '    "firmware": { "level": %s, "family": %s, "hw_generation": %s, "hw_eos_date": %s, "firmware_uak_expiry": %s, "aix_uak_expiry": %s, "source_commands": { "level": %s, "family": %s, "hw_eos_date": %s, "firmware_uak_expiry": %s, "aix_uak_expiry": %s }, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$UC_FW")" "$(jn "$UC_FWFAM")" "$(jn "$FACT_HW_GEN")" "$(jn "$FACT_HW_EOS")" "$(jn "$FACT_FW_UAK_EXPIRY")" "$(jn "$FACT_AIX_UAK_EXPIRY")" \
    "$(jcmds "lsmcode -c|prtconf")" "$(jcmds "prtconf")" "$(jcmds "prtconf")" "$(jcmds "$FACT_FW_UAK_COMMANDS")" "$(jcmds "$FACT_AIX_UAK_COMMANDS")" \
    "$FACT_FW_BASIS" "$(jlist "$FACT_FW_UNREAD")" "$(jlist "$FACT_FW_NA")"
  printf '    %s,\n' "$(emit_fact_software)"
  printf '    %s,\n' "$(emit_fact_adapter_microcode)"
  printf '    "capacity": {\n'
  printf '      "snapshot": true,\n'
  printf '      "cpu": { "mode": %s, "capped": %s, "entitled_capacity": %s, "online_vcpus": %s, "variable_weight": %s, "smt": %s, "physc": %s, "entc_pct": %s, "idle_pct": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$FACT_CPU_MODE")" "$(jbool "$FACT_CPU_CAPPED")" "$(jnum "$FACT_CPU_ENT_OUT")" \
    "$(jnum "$FACT_CPU_OVP")" "$(jnum "$FACT_CPU_WEIGHT_OUT")" "$(jnum "$FACT_CPU_SMT")" \
    "$(jnum "$FACT_CPU_PHYSC")" "$(jnum "$FACT_CPU_ENTC_OUT")" "$(jnum "$FACT_CPU_IDLE")" \
    "$FACT_CPU_BASIS" "$(jlist "$FACT_CPU_UNREAD")" "$(jlist "$FACT_CPU_NA")"
  printf '      "memory": { "total_mb": %s, "inuse_mb": %s, "available_mb": %s, "pinned_mb": %s, "computational_pct": %s, "numperm_pct": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jnum "$FACT_MEM_TOTAL")" "$(jnum "$FACT_MEM_INUSE")" "$(jnum "$FACT_MEM_AVAILABLE")" \
    "$(jnum "$FACT_MEM_PINNED")" "$(jnum "$FACT_MEM_COMP")" "$(jnum "$FACT_MEM_NUMPERM")" \
    "$FACT_MEM_BASIS" "$(jlist "$FACT_MEM_UNREAD")" "$(jlist "$FACT_MEM_NA")"
  printf '      "paging": { "spaces": %s, "max_used_pct": %s, "all_in_rootvg": %s, "shares_pv": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jnum "$FACT_PAGING_SPACES")" "$(jnum "$FACT_PAGING_MAX")" "$(jbool "$FACT_PAGING_ROOT")" \
    "$(jbool "$FACT_PAGING_DUP")" "$FACT_PAGING_BASIS" "$(jlist "$FACT_PAGING_UNREAD")" "$(jlist "$FACT_PAGING_NA")"
  printf '      "storage": { "filesystems": %s, "worst_fs_used_pct": %s, "worst_fs_mount": %s, "worst_vg_free_pct": %s, "worst_vg": %s, "max_inode_pct": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(emit_fact_filesystems)" "$(jnum "$FACT_STORAGE_WORST_FS_PCT")" "$(jn "$FACT_STORAGE_WORST_FS_MOUNT")" \
    "$(jnum "$FACT_STORAGE_WORST_VG_PCT")" "$(jn "$FACT_STORAGE_WORST_VG")" "$(jnum "$FACT_STORAGE_MAX_INODE")" \
    "$FACT_STORAGE_BASIS" "$(jlist "$FACT_STORAGE_UNREAD")" "$(jlist "$FACT_STORAGE_NA")"
  printf '      "basis": "%s", "unreadable": %s, "not_applicable": %s\n' \
    "$FACT_CAP_BASIS" "$(jlist "$FACT_CAP_UNREAD")" "$(jlist "$FACT_CAP_NA")"
  printf '    },\n'
  printf '    %s,\n' "$(emit_fact_storage_layout)"
  FACT_ALT_DISK_RECOVERY=$(emit_fact_alt_disk_recoverability)
  case "$FACT_ALT_DISK_RECOVERY" in
    *'"basis":"partial"'*|*'"basis":"not_assessed"'*) FACT_REC_BASIS=partial;;
  esac
  printf '    "recovery": { "mksysb_evidence": %s, "alt_disk_present": %s, "rootvg_mirror": %s, "rootvg_mirror_disks": %s, "bootlist_devices": %s, "nim_client": %s, "powerha_state": %s, %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$FACT_RECOVERY_MKSYSB")" "$(jbool "$FACT_RECOVERY_ALT")" "$(jn "$FACT_RECOVERY_MIRROR")" \
    "$(jnum "$FACT_RECOVERY_MIRROR_DISKS")" "$(jnum "$FACT_RECOVERY_BOOTLIST")" "$(jbool "$FACT_RECOVERY_NIM")" \
    "$(jn "$FACT_REC_POWERHA_OUT")" "$FACT_ALT_DISK_RECOVERY" "$FACT_REC_BASIS" \
    "$(jlist "$FACT_REC_UNREAD")" "$(jlist "$FACT_REC_NA")"
  printf '    %s\n' "$(emit_fact_network_inventory)"
