.meta b{color:var(--ink)}
.ro{display:inline-block;background:var(--bg);color:var(--green);font-family:var(--mono);font-size:10px;font-weight:600;padding:2px 9px;letter-spacing:.5px;border:1px solid color-mix(in srgb,var(--green) 40%,var(--line))}

.score{display:flex;flex-wrap:wrap;gap:0;padding:24px 40px 8px;align-items:stretch}
.banner{order:-1;flex-basis:100%;display:flex;align-items:center;gap:12px;margin-bottom:12px;padding:15px 20px;color:#fff;font-weight:600;font-size:14.5px;line-height:1.35}
.banner::before{content:"";width:10px;height:10px;background:rgba(255,255,255,.95);flex:none}
